def list_winline_current_map_polling_keys() -> List[str]:
    return list(_winline_current_map_pollers.keys())


def _load_winline_current_map_poller_module():
    global _winline_current_map_poller_mod
    if _winline_current_map_poller_mod is not None:
        return _winline_current_map_poller_mod
    poller_path = PROJECT_ROOT / "services" / "winline" / "winline_current_map_odds_poller.py"
    if not poller_path.is_file():
        raise FileNotFoundError(f"missing winline current-map poller: {poller_path}")
    spec = importlib.util.spec_from_file_location(
        "runtime_winline_current_map_odds_poller",
        str(poller_path),
    )
    if spec is None or spec.loader is None:
        raise ImportError(f"cannot load winline current-map poller from {poller_path}")
    mod = importlib.util.module_from_spec(spec)
    sys.modules["runtime_winline_current_map_odds_poller"] = mod
    spec.loader.exec_module(mod)
    _winline_current_map_poller_mod = mod
    return mod


def note_winline_current_map_service_generation(
    *,
    producer_pid: Any = None,
    producer_start_generation: Any = None,
) -> None:
    """Propagate service PID/start generation to all active pollers."""
    if producer_pid is not None:
        _winline_current_map_service_gen["pid"] = int(producer_pid)
    if producer_start_generation is not None:
        _winline_current_map_service_gen["gen"] = str(producer_start_generation or "")
    for poller in list(_winline_current_map_pollers.values()):
        note = getattr(poller, "note_service_generation", None)
        if callable(note):
            try:
                note(
                    producer_pid=_winline_current_map_service_gen.get("pid"),
                    producer_start_generation=_winline_current_map_service_gen.get("gen"),
                )
            except Exception:
                pass


# Пропажа матча из фида SourceTV — не доказательство конца карты. Probe может
# на минуты перестать обновлять sourcetv_matches.json (реконнект к GC, пауза),
# запись протухает по SOURCETV_STALE_SECONDS, и серия исчезает из снимка при
# живой игре. Гасить опрос по такому сигналу нельзя: линия теряется посреди
# карты, а в админ-чат уходит ложное «карта завершена» (16.08.2026, LGD Gaming —
# Team Yandex, карта 3: терминал в 14:37:43 на 57-й минуте игры).
def _winline_source_blackout_grace_seconds() -> float:
    raw = os.getenv("WINLINE_SOURCE_BLACKOUT_GRACE_S")
    if raw is None or str(raw).strip() == "":
        return 300.0
    try:
        value = float(str(raw).strip())
    except (TypeError, ValueError):
        return 300.0
    return value if value >= 0 else 300.0


def _winline_next_map_wait_seconds() -> float:
    """Сколько ждать следующую карту серии после конца предыдущей.

    Замер по `runtime/winline_odds_history.jsonl` (64 пары соседних карт):
    пауза между картами — медиана 29.8 мин, 90-й перцентиль 47.0, максимум
    74.4. Сорок пять минут накрывают около девяти пар из десяти; дальше ждать
    невыгодно — опрос стоит браузерного времени, а карта, скорее всего, уже не
    состоится.
    """
    raw = os.getenv("WINLINE_NEXT_MAP_WAIT_S")
    if raw is None or str(raw).strip() == "":
        return 45 * 60.0
    try:
        value = float(str(raw).strip())
    except (TypeError, ValueError):
        return 45 * 60.0
    return value if value >= 0 else 45 * 60.0


def _winline_next_map_poll_interval_seconds() -> float:
    """Такт опроса карты, которую мост ещё не подтвердил.

    Обычные пять секунд здесь были бы платой ни за что: до начала карты рынка
    нет, а пауза тянется получас — это больше трёхсот холостых заходов в
    браузер на одну серию. Минута даёт задержку обнаружения не больше минуты
    при паузе в тридцать.
    """
    raw = os.getenv("WINLINE_NEXT_MAP_POLL_INTERVAL_S")
    if raw is None or str(raw).strip() == "":
        return 60.0
    try:
        value = float(str(raw).strip())
    except (TypeError, ValueError):
        return 60.0
    return value if value > 0 else 60.0


#: Серии, чья карта доиграна, а следующая ещё не появилась в мосте:
#: {ключ серии: {"map_num", "since", "team1", "team2"}}. Отдельно от реестра
#: серий намеренно — реестр перезаписывается на каждой регистрации поллера и
#: на каждом снимке моста, и ожидание в нём не пережило бы собственный запуск
#: опроса.
_winline_pending_next_maps: Dict[str, Dict[str, Any]] = {}


def _winline_awaiting_next_map(series: Any, map_num: Any, now: Any = None) -> bool:
    """Ждём ли мы именно эту карту как следующую в серии.

    Карты, которой ещё нет в мосте, для реестра не существует, и предикат
    «карта текущая» отвечал бы «нет» — поллер не стартовал бы вовсе. Между тем
    рынок следующей карты у букмекера появляется раньше, чем карта у Valve, а
    иногда (22.08.2026, `8959362208`) карта у Valve не появляется никогда.
    """
    key = str(series or "").strip()
    if not key:
        return False
    with _winline_current_map_state_lock:
        pending = _winline_pending_next_maps.get(key)
    if not isinstance(pending, dict):
        return False
    try:
        if int(pending.get("map_num")) != int(map_num):
            return False
        since = float(pending.get("since") or 0)
    except (TypeError, ValueError):
        return False
    if since <= 0:
        return False
    moment = float(time.time() if now is None else now)
    return (moment - since) < _winline_next_map_wait_seconds()


def _winline_source_blackout_within_grace(reg: Any) -> bool:
    """Слепота источника моложе грейса — карта считается всё ещё текущей."""
    if not isinstance(reg, dict):
        return False
    since = reg.get("inactive_since")
    if since is None:
        return False
    try:
        elapsed = time.time() - float(since)
    except (TypeError, ValueError):
        return False
    return elapsed < _winline_source_blackout_grace_seconds()


def _winline_current_map_is_current(**kwargs: Any) -> Any:
    """Exact-map-current predicate for the parent poller controller.

    Registry holds the latest successfully-parsed current map per series.
    Older map_num for the same series is treated as proven map_rollover.
    """
    identity = kwargs.get("identity") if isinstance(kwargs.get("identity"), dict) else None
    series = str(
        (identity or {}).get("series")
        if identity is not None
        else kwargs.get("series")
        or ""
    ).strip()
    try:
        map_num = int(
            (identity or {}).get("map_num")
            if identity is not None and (identity or {}).get("map_num") is not None
            else kwargs.get("map_num")
        )
    except (TypeError, ValueError):
        return {"current": False, "reason": "invalid_map_num"}
    team1 = str(
        (identity or {}).get("team1") if identity is not None else kwargs.get("team1") or ""
    ).strip()
    team2 = str(
        (identity or {}).get("team2") if identity is not None else kwargs.get("team2") or ""
    ).strip()
    if not series:
        return {"current": False, "reason": "missing_series"}
    reg = _winline_current_map_registry.get(series)
    if reg is None:
        return True
    if _winline_awaiting_next_map(series, map_num):
        # Предыдущая карта серии кончилась, эта ещё не появилась в мосте.
        # Рынок следующей карты у букмекера открывается раньше, поэтому опрос
        # держим до истечения окна ожидания.
        return True
    if reg.get("active") is False:
        proven = bool(reg.get("inactive_proven"))
        if not proven and _winline_source_blackout_within_grace(reg):
            # Источник молчит, но конец карты этим не доказан: продолжаем опрос.
            return True
        return {
            "current": False,
            "reason": str(reg.get("inactive_reason") or "source_absent"),
            "proven": proven,
        }
    if int(reg.get("map_num") or 0) != int(map_num):
        return {"current": False, "reason": "map_rollover"}
    if not _winline_same_team_pair(reg.get("team1"), reg.get("team2"), team1, team2):
        return {"current": False, "reason": "map_rollover"}
    return True


def _winline_normalized_team_identity(value: Any) -> str:
    text = re.sub(r"[^0-9a-zA-Zа-яёА-ЯЁ]+", " ", str(value or "")).strip().lower()
    return " ".join(text.split())


def _winline_same_team_pair(a1: Any, a2: Any, b1: Any, b2: Any) -> bool:
    """Та же пара команд, НЕЗАВИСИМО от порядка.

    Между картами серии команды меняются сторонами, и `team1`/`team2` в
    идентичности карты — это radiant/dire ТЕКУЩЕЙ карты, а не постоянные роли.
    Ключ серии это уже учитывает (`_winline_sourcetv_series_key` сортирует
    id команд), а сравнение карты — нет, и перестановка читалась как смена
    карты.

    24.08.2026, RE ARISE — Team Lynx: опрос второй карты стартовал из ожидания
    следующей карты, то есть в порядке ПЕРВОЙ (RE ARISE, Team Lynx). Когда
    вторая началась с обменом сторон, предикат вернул `map_rollover`, в чат
    ушло «🏁 карта 2 · карта завершена» — по карте, которая только началась, —
    и через 27 секунд «🆕 карта 2» уже в обратном порядке. В истории кэфов та
    же карта лежит под двумя ключами с зеркальными ценами (1.42/2.55 и
    2.55/1.42).
    """
    left = {_winline_normalized_team_identity(a1), _winline_normalized_team_identity(a2)}
    right = {_winline_normalized_team_identity(b1), _winline_normalized_team_identity(b2)}
    if "" in left or "" in right:
        # Пустое имя рушит сравнение множеств (две пустые схлопнутся в одну):
        # без имён идентичность не проверяется, решает номер карты.
        return True
    return left == right


def _winline_map_slot(series: Any, map_num: Any, team1: Any, team2: Any) -> str:
    """Слот карты: серия + номер + пара команд БЕЗ порядка.

    Канонический ключ (`series|mapN|team1|team2`) держит порядок, потому что к
    нему привязаны цены `p1`/`p2` и подпись в чате. Для поиска «уже опрашиваем
    ли мы эту карту» порядок только мешает — иначе на смене сторон заводится
    второй опрос той же карты.
    """
    pair = "|".join(sorted((
        _winline_normalized_team_identity(team1),
        _winline_normalized_team_identity(team2),
    )))
    try:
        n = int(map_num)
    except (TypeError, ValueError):
        n = map_num
    return f"{str(series or '').strip()}|map{n}|{pair}"


def _winline_adopt_transposed_poller(canonical: str, series: Any, map_num: Any,
                                     team1: Any, team2: Any) -> Any:
    """Активный опрос той же карты, заведённый в другом порядке команд.

    Возвращает поллер, уже перевешенный на новый канонический ключ, либо None.
    Вместе с ним переезжает состояние чата, причём цены МЕНЯЮТСЯ МЕСТАМИ:
    `p1`/`p2` привязаны к подписи, и без обмена первое же сообщение после
    усыновления показало бы стрелки движения там, где цена не менялась.
    """
    slot = _winline_map_slot(series, map_num, team1, team2)
    with _winline_current_map_state_lock:
        for key, poller in list(_winline_current_map_pollers.items()):
            if key == canonical:
                continue
            ident = getattr(poller, "_identity", None)
            if not isinstance(ident, dict):
                continue
            if _winline_map_slot(ident.get("series"), ident.get("map_num"),
                                 ident.get("team1"), ident.get("team2")) != slot:
                continue
            if not getattr(poller, "is_active", lambda: False)():
                continue
            ident["team1"], ident["team2"] = str(team1 or ""), str(team2 or "")
            try:
                poller._canonical_key = canonical  # type: ignore[attr-defined]
            except Exception:
                pass
            _winline_current_map_pollers.pop(key, None)
            _winline_current_map_pollers[canonical] = poller
            prev = _winline_odds_notify_state.pop(key, None)
            if prev:
                prev["p1"], prev["p2"] = prev.get("p2"), prev.get("p1")
                _winline_odds_notify_state[canonical] = prev
            orient = _winline_odds_orientation_state.pop(key, None)
            if orient:
                orient["p1"], orient["p2"] = orient.get("p2"), orient.get("p1")
                _winline_odds_orientation_state[canonical] = orient
            logger.info(
                "winline: карта %s сменила стороны, опрос усыновлён (%s -> %s)",
                map_num, key, canonical)
            return poller
    return None


def _winline_sourcetv_series_key(match: Any) -> str:
    """Stable SourceTV series identity across per-map Valve match IDs."""
    payload = match if isinstance(match, dict) else {}
    explicit = str(payload.get("series_id") or "").strip()
    if explicit and explicit not in {"0", "none", "null"}:
        return f"sourcetv:series:{explicit}"
    league_id = str(payload.get("league_id") or "0").strip()
    team_ids = sorted(
        str(value)
        for value in (
            payload.get("radiant_team_id"),
            payload.get("dire_team_id"),
        )
        if str(value or "").strip() not in {"", "0"}
    )
    if len(team_ids) == 2:
        pair = "|".join(f"id:{value}" for value in team_ids)
    else:
        names = sorted(
            filter(
                None,
                (
                    _winline_normalized_team_identity(payload.get("radiant_team_name")),
                    _winline_normalized_team_identity(payload.get("dire_team_name")),
                ),
            )
        )
        pair = "|".join(f"name:{value}" for value in names)
    return f"sourcetv:league:{league_id}|{pair}" if pair else ""


def _winline_sourcetv_sides_accounts(payload: Any) -> Tuple[List[int], List[int]]:
    """Аккаунты сторон из записи моста: (радиант, дайр). Пусто — не разобрали.

    Мост кладёт `team_map` — {account_id: сторона}; это единственное место, где
    состав есть до разбора драфта.
    """
    data = payload if isinstance(payload, dict) else {}
    tmap = data.get("team_map")
    rad: List[int] = []
    dire: List[int] = []
    if isinstance(tmap, dict):
        for acc, side in tmap.items():
            try:
                acc_i = int(acc)
            except (TypeError, ValueError):
                continue
            if acc_i <= 0:
                continue
            (rad if str(side) == "radiant" else dire).append(acc_i)
    return rad, dire


#: Последний счёт, восстановленный по своим картам, вместе с ключом серии.
#: Нужен строке счёта в карточке: она получает только `live_league_data`, где
#: составов нет, а пробрасывать их через пять точек вызова — хуже, чем
#: запомнить одно значение рядом с ключом и сверять его.
_LAST_DELTA_SERIES_SCORE: Dict[str, Any] = {"key": "", "score": (0, 0), "ts": 0.0}
#: Дольше этого запомненный счёт не используется: серия к тому времени кончилась.
_DELTA_SERIES_SCORE_TTL = 3 * 3600


def _winline_series_score_from_delta(payload: Any) -> Tuple[int, int]:
    """Счёт серии по нашим завершённым картам: (радиант, дайр). Fail-open."""
    rad, dire = _winline_sourcetv_sides_accounts(payload)
    if len(rad) < 4 or len(dire) < 4:
        return 0, 0
    try:
        import prematch_live_delta
        score = prematch_live_delta.series_progress(rad, dire)
    except Exception:                                # noqa: BLE001
        return 0, 0
    if sum(score) > 0:
        key = _winline_sourcetv_series_key(payload)
        if key:
            _LAST_DELTA_SERIES_SCORE.update(key=key, score=score, ts=time.time())
    return score


def _winline_series_score_remembered(live_league: Any) -> Optional[Tuple[int, int]]:
    """Запомненный счёт, если он про ЭТУ серию и ещё не протух."""
    key = _winline_sourcetv_series_key(live_league)
    if not key or key != str(_LAST_DELTA_SERIES_SCORE.get("key") or ""):
        return None
    try:
        age = time.time() - float(_LAST_DELTA_SERIES_SCORE.get("ts") or 0.0)
    except (TypeError, ValueError):
        return None
    if age > _DELTA_SERIES_SCORE_TTL:
        return None
    score = _LAST_DELTA_SERIES_SCORE.get("score") or (0, 0)
    return (int(score[0]), int(score[1])) if sum(score) > 0 else None


def _winline_sourcetv_map_num(match: Any) -> Optional[int]:
    payload = match if isinstance(match, dict) else {}

    def _payload_int(value: Any, default: int = 0) -> int:
        try:
            return int(float(value))
        except (TypeError, ValueError, OverflowError):
            return int(default)

    try:
        game_number = int(payload.get("series_game_number") or 0)
    except (TypeError, ValueError):
        game_number = 0
    try:
        played = int(payload.get("radiant_series_wins") or 0) + int(
            payload.get("dire_series_wins") or 0
        )
    except (TypeError, ValueError):
        played = 0
    if game_number <= 0 and played <= 0:
        # Valve отдаёт счёт серии НЕ ВСЕГДА. 25.08.2026 в серии
        # Nemiga — PuckChamp он пришёл на второй карте и пропал на третьей:
        # карточка объявила третью карту первой со счётом 0:0. Свои сыгранные
        # карты мы знаем точно — считаем по ним.
        played = sum(_winline_series_score_from_delta(payload))
    resolved = max(game_number, played + 1)
    # During the inter-map break the GC bridge can keep the completed Valve
    # match as live, with its old series_game_number and frozen game_time, while
    # explicitly clearing both draft payloads. Winline already exposes the next
    # map then. Advance only on that strong completed-map signature; missing or
    # transiently incomplete payloads must not roll the map forward.
    fast_picks = payload.get("fast_picks")
    heroes = payload.get("_cyberscore_heroes_and_pos")
    draft_explicitly_cleared = bool(
        isinstance(fast_picks, dict)
        and not fast_picks
        and isinstance(heroes, dict)
        and "radiant" in heroes
        and "dire" in heroes
        and not heroes.get("radiant")
        and not heroes.get("dire")
    )
    game_time = _payload_int(payload.get("game_time"), 0)
    total_kills = _payload_int(payload.get("radiant_score"), 0) + _payload_int(
        payload.get("dire_score"), 0
    )
    raw_series_type = _payload_int(payload.get("series_type"), -1)
    is_postgame_intermission = bool(
        str(payload.get("status") or "").strip().lower() == "live"
        and draft_explicitly_cleared
        and game_time >= 10 * 60
        and total_kills > 0
        and raw_series_type != 0
    )
    if is_postgame_intermission and resolved < 5:
        resolved += 1
    return resolved if 1 <= resolved <= 5 else None


# Bo-формат серии из моста SourceTV: сколько побед нужно для матча.
_WINLINE_SERIES_WINS_NEEDED = {1: 2, 2: 3}  # 1 = Bo3, 2 = Bo5
_WINLINE_SERIES_TYPE_BO2 = 3
# Формулировка, которой парсер помечает промоцию рынка «Матч» на решающей карте
# (`_winline_promote_last_map_match_market`). Признак не переживает конвертацию
# в SiteResult отдельным полем, поэтому опознаём его по тексту details.
_WINLINE_PROMOTED_DETAILS_MARKER = "match winner promoted"
# Срез моста читается на каждой регистрации поллера, а меняется раз в цикл GC.
_winline_series_rows_cache: Dict[str, Any] = {"mtime": None, "rows": []}


def _winline_series_int(value: Any) -> Optional[int]:
    try:
        return int(float(value))
    except (TypeError, ValueError, OverflowError):
        return None


def _winline_series_name_key(value: Any) -> str:
    return re.sub(r"[^0-9a-zа-яё]+", "", str(value or "").strip().lower())


def _winline_series_rows() -> List[Dict[str, Any]]:
    """Строки моста SourceTV с кэшем по mtime файла (fail-open: [] при сбое)."""
    path = str(globals().get("SOURCETV_MATCHES_PATH") or "")
    if not path:
        return []
    try:
        mtime = os.path.getmtime(path)
    except OSError:
        return []
    cache = _winline_series_rows_cache
    if cache.get("mtime") == mtime:
        return list(cache.get("rows") or [])
    try:
        with open(path, encoding="utf-8") as fh:
            raw = json.load(fh)
    except (OSError, ValueError):
        return []
    if isinstance(raw, dict):
        values = list(raw.values())
    elif isinstance(raw, list):
        values = list(raw)
    else:
        values = []
    rows = [item for item in values if isinstance(item, dict)]
    cache["mtime"] = mtime
    cache["rows"] = rows
    return list(rows)


def _winline_series_row_last_map(row: Any, map_num: Any) -> bool:
    """Решающая ли карта `map_num` для этой строки серии.

    На последней карте серии Winline иногда не выставляет рынок карты вовсе и
    оставляет только «Матч»: победитель карты и победитель матча — одно событие
    (05.08.2026, `No Hoodwink — Lynx`, Bo3 при счёте 1:1, карта 3 — в карточке
    только `Матч 2.55 1.42`). Bo2 тоже «последняя карта» по смыслу, но там рынок
    «Матч» ТРЁХисходный (возможна ничья) — его отсекает уже структурный разбор
    парсера, а не этот флаг.

    Формат неизвестен или счёт серии нечитаем — False: подстановка матчевого
    рынка на НЕрешающей карте дала бы цену другого события.
    """
    if not isinstance(row, dict):
        return False
    map_i = _winline_series_int(map_num)
    if map_i is None or not (1 <= map_i <= 5):
        return False
    # Доказанный Bo1: победитель карты и победитель матча — одно событие, и
    # подстановка матчевого рынка там не «на решающей карте», а тождественна.
    # Доказательством считаем только формат от cyberscore: `series_type` = 0 у GC
    # означает и Bo1, и отсутствие поля, а гадать здесь нельзя — подстановка на
    # НЕрешающей карте даёт цену другого события.
    if _winline_series_int(row.get("cyberscore_best_of")) == 1:
        return map_i == 1
    series_type = _winline_series_int(row.get("series_type"))
    if series_type == _WINLINE_SERIES_TYPE_BO2:
        return map_i == 2
    needed = _WINLINE_SERIES_WINS_NEEDED.get(series_type)
    if needed is None:
        return False
    r_wins = _winline_series_int(row.get("radiant_series_wins"))
    d_wins = _winline_series_int(row.get("dire_series_wins"))
    if r_wins is None or d_wins is None:
        return False
    if not (r_wins == needed - 1 and d_wins == needed - 1):
        return False
    # Счёт серии должен согласовываться с номером карты: 1:1 — это карта 3.
    return map_i == r_wins + d_wins + 1


def _winline_series_last_map(map_num: Any, team1: Any, team2: Any, *payloads: Any) -> bool:
    """Последняя карта серии для этой пары команд.

    Payload'ы (данные матча, уже прочитанные вызывающим) главнее файла: они
    свежее. Без них пара ищется в срезе моста `SOURCETV_MATCHES_PATH`; матча в
    срезе нет — False.
    """
    merged: Dict[str, Any] = {}
    for payload in payloads:
        if isinstance(payload, dict):
            merged.update(payload)
    if merged.get("series_type") is not None:
        return _winline_series_row_last_map(merged, map_num)

    key1 = _winline_series_name_key(team1)
    key2 = _winline_series_name_key(team2)
    if not key1 or not key2:
        return False
    wanted = {key1, key2}
    for row in _winline_series_rows():
        pair = {
            _winline_series_name_key(row.get("radiant_team_name")),
            _winline_series_name_key(row.get("dire_team_name")),
        }
        if "" in pair or pair != wanted:
            continue
        return _winline_series_row_last_map(row, map_num)
    return False


def _winline_registry_series_last_map(series: Any) -> bool:
    """Флаг решающей карты, сохранённый при регистрации поллера серии."""
    key = str(series or "").strip()
    if not key:
        return False
    try:
        with _winline_current_map_state_lock:
            entry = _winline_current_map_registry.get(key)
        return bool(isinstance(entry, dict) and entry.get("series_last_map"))
    except Exception:
        return False


def _winline_polling_series_key(
    fallback: Any,
    *,
    live_data: Any = None,
    live_league: Any = None,
) -> str:
    if str(globals().get("DLTV_SOURCE_MODE") or "").strip().lower() != "sourcetv":
        return str(fallback or "").strip()
    payload: Dict[str, Any] = {}
    explicit_series = None
    if isinstance(live_data, dict):
        explicit_series = live_data.get("series_id")
    if isinstance(live_league, dict):
        payload.update(live_league)
    if isinstance(live_data, dict):
        payload.update(live_data)
    # live_league.series_id may be the runtime fallback match_id. Only the raw
    # bridge series_id is stable across maps.
    payload["series_id"] = explicit_series
    stable = _winline_sourcetv_series_key(payload)
    return stable or str(fallback or "").strip()


def _resolve_sourcetv_bridge_identity(matches: Any) -> Any:
    """Дописать названия команд и формат серии в записи моста по данным cyberscore.

    Опрос коэффициентов заводится от записи МОСТА, а не от карточки:
    `_reconcile_winline_sourcetv_polling` берёт имена и id оттуда и строит по ним
    идентичность поллера. Пока Valve молчит, получается
    `name:balu team|name:dire|map1` — поллер уходит искать на Winline команду
    «Dire» и не находит ничего. 26.08.2026 так пропали кэфы по картам
    Balu — PuckChamp и Synapse — Nemiga Gaming, хотя сами матчи разбирались.

    Поэтому личность подставляется ЗДЕСЬ, до реконсиляции поллеров: карточка
    получит те же имена из того же payload'а. Молча возвращает вход, если
    подставлять нечего.
    """
    if not isinstance(matches, dict) or not matches:
        return matches
    if not SOURCETV_IDENTITY_FALLBACK:
        return matches
    pending = []
    for key, payload in matches.items():
        if not isinstance(payload, dict):
            continue
        if not _league_matches_allowlist(payload.get("league_id"), payload.get("league_name")):
            continue
        needs_name = (
            _is_placeholder_team_name(payload.get("radiant_team_name"))
            or _is_placeholder_team_name(payload.get("dire_team_name"))
        )
        # Формат серии спрашиваем ровно там, где GC его не доказал: ноль и
        # отсутствие поля у protobuf неразличимы, а от этого зависит, можно ли
        # подставить рынок «Матч» (в Bo1 карта и есть матч). Там, где GC назвал
        # Bo3/Bo5, ходить в браузер незачем.
        needs_format = (
            _coerce_int(payload.get("cyberscore_best_of")) <= 0
            and _winline_series_int(payload.get("series_type")) in (0, None)
        )
        if needs_name or needs_format:
            pending.append((key, payload))
    if not pending:
        return matches
    try:
        rows = _sourcetv_identity_rows()
    except Exception as exc:
        logger.warning("CyberScore identity rows unavailable: %s", exc)
        return matches
    if not rows:
        return matches
    for key, payload in pending:
        try:
            identity = _resolve_sourcetv_identity_from_cyberscore(
                payload.get("match_id") or key,
                payload.get("radiant_team_name"),
                payload.get("dire_team_name"),
                rows=rows,
            )
        except Exception as exc:
            logger.warning("CyberScore identity for %s failed: %s", key, exc)
            continue
        if not identity:
            continue
        before_names = (payload.get("radiant_team_name"), payload.get("dire_team_name"))
        radiant_name, dire_name, _tournament = identity
        if radiant_name and _is_placeholder_team_name(payload.get("radiant_team_name")):
            payload["radiant_team_name"] = radiant_name
        if dire_name and _is_placeholder_team_name(payload.get("dire_team_name")):
            payload["dire_team_name"] = dire_name
        # Формат серии от cyberscore — единственное ДОКАЗАТЕЛЬСТВО Bo1: у GC
        # `series_type` = 0 одинаково означает и Bo1, и «поля нет» (proto3
        # отдаёт ноль по умолчанию), поэтому сам по себе ноль ничего не доказывает.
        row = rows.get(int(payload.get("match_id") or key or 0)) if str(
            payload.get("match_id") or key or ""
        ).isdigit() else None
        best_of = _coerce_int((row or {}).get("best_of"))
        if best_of > 0:
            payload["cyberscore_best_of"] = best_of
        for name_key, id_key in (
            ("radiant_team_name", "radiant_team_id"),
            ("dire_team_name", "dire_team_id"),
        ):
            if _coerce_int(payload.get(id_key)) > 0:
                continue
            known_ids = _find_known_team_ids_by_name(payload.get(name_key))
            if known_ids:
                payload[id_key] = int(min(known_ids))
        if before_names != (payload.get("radiant_team_name"), payload.get("dire_team_name")):
            print(
                f"   🔎 Личность моста из CyberScore: {payload.get('radiant_team_name')} vs "
                f"{payload.get('dire_team_name')} (матч {key})"
            )
    return matches


def _reconcile_winline_sourcetv_polling(
    matches: Any,
    *,
    authoritative: bool,
) -> None:
    """Update lifecycle from the successfully-read SourceTV bridge snapshot."""
    if isinstance(matches, dict):
        values = matches.values()
    elif isinstance(matches, list):
        values = matches
    else:
        values = []
    active: Dict[str, Dict[str, Any]] = {}
    for item in values:
        if not isinstance(item, dict):
            continue
        series = _winline_sourcetv_series_key(item)
        map_num = _winline_sourcetv_map_num(item)
        if not series or map_num is None:
            continue
        active[series] = {
            "map_num": map_num,
            "team1": str(item.get("radiant_team_name") or "").strip(),
            "team2": str(item.get("dire_team_name") or "").strip(),
            "active": True,
            "inactive_reason": None,
            "inactive_proven": False,
            "inactive_since": None,
            # Решающая карта считается из того же снимка: `series_type` мост
            # пишет GC-энумом (0=BO1, 1=BO3, 2=BO5), под который и сделан
            # _WINLINE_SERIES_WINS_NEEDED. Раньше сверка перетирала запись без
            # этого поля, флаг гас до следующей регистрации поллера, и промоция
            # рынка «Матч» в рынок карты моргала внутри одной карты.
            "series_last_map": _winline_series_row_last_map(item, map_num),
            # Счёт серии нужен, чтобы решить, БУДЕТ ЛИ следующая карта. Флага
            # решающей карты для этого мало: он говорит «эта карта последняя»,
            # а не «после неё серия точно продолжится».
            "series_type": _winline_series_int(item.get("series_type")),
            "wins": (_winline_series_int(item.get("radiant_series_wins")),
                     _winline_series_int(item.get("dire_series_wins"))),
        }

    with _winline_current_map_state_lock:
        for series, payload in active.items():
            previous = _winline_current_map_registry.get(series)
            if (
                not payload["series_last_map"]
                and isinstance(previous, dict)
                and previous.get("series_last_map")
                and _winline_series_int(previous.get("map_num")) == payload["map_num"]
            ):
                # Снимок не смог доказать решающую карту (нет series_type или
                # счёт серии нечитаем) — уже доказанный флаг ТОЙ ЖЕ карты не
                # гасим. При смене карты флаг не переносится.
                payload["series_last_map"] = True
            _winline_current_map_registry[series] = payload
            # Ожидаемая карта дошла до моста — ждать больше нечего.
            _winline_clear_pending_next_map(series, payload["map_num"])
        for series, current in list(_winline_current_map_registry.items()):
            if not str(series).startswith("sourcetv:") or series in active:
                continue
            was_active = current.get("active") is not False
            current["active"] = False
            current["inactive_reason"] = (
                "source_absent" if authoritative else "source_stale"
            )
            current["inactive_proven"] = bool(authoritative)
            # Момент начала слепоты: по нему предикат отмеряет грейс, а не гасит
            # опрос на первом же пропуске снимка.
            if was_active or current.get("inactive_since") is None:
                current["inactive_since"] = time.time()
            _winline_note_pending_next_map(series, current)
    _winline_start_pending_next_map_polling()


def _winline_apply_poll_interval(poller: Any, interval: Any) -> bool:
    """Сменить такт уже работающего опроса. `None` — оставить как есть.

    Отсутствие значения означает обычный такт: так вызывает живой путь, когда
    карта подтвердилась мостом, и редкий такт ожидания надо снять.
    """
    try:
        mod = _load_winline_current_map_poller_module()
        default = float(getattr(mod, "POLL_INTERVAL_SECONDS", 5.0))
    except Exception:
        default = 5.0
    try:
        value = default if interval is None else float(interval)
    except (TypeError, ValueError):
        return False
    if value <= 0:
        return False
    try:
        if float(getattr(poller, "_poll_interval", default)) == value:
            return False
        poller._poll_interval = value                    # type: ignore[attr-defined]
        return True
    except Exception:
        return False


def _winline_next_map_certain(reg: Any, current_map: Any) -> bool:
    """Состоится ли следующая карта серии ГАРАНТИРОВАННО.

    Исход только что сыгранной карты нам неизвестен, поэтому годится лишь то,
    что верно при любом её результате. В Bo3 при счёте 1:0 карта 3 будет только
    при 1:1, а при 2:0 серия кончается — ждать её нельзя. Формально: следующая
    карта неизбежна, когда даже победа лидера не даёт нужного числа побед,
    то есть `max(побед) + 1 < needed`.

    Цена ошибки уже заплачена: 23.08.2026 ожидание карты 3 в серии
    Team Spirit — Team Yandex запустило опрос несуществующей карты, и его
    завершение ушло в чат как «карта завершена».
    """
    if not isinstance(reg, dict):
        return False
    series_type = _winline_series_int(reg.get("series_type"))
    if series_type == _WINLINE_SERIES_TYPE_BO2:
        # В Bo2 играются обе карты независимо от исхода первой.
        return _winline_series_int(current_map) == 1
    needed = _WINLINE_SERIES_WINS_NEEDED.get(series_type)
    if needed is None:
        return False                     # формат неизвестен — не гадаем
    wins = reg.get("wins")
    if not isinstance(wins, (tuple, list)) or len(wins) != 2:
        return False
    r_wins, d_wins = _winline_series_int(wins[0]), _winline_series_int(wins[1])
    if r_wins is None or d_wins is None:
        return False                     # счёт нечитаем — не гадаем
    # Счёт должен согласовываться с номером карты, иначе одно из двух неверно.
    if r_wins + d_wins + 1 != _winline_series_int(current_map):
        return False
    return max(r_wins, d_wins) + 1 < needed


def _winline_note_pending_next_map(series: Any, reg: Any, now: Any = None) -> Optional[int]:
    """Отметить, какую карту серии ждём после ушедшей. Вернуть её номер.

    Серия продолжается, пока сыгранная карта не была решающей. Ждать её у
    Valve необязательно: рынок следующей карты Winline открывает раньше, а
    22.08.2026 карта `8959362208` не появилась у Valve вовсе — коэффициенты по
    ней не запрашивались ни разу, потому что опрос стартовал только от живой
    карты в мосте.
    """
    key = str(series or "").strip()
    if not key or not isinstance(reg, dict):
        return None
    moment = float(time.time() if now is None else now)
    with _winline_current_map_state_lock:
        already = _winline_pending_next_maps.get(key)
    if isinstance(already, dict):
        # Ожидание уже идёт. Номер не двигаем: реестр к этому моменту показывает
        # ту самую ожидаемую карту (её записала регистрация опроса), и сдвиг
        # означал бы перескок через карту, которую мы ещё ждём.
        try:
            if moment - float(already.get("since") or 0) < _winline_next_map_wait_seconds():
                return _winline_series_int(already.get("map_num"))
        except (TypeError, ValueError):
            pass
        with _winline_current_map_state_lock:
            _winline_pending_next_maps.pop(key, None)
        return None
    if reg.get("series_last_map"):
        # Решающая карта сыграна — серии дальше нет.
        return None
    if not reg.get("inactive_proven"):
        # Источник просто молчит; конец карты не доказан, ждать рано.
        return None
    current_map = _winline_series_int(reg.get("map_num"))
    if current_map is None or not (1 <= current_map <= 4):
        return None
    if not _winline_next_map_certain(reg, current_map):
        return None
    nxt = current_map + 1
    with _winline_current_map_state_lock:
        _winline_pending_next_maps[key] = {
            "map_num": nxt,
            "since": moment,
            "team1": str(reg.get("team1") or "").strip(),
            "team2": str(reg.get("team2") or "").strip(),
        }
    return nxt


def _winline_clear_pending_next_map(series: Any, map_num: Any = None) -> bool:
    """Снять ожидание: карта пришла в мост (или ушла дальше по серии)."""
    key = str(series or "").strip()
    if not key:
        return False
    with _winline_current_map_state_lock:
        pending = _winline_pending_next_maps.get(key)
        if not isinstance(pending, dict):
            return False
        if map_num is not None:
            try:
                if int(map_num) < int(pending.get("map_num")):
                    return False
            except (TypeError, ValueError):
                return False
        _winline_pending_next_maps.pop(key, None)
    return True


def _winline_start_pending_next_map_polling() -> int:
    """Завести опрос по каждой ожидаемой карте. Вернуть, сколько заведено.

    Такт редкий (`_winline_next_map_poll_interval_seconds`): до начала карты
    рынка нет, и обычные пять секунд означали бы сотни холостых заходов в
    браузер за одну паузу между картами.
    """
    started = 0
    with _winline_current_map_state_lock:
        pending = [(series, dict(state))
                   for series, state in _winline_pending_next_maps.items()
                   if isinstance(state, dict)]
        # Поколение продюсера берём готовое. Регистрация опроса умеет назначить
        # его сама (по `os.getpid()`), но здесь это был бы побочный эффект:
        # смена поколения — терминальная причина для ВСЕХ живых опросов, и
        # ожидание следующей карты гасило бы опрос текущей.
        known_pid = _winline_current_map_service_gen.get("pid") or None
        known_gen = _winline_current_map_service_gen.get("gen") or None
    for series, state in pending:
        map_num = _winline_series_int(state.get("map_num"))
        if map_num is None or not _winline_awaiting_next_map(series, map_num):
            continue
        team1 = str(state.get("team1") or "").strip()
        team2 = str(state.get("team2") or "").strip()
        if not team1 or not team2:
            continue
        canonical = f"{series}|map{map_num}|{team1}|{team2}"
        with _winline_current_map_state_lock:
            existing = _winline_current_map_pollers.get(canonical)
        if existing is not None and getattr(existing, "is_active", lambda: False)():
            continue
        outcome = ensure_winline_current_map_polling(
            series=series,
            map_num=map_num,
            team1=team1,
            team2=team2,
            selected_side=None,
            series_last_map=False,
            producer_pid=known_pid,
            producer_start_generation=known_gen,
            update_registry=False,
            poll_interval_seconds=_winline_next_map_poll_interval_seconds(),
            # Перезагрузка страницы лечит застывший DOM, а здесь карта просто
            # ещё не началась: рынка нет и после перезагрузки. Страница у всех
            # опросов общая, поэтому ожидание не имеет права её дёргать — иначе
            # оно ослепляет живые карты соседних матчей на десятки секунд.
            reload_after_consecutive_misses=10 ** 9,
        )
        if outcome:
            started += 1
            try:
                logger.info(
                    "winline: ждём карту %d серии %s (%s vs %s), опрос раз в %.0f c",
                    map_num, series, team1, team2,
                    _winline_next_map_poll_interval_seconds(),
                )
            except Exception:
                pass
    return started


def _winline_evidence_path_for_key(canonical_key: str) -> Path:
    digest = hashlib.sha256(str(canonical_key).encode("utf-8")).hexdigest()[:20]
    return WINLINE_CURRENT_MAP_POLLING_EVIDENCE_PATH.parent / "maps" / f"{digest}.json"


def _winline_write_current_map_evidence(payload: Dict[str, Any], path: Any = None) -> None:
    """Race-safe atomic evidence write (unique temp + lock + replace).

    Never raises into caller. Surfaces write failures via logger and optional
    payload/side-channel flags when possible; never leaves truncated/mixed JSON
    at the destination path.
    """
    tmp_path: Optional[Path] = None
    try:
        out = Path(path) if path is not None else Path(
            globals().get(
                "WINLINE_CURRENT_MAP_POLLING_EVIDENCE_PATH",
                WINLINE_CURRENT_MAP_POLLING_EVIDENCE_PATH,
            )
        )
        out.parent.mkdir(parents=True, exist_ok=True)
        data = json.dumps(payload, ensure_ascii=False, indent=2, default=str)
        digest = hashlib.sha256(data.encode("utf-8")).hexdigest()
        # Unique same-directory temp avoids fixed latest.json.tmp collisions
        # when scheduler + main-loop both publish.
        token = secrets.token_hex(8)
        tmp_path = out.with_name(f".{out.name}.{os.getpid()}.{token}.tmp")
        with _winline_current_map_evidence_lock:
            cache_key = str(out)
            if _winline_current_map_evidence_hashes.get(cache_key) == digest:
                return
            # Exclusive writer critical section for this destination.
            with open(tmp_path, "x", encoding="utf-8") as fh:
                fh.write(data)
                fh.flush()
                try:
                    os.fsync(fh.fileno())
                except Exception:
                    pass
            os.replace(str(tmp_path), str(out))
            tmp_path = None  # successfully moved
            _winline_current_map_evidence_hashes[cache_key] = digest
    except Exception as exc:
        # Best-effort cleanup of orphan temp; never publish partial dest.
        if tmp_path is not None:
            try:
                if tmp_path.exists():
                    tmp_path.unlink()
            except Exception:
                pass
        try:
            logger.warning("winline current-map evidence write failed: %s", exc)
        except Exception:
            pass
        # Surface failure onto payload for callers that keep a reference
        # (tests / diagnostics). Destination file is left untouched.
        try:
            if isinstance(payload, dict):
                payload["_evidence_write_error"] = f"{type(exc).__name__}:{exc}"
        except Exception:
            pass


def _winline_normalize_url_for_page_check(url: Any) -> str:
    """Loose URL normalize for expected-vs-actual page checks (no network)."""
    raw = str(url or "").strip()
    if not raw:
        return ""
    try:
        parsed = urlparse(raw if "://" in raw else f"https://{raw}")
        host = (parsed.hostname or "").lower().rstrip(".")
        path = (parsed.path or "").rstrip("/")
        return f"{host}{path}"
    except Exception:
        return raw.strip().rstrip("/").lower()


def _winline_urls_look_equivalent(left: Any, right: Any) -> bool:
    a = _winline_normalize_url_for_page_check(left)
    b = _winline_normalize_url_for_page_check(right)
    if not a or not b:
        return False
    if a == b:
        return True
    # Tolerate www / trailing slash / query-less host match for same bookmaker path.
    if a.startswith("www."):
        a = a[4:]
    if b.startswith("www."):
        b = b[4:]
    return a == b or a.endswith(b) or b.endswith(a)


# Парсер Winline отдаёт p1_team/p2_team как МАРКЕРЫ РОЛИ ("team1"/"team2") —
# они говорят, какой стороне принадлежат кэфы, а не как называется команда.
# Подставлять их в поля имён нельзя: приёмка сверяет имена с идентичностью
# поллера, поэтому отбраковывался КАЖДЫЙ матч при полностью валидном рынке.
_WINLINE_ROLE_MARKERS = frozenset({"team1", "team2", "p1", "p2"})


def _winline_reported_team_name(value: Any) -> Optional[str]:
    """Настоящее имя команды из результата парсера, либо None для маркера роли."""
    text = str(value or "").strip()
    if not text or text.lower() in _WINLINE_ROLE_MARKERS:
        return None
    return text


# Быстрый съём карточки Winline.
#
# Полный разбор тянет из браузера page.content() плюс несколько
# page.locator("body").inner_text(timeout=...) — именно эти round-trip'ы и стоят
# 6-25 c, а не парсинг. Быстрый путь делает ОДИН evaluate и дальше работает в
# Python.
#
# Страницу берём целиком. Так вход быстрого пути совпадает с входом полного
# разбора, и границы карточки считает та же функция с теми же предохранителями
# (_winline_matched_card_context / _extract_winline_current_map_winner), покрытая
# тестами. Своей логики решения здесь нет — раньше была, в виде эвристики на блок
# рынков внутри суженного поддерева, и она давала ложные «рынка нет».
#
# Замер на живой странице: outerHTML 0.035 c, сужение по 563 КБ — 0.07-0.25 c.
#
# Любая неудача быстрого пути — просто None и откат на полный разбор.
_WINLINE_FAST_CARD_JS = """
(args) => {
  const html = document.documentElement.outerHTML || '';
  return { html: html.length > args.maxHtml ? '' : html, url: location.href };
}
"""

# Потолок на случай неожиданно огромного документа: живая страница ~563 КБ.
WINLINE_FAST_CARD_MAX_HTML = 4000000

# Порог, ниже которого страницу нельзя считать загруженной целиком, а значит и
# УТВЕРЖДАТЬ отсутствие рынка по ней нельзя (живая ~563 КБ). Положительный ответ
# порогом не ограничен: найденная карточка со строкой рынка доказывает себя сама.
WINLINE_FAST_MIN_PAGE_HTML = 50000

# Узнаваемая разметка Winline: страница-заглушка или чужая страница не должна
# превращаться в «рынка нет».
_WINLINE_PAGE_CHROME_MARKERS = ("киберспорт", "winline")

_WINLINE_TEAM_GENERIC = frozenset(
    {"esports", "esport", "sports", "team", "gaming", "club", "org"}
)


def _winline_team_probe_tokens(value: Any) -> List[str]:
    """Значимые токены названия для поиска в DOM (родовые слова отбрасываем)."""
    text = re.sub(r"[^0-9a-zA-Zа-яёА-ЯЁ]+", " ", str(value or "")).strip().lower()
    if not text:
        return []
    tokens = [t for t in text.split() if t and t not in _WINLINE_TEAM_GENERIC]
    return tokens or text.split()


class _WinlineFastResult:
    """Утиный дублёр SiteResult для существующего конвертера в словарь."""

    status = "ok"
    market_closed = False
    market_kind = "current_map_winner"
    source = "winline_current_map_winner"
    acquisition_mode = "dynamic_dom_fast"
    parser_failure_reasons: List[str] = []
    acquisition_error = None
    error = None
    load_error = None
    p1_team = None
    p2_team = None
    # None = доступность исхода не доказана ни в одну сторону (fail-open).
    odds_bettable = None
    # Кэфы взяты из рынка «Матч» на решающей карте серии (промоция парсера).
    promoted_from_match = False
    # Сырой порядок карточки Winline (имена в порядке карточки + неразвёрнутая пара).
    card_team_order = None
    card_odds = None

    def __init__(self, *, odds, map_num, page_url, details, dom_signature):
        self.odds = list(odds)
        self.map_num = map_num
        self.page_url = page_url
        self.details = details
        self.body_text = details
        self.dom_signature = dom_signature
        self.dom_hash = dom_signature
        self.match_found = True


def _winline_fast_collect(
    page: Any,
    *,
    series: Any,
    map_num: int,
    team1: str,
    team2: str,
    expected_url: str,
) -> Optional[Dict[str, Any]]:
    """Быстрый съём карточки. None — значит откатываемся на полный разбор."""
    try:
        payload = page.evaluate(
            _WINLINE_FAST_CARD_JS,
            {"maxHtml": WINLINE_FAST_CARD_MAX_HTML},
        )
    except Exception:
        return None
    context = globals().get("_winline_current_map_batch_context")
    if isinstance(context, dict) and isinstance(payload, dict):
        context["payload"] = dict(payload)
    return _winline_fast_collect_from_payload(
        payload,
        series=series,
        map_num=map_num,
        team1=team1,
        team2=team2,
        expected_url=expected_url,
    )


def _winline_select_matching_pinned_card(
    page: Any,
    *,
    team1: str,
    team2: str,
) -> bool:
    """Select a generic Winline pinned event so its map markets enter the DOM.

    The selected-card flag is read from the live DOM on every recovery attempt.
    An in-memory "last selected" key is insufficient because Angular can replace
    the selected panel while keeping the same Playwright page object.
    """
    matcher = globals().get("_bookmaker_text_matches_teams")
    if not callable(matcher):
        return False
    try:
        cards = page.locator("ww-pinned-card")
        count = min(20, int(cards.count()))
    except Exception:
        return False
    for index in range(count):
        try:
            card = cards.nth(index)
            text = str(card.inner_text(timeout=1000) or "")
            if not matcher(text, team1, team2):
                continue
            try:
                if int(card.locator(".new-card--selected").count()) > 0:
                    return False
            except Exception:
                # Older test doubles and transient Angular nodes may not expose
                # descendant locators. Clicking the already-selected card is a
                # harmless fallback and is preferable to a permanent odds gap.
                pass
            card.click(timeout=3000)
            # Angular updates the selected event panel asynchronously. This is
            # Playwright's bounded browser wait, not a scheduler/thread sleep.
            with contextlib.suppress(Exception):
                page.wait_for_timeout(800)
            return True
        except Exception:
            continue
    return False


def _winline_fast_collect_from_payload(
    payload: Any,
    *,
    series: Any,
    map_num: int,
    team1: str,
    team2: str,
    expected_url: str,
) -> Optional[Dict[str, Any]]:
    """Parse one map from a shared full-page DOM snapshot."""
    card_ctx = globals().get("_bookmaker_winline_card_context")
    extract_fn = globals().get("_bookmaker_winline_extract")
    if not callable(card_ctx) or not callable(extract_fn):
        return None
    if not _winline_team_probe_tokens(team1) or not _winline_team_probe_tokens(team2):
        return None
    if not isinstance(payload, dict):
        return None
    html = str(payload.get("html") or "")
    current_url = str(payload.get("url") or "")
    if not html:
        return None
    if (
        expected_url
        and current_url
        and not _winline_urls_look_equivalent(current_url, expected_url)
    ):
        return None
    try:
        card = card_ctx("", team1, team2, html=html, map_num=map_num)
        extract = extract_fn(
            card or "",
            team1,
            team2,
            map_num,
            html=html,
            # Решающая карта серии: рынка карты у Winline может не быть вовсе,
            # тогда её победитель — это рынок «Матч» (промоция внутри парсера,
            # только по DOM и только при двухисходном рынке).
            series_last_map=_winline_registry_series_last_map(series),
        )
    except Exception:
        return None
    odds = list(getattr(extract, "odds", None) or [])
    if len(odds) < 2:
        # Отрицательный исход самый частый, и раньше он стоил полного разбора
        # (6-25 c). Короткозамыкаем его, но утверждать отсутствие позволяем только
        # по полной загруженной странице: сужение уже отработало по всему
        # документу теми же предохранителями, что и в полном разборе, поэтому
        # «рынка нет» здесь означает «ни у одного кандидата на странице строки
        # рынка нужной карты в границах его карточки нет», а не «мне дали узкий
        # кусок DOM».
        card_text = str(card or "")
        market_closed = bool(getattr(extract, "market_closed", False))
        page_low = html.lower()
        page_is_whole = len(html) >= WINLINE_FAST_MIN_PAGE_HTML and any(
            marker in page_low for marker in _WINLINE_PAGE_CHROME_MARKERS
        )
        if not page_is_whole:
            return None
        negative = _WinlineFastResult(
            odds=[],
            map_num=map_num,
            page_url=current_url or expected_url,
            # Карточки может не быть вовсе (матч не выставлен) — тогда evidence
            # всё равно обязан быть непустым, иначе преобразователь спишет это на
            # сбой браузера вместо честного отсутствия.
            details=card_text[:700] or f"winline_page_without_card:{len(html)}b",
            dom_signature=str(abs(hash(html)))[:32],
        )
        negative.market_closed = market_closed
        # Карточка найдена -> отсутствует РЫНОК; карточки нет -> матч не выставлен.
        negative.match_found = bool(card_text)
        # Почему не сработала подстановка рынка «Матч» на решающей карте. Быстрый
        # путь ходит в тот же парсер, поэтому объяснение обязано доезжать и здесь.
        negative.miss_fingerprint = str(
            getattr(extract, "miss_fingerprint", "") or "")[:200]
        negative.acquisition_mode = "dynamic_dom_fast"
        return _winline_map_site_result_to_collector_dict(
            negative,
            acquisition_mode="dynamic_dom_fast",
            series=series,
            map_num=map_num,
            team1=team1,
            team2=team2,
            expected_url=expected_url,
        )
    result = _WinlineFastResult(
        odds=odds[:2],
        map_num=map_num,
        page_url=current_url or expected_url,
        details=str(card or "")[:700],
        dom_signature=str(abs(hash(card or "")))[:32],
    )
    result.promoted_from_match = bool(getattr(extract, "promoted_from_match", False))
    result.card_team_order = getattr(extract, "card_team_order", None)
    result.card_odds = list(getattr(extract, "card_odds", None) or [])
    if result.promoted_from_match:
        # Держим в details объяснение парсера («рынка карты нет, взят Матч»):
        # без него в evidence не отличить промоцию от обычного рынка карты.
        promoted_details = str(getattr(extract, "details", "") or "")[:700]
        if promoted_details:
            result.details = promoted_details
            result.body_text = promoted_details
    # Числа распарсены, но принимает ли БК ставку — видно только по классам
    # кнопок исхода. Ошибку детектора глушим: он уточняет разбор, а не правит его.
    bettable_fn = globals().get("_bookmaker_winline_bettable")
    if callable(bettable_fn):
        try:
            result.odds_bettable = bettable_fn(html, team1, team2, map_num)
        except Exception:
            result.odds_bettable = None
    return _winline_map_site_result_to_collector_dict(
        result,
        acquisition_mode="dynamic_dom_fast",
        series=series,
        map_num=map_num,
        team1=team1,
        team2=team2,
        expected_url=expected_url,
    )


def _winline_map_site_result_to_collector_dict(
    result: Any,
    *,
    acquisition_mode: str,
    series: str,
    map_num: int,
    team1: str,
    team2: str,
    expected_url: Any = None,
) -> Dict[str, Any]:
    """Normalize bookmaker SiteResult into poller collector payload.

    Truth table (acquisition/classification seam):
    - expected loaded Winline page + correct URL + no load/acquisition error
      + nonblank body/DOM signature + match_found=False
      => page_valid=true, market_missing=true (eligible miss)
    - wrong URL OR blank body/signature OR acquisition/load error
      => page_valid=false (browser/acquisition failure), not eligible miss
    """
    odds = list(getattr(result, "odds", None) or [])
    p1 = None
    p2 = None
    try:
        if len(odds) >= 1 and odds[0] is not None:
            p1 = float(odds[0])
    except (TypeError, ValueError):
        p1 = None
    try:
        if len(odds) >= 2 and odds[1] is not None:
            p2 = float(odds[1])
    except (TypeError, ValueError):
        p2 = None
    market_closed = bool(getattr(result, "market_closed", False))
    # Заморозка: числа распарсились, но БК ставку не принимает. Для всех
    # потребителей это неторгуемый рынок, поэтому сводим к уже известному
    # 'closed' — вводить новый статус нельзя, поллер о нём не знает и
    # перестанет считать это допустимым промахом. Различие несёт odds_bettable.
    odds_bettable = getattr(result, "odds_bettable", None)
    if odds_bettable is False:
        market_closed = True
    status = str(getattr(result, "status", "") or "").strip().lower()
    match_found = getattr(result, "match_found", None)
    market_kind = str(getattr(result, "market_kind", "") or "")
    source = str(getattr(result, "source", None) or "Winline")
    if market_kind == "current_map_winner" or "current_map" in market_kind:
        source = "winline_current_map_winner"

    current_url = str(
        getattr(result, "page_url", None) or getattr(result, "url", None) or ""
    )
    dom_signature = str(getattr(result, "dom_signature", None) or "")[:128]
    body_text = str(
        getattr(result, "body_text", None)
        or getattr(result, "details", None)
        or ""
    )
    body_nonblank = bool(body_text.strip()) or bool(dom_signature.strip())
    acq_error = getattr(result, "acquisition_error", None)
    load_error = getattr(result, "load_error", None)
    err = getattr(result, "error", None) or load_error
    status_is_error = status in {"error", "request_error", "browser_error", "acquisition_error"}

    expected = expected_url
    if expected is None:
        expected = getattr(result, "expected_url", None)
    url_ok = True
    if expected:
        url_ok = _winline_urls_look_equivalent(current_url, expected)
    elif current_url:
        # Without explicit expected_url, reject blank/error page URLs only.
        low = current_url.strip().lower()
        if (not low) or low in {"about:blank", "about:error"} or low.startswith("chrome-error:"):
            url_ok = False

    # Playwright may time out waiting for the navigation lifecycle event even
    # though the requested match and its current-map market are already present
    # in the DOM.  A fully identified market is stronger evidence than that
    # lifecycle timeout: keep the error as diagnostics, but do not discard the
    # extracted result.  Team/map identity is established by the Winline parser
    # before it emits match_found=True and odds/closed.
    confirmed_market_payload = bool(
        body_nonblank
        and url_ok
        and match_found is True
        and (
            (p1 is not None and p2 is not None and not market_closed)
            or market_closed
        )
    )

    browser_failure = bool(
        status_is_error
        or (acq_error and not confirmed_market_payload)
        or (err and status_is_error)
        or (load_error and not body_nonblank)
        or (not url_ok)
        or (not body_nonblank and match_found is not True)
    )
    # Acquisition errors fail closed unless the same DOM pass produced a fully
    # identified current-map market.
    if acq_error and not confirmed_market_payload:
        browser_failure = True
    if status_is_error:
        browser_failure = True
    if not url_ok:
        browser_failure = True
    if match_found is False and not body_nonblank:
        browser_failure = True

    if status_is_error or browser_failure and (acq_error or status_is_error or not url_ok or not body_nonblank):
        # Distinguish market_status for browser failures vs eligible misses.
        if (acq_error and not confirmed_market_payload) or status_is_error or not url_ok or not body_nonblank:
            market_status = "error"
        elif market_closed:
            market_status = "closed"
        elif p1 is not None and p2 is not None and not market_closed:
            market_status = "open"
        else:
            market_status = "missing"
    elif market_closed:
        market_status = "closed"
    elif p1 is not None and p2 is not None and not market_closed:
        market_status = "open"
    elif match_found is False:
        market_status = "missing"
    else:
        market_status = "missing"

    market_missing = (
        (not browser_failure)
        and market_status in {"missing", "market_missing", "closed", "market_closed"}
        and not (p1 is not None and p2 is not None and not market_closed)
    )
    # Eligible loaded miss: valid page, no acquisition failure, market absent.
    page_valid = (not browser_failure) and body_nonblank and url_ok
    if match_found is False and page_valid:
        market_missing = True
        if market_status not in {"closed", "market_closed"}:
            market_status = "missing"

    acq_echo = getattr(result, "acquisition_mode", None) or acquisition_mode
    out = {
        "market_status": market_status,
        "market_missing": bool(market_missing),
        "source": source,
        "p1_odds": p1,
        "p2_odds": p2,
        # True/False — доказано по кнопкам исхода; None — определить не удалось.
        "odds_bettable": odds_bettable,
        "map_num": int(getattr(result, "map_num", None) or map_num),
        "team1": str(_winline_reported_team_name(getattr(result, "p1_team", None)) or team1),
        "team2": str(_winline_reported_team_name(getattr(result, "p2_team", None)) or team2),
        "series": series,
        "current_url": current_url,
        "dom_signature": dom_signature,
        "dom_hash": str(
            getattr(result, "dom_hash", None) or getattr(result, "dom_signature", None) or ""
        )[:128],
        "parser_failure_reasons": list(getattr(result, "parser_failure_reasons", None) or []),
        "error": err,
        "acquisition_error": acq_error,
        "page_valid": bool(page_valid),
        "acquisition_mode_echo": str(acq_echo or acquisition_mode),
        "match_found": match_found,
        # Решающая карта серии: у неё рынка карты может не быть, и кэфы берутся
        # из рынка «Матч». Держим обе метки в evidence — иначе по файлу не
        # отличить «промоция сработала» от «рынок карты был выставлен».
        # Признак промоции переживает конвертацию в SiteResult только в details,
        # поэтому читаем его оттуда (парсер пишет фиксированную формулировку).
        # Порядок и цены так, как их написал Winline: по ним одним видно, уехала
        # ли сторона, — `p1_odds/p2_odds` уже приведены к порядку запроса.
        # Отпечаток промаха: сколько блоков ленты дорисовано и кого из пары видно.
        "miss_fingerprint": str(getattr(result, "miss_fingerprint", None) or "")[:200] or None,
        "card_team_order": str(getattr(result, "card_team_order", None) or "")[:120] or None,
        "card_odds": [
            float(x) for x in (getattr(result, "card_odds", None) or [])[:2]
            if isinstance(x, (int, float))
        ] or None,
        "series_last_map": _winline_registry_series_last_map(series),
        "odds_promoted_from_match": bool(
            getattr(result, "promoted_from_match", False)
            or _WINLINE_PROMOTED_DETAILS_MARKER in body_text.lower()
        ),
    }
    return out


def _winline_current_map_poller_collect(
    *,
    acquisition_mode: str = "initial_goto",
    series: Any = None,
    map_num: Any = None,
    team1: Any = None,
    team2: Any = None,
    **_kwargs: Any,
) -> Dict[str, Any]:
    """Serial collector for the poller: shared Camoufox job + bookmaker:winline page.

    Never enables ordinary odds send. Failures map to poller browser/market statuses.
    """
    impl = globals().get("_winline_current_map_poller_collect_impl")
    if callable(impl):
        return impl(
            acquisition_mode=acquisition_mode,
            series=series,
            map_num=map_num,
            team1=team1,
            team2=team2,
            **_kwargs,
        )

    mode = str(acquisition_mode or "initial_goto").strip().lower() or "initial_goto"
    try:
        resolved_map = int(map_num)
    except (TypeError, ValueError):
        return {
            "market_status": "error",
            "page_valid": False,
            "error": "invalid_map_num",
            "acquisition_error": "invalid_map_num",
            "parser_failure_reasons": ["invalid_map_num"],
            "p1_odds": None,
            "p2_odds": None,
            "acquisition_mode_echo": mode,
        }
    t1 = str(team1 or "")
    t2 = str(team2 or "")
    series_s = str(series or "")

    if not BOOKMAKER_CAMOUFOX_IMPORTED or _bookmaker_parse_site_in_camoufox_page is None:
        return {
            "market_status": "error",
            "page_valid": False,
            "error": "camoufox_unavailable",
            "acquisition_error": "camoufox_unavailable",
            "parser_failure_reasons": ["camoufox_unavailable"],
            "p1_odds": None,
            "p2_odds": None,
            "acquisition_mode_echo": mode,
        }

    urls = _bookmaker_urls_for_mode("odds") or {}
    if "winline" not in urls:
        for mode_key in ("presence", "live", "odds"):
            urls = _bookmaker_urls_for_mode(mode_key) or {}
            if "winline" in urls:
                break
    if "winline" not in urls:
        return {
            "market_status": "error",
            "page_valid": False,
            "error": "winline_url_missing",
            "acquisition_error": "winline_url_missing",
            "parser_failure_reasons": ["winline_url_missing"],
            "p1_odds": None,
            "p2_odds": None,
            "acquisition_mode_echo": mode,
        }

    batch_context = globals().get("_winline_current_map_batch_context")
    if isinstance(batch_context, dict) and isinstance(batch_context.get("payload"), dict):
        batched = _winline_fast_collect_from_payload(
            batch_context["payload"],
            series=series_s,
            map_num=resolved_map,
            team1=t1,
            team2=t2,
            expected_url=urls["winline"],
        )
        if batched is not None:
            batched["acquisition_mode_echo"] = "shared_dom_batch"
            return batched

    def _job(browser):
        session = _shared_camoufox_session
        page = session.get_or_create_page("bookmaker:winline", browser)
        effective_mode = mode
        if mode == "controlled_reload":
            now_mono = time.monotonic()
            with _winline_current_map_state_lock:
                last_reload = _winline_shared_page_state.get("last_reload_monotonic")
            # All logical match pollers share this one physical page.  A reload
            # performed for one match refreshes every match card, so repeating
            # it for another poller within the same 60s window only blocks the
            # shared worker.
            if last_reload is not None and (now_mono - float(last_reload)) < 60.0:
                effective_mode = "dynamic_dom"

        if effective_mode in {"dynamic_dom", "initial_goto"}:
            # Страница уже на нужном URL — пробуем снять только карточку.
            # initial_goto is also eligible: after a prior timeout the named page
            # can still be healthy and already on the live URL.  Fast validation
            # avoids a 20-45s full parser recovery in that common case.
            fast = _winline_fast_collect(
                page,
                series=series_s,
                map_num=resolved_map,
                team1=t1,
                team2=t2,
                expected_url=urls["winline"],
            )
            if fast is not None:
                pinned_key = f"{series_s}|map{resolved_map}|{t1}|{t2}"
                should_select_pinned = bool(
                    fast.get("match_found") is True
                    and str(fast.get("market_status") or "").lower() == "missing"
                )
                if (
                    should_select_pinned
                    and _winline_select_matching_pinned_card(
                        page,
                        team1=t1,
                        team2=t2,
                    )
                ):
                    with _winline_current_map_state_lock:
                        _winline_shared_page_state["selected_pinned_page_id"] = id(page)
                        _winline_shared_page_state["selected_pinned_key"] = pinned_key
                    refreshed = _winline_fast_collect(
                        page,
                        series=series_s,
                        map_num=resolved_map,
                        team1=t1,
                        team2=t2,
                        expected_url=urls["winline"],
                    )
                    if refreshed is not None:
                        fast = refreshed
                if fast.get("page_valid") is True:
                    _bookmaker_restore_shared_camoufox_direct_route(
                        reason="winline_valid_page"
                    )
                fast["acquisition_mode_echo"] = effective_mode
                return fast
        result = _bookmaker_parse_site_in_camoufox_page(
            page,
            site="winline",
            url=urls["winline"],
            team1=t1,
            team2=t2,
            mode="odds",
            forced_map_num=resolved_map,
            acquisition_mode=effective_mode,
            series_last_map=_winline_registry_series_last_map(series_s),
        )
        if effective_mode == "controlled_reload":
            with _winline_current_map_state_lock:
                _winline_shared_page_state["last_reload_monotonic"] = time.monotonic()
        normalized = _winline_map_site_result_to_collector_dict(
            result,
            acquisition_mode=effective_mode,
            series=series_s,
            map_num=resolved_map,
            team1=t1,
            team2=t2,
            expected_url=urls.get("winline"),
        )
        if normalized.get("page_valid") is False and normalized.get("acquisition_error"):
            # A navigation timeout is not a market miss.  Do not keep polling a
            # stale named page forever.  Recovery is process-wide because all
            # match pollers share this page, and it is rate-limited: when only
            # one proxy is available, "rotation" selects the same address and
            # an immediate reset loop would starve every other match.
            now_mono = time.monotonic()
            should_recover = False
            with _winline_current_map_state_lock:
                streak = int(_winline_shared_page_state.get(
                    "acquisition_error_streak", 0)) + 1
                _winline_shared_page_state["acquisition_error_streak"] = streak
                last_recovery = _winline_shared_page_state.get(
                    "last_acquisition_recovery_monotonic"
                )
                # РАЗОВЫЙ СБОЙ НЕ СНОСИТ РАБОЧУЮ СТРАНИЦУ. Смена прокси
                # перезапускает браузер, а вместе с ним гибнет общая открытая
                # страница — та самая, ради которой опрос стоит 1-2 с при
                # `браузер 0.00c`. Дальше каждый опрос платит полную навигацию,
                # под нагрузкой не укладывается в
                # WINLINE_CURRENT_MAP_SHARED_JOB_TIMEOUT_S, это снова считается
                # ошибкой добычи — и петля затягивается сама.
                # Замер 20.08.2026: обычные опросы 1.09-2.39 с при нулевом
                # времени браузера, после первого сброса — 64.8, 131.6 и 85.4 с
                # при времени браузера 26.5, 36.0 и 12.7 с.
                # Кулдауна мало: он ограничивает частоту сбросов, но одиночную
                # задержку от голода процессора всё равно принимает за поломку
                # маршрута.
                if streak >= WINLINE_CURRENT_MAP_ERROR_STREAK_TO_ROTATE and (
                    last_recovery is None
                    or (now_mono - float(last_recovery))
                    >= WINLINE_CURRENT_MAP_RECOVERY_COOLDOWN_S
                ):
                    _winline_shared_page_state[
                        "last_acquisition_recovery_monotonic"
                    ] = now_mono
                    _winline_shared_page_state["acquisition_error_streak"] = 0
                    should_recover = True
            if should_recover:
                _bookmaker_rotate_shared_camoufox_proxy(
                    reason="winline_acquisition_error"
                )
        elif normalized.get("page_valid") is True:
            with _winline_current_map_state_lock:
                _winline_shared_page_state["acquisition_error_streak"] = 0
            _bookmaker_restore_shared_camoufox_direct_route(
                reason="winline_valid_page"
            )
        if isinstance(batch_context, dict) and batch_context.get("payload") is None:
            with contextlib.suppress(Exception):
                snapshot = page.evaluate(
                    _WINLINE_FAST_CARD_JS,
                    {"maxHtml": WINLINE_FAST_CARD_MAX_HTML},
                )
                if isinstance(snapshot, dict):
                    batch_context["payload"] = snapshot
        return normalized

    try:
        return _run_shared_camoufox_job(
            f"winline_current_map_poll:{series_s}|map{resolved_map}",
            _job,
            timeout=WINLINE_CURRENT_MAP_SHARED_JOB_TIMEOUT_S,
            # A timed-out callback keeps occupying the single shared worker.
            # Retrying immediately queues a duplicate behind it and doubles the
            # outage for every other active match.
            retry=False,
            reset_on_error=True,
        )
    except Exception as exc:
        return {
            "market_status": "error",
            "page_valid": False,
            "error": f"shared_camoufox_job:{type(exc).__name__}",
            "acquisition_error": f"shared_camoufox_job:{type(exc).__name__}",
            "parser_failure_reasons": ["browser_acquisition_failure"],
            "p1_odds": None,
            "p2_odds": None,
            "acquisition_mode_echo": mode,
            "dom_signature": "",
            "dom_hash": "",
            "source": "winline",
        }


def _winline_scheduler_sleep(seconds: float, *, stop_event: Optional[threading.Event] = None) -> None:
    """Interruptible short sleep used only by the dedicated scheduler thread."""
    ev = stop_event if stop_event is not None else _winline_current_map_scheduler_stop
    try:
        delay = max(0.0, float(seconds))
    except (TypeError, ValueError):
        delay = 0.0
    if delay <= 0:
        return
    # Event.wait is the only wait path; tests never call this (fake-clock drive seam).
    ev.wait(timeout=delay)


def _winline_current_map_scheduler_loop() -> None:
    """Process-local due checker independent of blocking general()."""
    meta = _winline_current_map_scheduler_meta
    while not _winline_current_map_scheduler_stop.is_set():
        interval = float(meta.get("interval_s") or WINLINE_CURRENT_MAP_SCHEDULER_INTERVAL_S)
        _winline_scheduler_sleep(interval)
        if _winline_current_map_scheduler_stop.is_set():
            break
        try:
            mono = meta.get("monotonic_fn")
            wall = meta.get("wall_fn")
            tick_kwargs: Dict[str, Any] = {}
            if callable(mono):
                tick_kwargs["monotonic_fn"] = mono
            if callable(wall):
                tick_kwargs["wall_fn"] = wall
            pid = meta.get("producer_pid")
            gen = meta.get("producer_start_generation")
            if pid is not None:
                tick_kwargs["producer_pid"] = pid
            if gen is not None:
                tick_kwargs["producer_start_generation"] = gen
            tick_winline_current_map_polling(_scheduler_tick=True, **tick_kwargs)
            with _winline_current_map_state_lock:
                meta["tick_count"] = int(meta.get("tick_count") or 0) + 1
                meta["last_error"] = None
        except Exception as exc:
            with _winline_current_map_state_lock:
                meta["last_error"] = f"{type(exc).__name__}:{exc}"
            try:
                logger.warning("winline current-map scheduler tick failed: %s", exc)
            except Exception:
                pass


def start_winline_current_map_polling_scheduler(
    *,
    interval_s: Any = None,
    producer_pid: Any = None,
    producer_start_generation: Any = None,
    monotonic_fn: Any = None,
    wall_fn: Any = None,
    force_restart: bool = False,
) -> bool:
    """Start process-local dedicated scheduler thread for 5s current-map polls.

    Due checks are independent of main-loop general() completion. Camoufox work
    still goes only through tick -> collector -> _run_shared_camoufox_job.
    Fail-closed: exceptions are logged; never opens a second browser / send path.
    """
    global _winline_current_map_scheduler_thread
    try:
        with _winline_current_map_state_lock:
            thr = _winline_current_map_scheduler_thread
            if thr is not None and thr.is_alive() and not force_restart:
                # Update live metadata only.
                if producer_pid is not None:
                    _winline_current_map_scheduler_meta["producer_pid"] = int(producer_pid)
                if producer_start_generation is not None:
                    _winline_current_map_scheduler_meta["producer_start_generation"] = str(
                        producer_start_generation
                    )
                if callable(monotonic_fn):
                    _winline_current_map_scheduler_meta["monotonic_fn"] = monotonic_fn
                if callable(wall_fn):
                    _winline_current_map_scheduler_meta["wall_fn"] = wall_fn
                if interval_s is not None:
                    _winline_current_map_scheduler_meta["interval_s"] = max(0.05, float(interval_s))
                _winline_current_map_scheduler_meta["started"] = True
                return True
        if thr is not None and thr.is_alive() and force_restart:
            stop_winline_current_map_polling_scheduler(join_timeout_s=1.0)
        _winline_current_map_scheduler_stop.clear()
        with _winline_current_map_state_lock:
            _winline_current_map_scheduler_meta["interval_s"] = max(
                0.05,
                float(
                    interval_s
                    if interval_s is not None
                    else _winline_current_map_scheduler_meta.get("interval_s")
                    or WINLINE_CURRENT_MAP_SCHEDULER_INTERVAL_S
                ),
            )
            _winline_current_map_scheduler_meta["nominal_poll_s"] = float(
                WINLINE_CURRENT_MAP_SCHEDULER_NOMINAL_S
            )
            if producer_pid is not None:
                _winline_current_map_scheduler_meta["producer_pid"] = int(producer_pid)
            elif _winline_current_map_scheduler_meta.get("producer_pid") is None:
                _winline_current_map_scheduler_meta["producer_pid"] = int(os.getpid())
            if producer_start_generation is not None:
                _winline_current_map_scheduler_meta["producer_start_generation"] = str(
                    producer_start_generation
                )
            if callable(monotonic_fn):
                _winline_current_map_scheduler_meta["monotonic_fn"] = monotonic_fn
            if callable(wall_fn):
                _winline_current_map_scheduler_meta["wall_fn"] = wall_fn
            _winline_current_map_scheduler_meta["started"] = True
            _winline_current_map_scheduler_meta["last_error"] = None
        thread = threading.Thread(
            target=_winline_current_map_scheduler_loop,
            name="winline-current-map-scheduler",
            daemon=True,
        )
        with _winline_current_map_state_lock:
            _winline_current_map_scheduler_thread = thread
        thread.start()
        return True
    except Exception as exc:
        with _winline_current_map_state_lock:
            _winline_current_map_scheduler_meta["last_error"] = f"{type(exc).__name__}:{exc}"
            _winline_current_map_scheduler_meta["started"] = False
        try:
            logger.warning("start_winline_current_map_polling_scheduler failed: %s", exc)
        except Exception:
            pass
        return False


def stop_winline_current_map_polling_scheduler(*, join_timeout_s: float = 1.0) -> None:
    """Stop dedicated scheduler thread (idempotent, thread-safe)."""
    global _winline_current_map_scheduler_thread
    _winline_current_map_scheduler_stop.set()
    thr = None
    with _winline_current_map_state_lock:
        thr = _winline_current_map_scheduler_thread
        _winline_current_map_scheduler_meta["started"] = False
    if thr is not None and thr is not threading.current_thread():
        try:
            thr.join(timeout=max(0.0, float(join_timeout_s)))
        except Exception:
            pass
    with _winline_current_map_state_lock:
        if _winline_current_map_scheduler_thread is thr:
            _winline_current_map_scheduler_thread = None


def drive_winline_current_map_polling_scheduler_for_tests(
    *,
    duration_s: float = 30.0,
    step_s: float = 1.0,
    monotonic_fn: Any = None,
    wall_fn: Any = None,
    advance_fn: Any = None,
    producer_pid: Any = None,
    producer_start_generation: Any = None,
) -> Dict[str, Any]:
    """Deterministic fake-clock driver for the scheduler due path (no real sleep).

    Advances the injected clock by step_s and invokes tick_winline_current_map_polling
    each step, simulating the dedicated scheduler loop while general() is blocked.
    Never starts a real thread and never touches send/bet paths.
    """
    try:
        duration = float(duration_s)
        step = float(step_s)
    except (TypeError, ValueError):
        return {
            "ok": False,
            "error": "invalid_duration_or_step",
            "scheduler_driven": True,
            "main_loop_tick_invocations": 0,
            "starts_observed": 0,
        }
    if step <= 0:
        step = 1.0
    mono = monotonic_fn if callable(monotonic_fn) else time.monotonic
    wall = wall_fn if callable(wall_fn) else time.time
    with _winline_current_map_state_lock:
        _winline_current_map_scheduler_meta["monotonic_fn"] = mono
        _winline_current_map_scheduler_meta["wall_fn"] = wall
        if producer_pid is not None:
            _winline_current_map_scheduler_meta["producer_pid"] = int(producer_pid)
        if producer_start_generation is not None:
            _winline_current_map_scheduler_meta["producer_start_generation"] = str(
                producer_start_generation
            )
        _winline_current_map_scheduler_meta["main_loop_tick_invocations"] = 0
        tick_before = int(_winline_current_map_scheduler_meta.get("tick_count") or 0)

    elapsed = 0.0
    steps = 0
    tick_results: List[Any] = []
    # Inclusive cover of duration window: 0..duration inclusive if aligned.
    target_steps = int(max(1, round(duration / step))) + 1
    while steps < target_steps and elapsed <= duration + 1e-9:
        try:
            out = tick_winline_current_map_polling(
                monotonic_fn=mono,
                wall_fn=wall,
                producer_pid=producer_pid,
                producer_start_generation=producer_start_generation,
            )
            tick_results.append(out)
            with _winline_current_map_state_lock:
                _winline_current_map_scheduler_meta["tick_count"] = (
                    int(_winline_current_map_scheduler_meta.get("tick_count") or 0) + 1
                )
                _winline_current_map_scheduler_meta["last_error"] = None
        except Exception as exc:
            with _winline_current_map_state_lock:
                _winline_current_map_scheduler_meta["last_error"] = f"{type(exc).__name__}:{exc}"
            tick_results.append({"status": "error", "error": f"{type(exc).__name__}:{exc}"})
        steps += 1
        if steps >= target_steps or elapsed + step > duration + 1e-9:
            break
        if callable(advance_fn):
            advance_fn(step)
        elapsed += step

    with _winline_current_map_state_lock:
        tick_after = int(_winline_current_map_scheduler_meta.get("tick_count") or 0)
        main_inv = int(_winline_current_map_scheduler_meta.get("main_loop_tick_invocations") or 0)
        last_err = _winline_current_map_scheduler_meta.get("last_error")
    return {
        "ok": last_err is None,
        "scheduler_driven": True,
        "main_loop_tick_invocations": main_inv,
        "steps": steps,
        "duration_s": duration,
        "step_s": step,
        "tick_count_delta": tick_after - tick_before,
        "last_error": last_err,
        "results_tail": tick_results[-3:],
    }



def ensure_winline_current_map_polling(
    *,
    series: Any,
    map_num: Any,
    team1: Any,
    team2: Any,
    selected_side: Any = None,
    producer_pid: Any = None,
    producer_start_generation: Any = None,
    monotonic_fn: Any = None,
    wall_fn: Any = None,
    collector: Any = None,
    is_map_current: Any = None,
    evidence_path: Any = None,
    series_last_map: Any = None,
    match_id: Any = None,
    update_registry: bool = True,
    **poller_kwargs: Any,
) -> Any:
    """Create/update exactly one poller for the exact canonical current map.

    Independent of STAR and of absent/empty selected_side. Never enables odds send.
    Fail-open: never raises into the parse seam.
    """
    try:
        series_s = str(series or "").strip()
        # Prefer stable series identity when match_key-like URL arrives.
        try:
            stable = _bookmaker_series_identity(series_s)
            if stable:
                series_s = stable
        except Exception:
            pass
        try:
            map_i = int(map_num)
        except (TypeError, ValueError):
            return False
        t1 = str(team1 or "").strip()
        t2 = str(team2 or "").strip()
        if not series_s or not (1 <= map_i <= 5):
            return False

        # Register as the latest current map for this series (rollover stop for older).
        # Опрос карты, которую мост ещё не подтвердил, реестр НЕ трогает: реестр
        # описывает карту, идущую на самом деле, и запись туда несыгранной карты
        # выглядела бы для опроса текущей как смена карты (`map_rollover`).
        if update_registry:
            with _winline_current_map_state_lock:
                _winline_current_map_registry[series_s] = {
                    "map_num": map_i,
                    "team1": t1,
                    "team2": t2,
                    "active": True,
                    "inactive_reason": None,
                    "inactive_proven": False,
                    "inactive_since": None,
                    # Решающая карта: разрешает промоцию рынка «Матч» в рынок карты.
                    "series_last_map": bool(series_last_map),
                }

        pid = int(producer_pid) if producer_pid is not None else int(os.getpid())
        gen = (
            str(producer_start_generation)
            if producer_start_generation is not None
            else str(_winline_current_map_service_gen.get("gen") or "")
        )
        if not gen:
            # Stable process-lifetime generation (not wall clock — restart-stable within run).
            gen = str(_winline_current_map_service_gen.get("gen") or f"pid-{pid}")
            _winline_current_map_service_gen["gen"] = gen
        _winline_current_map_service_gen["pid"] = pid

        mod = _load_winline_current_map_poller_module()
        make_key = getattr(mod, "make_canonical_map_key", None) or getattr(
            mod, "canonical_map_key", None
        )
        factory = getattr(mod, "WinlineCurrentMapOddsPoller", None) or getattr(
            mod, "CurrentMapOddsPoller", None
        )
        if factory is None or make_key is None:
            return False
        canonical = make_key(series_s, map_i, t1, t2)

        # Propagate generation to existing pollers first (stale gen terminals).
        note_winline_current_map_service_generation(
            producer_pid=pid,
            producer_start_generation=gen,
        )

        with _winline_current_map_state_lock:
            existing = _winline_current_map_pollers.get(canonical)
            if existing is None:
                # Тот же слот карты, но команды пришли в другом порядке — это
                # смена сторон внутри серии, а не новая карта. Опрос усыновляем
                # вместе с накопленным состоянием чата: иначе в реестре повиснут
                # два поллера одной карты, старый закроется как «карта
                # завершена», а новый начнёт с «🆕» (24.08.2026, RE ARISE —
                # Team Lynx, карта 2 под двумя ключами).
                existing = _winline_adopt_transposed_poller(
                    canonical, series_s, map_i, t1, t2)
        if existing is not None and getattr(existing, "is_active", lambda: False)():
            # Same exact identity still active — keep; selected_side non-gating.
            # Такт при этом обновляем: опрос ожидаемой карты идёт редко, и когда
            # карта наконец пришла в мост, он обязан вернуться к обычной частоте,
            # иначе движение линии на живой карте читалось бы раз в минуту.
            _winline_apply_poll_interval(existing, poller_kwargs.get("poll_interval_seconds"))
            if evidence_path is not None:
                try:
                    existing._evidence_path = Path(evidence_path)  # type: ignore[attr-defined]
                    existing._evidence_is_custom = True  # type: ignore[attr-defined]
                except Exception:
                    pass
            # Keep scheduler alive for active map.
            try:
                start_winline_current_map_polling_scheduler(
                    producer_pid=pid,
                    producer_start_generation=gen,
                    monotonic_fn=monotonic_fn if callable(monotonic_fn) else None,
                    wall_fn=wall_fn if callable(wall_fn) else None,
                )
            except Exception:
                pass
            return existing

        collect_fn = collector if callable(collector) else _winline_current_map_poller_collect
        pred = is_map_current if callable(is_map_current) else _winline_current_map_is_current
        mono = monotonic_fn if callable(monotonic_fn) else time.monotonic
        wall = wall_fn if callable(wall_fn) else time.time

        # Drop terminal/stale slot for this key before recreate.
        if existing is not None:
            _winline_current_map_pollers.pop(canonical, None)

        kwargs = dict(poller_kwargs or {})
        if _winline_continuous_enabled():
            kwargs.setdefault("continuous", True)
        poller = factory(
            collector=collect_fn,
            is_map_current=pred,
            monotonic_fn=mono,
            wall_fn=wall,
            producer_pid=pid,
            producer_start_generation=gen,
            selected_side=selected_side,
            **kwargs,
        )
        started = poller.begin(series=series_s, map_num=map_i, team1=t1, team2=t2,
                               match_id=match_id)
        if not started and not getattr(poller, "is_active", lambda: False)():
            return False
        try:
            poller._evidence_path = Path(  # type: ignore[attr-defined]
                evidence_path
                if evidence_path is not None
                else _winline_evidence_path_for_key(canonical)
            )
            poller._evidence_is_custom = evidence_path is not None  # type: ignore[attr-defined]
            poller._winline_batch_eligible = (  # type: ignore[attr-defined]
                collect_fn is _winline_current_map_poller_collect
            )
        except Exception:
            pass
        with _winline_current_map_state_lock:
            _winline_current_map_pollers[canonical] = poller

        # Ensure independent 5s scheduler is running (idempotent).
        try:
            start_winline_current_map_polling_scheduler(
                producer_pid=pid,
                producer_start_generation=gen,
                monotonic_fn=mono,
                wall_fn=wall,
            )
        except Exception:
            pass

        return poller
    except Exception as exc:
        try:
            logger.warning("ensure_winline_current_map_polling failed: %s", exc)
        except Exception:
            pass
        return False


# --- Winline current-map odds -> Telegram ------------------------------------
# Отдельным сообщением в АДМИН-чат и только при ИЗМЕНЕНИИ пары кэфов: при опросе
# раз в 5 с отправка каждого парса дала бы ~720 сообщений в час на матч, что
# упирается в лимит Telegram (~20/мин) и грозит flood-баном боевых сигналов.
WINLINE_ODDS_TELEGRAM_ENABLED_ENV = "WINLINE_ODDS_TELEGRAM_ENABLED"
WINLINE_ODDS_TELEGRAM_MIN_SPACING_ENV = "WINLINE_ODDS_TELEGRAM_MIN_SPACING_S"
WINLINE_ODDS_TELEGRAM_MAX_PER_MIN_ENV = "WINLINE_ODDS_TELEGRAM_MAX_PER_MIN"
WINLINE_CURRENT_MAP_CONTINUOUS_ENV = "WINLINE_CURRENT_MAP_CONTINUOUS"

_winline_odds_notify_state: Dict[str, Dict[str, Any]] = {}

_TRUE_ENV_VALUES = {"1", "true", "yes", "on"}


def _winline_env_flag(name: str) -> bool:
    return str(os.getenv(name, "") or "").strip().lower() in _TRUE_ENV_VALUES


def _winline_env_float(name: str, default: float) -> float:
    raw = os.getenv(name)
    if raw is None or str(raw).strip() == "":
        return float(default)
    try:
        return float(str(raw).strip())
    except (TypeError, ValueError):
        return float(default)


def _winline_odds_notify_enabled() -> bool:
    return _winline_env_flag(WINLINE_ODDS_TELEGRAM_ENABLED_ENV)


def _winline_continuous_enabled() -> bool:
    return _winline_env_flag(WINLINE_CURRENT_MAP_CONTINUOUS_ENV)


def _winline_parse_canonical_key(key: Any) -> Tuple[Optional[int], str, str]:
    """'<series>|map<N>|<team1>|<team2>' -> (map_num, team1, team2)."""
    # SourceTV series identities contain their own ``|``-separated team IDs.
    # Split from the right so those opaque series segments cannot displace the
    # map token and the two display names.
    parts = str(key or "").rsplit("|", 3)
    if len(parts) < 4:
        return None, "", ""
    token = parts[1].strip().lower()
    map_num: Optional[int] = None
    if token.startswith("map"):
        try:
            map_num = int(token[3:])
        except (TypeError, ValueError):
            map_num = None
    return map_num, parts[2].strip(), parts[3].strip()


def _winline_fmt_odd(value: Any) -> str:
    try:
        return f"{float(value):.2f}"
    except (TypeError, ValueError):
        return "—"


def _winline_odd_arrow(prev: Any, cur: Any) -> str:
    try:
        prev_f, cur_f = float(prev), float(cur)
    except (TypeError, ValueError):
        return ""
    if cur_f > prev_f:
        return " ↑"
    if cur_f < prev_f:
        return " ↓"
    return ""


def _winline_odds_side(prev: Any, cur: Any) -> str:
    """'1.18 → 1.21 ↑' или просто '1.21', если предыдущего значения нет."""
    if prev is None:
        return _winline_fmt_odd(cur)
    return f"{_winline_fmt_odd(prev)} → {_winline_fmt_odd(cur)}{_winline_odd_arrow(prev, cur)}"


def _winline_relative_odds_delta(value: float, reference: float) -> float:
    return abs(float(value) - float(reference)) / max(abs(float(reference)), 1e-9)


def _winline_odds_pair_looks_transposed(
    prev_p1: Any,
    prev_p2: Any,
    p1: Any,
    p2: Any,
) -> bool:
    """Detect a parser-side P1/P2 permutation, not a normal price movement."""
    try:
        old1, old2 = float(prev_p1), float(prev_p2)
        cur1, cur2 = float(p1), float(p2)
    except (TypeError, ValueError):
        return False
    if not all(math.isfinite(value) and value > 1.0 for value in (old1, old2, cur1, cur2)):
        return False
    # Near-even markets are too ambiguous for temporal orientation recovery.
    if max(old1, old2) / min(old1, old2) < 1.35:
        return False
    cross1 = _winline_relative_odds_delta(cur1, old2)
    cross2 = _winline_relative_odds_delta(cur2, old1)
    direct = (
        _winline_relative_odds_delta(cur1, old1)
        + _winline_relative_odds_delta(cur2, old2)
    )
    cross = cross1 + cross2
    return (
        cross1 <= 0.03
        and cross2 <= 0.03
        and direct >= 0.50
        and direct >= (cross * 5.0) + 0.25
    )


def _winline_stabilize_odds_orientation(
    payload: Any,
    canonical_key: Any,
) -> Any:
    """Keep P1/P2 bound to canonical teams across transient DOM-order flips."""
    if not isinstance(payload, dict):
        return payload
    key = str(canonical_key or "")
    if not key:
        return payload
    status = str(payload.get("market_status") or "").strip().lower()
    if (
        payload.get("page_valid") is False
        or status not in {"open", "ok", "available"}
        or payload.get("p1_odds") is None
        or payload.get("p2_odds") is None
    ):
        return payload
    try:
        p1 = float(payload["p1_odds"])
        p2 = float(payload["p2_odds"])
    except (TypeError, ValueError):
        return payload
    if not all(math.isfinite(value) and value > 1.0 for value in (p1, p2)):
        return payload

    with _winline_current_map_state_lock:
        previous = dict(_winline_odds_orientation_state.get(key) or {})
        if previous and _winline_odds_pair_looks_transposed(
            previous.get("p1"),
            previous.get("p2"),
            p1,
            p2,
        ):
            payload["p1_odds"], payload["p2_odds"] = p2, p1
            payload["odds_orientation_correction"] = "temporal_pair_transposition"
            p1, p2 = p2, p1
        _winline_odds_orientation_state[key] = {"p1": p1, "p2": p2}
    return payload


def _winline_build_odds_message(
    *,
    kind: str,
    map_num: Optional[int],
    team1: str,
    team2: str,
    p1: Any,
    p2: Any,
    prev_p1: Any,
    prev_p2: Any,
    stamp: str,
) -> str:
    head = {
        "first": "🆕 Winline",
        "change": "📊 Winline",
        "closed": "🔒 Winline",
        "terminal": "🏁 Winline",
        "stopped": "⏹️ Winline",
    }.get(kind, "📊 Winline")
    map_label = f" · карта {map_num}" if map_num else ""
    lines = [f"{head}{map_label}", f"{team1} — {team2}"]
    if kind == "closed":
        lines.append("рынок закрыт")
    elif kind == "terminal":
        lines.append("карта завершена")
    elif kind == "stopped":
        # Опрос кончился не потому, что кончилась карта: потолок безопасности или
        # молчащий источник. Писать «карта завершена» тут значит врать в чат.
        lines.append("опрос остановлен, конец карты не подтверждён")
    else:
        lines.append(
            f"{_winline_odds_side(prev_p1, p1)}   |   {_winline_odds_side(prev_p2, p2)}"
        )
    lines.append(f"🕐 {stamp}")
    return "\n".join(lines)


def _winline_odds_telegram_notify(
    payload: Any,
    canonical_key: Any,
    *,
    is_terminal: bool = False,
    map_end_proven: bool = True,
    send_fn: Any = None,
    monotonic_fn: Any = None,
    stamp_fn: Any = None,
) -> Optional[str]:
    """Сообщить в админ-чат об изменении кэфов текущей карты. Fail-open.

    Возвращает отправленный текст или None. Состояние обновляется ТОЛЬКО при
    фактической отправке — поэтому подавленное троттлингом изменение не теряется:
    следующее разрешённое сообщение покажет свежие кэфы относительно последнего
    отправленного, а не относительно пропущенного промежуточного.
    """
    if not _winline_odds_notify_enabled():
        return None
    if not isinstance(payload, dict):
        return None

    key = str(canonical_key or "")
    if not key:
        return None
    payload = _winline_stabilize_odds_orientation(payload, key)

    # Замороженный рынок: число на странице есть, но принять ставку по нему
    # нельзя. Молчим — состояние не трогаем, поэтому после разморозки первое же
    # сообщение покажет изменение относительно последнего ОТПРАВЛЕННОГО кэфа.
    if payload.get("odds_bettable") is False:
        return None

    mono = (monotonic_fn or time.monotonic)()
    p1 = payload.get("p1_odds")
    p2 = payload.get("p2_odds")
    status = str(payload.get("market_status") or "").strip().lower()
    has_odds = p1 is not None and p2 is not None

    with _winline_current_map_state_lock:
        prev = dict(_winline_odds_notify_state.get(key) or {})

    if is_terminal:
        if not prev:
            # По этой карте мы не отправили ни одной строки: рынка не было ни
            # разу. «Карта завершена» тогда объявляет конец тому, чего чат не
            # видел, а при опросе ещё не начавшейся карты — конец тому, чего не
            # было вовсе (23.08.2026, «Winline · карта 3» в серии
            # Team Spirit — Team Yandex: третьей карты не существовало).
            return None
        # Терминал без доказанного конца карты (потолок 90 минут, молчащий фид)
        # объявляем остановкой опроса, а не финишем карты.
        kind = "terminal" if map_end_proven else "stopped"
    elif status in {"closed", "suspended"}:
        kind = "closed"
    elif not has_odds:
        return None
    elif not prev:
        kind = "first"
    elif prev.get("p1") == p1 and prev.get("p2") == p2 and prev.get("status") == status:
        return None
    else:
        kind = "change"

    # Не повторяем один и тот же служебный статус подряд.
    if kind in {"closed", "terminal", "stopped"} and prev.get("kind") == kind:
        return None

    # Финальные события карты — одноразовые: троттлинг потока цен их не глушит.
    lifecycle_kind = kind in {"terminal", "stopped"}
    min_spacing = _winline_env_float(WINLINE_ODDS_TELEGRAM_MIN_SPACING_ENV, 3.0)
    max_per_min = _winline_env_float(WINLINE_ODDS_TELEGRAM_MAX_PER_MIN_ENV, 12.0)
    last_sent = prev.get("last_sent_mono")
    if not lifecycle_kind and last_sent is not None and (mono - float(last_sent)) < min_spacing:
        return None
    recent = [t for t in (prev.get("sent_mono") or []) if mono - float(t) < 60.0]
    if not lifecycle_kind and max_per_min > 0 and len(recent) >= max_per_min:
        return None

    map_num, team1, team2 = _winline_parse_canonical_key(key)
    stamp = (stamp_fn or (lambda: datetime.now().strftime("%H:%M:%S")))()
    message = _winline_build_odds_message(
        kind=kind,
        map_num=map_num,
        team1=team1,
        team2=team2,
        p1=p1,
        p2=p2,
        prev_p1=prev.get("p1"),
        prev_p2=prev.get("p2"),
        stamp=stamp,
    )

    # Кэфы Winline уходят в ОТДЕЛЬНЫЙ бот (keys.WinlineToken), ставки остаются
    # в основном. Токен разный, чат тот же (админ).
    sender = send_fn or send_winline_odds_message
    try:
        # Кэфы — служебный поток: шлём без звука, чтобы не глушить пуши ставок.
        delivered = sender(
            message,
            admin_only=True,
            mirror_to_vk=False,
            silent=True,
        )
        if delivered is False:
            logger.warning("winline odds telegram notify returned delivered=false")
            return None
    except Exception as exc:
        try:
            logger.warning("winline odds telegram notify failed: %s", exc)
        except Exception:
            pass
        return None

    with _winline_current_map_state_lock:
        _winline_odds_notify_state[key] = {
            "p1": p1,
            "p2": p2,
            "status": status,
            "kind": kind,
            "last_sent_mono": mono,
            "sent_mono": recent + [mono],
        }
    return message


def _tick_winline_current_map_polling_impl(
    *,
    monotonic_fn: Any = None,
    wall_fn: Any = None,
    producer_pid: Any = None,
    producer_start_generation: Any = None,
    **_extra: Any,
) -> List[Dict[str, Any]]:
    """Drive all active pollers once (no sleep). Safe to call every main-loop cycle."""
    results: List[Dict[str, Any]] = []
    # Telegram-отправка блокирующая (до TELEGRAM_SEND_TIMEOUT_SECONDS). На backup-тике
    # из главного цикла её не делаем: пусть уведомляет выделенный поток-шедулер,
    # чтобы никакая сетевая задержка не удлиняла цикл отправки ставок.
    from_main_loop = bool(_extra.get("from_main_loop"))
    try:
        if from_main_loop:
            with _winline_current_map_state_lock:
                _winline_current_map_scheduler_meta["main_loop_tick_invocations"] = (
                    int(_winline_current_map_scheduler_meta.get("main_loop_tick_invocations") or 0)
                    + 1
                )
        if producer_pid is not None or producer_start_generation is not None:
            note_winline_current_map_service_generation(
                producer_pid=producer_pid,
                producer_start_generation=producer_start_generation,
            )
        pid = (
            int(producer_pid)
            if producer_pid is not None
            else int(_winline_current_map_service_gen.get("pid") or 0)
        )
        gen = (
            str(producer_start_generation)
            if producer_start_generation is not None
            else str(_winline_current_map_service_gen.get("gen") or "")
        )
        dead_keys: List[str] = []
        for key, poller in list(_winline_current_map_pollers.items()):
            try:
                out = poller.tick(
                    producer_pid=pid or None,
                    producer_start_generation=gen or None,
                )
            except Exception as exc:
                out = {"status": "error", "error": f"{type(exc).__name__}:{exc}", "canonical_key": key}
            if out is not None:
                if isinstance(out, dict):
                    out.setdefault("canonical_key", key)
                results.append(out if isinstance(out, dict) else {"status": "ok", "raw": out, "canonical_key": key})
                # Evidence: attempt or terminal payload.
                try:
                    attempt = out.get("attempt") if isinstance(out, dict) else None
                    terminal = out.get("terminal") if isinstance(out, dict) else None
                    payload = terminal or attempt or (out if isinstance(out, dict) else None)
                    if isinstance(payload, dict):
                        payload = _winline_stabilize_odds_orientation(payload, key)
                        epath = getattr(poller, "_evidence_path", None)
                        _winline_write_current_map_evidence(payload, path=epath)
                        if not bool(getattr(poller, "_evidence_is_custom", False)):
                            _winline_write_current_map_evidence(
                                payload,
                                path=WINLINE_CURRENT_MAP_POLLING_EVIDENCE_PATH,
                            )
                except Exception:
                    pass
                try:
                    notify_payload = attempt if isinstance(attempt, dict) else None
                    if notify_payload is None and isinstance(terminal, dict):
                        notify_payload = terminal
                    lifecycle_terminal = (
                        terminal
                        if isinstance(terminal, dict) and not isinstance(attempt, dict)
                        else None
                    )
                    if isinstance(notify_payload, dict) and not from_main_loop:
                        _winline_odds_telegram_notify(
                            notify_payload,
                            key,
                            is_terminal=lifecycle_terminal is not None,
                            # «Карта завершена» — только когда конец карты доказан
                            # поллером; иначе это остановка опроса.
                            map_end_proven=bool(
                                lifecycle_terminal
                                and lifecycle_terminal.get("map_end_proven")
                            ),
                        )
                except Exception:
                    pass
            try:
                if not getattr(poller, "is_active", lambda: True)():
                    # Keep terminal briefly; prune fully inactive after terminal recorded.
                    term = getattr(poller, "terminal", lambda: None)()
                    if term is not None or out is None:
                        # leave terminal entries; prune only if tick returned None and inactive
                        if not getattr(poller, "is_active", lambda: False)() and term is not None:
                            dead_keys.append(key)
            except Exception:
                pass
        if dead_keys:
            with _winline_current_map_state_lock:
                for key in dead_keys:
                    _winline_current_map_pollers.pop(key, None)
        return results
    except Exception as exc:
        try:
            logger.warning("tick_winline_current_map_polling failed: %s", exc)
        except Exception:
            pass
        return results


def tick_winline_current_map_polling(
    *,
    monotonic_fn: Any = None,
    wall_fn: Any = None,
    producer_pid: Any = None,
    producer_start_generation: Any = None,
    **extra: Any,
) -> List[Dict[str, Any]]:
    """Run one serialized scheduler tick with one reusable DOM snapshot."""
    global _winline_current_map_batch_context
    background_tick = bool(extra.get("from_main_loop") or extra.pop("_scheduler_tick", False))
    # Keep the exact acquired instance. Some integration tests reload modules
    # while a daemon scheduler is winding down; resolving the global again in
    # finally could otherwise release a newly-created, unlocked lock.
    tick_lock = _winline_current_map_tick_lock
    if not tick_lock.acquire(blocking=not background_tick):
        return []
    try:
        with _winline_current_map_state_lock:
            production_active = sum(
                1
                for poller in _winline_current_map_pollers.values()
                if getattr(poller, "is_active", lambda: False)()
                and bool(getattr(poller, "_winline_batch_eligible", False))
            )
        _winline_current_map_batch_context = (
            {"payload": None} if production_active >= 2 else None
        )
        return _tick_winline_current_map_polling_impl(
            monotonic_fn=monotonic_fn,
            wall_fn=wall_fn,
            producer_pid=producer_pid,
            producer_start_generation=producer_start_generation,
            **extra,
        )
    finally:
        _winline_current_map_batch_context = None
        tick_lock.release()


def accelerate_winline_current_map_polling(match_key: str) -> bool:
    """Set accelerated mode on active poller(s) matching match_key. Idempotent, fail-open."""
    try:
        series_s = str(match_key or "").strip()
        try:
            stable = _bookmaker_series_identity(series_s)
            if stable:
                series_s = stable
        except Exception:
            pass
        with _winline_current_map_state_lock:
            for _key, poller in _winline_current_map_pollers.items():
                if not getattr(poller, "is_active", lambda: False)():
                    continue
                identity = getattr(poller, "_identity", None)
                if identity and str(identity.get("series") or "") == series_s:
                    poller.set_accelerated(True)
                    return True
        return False
    except Exception:
        return False


def decelerate_winline_current_map_polling(match_key: str) -> bool:
    """Clear accelerated mode on active poller(s) matching match_key. Idempotent, fail-open."""
    try:
        series_s = str(match_key or "").strip()
        try:
            stable = _bookmaker_series_identity(series_s)
            if stable:
                series_s = stable
        except Exception:
            pass
        with _winline_current_map_state_lock:
            for _key, poller in _winline_current_map_pollers.items():
                identity = getattr(poller, "_identity", None)
                if identity and str(identity.get("series") or "") == series_s:
                    poller.set_accelerated(False)
                    return True
        return False
    except Exception:
        return False


