class _Tee:
    def __init__(self, *streams):
        self._streams = streams
        self.encoding = getattr(streams[0], "encoding", "utf-8")
        self.errors = getattr(streams[0], "errors", "replace")

    def write(self, data):
        for stream in self._streams:
            try:
                stream.write(data)
            except Exception:
                pass

    def flush(self):
        for stream in self._streams:
            try:
                stream.flush()
            except Exception:
                pass

    def isatty(self):
        stream = self._streams[0] if self._streams else None
        if stream is None:
            return False
        return getattr(stream, "isatty", lambda: False)()

    def fileno(self):
        stream = self._streams[0] if self._streams else None
        if stream is None:
            raise OSError("No underlying stream")
        return stream.fileno()


# --- Dual logging: log.txt (user-facing) via print(), log_detailed.txt via detail_log() ---
_DETAIL_LOG_FILE = None


def _init_detail_log() -> None:
    global _DETAIL_LOG_FILE
    if _DETAIL_LOG_FILE is not None:
        return
    root_dir = Path(__file__).resolve().parent.parent
    detail_path = root_dir / "log_detailed.txt"
    _DETAIL_LOG_FILE = open(detail_path, "a", encoding="utf-8", buffering=1)


def detail_log(*args, **kwargs) -> None:
    """Write to log_detailed.txt only (verbose/debug output)."""
    global _DETAIL_LOG_FILE
    if _DETAIL_LOG_FILE is None:
        _init_detail_log()
    try:
        text = " ".join(str(a) for a in args)
        _DETAIL_LOG_FILE.write(text + "\n")
    except Exception:
        pass


def _setup_run_logging():
    root_dir = Path(__file__).resolve().parent.parent
    log_path = root_dir / "log.txt"
    session_started_at = datetime.now().astimezone().strftime("%Y-%m-%d %H:%M:%S %z")
    # Write session header directly (nohup redirects stdout/stderr to log.txt)
    print(
        "\n"
        + "=" * 24
        + f" RUN START {session_started_at} pid={os.getpid()} "
        + "=" * 24
    )
    root_logger = logging.getLogger()
    if root_logger.level == logging.NOTSET or root_logger.level > logging.INFO:
        root_logger.setLevel(logging.INFO)
    if not root_logger.handlers:
        logging.basicConfig(level=logging.INFO, format="%(message)s", stream=sys.stdout)
    else:
        for handler in root_logger.handlers:
            try:
                handler.setFormatter(logging.Formatter("%(message)s"))
            except Exception:
                pass
            if isinstance(handler, logging.StreamHandler):
                handler.setStream(sys.stdout)
    print(f"Logging to {log_path}")


def _release_runtime_instance_lock() -> None:
    global runtime_instance_lock_handle
    handle = globals().get("runtime_instance_lock_handle")
    runtime_instance_lock_handle = None
    if handle is None:
        return
    try:
        if fcntl is not None:
            fcntl.flock(handle.fileno(), fcntl.LOCK_UN)
    except Exception:
        pass
    try:
        handle.close()
    except Exception:
        pass


def _odds_requested_flag(raw_odds: Any) -> bool:
    if raw_odds is None:
        return _safe_bool_env("BOOKMAKER_PREFETCH_ENABLED", False)
    if isinstance(raw_odds, str):
        return raw_odds.strip().lower() in {"1", "true", "yes", "y", "on"}
    return bool(raw_odds)


def _runtime_instance_mode_label(raw_odds: Any) -> str:
    return "odds" if _odds_requested_flag(raw_odds) else "no_odds"


def _mode_specific_runtime_path(base_path_raw: str, mode_label: str) -> Path:
    base_path = Path(base_path_raw)
    if not mode_label:
        return base_path
    if base_path.suffix:
        return base_path.with_name(f"{base_path.stem}.{mode_label}{base_path.suffix}")
    return base_path.with_name(f"{base_path.name}.{mode_label}")


def _runtime_instance_lock_path_for_mode(mode_label: str) -> Path:
    return _mode_specific_runtime_path(RUNTIME_INSTANCE_LOCK_PATH, mode_label)


def _delayed_queue_path_for_mode(mode_label: str) -> Path:
    return _mode_specific_runtime_path(DELAYED_QUEUE_PATH, mode_label)


def _try_acquire_runtime_instance_lock(*, mode_label: str) -> bool:
    global runtime_instance_lock_handle
    current_handle = globals().get("runtime_instance_lock_handle")
    if current_handle is not None:
        runtime_instance_lock_handle = current_handle
        return True
    if fcntl is None:
        logger.warning("fcntl is unavailable; runtime single-instance lock is disabled")
        return True

    lock_path = _runtime_instance_lock_path_for_mode(mode_label)
    lock_path.parent.mkdir(parents=True, exist_ok=True)
    handle = lock_path.open("a+", encoding="utf-8")
    try:
        fcntl.flock(handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
    except OSError:
        owner_info = ""
        try:
            handle.seek(0)
            owner_info = handle.read().strip()
        except Exception:
            owner_info = ""
        try:
            handle.close()
        except Exception:
            pass
        owner_suffix = f" owner={owner_info}" if owner_info else ""
        logger.error("Runtime lock is already held for mode=%s: %s%s", mode_label, lock_path, owner_suffix)
        print(
            f"⛔ Второй процесс запрещен: runtime lock уже занят "
            f"(mode={mode_label}): {lock_path}{owner_suffix}"
        )
        return False

    runtime_instance_lock_handle = handle
    payload = {
        "pid": os.getpid(),
        "started_at": datetime.now().isoformat(timespec="seconds"),
        "cwd": os.getcwd(),
        "mode": mode_label,
    }
    try:
        handle.seek(0)
        handle.truncate()
        handle.write(json.dumps(payload, ensure_ascii=False))
        handle.flush()
        os.fsync(handle.fileno())
    except Exception:
        logger.exception("Failed to write runtime lock payload into %s", lock_path)
    return True


def _clear_journal_file(path: Path) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temp_path = tempfile.mkstemp(
        prefix=f".{path.name}.",
        suffix=".tmp",
        dir=str(path.parent),
    )
    try:
        with os.fdopen(fd, "wb") as temp_file:
            temp_file.write(b"")
            temp_file.flush()
            os.fsync(temp_file.fileno())
        os.replace(temp_path, path)
    finally:
        try:
            os.unlink(temp_path)
        except FileNotFoundError:
            pass


def _append_journal_entry_to_path(path: Path, entry: dict[str, Any]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    payload = orjson.dumps(entry) + b"\n"
    with path.open("ab") as fh:
        fh.write(payload)
        fh.flush()
        os.fsync(fh.fileno())


def _write_json_atomic(path: Path, data: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, temp_path = tempfile.mkstemp(
        prefix=f".{path.name}.",
        suffix=".tmp",
        dir=str(path.parent),
    )
    try:
        with os.fdopen(fd, "wb") as temp_file:
            temp_file.write(orjson.dumps(data, option=orjson.OPT_NON_STR_KEYS))
            temp_file.flush()
            os.fsync(temp_file.fileno())
        os.replace(temp_path, path)
    finally:
        try:
            os.unlink(temp_path)
        except FileNotFoundError:
            pass


atexit.register(_release_runtime_instance_lock)


def _coerce_metric_value(value: Any) -> Optional[float]:
    if value is None:
        return None
    if isinstance(value, str):
        v = value.strip()
        # Display-only synergy confirmations use ``**`` while STAR hits use
        # ``*``.  Strip every trailing marker so decorated values remain safe
        # for diagnostics and delayed-message refreshes.
        v = v.rstrip('*').strip()
        if not v:
            return None
        try:
            return float(v)
        except ValueError:
            return None
    if isinstance(value, (int, float)):
        return float(value)
    return None


def _short_exception_message(exc: BaseException) -> str:
    message = str(exc or "").strip()
    if not message:
        return exc.__class__.__name__
    return message.splitlines()[0].strip() or exc.__class__.__name__


def _transient_exception_message(exc: BaseException) -> str:
    message = _short_exception_message(exc)
    if "NS_ERROR_NET_RESET" in message or "ERR_CONNECTION_RESET" in message:
        return "network reset"
    if "NS_ERROR_NET_INTERRUPT" in message:
        return "network interrupted"
    if "ERR_TIMED_OUT" in message or "Timeout" in message or "timed out" in message:
        return "network timeout"
    return message


def _block_hits_thresholds(data: dict, thresholds: list[tuple]) -> bool:
    star_count = 0
    block_sign = None
    conflict = False
    for key, threshold in thresholds:
        val = _coerce_metric_value(data.get(key))
        if val is None:
            continue
        if abs(val) >= threshold:
            star_count += 1
            sign = 1 if val > 0 else (-1 if val < 0 else None)
            if sign is None:
                continue
            if block_sign is None:
                block_sign = sign
            elif block_sign != sign:
                conflict = True
                break
    return star_count > 0 and not conflict


def _nearest_star_wr_level(raw_level: float, candidate_levels: List[int]) -> Optional[int]:
    try:
        value = float(raw_level)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(value):
        return None
    levels = sorted(
        {
            int(level)
            for level in candidate_levels
            if STAR_LEVEL_MIN <= int(level) <= STAR_LEVEL_MAX
        }
    )
    if not levels:
        levels = list(range(int(STAR_LEVEL_MIN), int(STAR_LEVEL_MAX) + 1))
    return min(levels, key=lambda level: (abs(float(level) - value), -int(level)))


def _recommendation_from_star_levels(
    metric_levels: List[int],
    *,
    candidate_levels: List[int],
    calibration_phase_key: str,
) -> Optional[dict]:
    if not metric_levels:
        return None
    average_level = sum(float(level) for level in metric_levels) / float(len(metric_levels))
    recommended_level = _nearest_star_wr_level(average_level, candidate_levels)
    if recommended_level is None:
        return None
    wr_pct = float(recommended_level)
    if STAR_ODDS_USE_CALIBRATION:
        calibrated_wr = STAR_CONFIDENCE_CALIBRATION.get(calibration_phase_key, {}).get(recommended_level)
        if calibrated_wr is not None:
            wr_pct = float(calibrated_wr)
    if wr_pct <= 0:
        wr_pct = float(recommended_level)
    min_odds = round(100.0 / wr_pct, 2)
    return {
        'level': recommended_level,
        'min_odds': min_odds,
        'wr_pct': wr_pct,
    }


def _star_level_from_base_ratio(ratio: float) -> Optional[int]:
    try:
        ratio_value = float(ratio)
    except (TypeError, ValueError):
        return None
    if ratio_value < 1.0:
        return None
    for min_ratio, wr_level in _STAR_INDEX_WR_MULTIPLIER_TO_LEVEL:
        if ratio_value >= float(min_ratio):
            return max(STAR_LEVEL_MIN, min(STAR_LEVEL_MAX, int(wr_level)))
    return None


def _recommend_odds_for_block(data: dict, phase: str) -> Optional[dict]:
    if not isinstance(data, dict):
        return None

    phase_name = str(phase or "").strip().lower()
    section = {
        "early": "early_output",
        "early_end": "early_end_output",
        "early_winner": "early_end_output",
        "mid": "mid_output",
        "late": "mid_output",
        "all": "all_output",
    }.get(phase_name, "mid_output")
    # STAR threshold tables only key early_output; early_end shares the same gate table.
    threshold_section = "early_output" if section == "early_end_output" else section

    # Рекомендации считаем только по фактическим STAR-метрикам (с '*'),
    # чтобы не получать "высокие уровни" на незвездных числах.
    star_only_data: Dict[str, float] = {}
    for metric, raw in data.items():
        if not _star_metric_enabled_for_section(str(metric), section):
            continue
        if not isinstance(raw, str) or not raw.strip().endswith('*'):
            continue
        value = _coerce_metric_value(raw)
        if value is None or value == 0:
            continue
        star_only_data[str(metric)] = float(value)
    if not star_only_data:
        return None
    # В одном блоке ожидаем единый знак STAR-метрик; при конфликте не даем рекомендацию.
    star_signs = {1 if v > 0 else -1 for v in star_only_data.values() if v != 0}
    if len(star_signs) > 1:
        return None

    calibration_phase_key = (
        "early"
        if section in {"early_output", "early_end_output"}
        else "all"
        if section == "all_output"
        else "late"
    )
    available_levels = [
        int(level)
        for level, payload in STAR_THRESHOLDS_BY_WR.items()
        if isinstance(payload, dict) and payload.get(threshold_section)
    ]
    # If runtime has only one WR-level table (typically fallback WR60),
    # recover dynamic WR display by comparing metric indexes to base thresholds.
    if len(set(available_levels)) <= 1:
        base_level = available_levels[0] if available_levels else 60
        base_payload = STAR_THRESHOLDS_BY_WR.get(base_level) or STAR_THRESHOLDS_BY_WR.get(60, {})
        base_rows = base_payload.get(threshold_section, []) if isinstance(base_payload, dict) else []
        thresholds_by_metric: Dict[str, int] = {}
        for metric, raw_threshold in base_rows:
            try:
                metric_name = str(metric)
                if not _star_metric_enabled_for_section(metric_name, section):
                    continue
                thresholds_by_metric[metric_name] = max(1, int(raw_threshold))
            except (TypeError, ValueError):
                continue
        if not thresholds_by_metric:
            return None

        # Ориентируемся на средний WR starred-индексов.
        metric_levels: List[int] = []
        for metric, value in star_only_data.items():
            fixed_level = _fixed_star_wr_level_for_metric(metric, value, section)
            if fixed_level is not None:
                metric_levels.append(int(fixed_level))
                continue
            threshold = thresholds_by_metric.get(metric)
            if threshold is None:
                return None
            metric_level = _star_level_from_base_ratio(abs(value) / float(threshold))
            if metric_level is not None:
                metric_levels.append(metric_level)
        return _recommendation_from_star_levels(
            metric_levels,
            candidate_levels=[int(level) for _, level in _STAR_INDEX_WR_MULTIPLIER_TO_LEVEL],
            calibration_phase_key=calibration_phase_key,
        )

    thresholds_by_level: Dict[int, Dict[str, int]] = {}
    for level in sorted(set(available_levels)):
        thresholds = STAR_THRESHOLDS_BY_WR.get(level, {}).get(threshold_section, [])
        if not thresholds:
            continue
        threshold_map: Dict[str, int] = {}
        for metric, threshold in thresholds:
            try:
                compact_metric = str(metric)
                compact_threshold = int(threshold)
            except (TypeError, ValueError):
                continue
            if not _star_metric_enabled_for_section(compact_metric, section):
                continue
            if compact_threshold < 1:
                compact_threshold = 1
            threshold_map[compact_metric] = compact_threshold
        if threshold_map:
            thresholds_by_level[int(level)] = threshold_map

    metric_levels: List[int] = []
    for metric, value in star_only_data.items():
        fixed_level = _fixed_star_wr_level_for_metric(metric, value, section)
        if fixed_level is not None:
            metric_levels.append(int(fixed_level))
            continue
        metric_best_level = None
        metric_max_threshold = 0
        abs_value = abs(value)
        for level in sorted(thresholds_by_level):
            threshold = thresholds_by_level[level].get(metric)
            if threshold is None:
                continue
            # Если порог для более высокого WR не вырос, не повышаем confidence.
            # Это устраняет скачки вида 7* -> WR60, 8* -> WR90 при плато таблицы.
            if threshold <= metric_max_threshold:
                continue
            metric_max_threshold = int(threshold)
            if abs_value >= metric_max_threshold:
                metric_best_level = int(level)
        if metric_best_level is None:
            continue
        metric_levels.append(metric_best_level)
    return _recommendation_from_star_levels(
        metric_levels,
        candidate_levels=list(thresholds_by_level.keys()),
        calibration_phase_key=calibration_phase_key,
    )


def _format_wr_estimate_line(
    label: str,
    team_name: str,
    wr_pct: Optional[float],
    rec: Optional[dict],
) -> Optional[str]:
    if not rec:
        return None
    phase_label = str(label or "").strip() or "Signal"
    clean_team_name = str(team_name or "").strip()
    try:
        wr_value = float(wr_pct) if wr_pct is not None else 0.0
    except (TypeError, ValueError):
        wr_value = 0.0
    line = (
        f"{phase_label}: {clean_team_name} WR≈{wr_value:.1f}%"
        if clean_team_name
        else f"{phase_label}: WR≈{wr_value:.1f}%"
    )
    if isinstance(rec, dict) and rec.get("min_odds"):
        try:
            line += f" от кэфа {float(rec['min_odds']):.2f}"
        except (TypeError, ValueError):
            pass
    return line


def _compose_star_metric_blocks_for_message(
    early_block: str,
    late_block: str,
    all_block: str,
    mix_block: str = "",
) -> str:
    """Порядок блоков в сообщении: Early → Late → All → Mix.

    Mix идёт последним и по умолчанию пуст — так старые вызовы (и тесты,
    сверяющие текст без него) продолжают собирать прежнее сообщение.
    """
    return (
        f"{str(early_block or '')}"
        f"{str(late_block or '')}"
        f"{str(all_block or '')}"
        f"{str(mix_block or '')}"
    )


# Модульный уровень: тот же формат, что у nested _format_metrics в star-ветке
# check_head — нужно, чтобы no-star ветка отказа тоже собирала bet_message
# с детальными блоками Early/Late/All для tail_log.
