# Метрики из ВНЕШНИХ источников (dota2protracker, голосование DLTV) — они не
# считаются по нашим словарям и живут отдельным блоком Mix, а не внутри All.
# Значения по-прежнему лежат в ``all_output``: переезд касается подачи, а не
# места хранения. DLTV_rating и Protracker_1vs1 при этом остаются STAR-метриками
# (пороги заданы в секции ``all_output``), остальные три — display-only.
_STAR_METRICS_BLOCK_MIX_LIST: Tuple[Tuple[str, str], ...] = (
    ('dota2protracker_cp1vs1', 'Protracker_1vs1'),
    ('dota2protracker_duo', 'Protracker_duo'),
    ('dota2protracker_solo', 'Protracker_solo'),
    ('dota2protracker_solo_overall', 'Protracker_solo_overall'),
    ('dltv_rating', 'DLTV_rating'),
)


def _format_star_metrics_block(
    title: str,
    block: Any,
    metrics: Any,
) -> str:
    data = block if isinstance(block, dict) else {}
    lines = [title]
    for key, label in metrics:
        value = data.get(key)
        if key in (
            "dota2protracker_cp1vs1",
            "dota2protracker_duo",
            "dota2protracker_solo",
            "dota2protracker_solo_overall",
        ):
            value = _format_dota2protracker_output_value(value)
        lines.append(f"{label}: {value}")
    return "\n".join(lines) + "\n"


_STAR_HITS_SUMMARY_WR_LEVELS: Tuple[int, ...] = (60, 65, 70, 75, 80, 85, 90)

_STAR_HITS_SUMMARY_METRIC_LABELS: Dict[str, str] = {
    "counterpick_1vs1": "Counterpick_1vs1",
    "counterpick_1vs2": "Counterpick_1vs2",
    "solo": "Solo",
    "synergy_duo": "Synergy_duo",
    "synergy_trio": "Synergy_trio",
    "dota2protracker_cp1vs1": "Protracker_1vs1",
    "dota2protracker_duo": "Protracker_duo",
    "dota2protracker_solo": "Protracker_solo",
    "dota2protracker_solo_overall": "Protracker_solo_overall",
    "dltv_rating": "DLTV_rating",
}

# Метрики с ФИКСИРОВАННЫМ WR-уровнем: у них один порог, и уровень не выводится
# из таблицы порогов, а задаётся здесь. Нужно потому, что уровень по таблице
# засчитывается только при РОСТЕ порога между WR-уровнями (защита от плато в
# ``_recommend_odds_for_block``): одинаковый порог на WR60/WR65 иначе даёт
# блоку wr_pct=60, и витрина (``⭐ Star hits``) расходится с диспатчем.
_STAR_FIXED_WR_LEVEL_BY_METRIC: Dict[str, int] = {
    # DLTV draft-vote: |radiant_pct-50| >= 30 — по бэктесту 625 карт WR≈85%,
    # но уровень намеренно держим на 65 (консервативно и стабильно).
    "dltv_rating": 65,
}


def _fixed_star_wr_level_for_metric(
    metric: str,
    value: Any,
    section: str,
) -> Optional[int]:
    """WR-уровень метрики с фиксированным уровнем; ``None`` — если не про неё.

    Возвращает уровень, только когда метрика включена в секции и её значение
    дотягивает до порога (берётся минимальный порог метрики по таблице).
    """
    metric_name = str(metric or "").strip()
    fixed_level = _STAR_FIXED_WR_LEVEL_BY_METRIC.get(metric_name)
    if fixed_level is None:
        return None
    if not _star_metric_enabled_for_section(metric_name, section):
        return None
    try:
        abs_value = abs(float(value))
    except (TypeError, ValueError):
        return None
    thresholds = [
        float(_star_thresholds_for_wr(wr_level, section)[metric_name])
        for wr_level in _STAR_HITS_SUMMARY_WR_LEVELS
        if metric_name in _star_thresholds_for_wr(wr_level, section)
    ]
    if not thresholds:
        return None
    if abs_value < min(thresholds):
        return None
    return int(fixed_level)


def _max_star_wr_level_for_metric(
    *,
    metric: str,
    value: float,
    section: str,
) -> Optional[int]:
    """Return the highest WR level whose threshold the absolute value reaches.

    Uses the same threshold table as runtime STAR diagnostics.  Considers only
    metrics enabled for STAR signal decisions (gated by
    ``_star_metric_enabled_for_section``).  Returns ``None`` when no level is
    satisfied or when the metric is disabled for the given section.
    """

    metric_name = str(metric or "").strip()
    if not metric_name:
        return None
    if not _star_metric_enabled_for_section(metric_name, section):
        return None
    try:
        abs_value = abs(float(value))
    except (TypeError, ValueError):
        return None
    if abs_value <= 0:
        return None
    fixed_level = _fixed_star_wr_level_for_metric(metric_name, abs_value, section)
    if fixed_level is not None:
        return fixed_level
    best_level: Optional[int] = None
    for wr_level in _STAR_HITS_SUMMARY_WR_LEVELS:
        thresholds = _star_thresholds_for_wr(wr_level, section)
        threshold = thresholds.get(metric_name)
        if threshold is None:
            continue
        if abs_value >= float(threshold):
            if best_level is None or wr_level > best_level:
                best_level = int(wr_level)
    return best_level


def _collect_star_hits_for_block(
    raw_block: Optional[dict],
    section: str,
) -> List[Dict[str, Any]]:
    block = raw_block if isinstance(raw_block, dict) else {}
    hits: List[Dict[str, Any]] = []
    for metric in _STAR_METRIC_ORDER:
        value = _coerce_metric_value(block.get(metric))
        if value is None or value == 0:
            continue
        level = _max_star_wr_level_for_metric(
            metric=metric,
            value=float(value),
            section=section,
        )
        if level is None:
            continue
        hits.append(
            {
                "metric": metric,
                "value": float(value),
                "wr_level": int(level),
            }
        )
    return hits


def _has_opposite_early_wr60_hit(
    raw_early_output: Optional[dict],
    late_sign: Optional[int],
) -> bool:
    """Return True when the EARLY block has at least one STAR-eligible WR60+
    hit whose sign is opposite to the late side.

    Used to keep the late-only pre27 watcher blocked before ~21:00 even when
    the early STAR block is not a fully-valid signal (e.g. sign conflict among
    required metrics) but still shows an opposite-side early edge. Mirrors the
    multi-hit opposite-signs waiting behaviour for the single-hit case.
    """
    if late_sign not in (-1, 1):
        return False
    hits = _collect_star_hits_for_block(raw_early_output, "early_output")
    for hit in hits:
        try:
            value = float(hit.get("value"))
        except (TypeError, ValueError):
            continue
        if value == 0:
            continue
        sign = 1 if value > 0 else -1
        if sign != int(late_sign):
            return True
    return False


def _format_star_hits_line(hits: List[Dict[str, Any]]) -> str:
    parts: List[str] = []
    for hit in hits:
        metric = str(hit.get("metric") or "")
        label = _STAR_HITS_SUMMARY_METRIC_LABELS.get(metric, metric or "?")
        try:
            value = float(hit.get("value"))
        except (TypeError, ValueError):
            continue
        try:
            wr_level = int(hit.get("wr_level"))
        except (TypeError, ValueError):
            continue
        formatted_value = _format_metric_value(value)
        if not formatted_value.startswith("-"):
            formatted_value = f"+{formatted_value}"
        parts.append(f"{label} {formatted_value} (WR{wr_level})")
    return ", ".join(parts)


def _format_win_model_line(*blocks) -> str:
    """Строка с оценкой драфтовой ML-модели для Telegram и лога.

    Индекс кладёт в каждый блок `synergy_and_counterpick`; он одинаков во всех,
    поэтому берётся первый найденный. Печатается ВСЕГДА, когда модель доступна —
    по ней работает вето, и оператор должен видеть её мнение даже там, где вето
    не сработало. Модель недоступна -> строки нет (шум вместо данных не нужен).
    """
    index = None
    source = None
    for block in blocks:
        if isinstance(block, dict):
            raw = block.get(win_model_veto.INDEX_KEY)
            if raw is not None:
                try:
                    index = float(raw)
                except (TypeError, ValueError):
                    index = None
                if index is not None:
                    source = block.get(win_model_veto.SOURCE_KEY)
                    break
    if index is None:
        return ""
    side = "Radiant" if index > 0 else ("Dire" if index < 0 else "\u2014")
    confidence = 50.0 + abs(index)
    line = f"\U0001F916 ML-\u043c\u043e\u0434\u0435\u043b\u044c: {side} {confidence:.1f}%"
    # \u00abML \u043e\u0442 \u043a\u044d\u0444\u0430\u00bb \u2014 \u043c\u0438\u043d\u0438\u043c\u0430\u043b\u044c\u043d\u044b\u0439 \u043a\u043e\u044d\u0444\u0444\u0438\u0446\u0438\u0435\u043d\u0442, \u043f\u0440\u0438 \u043a\u043e\u0442\u043e\u0440\u043e\u043c \u0441\u0442\u0430\u0432\u043a\u0430 \u043f\u043e \u043c\u043e\u0434\u0435\u043b\u0438
    # \u043e\u043a\u0443\u043f\u0430\u0435\u0442\u0441\u044f. \u0421\u0447\u0438\u0442\u0430\u0435\u0442\u0441\u044f \u041d\u0415 \u043e\u0442 \u0441\u0430\u043c\u043e\u0439 \u0443\u0432\u0435\u0440\u0435\u043d\u043d\u043e\u0441\u0442\u0438, \u0430 \u043e\u0442 \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u0432\u0438\u043d\u0440\u0435\u0439\u0442\u0430
    # \u044d\u0442\u043e\u0439 \u043f\u043e\u043b\u043e\u0441\u044b \u043d\u0430 \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0438\u0445 \u043e\u0444\u043b\u0430\u0439\u043d-\u0442\u0443\u0440\u043d\u0438\u0440\u0430\u0445 (prematch_scorer.LAN_ODDS_GRID):
    # \u043c\u043e\u0434\u0435\u043b\u044c \u043f\u0435\u0440\u0435\u043e\u0446\u0435\u043d\u0438\u0432\u0430\u0435\u0442 \u0441\u0435\u0431\u044f, \u0438 \u0431\u0440\u0430\u0442\u044c \u0435\u0451 \u043f\u0440\u043e\u0446\u0435\u043d\u0442 \u0437\u0430 \u0432\u0435\u0440\u043e\u044f\u0442\u043d\u043e\u0441\u0442\u044c \u0437\u043d\u0430\u0447\u0438\u043b\u043e \u0431\u044b
    # \u0437\u0430\u043d\u0438\u0436\u0430\u0442\u044c \u0442\u0440\u0435\u0431\u0443\u0435\u043c\u0443\u044e \u0446\u0435\u043d\u0443. \u0422\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u0435\u0434\u043c\u0430\u0442\u0447\u0435\u0432\u044b\u0439 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u2014 \u0434\u0440\u0430\u0444\u0442\u043e\u0432\u0430\u044f \u0448\u043a\u0430\u043b\u0430
    # \u043d\u0430 LAN \u043d\u0435 \u043c\u0435\u0440\u044f\u043b\u0430\u0441\u044c.
    if str(source or "") == win_model_veto.SOURCE_PREMATCH:
        try:
            from base import prematch_scorer as _ps
            line += f" | ML \u043e\u0442 \u043a\u044d\u0444\u0430: {_ps.lan_min_odds(confidence / 100.0):.2f}"
        except Exception:                            # noqa: BLE001
            pass
    # Доля входа, собранная из реальных данных. Печатается ВСЕГДА, когда
    # известна: отсутствие пометки раньше означало и «всё заполнено», и
    # «счётчика нет» — различить было нельзя (E-195).
    try:
        _elo = win_model_veto.last_model_elo(index)
        if _elo is not None:
            line += f" | ELO модели: {_elo:+.0f}"
        _parts = win_model_veto.last_parts(index)
        if _parts:
            # Доли от суммы МОДУЛЕЙ: по модулю дают 100%, и видно, кто тянет
            # против. Знак — в ориентации Radiant, как у `ELO модели`.
            _tot = sum(abs(v) for v in _parts.values()) or 1.0
            _names = (("elo", "ELO"), ("draft", "драфт"),
                      ("players", "игроки"), ("h2h", "очные"))
            _sh = " ".join(f"{_ru} {_parts.get(_k, 0.0)/_tot:+.0%}"
                           for _k, _ru in _names if _k in _parts)
            if _sh:
                line += f" | вклад: {_sh}"
        _dr = win_model_veto.last_draft_rank(index)
        if _dr and not _parts:
            # Единый знаменатель со строкой ELO: минус за Dire, плюс за Radiant.
            # `draft_share` считается ПОСЛЕ переворота вкладов на сторону ставки,
            # поэтому его знак означает «за выбранную сторону»; домножаем на знак
            # стороны и получаем ориентацию Radiant, ту же, что у `ELO модели`.
            # Внутреннюю величину не трогаем: на ней стоит гейт _DRAFT_FIRST_ONLY.
            _draft_radiant_oriented = _dr[1] * (1.0 if index > 0 else -1.0)
            line += f" | драфт {_draft_radiant_oriented:+.1%}"
        _fill = win_model_veto.last_fill(index)
        if _fill is not None:
            line += f" | вход {float(_fill):.0%}"
    except Exception:                                # noqa: BLE001
        pass
    # Late-модель: тот же драфт, но обучена ТОЛЬКО на картах >= 36 минут
    # (E-240). Показывается всегда, когда оценка есть: она предматчевая,
    # живого состояния не требует. Нет строки — модель не загрузилась или
    # драфт неполный, и карточка выглядит ровно как раньше.
    try:
        _late = win_model_veto.last_late(index)
    except Exception:                                # noqa: BLE001
        _late = None
    if _late:
        line += (f"\n\U0001F551 Late ML-\u043c\u043e\u0434\u0435\u043b\u044c: "
                 f"{_late['side']} {float(_late['confidence']) * 100:.1f}%")
    # Блок панели окон килов. Пустая строка, если панель не готова, — карточка
    # тогда выглядит ровно как раньше.
    try:
        _panel_text = win_model_veto.last_panel_text()
    except Exception:                                # noqa: BLE001
        _panel_text = ""
    if _panel_text:
        return line + "\n" + _panel_text + "\n"
    return line + "\n"


def _build_star_hits_summary_block(
    *,
    early_output: Optional[dict],
    mid_output: Optional[dict],
    all_output: Optional[dict],
) -> str:
    """Return multi-line ``⭐ Star hits (WR60+):`` block for Telegram/log output.

    Returns an empty string when no STAR-signal metric in any block reaches the
    WR60 threshold.  Only metrics that participate in STAR decisions (governed
    by ``_star_metric_enabled_for_section``) are considered.
    """

    early_hits = _collect_star_hits_for_block(early_output, "early_output")
    mid_hits = _collect_star_hits_for_block(mid_output, "mid_output")
    section_all_hits = _collect_star_hits_for_block(all_output, "all_output")

    # Хиты внешних источников (ProTracker, голосование DLTV) показываем строкой
    # Mix, а не внутри All — как и сами метрики в детальных блоках. Считаются
    # они по-прежнему в секции ``all_output``: делится ПОДАЧА, а не оценка,
    # поэтому набор сработавших метрик и решения диспатча не меняются.
    mix_metric_names = {metric for metric, _label in _STAR_METRICS_BLOCK_MIX_LIST}
    all_hits = [h for h in section_all_hits if h.get("metric") not in mix_metric_names]
    mix_hits = [h for h in section_all_hits if h.get("metric") in mix_metric_names]

    model_line = _format_win_model_line(early_output, mid_output, all_output)
    if not any((early_hits, mid_hits, all_hits, mix_hits)):
        return model_line

    lines: List[str] = ["⭐ Star hits (WR60+):"]
    for label, hits in (
        ("Early", early_hits),
        ("Late", mid_hits),
        ("All", all_hits),
        ("Mix", mix_hits),
    ):
        if not hits:
            continue
        lines.append(f"  {label}: {_format_star_hits_line(hits)}")
    return model_line + "\n".join(lines) + "\n"


def _late_star_hits_by_sign(raw_mid_output: Optional[dict]) -> Dict[str, Any]:
    """Partition STAR-signal metric hits in the Late block by sign (WR60 only).

    Returns a dict with three lists of metric names: ``same_sign_pos``,
    ``same_sign_neg``, ``zero_metrics`` (values that are numerically zero).
    The helper only counts metrics enabled for STAR signal decisions and uses
    WR60 thresholds because Late is promoted / routed to kills exactly at that
    base level.
    """

    block = raw_mid_output if isinstance(raw_mid_output, dict) else {}
    thresholds = _star_thresholds_for_wr(60, "mid_output")
    pos_hits: List[str] = []
    neg_hits: List[str] = []
    zero_metrics: List[str] = []
    nonzero_by_sign: Dict[int, List[str]] = {1: [], -1: []}

    for metric in _STAR_METRIC_ORDER:
        if not _star_metric_enabled_for_section(metric, "mid_output"):
            continue
        value = _coerce_metric_value(block.get(metric))
        if value is None:
            continue
        if value == 0:
            zero_metrics.append(metric)
            continue
        sign = 1 if value > 0 else -1
        nonzero_by_sign[sign].append(metric)
        threshold = thresholds.get(metric)
        if threshold is None:
            continue
        if abs(value) < float(threshold):
            continue
        if sign > 0:
            pos_hits.append(metric)
        else:
            neg_hits.append(metric)

    return {
        "same_sign_pos": pos_hits,
        "same_sign_neg": neg_hits,
        "zero_metrics": zero_metrics,
        "nonzero_by_sign": nonzero_by_sign,
    }


def _late_hits_for_expected_sign(
    late_hit_summary: Dict[str, Any],
    expected_sign: Optional[int],
) -> Tuple[List[str], List[str]]:
    """Return ``(same_sign_hits, opposite_sign_hits)`` relative to ``expected_sign``."""

    if expected_sign not in (-1, 1):
        return [], []
    if int(expected_sign) > 0:
        return list(late_hit_summary.get("same_sign_pos") or []), list(
            late_hit_summary.get("same_sign_neg") or []
        )
    return list(late_hit_summary.get("same_sign_neg") or []), list(
        late_hit_summary.get("same_sign_pos") or []
    )


def _evaluate_late_all_same_sign_promote(
    *,
    has_early_star: bool,
    has_late_star: bool,
    has_all_star: bool,
    early_sign: Optional[int],
    all_sign: Optional[int],
    raw_mid_output: Optional[dict],
) -> Dict[str, Any]:
    """Decide whether the Late block can be promoted to a valid same-sign star.

    Promotion requires (pt2 from the kills-gate spec):
      * Early and All are both valid STAR blocks of the same sign
      * Late is **not** already a valid STAR block
      * Late has at least one WR60 star-hit of the same sign
      * Late has no WR60 star-hit of the opposite sign
      * Late has no nonzero metric of the opposite sign
    """

    active = bool(
        has_early_star
        and has_all_star
        and not has_late_star
        and early_sign in (-1, 1)
        and all_sign in (-1, 1)
        and int(early_sign) == int(all_sign)
    )
    late_summary = _late_star_hits_by_sign(raw_mid_output)
    same_sign_hits, opposite_sign_hits = _late_hits_for_expected_sign(
        late_summary,
        early_sign if active else None,
    )
    opposite_sign_nonzero: List[str] = []
    if active and early_sign in (-1, 1):
        opposite_sign_nonzero = list(
            late_summary.get("nonzero_by_sign", {}).get(-int(early_sign), [])
        )
    valid = bool(
        active
        and same_sign_hits
        and not opposite_sign_hits
        and not opposite_sign_nonzero
    )
    return {
        "active": active,
        "valid": valid,
        "same_sign_hits": same_sign_hits,
        "opposite_sign_hits": opposite_sign_hits,
        "opposite_sign_nonzero": opposite_sign_nonzero,
        "late_hits_summary": late_summary,
    }


def _late_block_has_any_star_hit(raw_mid_output: Optional[dict]) -> bool:
    """True if Late contains ≥1 STAR-signal metric hit at WR60 (any sign)."""

    late_summary = _late_star_hits_by_sign(raw_mid_output)
    return bool(late_summary.get("same_sign_pos") or late_summary.get("same_sign_neg"))


# Early STAR WR bar for kills bets: WR>=70 AND hits>=2.
KILLS_GATE_EARLY_STAR_MIN_WR = 70.0
KILLS_GATE_EARLY_STAR_MIN_HITS = 2


def _early_star_meets_kills_wr_gate(
    *,
    early_wr_pct: Optional[float],
    early_hit_count: Optional[int],
) -> Dict[str, Any]:
    """Decide whether the Early STAR block passes the kills-gate WR bar.

    Criteria (kills-gate WR bar):
      * ``early_wr_pct >= KILLS_GATE_EARLY_STAR_MIN_WR`` (70)
      * ``AND early_hit_count >= KILLS_GATE_EARLY_STAR_MIN_HITS`` (2)
    """

    try:
        wr_value = float(early_wr_pct) if early_wr_pct is not None else None
    except (TypeError, ValueError):
        wr_value = None
    try:
        hit_count_value = int(early_hit_count) if early_hit_count is not None else 0
    except (TypeError, ValueError):
        hit_count_value = 0
    passes_wr70 = bool(
        wr_value is not None and wr_value >= float(KILLS_GATE_EARLY_STAR_MIN_WR)
    )
    passes_min_hits = bool(hit_count_value >= int(KILLS_GATE_EARLY_STAR_MIN_HITS))
    valid = bool(passes_wr70 and passes_min_hits)
    # Legacy key: True when the new combined bar passes (WR70+2hits).
    # Old consumers treated this as the multi-hit path; keep name for logs.
    passes_wr65_two_hits = valid
    return {
        "valid": valid,
        "early_wr_pct": wr_value,
        "early_hit_count": hit_count_value,
        "passes_wr70": passes_wr70,
        "passes_min_hits": passes_min_hits,
        "passes_wr65_two_hits": passes_wr65_two_hits,
        "min_wr": float(KILLS_GATE_EARLY_STAR_MIN_WR),
        "min_hits": int(KILLS_GATE_EARLY_STAR_MIN_HITS),
    }


def _evaluate_kills_gate(
    *,
    has_early_star: bool,
    has_late_star: bool,
    has_all_star: bool,
    early_sign: Optional[int],
    all_sign: Optional[int],
    early_wr_pct: Optional[float],
    early_hit_count: Optional[int],
    raw_mid_output: Optional[dict],
    late_all_same_sign_promote_valid: bool,
) -> Dict[str, Any]:
    """Decide whether the match should fall through to the kills betting gate.

    The gate activates when:
      * Early is a valid STAR block
      * Late is **not** a valid STAR block (primary) **and** the pt2 promote
        did **not** succeed
      * Late contains at least one WR60 STAR-signal hit (any sign)
      * Either All is absent **or** All is a valid STAR of the same sign as
        Early (the opposite-sign All is blocked earlier by
        ``no_late_early_all_opposite_signs``)

    A positive ``valid`` result means the kills header/path is authorised.
    ``active_but_blocked`` signals that we reached the gate but the Early WR
    bar rejected the match, meaning we must add_url instead of firing any
    other branch.
    """

    active = bool(
        has_early_star
        and not has_late_star
        and not late_all_same_sign_promote_valid
        and early_sign in (-1, 1)
        and _late_block_has_any_star_hit(raw_mid_output)
    )
    all_same_sign_ok = bool(
        not has_all_star
        or (
            has_all_star
            and all_sign in (-1, 1)
            and early_sign in (-1, 1)
            and int(all_sign) == int(early_sign)
        )
    )
    active = active and all_same_sign_ok
    wr_gate = _early_star_meets_kills_wr_gate(
        early_wr_pct=early_wr_pct,
        early_hit_count=early_hit_count,
    )
    valid = bool(active and wr_gate.get("valid"))
    return {
        "active": active,
        "valid": valid,
        "active_but_blocked": bool(active and not wr_gate.get("valid")),
        "wr_gate": wr_gate,
        "has_all_star_same_sign": bool(has_all_star and all_same_sign_ok),
        "early_sign": early_sign,
    }


def _extract_ml_block_confidence_pct(data: dict, phase: str) -> Optional[float]:
    if not isinstance(data, dict):
        return None
    phase_key = "early" if phase == "early" else "late"
    ml_meta = data.get("_ml_meta")
    if not isinstance(ml_meta, dict):
        return None
    phase_meta = ml_meta.get(phase_key)
    if not isinstance(phase_meta, dict):
        return None
    probs = phase_meta.get("probs")
    if not isinstance(probs, dict) or not probs:
        return None
    # Учитываем confidence только для метрик, которые реально остались в блоке
    # после применения wrapper (value != 0). Иначе "сырой" prob для уже
    # обнуленной метрики создает шум (например 20-40%), хотя ML-сигнала нет.
    alive_metrics = {
        key
        for key, raw in data.items()
        if key in {
            "counterpick_1vs1",
            "pos1_vs_pos1",
            "counterpick_1vs2",
            "solo",
            "synergy_duo",
            "synergy_trio",
        }
        and _coerce_metric_value(raw) not in (None, 0.0)
    }
    if not alive_metrics:
        return None
    vals = []
    for metric, raw in probs.items():
        if metric not in alive_metrics:
            continue
        try:
            p = float(raw)
        except (TypeError, ValueError):
            continue
        if math.isfinite(p):
            vals.append(max(0.0, min(1.0, p)) * 100.0)
    if not vals:
        return None
    return max(vals)


def _resolve_ml_block_confidence(data: dict, phase: str, source_mode: str) -> Tuple[Optional[float], str]:
    mode = _normalize_ml_confidence_source(source_mode, "hybrid")
    if mode == "model_only":
        wr = _extract_ml_block_confidence_pct(data, phase)
        return wr, ("model_prob_max" if wr is not None else "n/a")
    if mode == "star_only":
        rec = _recommend_odds_for_block(data, phase)
        if rec is None:
            return None, "n/a"
        return float(rec.get("wr_pct")), "star_calibrated"
    # hybrid: prefer star-calibrated WR, fallback to model probability.
    rec = _recommend_odds_for_block(data, phase)
    if rec is not None:
        return float(rec.get("wr_pct")), "star_calibrated"
    wr = _extract_ml_block_confidence_pct(data, phase)
    return wr, ("model_prob_max" if wr is not None else "n/a")


def _star_block_sign(block: Optional[dict]) -> Optional[int]:
    if not isinstance(block, dict):
        return None
    signs = set()
    for raw_value in block.values():
        if not isinstance(raw_value, str) or not raw_value.strip().endswith('*'):
            continue
        value = _coerce_metric_value(raw_value)
        if value is None or value == 0:
            continue
        signs.add(1 if value > 0 else -1)
    if not signs:
        return None
    if len(signs) > 1:
        return 0
    return next(iter(signs))


