def _decorate_star_block_for_display(
    raw_block: Optional[dict],
    section: str,
    target_wr: int,
) -> Dict[str, Any]:
    """Render STAR ``*`` and display-only synergy ``**`` markers.

    Both marker types are purely visual. A single star means a STAR metric
    crossed the WR60 (or higher) threshold for this section; double stars mean
    duo/trio reached the fixed confirmation threshold. Display is intentionally
    decoupled from the block-level STAR
    diagnostics (``_star_block_diagnostics``), which can reject a block for
    reasons like sign-consistency or required-zero-metric checks even when
    one or more individual cells did pass the threshold. Without this
    decoupling the ``⭐ Star hits (WR60+):`` summary line and the per-section
    grid would disagree (e.g. summary shows ``All: Counterpick_1vs2 +6
    (WR75)`` but the grid prints ``Counterpick_1vs2: 6`` without a star).
    """
    src = raw_block if isinstance(raw_block, dict) else {}
    out = dict(src)
    for metric in _STAR_METRIC_ORDER:
        value = _coerce_metric_value(src.get(metric))
        if value is None or value == 0:
            # Re-format any leftover ``*``-suffixed string to plain numeric form.
            raw = out.get(metric)
            if isinstance(raw, str) and raw.strip().endswith("*"):
                if value is not None:
                    out[metric] = _format_metric_value(value)
            continue
        wr_level = _max_star_wr_level_for_metric(
            metric=metric,
            value=float(value),
            section=section,
        )
        if wr_level is None:
            # No WR level passes for this metric → leave the cell as plain number.
            raw = out.get(metric)
            if isinstance(raw, str) and raw.strip().endswith("*"):
                out[metric] = _format_metric_value(value)
            continue
        out[metric] = f"{_format_metric_value(value)}*"
    # Duo/trio confirmations deliberately do not belong to
    # ``_STAR_SIGNAL_METRICS`` and therefore cannot create STAR hits.  Their
    # fixed |index|>=9 marker is only a visual confirmation/veto hint.
    for metric in _SYNERGY_CONFIRMATION_METRICS:
        value = _coerce_metric_value(src.get(metric))
        if value is None:
            continue
        if abs(value) >= float(SYNERGY_CONFIRMATION_ABS_THRESHOLD):
            out[metric] = f"{_format_metric_value(value)}**"
        elif isinstance(out.get(metric), str) and out[metric].strip().endswith("*"):
            out[metric] = _format_metric_value(value)
    return out


def _should_delay_star_signal(
    early_output: Optional[dict],
    mid_output: Optional[dict],
    target_wr: int,
) -> tuple[bool, str]:
    early_diag = _star_block_diagnostics(
        raw_block=early_output,
        target_wr=target_wr,
        section="early_output",
    )
    late_diag = _star_block_diagnostics(
        raw_block=mid_output,
        target_wr=target_wr,
        section="mid_output",
    )
    has_early_star = bool(early_diag.get("valid"))
    has_late_star = bool(late_diag.get("valid"))
    early_sign = early_diag.get("sign") if has_early_star else None
    late_sign = late_diag.get("sign") if has_late_star else None

    if has_late_star and not has_early_star:
        return True, 'late_only_star'
    if has_early_star and has_late_star and early_sign != late_sign:
        return True, 'opposite_star_signs'
    return False, ''


def _target_side_from_sign(sign: Optional[int]) -> Optional[str]:
    if sign == 1:
        return "radiant"
    if sign == -1:
        return "dire"
    return None


def _networth_lead_is_unknown(
    radiant_lead: Any,
    game_time_seconds: Any,
    *,
    after_seconds: Optional[float] = None,
) -> bool:
    """True, когда networth-лид недоступен, а не «равный счёт».

    Живой фид (GC/SourceTV, cyberscore networth-график) отдаёт ровный 0 как
    «данных ещё нет»; отличить его от настоящего нуля можно только по времени —
    после ``NETWORTH_UNKNOWN_AFTER_SECONDS`` ровный 0 в проде не
    встречается. См. комментарий у константы.
    """
    if radiant_lead is None:
        return True
    try:
        lead = float(radiant_lead)
    except (TypeError, ValueError):
        return True
    if not math.isfinite(lead):
        return True
    if lead != 0.0:
        return False
    try:
        threshold = float(
            after_seconds
            if after_seconds is not None
            else NETWORTH_UNKNOWN_AFTER_SECONDS
        )
    except (TypeError, ValueError):
        threshold = 120.0
    try:
        gt = float(game_time_seconds)
    except (TypeError, ValueError):
        return False
    if not math.isfinite(gt):
        return False
    return gt >= threshold


def _target_networth_diff_from_radiant_lead(
    radiant_lead: Any,
    target_side: Optional[str],
    game_time_seconds: Any = None,
) -> Optional[float]:
    """NW-лид со стороны таргета; None — когда стороны нет или лид неизвестен.

    ``game_time_seconds`` включает проверку пустого фида
    (``_networth_lead_is_unknown``): ровный 0 после
    ``NETWORTH_UNKNOWN_AFTER_SECONDS`` — «данных нет», а не равный нетворс.
    Все NW-гейты трактуют None как «не сошлось» и ждут, поэтому пустой фид
    больше нигде не проходит за настоящий ноль. Без ``game_time_seconds``
    проверка не применяется (вызовы, где времени под рукой нет).
    """
    if target_side not in {"radiant", "dire"}:
        return None
    if game_time_seconds is not None and _networth_lead_is_unknown(
        radiant_lead, game_time_seconds
    ):
        return None
    try:
        lead_value = float(radiant_lead)
    except (TypeError, ValueError):
        return None
    return lead_value if target_side == "radiant" else -lead_value


def _networth_monitor_hold_check(
    *,
    current_game_time: Optional[float],
    target_networth_diff: Optional[float],
    monitor_threshold: Optional[float],
    hold_started_game_time: Optional[float],
    hold_seconds: Optional[float] = None,
    allow_zero_threshold: bool = False,
) -> Dict[str, Any]:
    try:
        hold_required_seconds = (
            float(hold_seconds)
            if hold_seconds is not None
            else float(NETWORTH_MONITOR_HOLD_SECONDS)
        )
    except (TypeError, ValueError):
        hold_required_seconds = float(NETWORTH_MONITOR_HOLD_SECONDS)
    hold_required_seconds = max(0.0, hold_required_seconds)

    try:
        threshold_value = float(monitor_threshold) if monitor_threshold is not None else None
    except (TypeError, ValueError):
        threshold_value = None
    try:
        target_diff_value = (
            float(target_networth_diff) if target_networth_diff is not None else None
        )
    except (TypeError, ValueError):
        target_diff_value = None
    try:
        game_time_value = float(current_game_time) if current_game_time is not None else None
    except (TypeError, ValueError):
        game_time_value = None
    try:
        hold_started_value = (
            float(hold_started_game_time)
            if hold_started_game_time is not None
            else None
        )
    except (TypeError, ValueError):
        hold_started_value = None

    enabled = bool(
        threshold_value is not None
        and (
            threshold_value > 0
            or (allow_zero_threshold and threshold_value >= 0)
        )
        and hold_required_seconds > 0.0
    )
    threshold_met = bool(
        threshold_value is not None
        and target_diff_value is not None
        and target_diff_value >= threshold_value
    )
    if not enabled:
        return {
            "enabled": False,
            "ready": threshold_met,
            "threshold_met": threshold_met,
            "hold_started_game_time": hold_started_value if threshold_met else None,
            "held_seconds": 0.0,
            "hold_seconds": hold_required_seconds,
        }
    if not threshold_met or game_time_value is None:
        return {
            "enabled": True,
            "ready": False,
            "threshold_met": threshold_met,
            "hold_started_game_time": None,
            "held_seconds": 0.0,
            "hold_seconds": hold_required_seconds,
        }
    effective_hold_started = (
        hold_started_value if hold_started_value is not None else game_time_value
    )
    held_seconds = max(0.0, game_time_value - effective_hold_started)
    return {
        "enabled": True,
        "ready": held_seconds >= hold_required_seconds,
        "threshold_met": True,
        "hold_started_game_time": effective_hold_started,
        "held_seconds": held_seconds,
        "hold_seconds": hold_required_seconds,
    }


def _late_star_pub_table_wr_level(late_wr_pct: Optional[float]) -> Optional[int]:
    try:
        wr_value = float(late_wr_pct) if late_wr_pct is not None else None
    except (TypeError, ValueError):
        wr_value = None
    if wr_value is None:
        return None
    candidate_levels = [60, 65, 70, 75, 80, 85, 90]
    return min(candidate_levels, key=lambda level: (abs(level - wr_value), level))


def _late_pub_table_has_thresholds(wr_level: Optional[int]) -> bool:
    if not isinstance(late_pub_comeback_table_thresholds_by_wr, dict):
        return False
    if not late_pub_comeback_table_thresholds_by_wr:
        return False
    try:
        normalized_wr = int(wr_level) if wr_level is not None else None
    except (TypeError, ValueError):
        normalized_wr = None
    if normalized_wr is None:
        return False
    thresholds = late_pub_comeback_table_thresholds_by_wr.get(normalized_wr)
    return isinstance(thresholds, dict) and bool(thresholds)


def _default_late_pub_table_wr_level() -> Optional[int]:
    if not isinstance(late_pub_comeback_table_thresholds_by_wr, dict):
        return None
    if 60 in late_pub_comeback_table_thresholds_by_wr:
        return 60
    available_levels = []
    for raw_level, thresholds in late_pub_comeback_table_thresholds_by_wr.items():
        if not isinstance(thresholds, dict) or not thresholds:
            continue
        try:
            available_levels.append(int(raw_level))
        except (TypeError, ValueError):
            continue
    return min(available_levels) if available_levels else None


def _late_pub_table_wr_level_from_values(*wr_values: Any) -> Optional[int]:
    # С 30.08.2026 networth-гейт late-ставок не зависит от WR конкретного
    # сигнала: строка таблицы одна на всех (`_late_pub_table_gate_wr_level`).
    # Аргументы сохранены, чтобы не трогать вызовы.
    return _late_pub_table_gate_wr_level()


def _late_pub_table_wr_level_from_signal_values(*wr_values: Any) -> Optional[int]:
    for value in wr_values:
        level = _late_star_pub_table_wr_level(value)
        if _late_pub_table_has_thresholds(level):
            return level
    default_level = _default_late_pub_table_wr_level()
    if _late_pub_table_has_thresholds(default_level):
        return default_level
    return None


def _late_pub_table_wr_level_from_payload(payload: Optional[Dict[str, Any]]) -> Optional[int]:
    # См. `_late_pub_table_wr_level_from_values`: уровень один на все сигналы.
    return _late_pub_table_gate_wr_level()


def _late_star_pub_table_decision(
    *,
    wr_level: Optional[int],
    game_time_seconds: Any,
    target_networth_diff: Optional[float],
    threshold_multiplier: float = 1.0,
) -> Dict[str, Any]:
    try:
        current_game_time = float(game_time_seconds) if game_time_seconds is not None else None
    except (TypeError, ValueError):
        current_game_time = None
    try:
        target_diff = float(target_networth_diff) if target_networth_diff is not None else None
    except (TypeError, ValueError):
        target_diff = None

    result: Dict[str, Any] = {
        "available": False,
        "ready": False,
        "wr_level": int(wr_level) if wr_level is not None else None,
        "current_minute": None,
        "source_minute": None,
        "threshold": None,
        "target_diff": target_diff,
    }

    if current_game_time is None:
        return result

    current_minute = int(max(0.0, current_game_time) // 60)
    result["current_minute"] = current_minute
    if current_game_time < float(LATE_PUB_COMEBACK_TABLE_START_SECONDS):
        return result

    if not isinstance(late_pub_comeback_table_thresholds_by_wr, dict):
        return result
    try:
        normalized_wr = int(wr_level) if wr_level is not None else None
    except (TypeError, ValueError):
        normalized_wr = None
    if normalized_wr is None:
        return result

    wr_thresholds = late_pub_comeback_table_thresholds_by_wr.get(normalized_wr)
    if not isinstance(wr_thresholds, dict) or not wr_thresholds:
        return result

    available_minutes = sorted(int(minute) for minute in wr_thresholds.keys())
    eligible_minutes = [minute for minute in available_minutes if minute <= current_minute]
    if not eligible_minutes:
        return result

    source_minute = max(eligible_minutes)
    threshold = wr_thresholds.get(source_minute)
    try:
        base_threshold_value = float(threshold) if threshold is not None else None
    except (TypeError, ValueError):
        base_threshold_value = None
    if base_threshold_value is None:
        return result
    try:
        mult = float(threshold_multiplier)
    except (TypeError, ValueError):
        mult = 1.0
    threshold_value = base_threshold_value * mult

    result["available"] = True
    result["source_minute"] = source_minute
    result["base_threshold"] = base_threshold_value
    result["threshold_multiplier"] = mult
    result["threshold"] = threshold_value
    result["ready"] = bool(target_diff is not None and float(target_diff) >= float(threshold_value))
    return result


def _late_pub_table_gate_wr_level() -> Optional[int]:
    """Единый WR-уровень таблицы для networth-гейта late-ставок.

    До 30.08.2026 каждый сигнал брал строку своего WR. Теперь строка одна на
    всех: `LATE_PUB_TABLE_GATE_WR_LEVEL`, а при 0 — самый высокий уровень
    загруженной таблицы. В тестах, где таблица подменяется одним уровнем,
    «самый высокий» = этот уровень, и подмена работает как раньше.
    """

    configured = int(LATE_PUB_TABLE_GATE_WR_LEVEL or 0)
    if configured > 0 and _late_pub_table_has_thresholds(configured):
        return configured
    if not isinstance(late_pub_comeback_table_thresholds_by_wr, dict):
        return None
    levels: List[int] = []
    for raw_level, thresholds in late_pub_comeback_table_thresholds_by_wr.items():
        if not isinstance(thresholds, dict) or not thresholds:
            continue
        try:
            levels.append(int(raw_level))
        except (TypeError, ValueError):
            continue
    return max(levels) if levels else None


def _late_pre27_watcher_available_levels(signal_group: str) -> List[int]:
    group_key = str(signal_group or "").strip().lower()
    payload = late_pre27_watcher_thresholds_by_group_wr.get(group_key)
    if not isinstance(payload, dict):
        return []
    levels: List[int] = []
    for raw_level, thresholds in payload.items():
        if not isinstance(thresholds, dict) or not thresholds:
            continue
        try:
            levels.append(int(raw_level))
        except (TypeError, ValueError):
            continue
    return sorted(set(levels))


def _late_pre27_watcher_has_thresholds(signal_group: str, wr_level: Optional[int]) -> bool:
    group_key = str(signal_group or "").strip().lower()
    try:
        normalized_wr = int(wr_level) if wr_level is not None else None
    except (TypeError, ValueError):
        normalized_wr = None
    if normalized_wr is None:
        return False
    payload = late_pre27_watcher_thresholds_by_group_wr.get(group_key)
    if not isinstance(payload, dict):
        return False
    thresholds = payload.get(normalized_wr)
    return isinstance(thresholds, dict) and bool(thresholds)


def _late_pre27_watcher_wr_level(signal_group: str, raw_wr: Any) -> Optional[int]:
    levels = _late_pre27_watcher_available_levels(signal_group)
    if not levels:
        return None
    try:
        wr_value = float(raw_wr) if raw_wr is not None else None
    except (TypeError, ValueError):
        wr_value = None
    if wr_value is None or not math.isfinite(wr_value):
        return levels[0]
    return min(levels, key=lambda level: (abs(float(level) - wr_value), -int(level)))


def _late_pre27_watcher_signal_wr(
    *,
    signal_group: str,
    late_wr_pct: Optional[float],
    all_wr_pct: Optional[float],
    selected_star_wr: Optional[int] = None,
) -> Optional[float]:
    group_key = str(signal_group or "").strip().lower()
    try:
        late_wr_value = float(late_wr_pct) if late_wr_pct is not None else None
    except (TypeError, ValueError):
        late_wr_value = None
    try:
        all_wr_value = float(all_wr_pct) if all_wr_pct is not None else None
    except (TypeError, ValueError):
        all_wr_value = None
    if group_key == "late_all" and late_wr_value is not None and all_wr_value is not None:
        return (late_wr_value + all_wr_value) / 2.0
    if late_wr_value is not None:
        return late_wr_value
    try:
        return float(selected_star_wr) if selected_star_wr is not None else None
    except (TypeError, ValueError):
        return None


def _late_pre27_watcher_monitor_config(
    *,
    signal_group: str,
    target_sign: Optional[int],
    late_wr_pct: Optional[float],
    all_wr_pct: Optional[float],
    selected_star_wr: Optional[int] = None,
    has_opposite_early_star: bool = False,
    all_opposes_target: Optional[bool] = None,
) -> Optional[Dict[str, Any]]:
    target_side = _target_side_from_sign(target_sign)
    if target_side not in {"radiant", "dire"}:
        return None
    group_key = str(signal_group or "").strip().lower()
    if group_key not in {"late_only", "late_all"}:
        return None
    signal_wr = _late_pre27_watcher_signal_wr(
        signal_group=group_key,
        late_wr_pct=late_wr_pct,
        all_wr_pct=all_wr_pct,
        selected_star_wr=selected_star_wr,
    )
    wr_level = _late_pre27_watcher_wr_level(group_key, signal_wr)
    if not _late_pre27_watcher_has_thresholds(group_key, wr_level):
        return None
    thresholds = late_pre27_watcher_thresholds_by_group_wr.get(group_key, {}).get(int(wr_level), {})
    return {
        "enabled": True,
        "profile": LATE_PRE27_WATCHER_PROFILE,
        "signal_group": group_key,
        "target_game_time": float(LATE_PUB_COMEBACK_TABLE_START_SECONDS),
        "target_sign": int(target_sign),
        "target_side": target_side,
        "wr_level": int(wr_level),
        "signal_wr": float(signal_wr) if signal_wr is not None else None,
        "thresholds_by_minute": {int(k): float(v) for k, v in thresholds.items()},
        "status_label": NETWORTH_STATUS_LATE_PRE27_WATCHER_WAIT,
        "has_opposite_early_star": bool(has_opposite_early_star),
        # Ранний релиз до 24:00 разрешён только когда точно известно, что all-блок
        # НЕ на стороне early (иначе — блок как раньше). None = неизвестно = блок.
        "opposite_early_release_allowed": bool(
            has_opposite_early_star and all_opposes_target is False
        ),
        # Phase 1 — flat 1000 за target в окне [4:00, 20:00).
        "flat_threshold_until_minute": 20,
        "flat_threshold_value": 1000.0,
        # Phase 2 — flat 800 за target в окне [20:00, минимальная минута).
        # Watcher comeback grid (исторические медианы) намеренно не используется
        # в этой ветке: для late star (с/без early/all) до минимальной минуты
        # dispatch допустим только когда target ведёт минимум на 800.
        # Верхняя граница ОБЯЗАНА совпадать с LATE_PUB_COMEBACK_TABLE_START_MINUTE:
        # иначе в промежутке между концом фазы и минимальной минутой порог молча
        # подменяется исторической сеткой (на 27-й минуте late_only это −3648…−4820
        # против +800), то есть окно, которое должно быть закрыто, наоборот
        # открывается на куда более слабом условии.
        "flat_phase2_from_minute": 20,
        "flat_phase2_until_minute": int(LATE_PUB_COMEBACK_TABLE_START_MINUTE),
        "flat_phase2_value": 800.0,
    }


def _all_block_opposes_target(
    *,
    has_selected_all_star: bool,
    selected_all_sign: Optional[int],
    target_sign: Optional[int],
) -> bool:
    """True, если all-блок стоит против таргета (то есть на стороне early).

    Отсутствие all-звезды — это НЕ "против": по замерам ранний релиз в такой
    ветке работает не хуже, чем при поддерживающем all.
    """
    return bool(
        has_selected_all_star
        and selected_all_sign in (-1, 1)
        and target_sign in (-1, 1)
        and int(selected_all_sign) != int(target_sign)
    )


def _opposite_early_release_window(
    source: Optional[Dict[str, Any]],
    current_game_time: Optional[float],
) -> Optional[Dict[str, Any]]:
    """Ранний релиз до 24:00, когда early-звезда у оппонента.

    Раньше такие сигналы жёстко блокировались до 24:00. Замер 01.08.2026
    (PRO n=1039, PUB n=18751; harness runtime/opp_early_release_*.py) показал:
    ставка на тех же матчах, но на 17-18-й минуте вместо 24-й, идёт по кэфу
    ~1.42 вместо ~1.35 при том же исходе (+25 п.п. ROI на перенесённых ставках).
    Матчи с неустойчивым лидом (WR ~37%) отсекаются требованием держать большой
    лид OPPOSITE_EARLY_RELEASE_HOLD_SECONDS игровых секунд подряд — без hold
    добавка мусора съедает весь выигрыш от цены (Δ ROI/сигнал ≈ 0).

    Окно закрыто, если all-блок стоит на стороне early (против таргета):
    там ранний релиз строго вреден (PRO Δ=-4.8 п.п. CI[-8.7,-1.3]).
    Неизвестный all (None на входе конфига) трактуется как запрет.

    Возвращает {"threshold", "hold_seconds"} либо None (блок как раньше).
    """
    if not OPPOSITE_EARLY_RELEASE_ENABLED:
        return None
    if not isinstance(source, dict):
        return None
    if not bool(source.get("opposite_early_release_allowed")):
        return None
    try:
        game_time_value = float(current_game_time) if current_game_time is not None else None
    except (TypeError, ValueError):
        game_time_value = None
    if game_time_value is None or game_time_value < OPPOSITE_EARLY_RELEASE_FROM_SECONDS:
        return None
    if OPPOSITE_EARLY_RELEASE_THRESHOLD <= 0:
        return None
    return {
        "threshold": float(OPPOSITE_EARLY_RELEASE_THRESHOLD),
        "hold_seconds": float(OPPOSITE_EARLY_RELEASE_HOLD_SECONDS),
    }


def _late_pre27_watcher_snapshot(
    source: Optional[Dict[str, Any]],
    game_time_seconds: Optional[float],
) -> Dict[str, Any]:
    try:
        current_game_time = float(game_time_seconds) if game_time_seconds is not None else None
    except (TypeError, ValueError):
        current_game_time = None
    if current_game_time is None or not isinstance(source, dict):
        return {"threshold": None, "status_label": ""}

    try:
        target_game_time = float(
            source.get("target_game_time")
            if source.get("target_game_time") is not None
            else LATE_PUB_COMEBACK_TABLE_START_SECONDS
        )
    except (TypeError, ValueError):
        target_game_time = float(LATE_PUB_COMEBACK_TABLE_START_SECONDS)
    if current_game_time < float(NETWORTH_GATE_SAME_SIGN_LANE_ADV_WINDOW_START_SECONDS):
        # Pre-4 min block: no dispatch before 4:00
        return {
            "threshold": None,
            "status_label": str(
                source.get("dispatch_status_label")
                or source.get("status_label")
                or NETWORTH_STATUS_LATE_PRE27_WATCHER_WAIT
            ),
        }
    if current_game_time >= target_game_time:
        return {"threshold": None, "status_label": ""}

    # Gate: if opposite team has an early star, block dispatch before 24:00 —
    # кроме окна раннего релиза по устойчивому большому лиду
    # (см. _opposite_early_release_window).
    if bool(source.get("has_opposite_early_star")) and current_game_time < 24 * 60:
        early_release = _opposite_early_release_window(source, current_game_time)
        if early_release is None:
            return {
                "threshold": None,
                "status_label": str(
                    source.get("dispatch_status_label")
                    or source.get("status_label")
                    or NETWORTH_STATUS_LATE_PRE27_WATCHER_WAIT
                ),
            }
        return {
            "threshold": float(early_release["threshold"]),
            "hold_seconds": float(early_release["hold_seconds"]),
            "status_label": str(
                source.get("networth_monitor_status")
                or source.get("status_label")
                or source.get("dispatch_status_label")
                or NETWORTH_STATUS_LATE_PRE27_WATCHER_WAIT
            ),
            "source_minute": int(max(0.0, current_game_time) // 60),
        }

    raw_thresholds = source.get("networth_monitor_thresholds_by_minute")
    if raw_thresholds is None:
        raw_thresholds = source.get("thresholds_by_minute")
    if not isinstance(raw_thresholds, dict) or not raw_thresholds:
        return {
            "threshold": None,
            "status_label": str(
                source.get("dispatch_status_label")
                or source.get("status_label")
                or NETWORTH_STATUS_LATE_PRE27_WATCHER_WAIT
            ),
        }

    current_minute = int(max(0.0, current_game_time) // 60)

    # Phase 1 — flat threshold (например 1000) до flat_threshold_until_minute.
    flat_threshold_until_minute = int(source.get("flat_threshold_until_minute") or 0)
    flat_threshold_value = float(source.get("flat_threshold_value") or 0.0)
    if flat_threshold_until_minute > 0 and current_minute < flat_threshold_until_minute:
        return {
            "threshold": flat_threshold_value if flat_threshold_value > 0 else None,
            "status_label": str(
                source.get("networth_monitor_status")
                or source.get("status_label")
                or source.get("dispatch_status_label")
                or NETWORTH_STATUS_LATE_PRE27_WATCHER_WAIT
            ),
            "source_minute": int(current_minute),
        }

    # Phase 2 — flat threshold (например 800) в окне
    # [flat_phase2_from_minute, flat_phase2_until_minute). Заменяет watcher grid
    # для веток с late star: до конца окна dispatch допустим только когда target
    # ведёт минимум на flat_phase2_value.
    flat_phase2_from_minute = int(source.get("flat_phase2_from_minute") or 0)
    flat_phase2_until_minute = int(source.get("flat_phase2_until_minute") or 0)
    flat_phase2_value = float(source.get("flat_phase2_value") or 0.0)
    if (
        flat_phase2_from_minute > 0
        and flat_phase2_until_minute > flat_phase2_from_minute
        and flat_phase2_from_minute <= current_minute < flat_phase2_until_minute
    ):
        return {
            "threshold": flat_phase2_value if flat_phase2_value > 0 else None,
            "status_label": str(
                source.get("networth_monitor_status")
                or source.get("status_label")
                or source.get("dispatch_status_label")
                or NETWORTH_STATUS_LATE_PRE27_WATCHER_WAIT
            ),
            "source_minute": int(current_minute),
        }

    thresholds_by_minute: Dict[int, float] = {}
    for raw_minute, raw_threshold in raw_thresholds.items():
        try:
            minute = int(raw_minute)
            threshold = float(raw_threshold)
        except (TypeError, ValueError):
            continue
        thresholds_by_minute[minute] = threshold
    eligible_minutes = [minute for minute in thresholds_by_minute if minute <= current_minute]
    if not eligible_minutes:
        return {
            "threshold": None,
            "status_label": str(
                source.get("dispatch_status_label")
                or source.get("status_label")
                or NETWORTH_STATUS_LATE_PRE27_WATCHER_WAIT
            ),
        }
    source_minute = max(eligible_minutes)
    return {
        "threshold": thresholds_by_minute.get(source_minute),
        "status_label": str(
            source.get("networth_monitor_status")
            or source.get("status_label")
            or source.get("dispatch_status_label")
            or NETWORTH_STATUS_LATE_PRE27_WATCHER_WAIT
        ),
        "source_minute": int(source_minute),
    }


def _all_only_watcher_available_levels() -> List[int]:
    payload = all_only_watcher_thresholds_by_wr
    if not isinstance(payload, dict):
        return []
    levels: List[int] = []
    for raw_level, thresholds in payload.items():
        if not isinstance(thresholds, dict) or not thresholds:
            continue
        try:
            levels.append(int(raw_level))
        except (TypeError, ValueError):
            continue
    return sorted(set(levels))


def _all_only_watcher_has_thresholds(wr_level: Optional[int]) -> bool:
    try:
        normalized_wr = int(wr_level) if wr_level is not None else None
    except (TypeError, ValueError):
        normalized_wr = None
    if normalized_wr is None:
        return False
    payload = all_only_watcher_thresholds_by_wr
    if not isinstance(payload, dict):
        return False
    thresholds = payload.get(normalized_wr)
    return isinstance(thresholds, dict) and bool(thresholds)


def _all_only_watcher_wr_level(raw_wr: Any) -> Optional[int]:
    levels = _all_only_watcher_available_levels()
    if not levels:
        return None
    try:
        wr_value = float(raw_wr) if raw_wr is not None else None
    except (TypeError, ValueError):
        wr_value = None
    if wr_value is None or not math.isfinite(wr_value):
        return levels[0]
    return min(levels, key=lambda level: (abs(float(level) - wr_value), -int(level)))


def _all_only_watcher_monitor_config(
    *,
    target_sign: Optional[int],
    all_wr_pct: Optional[float],
    selected_star_wr: Optional[int] = None,
) -> Optional[Dict[str, Any]]:
    target_side = _target_side_from_sign(target_sign)
    if target_side not in {"radiant", "dire"}:
        return None
    try:
        signal_wr = float(all_wr_pct) if all_wr_pct is not None else None
    except (TypeError, ValueError):
        signal_wr = None
    if signal_wr is None:
        try:
            signal_wr = float(selected_star_wr) if selected_star_wr is not None else None
        except (TypeError, ValueError):
            signal_wr = None
    wr_level = _all_only_watcher_wr_level(signal_wr)
    if not _all_only_watcher_has_thresholds(wr_level):
        return None
    thresholds = all_only_watcher_thresholds_by_wr.get(int(wr_level), {})
    return {
        "enabled": True,
        "profile": ALL_ONLY_WATCHER_PROFILE,
        "target_game_time": float(ALL_ONLY_WATCHER_TARGET_GAME_TIME_SECONDS),
        "target_sign": int(target_sign),
        "target_side": target_side,
        "wr_level": int(wr_level),
        "signal_wr": float(signal_wr) if signal_wr is not None else None,
        "thresholds_by_minute": {int(k): float(v) for k, v in thresholds.items()},
        "status_label": NETWORTH_STATUS_ALL_ONLY_WATCHER_WAIT,
        "timeout_add_url_reason": "star_signal_rejected_all_only_watcher_timeout",
        "timeout_status_label": NETWORTH_STATUS_ALL_ONLY_WATCHER_TIMEOUT_NO_SEND,
    }


def _all_only_watcher_snapshot(
    source: Optional[Dict[str, Any]],
    game_time_seconds: Optional[float],
) -> Dict[str, Any]:
    try:
        current_game_time = float(game_time_seconds) if game_time_seconds is not None else None
    except (TypeError, ValueError):
        current_game_time = None
    if current_game_time is None or not isinstance(source, dict):
        return {"threshold": None, "status_label": "", "drop_without_fallback": False}

    try:
        target_game_time = float(
            source.get("target_game_time")
            if source.get("target_game_time") is not None
            else ALL_ONLY_WATCHER_TARGET_GAME_TIME_SECONDS
        )
    except (TypeError, ValueError):
        target_game_time = float(ALL_ONLY_WATCHER_TARGET_GAME_TIME_SECONDS)
    if current_game_time < float(NETWORTH_GATE_EARLY_WINDOW_END_SECONDS):
        # Early window: before 4:00 we never send (pre-4 block); between 4:00
        # and 10:00 expose the 4-10 networth gate threshold so a clearly
        # dominating all-only signal can be released before the minute-10 table
        # window kicks in.
        if current_game_time >= float(NETWORTH_GATE_ALL_ONLY_EARLY_WINDOW_START_SECONDS):
            return {
                "threshold": float(NETWORTH_GATE_ALL_ONLY_EARLY_MIN_DIFF),
                "status_label": str(
                    source.get("dispatch_status_label")
                    or source.get("status_label")
                    or NETWORTH_STATUS_ALL_ONLY_EARLY_3_10_SEND
                ),
                "drop_without_fallback": False,
            }
        return {
            "threshold": None,
            "status_label": str(
                source.get("dispatch_status_label")
                or source.get("status_label")
                or NETWORTH_STATUS_ALL_ONLY_EARLY_PRE3_WAIT
            ),
            "drop_without_fallback": False,
        }
    if current_game_time >= target_game_time:
        return {
            "threshold": None,
            "status_label": str(
                source.get("timeout_status_label")
                or NETWORTH_STATUS_ALL_ONLY_WATCHER_TIMEOUT_NO_SEND
            ),
            "drop_without_fallback": True,
        }

    raw_thresholds = source.get("networth_monitor_thresholds_by_minute")
    if raw_thresholds is None:
        raw_thresholds = source.get("thresholds_by_minute")
    if not isinstance(raw_thresholds, dict) or not raw_thresholds:
        return {
            "threshold": None,
            "status_label": str(
                source.get("dispatch_status_label")
                or source.get("status_label")
                or NETWORTH_STATUS_ALL_ONLY_WATCHER_WAIT
            ),
            "drop_without_fallback": False,
        }

    current_minute = int(max(0.0, current_game_time) // 60)
    thresholds_by_minute: Dict[int, float] = {}
    for raw_minute, raw_threshold in raw_thresholds.items():
        try:
            minute = int(raw_minute)
            threshold = float(raw_threshold)
        except (TypeError, ValueError):
            continue
        thresholds_by_minute[minute] = threshold
    eligible_minutes = [minute for minute in thresholds_by_minute if minute <= current_minute]
    if not eligible_minutes:
        return {
            "threshold": None,
            "status_label": str(
                source.get("dispatch_status_label")
                or source.get("status_label")
                or NETWORTH_STATUS_ALL_ONLY_WATCHER_WAIT
            ),
            "drop_without_fallback": False,
        }
    source_minute = max(eligible_minutes)
    return {
        "threshold": thresholds_by_minute.get(source_minute),
        "status_label": str(
            source.get("networth_monitor_status")
            or source.get("status_label")
            or source.get("dispatch_status_label")
            or NETWORTH_STATUS_ALL_ONLY_WATCHER_WAIT
        ),
        "source_minute": int(source_minute),
        "drop_without_fallback": False,
    }


def _resolve_signal_wr_for_elo_guard(
    *,
    target_side: Optional[str],
    has_selected_early_star: bool,
    has_selected_late_star: bool,
    selected_early_sign: Optional[int],
    selected_late_sign: Optional[int],
    early_wr_pct: Optional[float],
    late_wr_pct: Optional[float],
    has_selected_all_star: bool = False,
    selected_all_sign: Optional[int] = None,
    all_wr_pct: Optional[float] = None,
) -> Optional[Dict[str, Any]]:
    candidates: List[Tuple[str, float]] = []
    early_side = _target_side_from_sign(selected_early_sign) if has_selected_early_star else None
    late_side = _target_side_from_sign(selected_late_sign) if has_selected_late_star else None
    all_side = _target_side_from_sign(selected_all_sign) if has_selected_all_star else None
    if (
        has_selected_early_star
        and early_wr_pct is not None
        and early_side == target_side
    ):
        candidates.append(("early", float(early_wr_pct)))
    if (
        has_selected_late_star
        and late_wr_pct is not None
        and late_side == target_side
    ):
        candidates.append(("late", float(late_wr_pct)))
    if (
        has_selected_all_star
        and all_wr_pct is not None
        and all_side == target_side
    ):
        candidates.append(("all", float(all_wr_pct)))
    if not candidates:
        return None
    candidates.sort(key=lambda item: item[1], reverse=True)
    best_source, best_wr_pct = candidates[0]
    if len(candidates) > 1:
        candidate_sources = {label for label, _value in candidates}
        best_source = "best_of_star_blocks" if "all" in candidate_sources else "best_of_early_late"
    return {
        "wr_pct": float(best_wr_pct),
        "source": best_source,
        "candidates": {label: float(value) for label, value in candidates},
    }


def _elo_underdog_guard_decision(
    *,
    team_elo_meta: Optional[Dict[str, Any]],
    target_side: Optional[str],
    signal_wr_pct: Optional[float],
    favorite_edge_pp: float = ELO_UNDERDOG_GUARD_FAVORITE_EDGE_PP,
    min_signal_wr: float = ELO_UNDERDOG_GUARD_MIN_SIGNAL_WR,
) -> Optional[Dict[str, Any]]:
    return None


def _team_elo_wr_for_side(
    team_elo_meta: Optional[Dict[str, Any]],
    side: Optional[str],
) -> Optional[float]:
    if not isinstance(team_elo_meta, dict):
        return None
    if side == "radiant":
        keys = ("raw_radiant_wr", "adjusted_radiant_wr")
    elif side == "dire":
        keys = ("raw_dire_wr", "adjusted_dire_wr")
    else:
        return None
    for key in keys:
        try:
            return float(team_elo_meta.get(key))
        except (TypeError, ValueError):
            continue
    return None


def _team_elo_abs_diff_for_guard(team_elo_meta: Optional[Dict[str, Any]]) -> Optional[float]:
    if not isinstance(team_elo_meta, dict):
        return None
    for key in ("raw_diff", "adjusted_diff", "elo_diff", "team_elo_diff"):
        try:
            return abs(float(team_elo_meta.get(key)))
        except (TypeError, ValueError):
            continue
    return None


def _team_elo_base_rating_for_side(
    team_elo_meta: Optional[Dict[str, Any]],
    side: Optional[str],
) -> Optional[float]:
    if not isinstance(team_elo_meta, dict):
        return None
    if side == "radiant":
        key = "radiant_base_rating"
    elif side == "dire":
        key = "dire_base_rating"
    else:
        return None
    try:
        return float(team_elo_meta.get(key))
    except (TypeError, ValueError):
        return None


def _team_elo_rank_for_side(
    team_elo_meta: Optional[Dict[str, Any]],
    side: Optional[str],
) -> Optional[int]:
    if not isinstance(team_elo_meta, dict):
        return None
    if side == "radiant":
        key = "radiant_leaderboard_rank"
    elif side == "dire":
        key = "dire_leaderboard_rank"
    else:
        return None
    try:
        rank_value = team_elo_meta.get(key)
        return int(rank_value) if rank_value is not None else None
    except (TypeError, ValueError):
        return None


def _elo_block_wr_penalty_pp(
    team_elo_meta: Optional[Dict[str, Any]],
    target_side: Optional[str],
) -> float:
    abs_diff = _team_elo_abs_diff_for_guard(team_elo_meta)
    if abs_diff is not None and abs_diff < float(ELO_GUARD_MIN_ABS_DIFF):
        return 0.0
    side_wr = _team_elo_wr_for_side(team_elo_meta, target_side)
    if side_wr is None:
        return 0.0
    return max(0.0, 50.0 - float(side_wr))


def _apply_elo_block_wr_guard(
    *,
    diag: Dict[str, Any],
    block_wr_pct: Optional[float],
    team_elo_meta: Optional[Dict[str, Any]],
    min_adjusted_wr: float = ELO_BLOCK_WR_MIN_AFTER_PENALTY,
) -> Dict[str, Any]:
    out = dict(diag or {})
    raw_valid = bool(out.get("valid"))
    out["raw_valid"] = raw_valid
    out["raw_status"] = str(out.get("status") or "unknown")
    target_side = _target_side_from_sign(out.get("sign"))
    target_elo_wr = _team_elo_wr_for_side(team_elo_meta, target_side)
    penalty_pp = _elo_block_wr_penalty_pp(team_elo_meta, target_side)
    adjusted_wr_pct: Optional[float]
    try:
        adjusted_wr_pct = (
            float(block_wr_pct) - float(penalty_pp)
            if block_wr_pct is not None
            else None
        )
    except (TypeError, ValueError):
        adjusted_wr_pct = None

    out["block_wr_pct"] = float(block_wr_pct) if block_wr_pct is not None else None
    out["elo_target_side"] = target_side
    out["elo_target_wr"] = float(target_elo_wr) if target_elo_wr is not None else None
    out["elo_wr_penalty_pp"] = float(penalty_pp)
    out["elo_adjusted_wr_pct"] = float(adjusted_wr_pct) if adjusted_wr_pct is not None else None
    out["elo_block_min_wr"] = float(min_adjusted_wr)
    return out


def _top25_late_elo_block_opposite_monitor_override(
    *,
    team_elo_meta: Optional[Dict[str, Any]],
    selected_early_diag: Dict[str, Any],
    selected_late_diag: Dict[str, Any],
    raw_selected_early_diag: Dict[str, Any],
    raw_selected_late_diag: Dict[str, Any],
) -> Optional[Dict[str, Any]]:
    if not STAR_ALLOW_TOP25_LATE_ELO_BLOCK_OPPOSITE_MONITOR:
        return None
    if bool(selected_late_diag.get("valid")):
        return None
    if str(selected_late_diag.get("status") or "") != "elo_wr_below_min60":
        return None
    if not bool(raw_selected_late_diag.get("valid")):
        return None
    raw_late_sign = raw_selected_late_diag.get("sign")
    if raw_late_sign not in (-1, 1):
        return None

    override_mode: Optional[str] = None
    raw_early_sign = raw_selected_early_diag.get("sign")
    if bool(selected_early_diag.get("valid")) and bool(raw_selected_early_diag.get("valid")):
        if raw_early_sign not in (-1, 1):
            return None
        if raw_early_sign == raw_late_sign:
            return None
        override_mode = "opposite_signs"
    else:
        raw_early_status = str(raw_selected_early_diag.get("status") or "")
        selected_early_status = str(selected_early_diag.get("status") or "")
        if raw_early_status != "no_hits" or selected_early_status != "no_hits":
            return None
        override_mode = "no_early"

    late_side = _target_side_from_sign(raw_late_sign)
    if late_side not in {"radiant", "dire"}:
        return None
    late_rank = _team_elo_rank_for_side(team_elo_meta, late_side)
    if late_rank is None or late_rank > int(TOP25_LATE_ELO_BLOCK_RANK_THRESHOLD):
        return None
    late_elo_wr = _team_elo_wr_for_side(team_elo_meta, late_side)
    return {
        "enabled": True,
        "target_sign": int(raw_late_sign),
        "target_side": late_side,
        "leaderboard_rank": int(late_rank),
        "elo_target_wr": float(late_elo_wr) if late_elo_wr is not None else None,
        "mode": override_mode,
        "window_start_seconds": float(NETWORTH_GATE_LATE_TOP25_ELO_BLOCK_WINDOW_START_SECONDS),
        "window_threshold": float(NETWORTH_GATE_LATE_TOP25_ELO_BLOCK_DIFF),
        "target_game_time": float(DELAYED_SIGNAL_TARGET_GAME_TIME),
        "profile": "late_top25_elo_block_opposite_monitor",
    }


def _opposite_signs_early90_monitor_config(
    *,
    team_elo_meta: Optional[Dict[str, Any]],
    early_wr_pct: Optional[float],
    selected_early_sign: Optional[int],
    selected_late_sign: Optional[int],
) -> Optional[Dict[str, Any]]:
    try:
        early_wr_value = float(early_wr_pct) if early_wr_pct is not None else None
    except (TypeError, ValueError):
        early_wr_value = None
    if early_wr_value is None or early_wr_value < float(OPPOSITE_SIGNS_EARLY90_TRIGGER_WR):
        return None
    early_side = _target_side_from_sign(selected_early_sign)
    late_side = _target_side_from_sign(selected_late_sign)
    if early_side not in {"radiant", "dire"} or late_side not in {"radiant", "dire"}:
        return None
    if early_side == late_side:
        return None

    early_elo_wr = _team_elo_wr_for_side(team_elo_meta, early_side)
    late_elo_wr = _team_elo_wr_for_side(team_elo_meta, late_side)
    elo_gap_pp = None
    early_is_elo_underdog_by_gap = False
    if early_elo_wr is not None and late_elo_wr is not None:
        elo_gap_pp = float(late_elo_wr - early_elo_wr)
        early_is_elo_underdog_by_gap = bool(
            late_elo_wr > early_elo_wr and elo_gap_pp >= float(OPPOSITE_SIGNS_EARLY90_ELO_GAP_PP)
        )

    threshold_10_to_20 = (
        float(NETWORTH_GATE_LATE_OPPOSITE_EARLY90_UNDERDOG_10_TO_20_DIFF)
        if early_is_elo_underdog_by_gap
        else float(NETWORTH_GATE_LATE_OPPOSITE_DIFF)
    )
    status_10_to_20 = (
        NETWORTH_STATUS_LATE_CONFLICT_WAIT_1500
        if early_is_elo_underdog_by_gap
        else NETWORTH_STATUS_LATE_CONFLICT_WAIT_3000
    )
    return {
        "enabled": True,
        "profile": "late_only_opposite_signs_early90",
        "early_side": early_side,
        "late_side": late_side,
        "early_wr_pct": float(early_wr_value),
        "early_elo_wr": float(early_elo_wr) if early_elo_wr is not None else None,
        "late_elo_wr": float(late_elo_wr) if late_elo_wr is not None else None,
        "elo_gap_pp": float(elo_gap_pp) if elo_gap_pp is not None else None,
        "early_is_elo_underdog_by_gap": bool(early_is_elo_underdog_by_gap),
        "target_game_time": float(LATE_PUB_COMEBACK_TABLE_START_SECONDS),
        "dispatch_status_label": NETWORTH_STATUS_LATE_OPPOSITE_EARLY90_WAIT_20_20,
        "send_on_target_game_time": False,
        "wait_until_target_then_post_target_comeback": True,
    }


def _star_recommendation_level(
    rec: Optional[Dict[str, Any]],
    wr_pct: Optional[float],
) -> Optional[int]:
    raw_level = rec.get("level") if isinstance(rec, dict) else None
    for candidate in (raw_level, wr_pct):
        try:
            value = float(candidate) if candidate is not None else None
        except (TypeError, ValueError):
            value = None
        if value is None or not math.isfinite(value):
            continue
        return _nearest_star_wr_level(value, [60, 65, 70, 75, 80, 85, 90])
    return None


def _late_pre27_dominance_thresholds_for_delta(delta_level: int) -> Tuple[str, float, float, float]:
    if delta_level <= -15:
        return "late_much_weaker", 3000.0, 3000.0, 5000.0
    if delta_level < 0:
        return "late_weaker", 4000.0, 2500.0, 2500.0
    if delta_level == 0:
        return "equal", 2500.0, 800.0, 500.0
    if delta_level < 15:
        return "late_stronger", 2000.0, 500.0, 0.0
    return "late_much_stronger", 800.0, 0.0, 0.0


def _late_pre27_dominance_monitor_config(
    *,
    has_selected_early_star: bool,
    selected_early_sign: Optional[int],
    has_selected_late_star: bool,
    selected_late_sign: Optional[int],
    early_rec: Optional[Dict[str, Any]],
    late_rec: Optional[Dict[str, Any]],
    early_wr_pct: Optional[float],
    late_wr_pct: Optional[float],
    all_opposes_target: Optional[bool] = None,
) -> Optional[Dict[str, Any]]:
    if not (
        has_selected_early_star
        and has_selected_late_star
        and selected_early_sign in (-1, 1)
        and selected_late_sign in (-1, 1)
        and selected_early_sign != selected_late_sign
    ):
        return None

    early_level = _star_recommendation_level(early_rec, early_wr_pct)
    late_level = _star_recommendation_level(late_rec, late_wr_pct)
    if early_level is None or late_level is None:
        return None

    delta_level = int(late_level) - int(early_level)
    bucket, threshold_10_to_16, threshold_17_to_19, threshold_20_to_26 = (
        _late_pre27_dominance_thresholds_for_delta(delta_level)
    )
    # For opposite-sign scenarios with equal or similar WR, the early-star is ALWAYS
    # on the opposite side of the late-star target. Block dispatch before 20:00 to let
    # the early window fully play out.
    has_opposite_early = bool(
        has_selected_early_star
        and selected_early_sign in (-1, 1)
        and selected_late_sign in (-1, 1)
        and selected_early_sign != selected_late_sign
    )
    return {
        "enabled": True,
        "profile": LATE_PRE27_DOMINANCE_PROFILE,
        "target_game_time": float(LATE_PUB_COMEBACK_TABLE_START_SECONDS),
        "target_sign": int(selected_late_sign),
        "target_side": _target_side_from_sign(selected_late_sign),
        "early_wr_level": int(early_level),
        "late_wr_level": int(late_level),
        "delta_level": int(delta_level),
        "delta_bucket": bucket,
        "threshold_10_to_16": float(threshold_10_to_16),
        "threshold_17_to_19": float(threshold_17_to_19),
        "threshold_20_to_26": float(threshold_20_to_26),
        "status_10_to_16": NETWORTH_STATUS_LATE_PRE27_DOMINANCE_WAIT,
        "status_17_to_19": NETWORTH_STATUS_LATE_PRE27_DOMINANCE_WAIT,
        "status_20_to_26": NETWORTH_STATUS_LATE_PRE27_DOMINANCE_WAIT,
        "hold_zero_threshold": True,
        "has_opposite_early_star": has_opposite_early,
        # Ранний релиз до 24:00 разрешён только когда точно известно, что all-блок
        # НЕ на стороне early (иначе — блок как раньше). None = неизвестно = блок.
        "opposite_early_release_allowed": bool(
            has_opposite_early and all_opposes_target is False
        ),
    }


def _late_pre27_dominance_snapshot(
    source: Optional[Dict[str, Any]],
    game_time_seconds: Optional[float],
) -> Dict[str, Any]:
    try:
        current_game_time = float(game_time_seconds) if game_time_seconds is not None else None
    except (TypeError, ValueError):
        current_game_time = None
    if current_game_time is None or not isinstance(source, dict):
        return {"threshold": None, "status_label": ""}

    try:
        target_game_time = float(
            source.get("target_game_time")
            if source.get("target_game_time") is not None
            else LATE_PUB_COMEBACK_TABLE_START_SECONDS
        )
    except (TypeError, ValueError):
        target_game_time = float(LATE_PUB_COMEBACK_TABLE_START_SECONDS)

    if current_game_time < float(NETWORTH_GATE_EARLY_WINDOW_END_SECONDS):
        return {
            "threshold": None,
            "status_label": str(
                source.get("dispatch_status_label")
                or NETWORTH_STATUS_LATE_PRE27_DOMINANCE_WAIT
            ),
        }
    if current_game_time >= target_game_time:
        return {"threshold": None, "status_label": ""}

    # Gate: if the opposite team has an early star, block dispatch before 24:00
    # (opposite early = early-star on a different side than target/late). This prevents
    # short-lived netw spikes at 10-23 min from triggering against still-active early window.
    # Исключение — окно раннего релиза по устойчивому большому лиду
    # (см. _opposite_early_release_window).
    if bool(source.get("has_opposite_early_star")) and current_game_time < 24 * 60:
        early_release = _opposite_early_release_window(source, current_game_time)
        if early_release is None:
            return {
                "threshold": None,
                "status_label": str(
                    source.get("dispatch_status_label")
                    or NETWORTH_STATUS_LATE_PRE27_DOMINANCE_WAIT
                ),
            }
        return {
            "threshold": float(early_release["threshold"]),
            "hold_seconds": float(early_release["hold_seconds"]),
            "status_label": str(
                source.get("dispatch_status_label")
                or NETWORTH_STATUS_LATE_PRE27_DOMINANCE_WAIT
            ),
        }

    if current_game_time < 17 * 60:
        threshold_key = "threshold_10_to_16"
        status_key = "status_10_to_16"
    elif current_game_time < 20 * 60:
        threshold_key = "threshold_17_to_19"
        status_key = "status_17_to_19"
    else:
        # Окно [20:00, target_game_time): для всех dominance-веток с late star
        # требуется только flat 800 за target. Старая сетка по delta_level
        # (threshold_20_to_26) намеренно не используется здесь — dispatch
        # допустим только когда target ведёт минимум на 800 NW. Верхняя граница
        # окна — target_game_time (проверка выше), поэтому сдвиг минимальной
        # минуты растягивает flat-800 сам собой; имена полей *_20_to_26
        # исторические и границу окна не задают.
        return {
            "threshold": 800.0,
            "status_label": str(
                source.get("networth_monitor_status_20_to_26")
                or source.get("status_20_to_26")
                or source.get("dispatch_status_label")
                or NETWORTH_STATUS_LATE_PRE27_DOMINANCE_WAIT
            ),
        }

    threshold_raw = source.get(
        f"networth_monitor_{threshold_key}",
        source.get(threshold_key),
    )
    try:
        threshold = float(threshold_raw) if threshold_raw is not None else None
    except (TypeError, ValueError):
        threshold = None
    return {
        "threshold": threshold,
        "status_label": str(
            source.get(f"networth_monitor_{status_key}")
            or source.get(status_key)
            or source.get("dispatch_status_label")
            or NETWORTH_STATUS_LATE_PRE27_DOMINANCE_WAIT
        ),
    }


def _opposite_signs_early90_tier1_fast_release_config(
    *,
    team_elo_meta: Optional[Dict[str, Any]],
    early_wr_pct: Optional[float],
    selected_early_sign: Optional[int],
    selected_late_sign: Optional[int],
    radiant_team_id: Optional[int],
    dire_team_id: Optional[int],
) -> Optional[Dict[str, Any]]:
    del team_elo_meta
    del early_wr_pct
    del selected_early_sign
    del selected_late_sign
    del radiant_team_id
    del dire_team_id
    return None


def _synergy_confirmation_snapshot_for_target(
    *,
    target_side: Optional[str],
    early_output: Optional[dict] = None,
    early_end_output: Optional[dict] = None,
    mid_output: Optional[dict] = None,
    all_output: Optional[dict] = None,
) -> Dict[str, Any]:
    """Collect display-only duo/trio confirmations relative to the target.

    Synergy confirmations never become STAR hits.  A confirmation whose
    absolute index reaches the fixed threshold and whose sign points at the
    opposite side is persisted as a stake veto for every immediate/delayed
    dispatch path.
    """
    target_sign = (
        1 if target_side == "radiant" else -1 if target_side == "dire" else None
    )
    confirmations: List[Dict[str, Any]] = []
    conflicts: List[Dict[str, Any]] = []
    blocks = (
        ("early", early_output),
        ("early_winner", early_end_output),
        ("late", mid_output),
        ("all", all_output),
    )
    for phase, raw_block in blocks:
        block = raw_block if isinstance(raw_block, dict) else {}
        for metric in _SYNERGY_CONFIRMATION_METRICS:
            value = _coerce_metric_value(block.get(metric))
            if value is None or not math.isfinite(value):
                continue
            if abs(value) < float(SYNERGY_CONFIRMATION_ABS_THRESHOLD):
                continue
            sign = 1 if value > 0 else -1 if value < 0 else None
            if sign is None:
                continue
            item = {
                "phase": phase,
                "metric": metric,
                "value": float(value),
                "sign": int(sign),
                "side": _target_side_from_sign(sign),
            }
            confirmations.append(item)
            if target_sign in (-1, 1) and sign != target_sign:
                conflicts.append(dict(item))
    return {
        "threshold": float(SYNERGY_CONFIRMATION_ABS_THRESHOLD),
        "target_side": target_side,
        "confirmations": confirmations,
        "conflicts": conflicts,
        "has_opposite": bool(conflicts),
    }


def _retarget_stake_context_synergy_confirmation(
    stake_multiplier_context: Optional[Dict[str, Any]],
    *,
    target_side: Optional[str],
    early_output: Optional[dict] = None,
    early_end_output: Optional[dict] = None,
    mid_output: Optional[dict] = None,
    all_output: Optional[dict] = None,
) -> Dict[str, Any]:
    """Copy a stake context and recompute synergy veto for a new target."""
    context = (
        dict(stake_multiplier_context)
        if isinstance(stake_multiplier_context, dict)
        else {}
    )
    snapshot = _synergy_confirmation_snapshot_for_target(
        target_side=target_side,
        early_output=early_output,
        early_end_output=early_end_output,
        mid_output=mid_output,
        all_output=all_output,
    )
    context["target_side"] = target_side
    context["synergy_confirmation_snapshot"] = snapshot
    context["synergy_opposes_target"] = bool(snapshot.get("has_opposite"))
    return context


def _stake_multiplier_for_signal(
    *,
    team_elo_meta: Optional[Dict[str, Any]],
    target_side: Optional[str],
    selected_early_sign: Optional[int],
    selected_late_sign: Optional[int],
    has_selected_early_star: bool,
    has_selected_late_star: bool,
    early_wr_pct: Optional[float],
    late_wr_pct: Optional[float],
    game_time_seconds: Optional[float],
    radiant_lead: Optional[float],
    late_star_hit_count: Optional[int] = None,
    target_rating: Optional[float] = None,
    opposite_rating: Optional[float] = None,
    target_elo_wr: Optional[float] = None,
    force_half_due_to_early_no_valid_late: bool = False,
    selected_all_sign: Optional[int] = None,
    has_selected_all_star: bool = False,
    all_star_hit_count: Optional[int] = None,
    early_star_hit_count: Optional[int] = None,
    late_star_hit_metrics: Optional[List[str]] = None,
    synergy_opposes_target: bool = False,
) -> float:
    if target_side not in {"radiant", "dire"}:
        return 1
    # A strong duo/trio against the actual target is an unconditional size
    # veto.  Apply it before STAR dispatch-side fallbacks so no exceptional
    # branch can return x1 merely because its selected block points elsewhere.
    if synergy_opposes_target:
        return 0.5

    early_side = _target_side_from_sign(selected_early_sign)
    late_side = _target_side_from_sign(selected_late_sign)
    all_side = _target_side_from_sign(selected_all_sign)
    dispatch_side = (
        late_side
        if late_side in {"radiant", "dire"}
        else early_side
        if early_side in {"radiant", "dire"}
        else all_side
        if all_side in {"radiant", "dire"}
        else None
    )
    if dispatch_side not in {"radiant", "dire"}:
        return 1
    if dispatch_side != target_side:
        return 1
    if force_half_due_to_early_no_valid_late:
        return 0.5

    # Count total valid blocks and total hit metrics across all valid blocks
    valid_block_count = sum([
        bool(has_selected_early_star),
        bool(has_selected_late_star),
        bool(has_selected_all_star),
    ])

    # Rule: if only 1 valid block total with only 1 star-hit metric → 0.5
    if valid_block_count == 1:
        try:
            early_hits = int(early_star_hit_count or 0) if has_selected_early_star else 0
        except (TypeError, ValueError):
            early_hits = 0
        try:
            late_hits = int(late_star_hit_count or 0) if has_selected_late_star else 0
        except (TypeError, ValueError):
            late_hits = 0
        try:
            all_hits = int(all_star_hit_count or 0) if has_selected_all_star else 0
        except (TypeError, ValueError):
            all_hits = 0
        total_hits = early_hits + late_hits + all_hits
        if total_hits <= 1:
            return 0.5

    # All-only (no early, no late) → always 0.5 regardless of hit count
    if not has_selected_early_star and not has_selected_late_star:
        return 0.5

    # Rule: if late and all blocks point at opposite sides, the signal is
    # contradictory enough to cap the stake at 0.5.
    if (
        has_selected_late_star
        and has_selected_all_star
        and late_side in {"radiant", "dire"}
        and all_side in {"radiant", "dire"}
        and late_side != all_side
    ):
        return 0.5

    try:
        early_wr_value = float(early_wr_pct) if early_wr_pct is not None else None
    except (TypeError, ValueError):
        early_wr_value = None
    try:
        late_wr_value = float(late_wr_pct) if late_wr_pct is not None else None
    except (TypeError, ValueError):
        late_wr_value = None

    try:
        late_star_hit_count_value = int(late_star_hit_count) if late_star_hit_count is not None else None
    except (TypeError, ValueError):
        late_star_hit_count_value = None
    if not has_selected_late_star:
        late_star_hit_count_value = 0

    # Any multiplier above 0.5 requires at least 2 late star-hits. Fewer than 2
    # hits — including an unknown (None) hit count — caps the stake at 0.5.
    if late_star_hit_count_value is None or late_star_hit_count_value < 2:
        return 0.5

    # x1/x2/x3 require star hits on ALL 3 core metrics (cp1vs1, cp1vs2, solo).
    # If any of the 3 is missing from hit_metrics → cap at 0.5.
    if late_star_hit_metrics is not None:
        _core_metrics = set(_STAR_LATE_CORE_METRIC_ORDER)
        _hit_set = set(late_star_hit_metrics)
        if not _core_metrics.issubset(_hit_set):
            return 0.5

    if not has_selected_late_star or late_wr_value is None:
        return 1

    # A WR60-level late signal is the lowest-confidence late tier: always cap at
    # 0.5 regardless of how many late star-hits it has.
    if _late_star_pub_table_wr_level(late_wr_value) == 60:
        return 0.5

    # ELO gate removed — multiplier depends only on late hit count and WR.
    # (late_star_hit_count_value >= 2 is guaranteed here.)
    if late_wr_value >= 85.0:
        return 3
    if late_wr_value >= 75.0:
        return 2

    return 1


def _build_stake_multiplier_context(
    *,
    stake_team_name: str,
    target_side: Optional[str],
    team_elo_meta: Optional[Dict[str, Any]],
    radiant_team_name: Optional[str],
    dire_team_name: Optional[str],
    selected_early_sign: Optional[int],
    selected_late_sign: Optional[int],
    has_selected_early_star: bool,
    has_selected_late_star: bool,
    early_wr_pct: Optional[float],
    late_wr_pct: Optional[float],
    late_star_hit_count: Optional[int],
    selected_all_sign: Optional[int] = None,
    has_selected_all_star: bool = False,
    all_wr_pct: Optional[float] = None,
    force_half_due_to_early_no_valid_late: bool = False,
    special_header_mode: str = "",
    all_star_hit_count: Optional[int] = None,
    early_star_hit_count: Optional[int] = None,
    late_star_hit_metrics: Optional[List[str]] = None,
    all_star_hits: Optional[List[Dict[str, Any]]] = None,
    synergy_confirmation_snapshot: Optional[Dict[str, Any]] = None,
    kills_window_ed_by_label: Optional[Dict[str, Any]] = None,
    kills_window_header_label: Optional[str] = None,
) -> Dict[str, Any]:
    opposite_side = "dire" if target_side == "radiant" else "radiant"
    return {
        "stake_team_name": str(stake_team_name or ""),
        "target_side": target_side,
        "radiant_team_name": str(radiant_team_name or ""),
        "dire_team_name": str(dire_team_name or ""),
        "selected_early_sign": selected_early_sign,
        "selected_late_sign": selected_late_sign,
        "selected_all_sign": selected_all_sign,
        "has_selected_early_star": bool(has_selected_early_star),
        "has_selected_late_star": bool(has_selected_late_star),
        "has_selected_all_star": bool(has_selected_all_star),
        "early_wr_pct": float(early_wr_pct) if early_wr_pct is not None else None,
        "late_wr_pct": float(late_wr_pct) if late_wr_pct is not None else None,
        "all_wr_pct": float(all_wr_pct) if all_wr_pct is not None else None,
        "late_star_hit_count": int(late_star_hit_count) if late_star_hit_count is not None else None,
        "all_star_hit_count": int(all_star_hit_count) if all_star_hit_count is not None else None,
        "early_star_hit_count": int(early_star_hit_count) if early_star_hit_count is not None else None,
        "late_star_hit_metrics": list(late_star_hit_metrics) if late_star_hit_metrics is not None else None,
        # WR60+ star-хиты блока All (metric/value/wr_level) — нужны delayed
        # watcher'у, чтобы перепроверить late-гейт по снимку сигнала.
        "all_star_hits": (
            [dict(hit) for hit in all_star_hits if isinstance(hit, dict)]
            if all_star_hits is not None
            else None
        ),
        "synergy_confirmation_snapshot": (
            dict(synergy_confirmation_snapshot)
            if isinstance(synergy_confirmation_snapshot, dict)
            else None
        ),
        "synergy_opposes_target": bool(
            isinstance(synergy_confirmation_snapshot, dict)
            and synergy_confirmation_snapshot.get("has_opposite")
        ),
        "force_half_due_to_early_no_valid_late": bool(force_half_due_to_early_no_valid_late),
        "special_header_mode": str(special_header_mode or ""),
        "target_rating": _team_elo_base_rating_for_side(team_elo_meta, target_side),
        "opposite_rating": _team_elo_base_rating_for_side(team_elo_meta, opposite_side),
        "target_elo_wr": _team_elo_wr_for_side(team_elo_meta, target_side),
        "kills_window_ed_by_label": (
            dict(kills_window_ed_by_label)
            if isinstance(kills_window_ed_by_label, dict)
            else None
        ),
        "kills_window_header_label": (
            str(kills_window_header_label).strip() or None
            if kills_window_header_label is not None
            else None
        ),
    }


def _format_stake_multiplier_label(multiplier: Optional[float]) -> str:
    try:
        value = float(multiplier)
    except (TypeError, ValueError):
        value = 1.0
    if value.is_integer():
        return str(int(value))
    return f"{value:g}"


def _format_signal_header(
    *,
    stake_team_name: str,
    stake_multiplier: Optional[float],
    special_header_mode: str = "",
    kills_window_label: Any = None,
) -> str:
    team_name = normalize_team_name_display(str(stake_team_name or "")) or "НЕИЗВЕСТНАЯ КОМАНДА"
    if special_header_mode == "kills_from":
        return f"СТАВКА НА килы от {team_name}"
    if special_header_mode == "early_kills":
        # Окно kills_window (strongest same-side) — "СТАВКА НА Ранние килы 10-20 <team>"
        window_text = str(kills_window_label or "").strip().replace("_", "-")
        if window_text:
            return f"СТАВКА НА Ранние килы {window_text} {team_name}"
        return f"СТАВКА НА Ранние килы {team_name}"
    return f"СТАВКА НА {team_name} x{_format_stake_multiplier_label(stake_multiplier)}"


# Хедер обычной ставки: "СТАВКА НА <team> x<mult>". Kills-хедеры множителя не
# несут, поэтому под x0.5-гейт не попадают.
_STAKE_HEADER_MULTIPLIER_RE = re.compile(r"^СТАВКА НА .+\sx(?P<mult>\d+(?:[.,]\d+)?)\s*$")


def _stake_multiplier_from_message(message_text: Optional[str]) -> Optional[float]:
    """Множитель ставки из первой строки сообщения, или None если хедер иной."""
    first_line = str(message_text or "").splitlines()[:1]
    if not first_line:
        return None
    match = _STAKE_HEADER_MULTIPLIER_RE.match(first_line[0].strip())
    if not match:
        return None
    try:
        return float(match.group("mult").replace(",", "."))
    except (TypeError, ValueError):
        return None


def _half_stake_elo_underdog_reject(
    *,
    stake_multiplier: Optional[float],
    target_rating: Optional[float],
    opposite_rating: Optional[float],
    min_diff: Optional[float] = None,
    enabled: Optional[bool] = None,
) -> Optional[Dict[str, Any]]:
    """Блок x0.5, если таргет слабее оппонента по ELO на ``min_diff`` и больше.

    Возвращает диагностику блокировки или None (отправка разрешена). Отсутствие
    рейтингов = не блокируем (нет данных — нет запрета).
    """
    # Читаем модульные константы внутри (а не в дефолтах), чтобы env/тесты
    # могли переопределить порог и выключатель без перезагрузки модуля.
    if enabled is None:
        enabled = HALF_STAKE_ELO_UNDERDOG_BLOCK_ENABLED
    if min_diff is None:
        min_diff = HALF_STAKE_ELO_UNDERDOG_MIN_DIFF
    if not enabled:
        return None
    try:
        multiplier_value = float(stake_multiplier)
    except (TypeError, ValueError):
        return None
    if abs(multiplier_value - 0.5) > 1e-9:
        return None
    try:
        target_value = float(target_rating)
        opposite_value = float(opposite_rating)
    except (TypeError, ValueError):
        return None
    if not math.isfinite(target_value) or not math.isfinite(opposite_value):
        return None
    elo_diff = opposite_value - target_value
    if elo_diff < float(min_diff):
        return None
    return {
        "reject": True,
        "stake_multiplier": multiplier_value,
        "target_rating": target_value,
        "opposite_rating": opposite_value,
        "elo_diff": float(elo_diff),
        "min_diff": float(min_diff),
    }


def _half_stake_elo_underdog_reject_for_delivery(
    message_text: Optional[str],
    stake_multiplier_context: Optional[Dict[str, Any]],
) -> Optional[Dict[str, Any]]:
    """Тот же гейт, но по фактическому тексту сигнала и снимку ставки."""
    if not isinstance(stake_multiplier_context, dict):
        return None
    decision = _half_stake_elo_underdog_reject(
        stake_multiplier=_stake_multiplier_from_message(message_text),
        target_rating=stake_multiplier_context.get("target_rating"),
        opposite_rating=stake_multiplier_context.get("opposite_rating"),
    )
    if decision is None:
        return None
    decision["target_side"] = stake_multiplier_context.get("target_side")
    decision["stake_team_name"] = str(stake_multiplier_context.get("stake_team_name") or "")
    return decision


_half_stake_elo_block_logged_lock = threading.Lock()
_half_stake_elo_block_logged_keys: set = set()


def _log_half_stake_elo_block_once(match_key: str, decision: Dict[str, Any]) -> None:
    """Печатает причину блока x0.5 один раз на матч (перепроверок много)."""
    log_key = f"{match_key}|{decision.get('target_side')}"
    with _half_stake_elo_block_logged_lock:
        already_logged = log_key in _half_stake_elo_block_logged_keys
        _half_stake_elo_block_logged_keys.add(log_key)
    if already_logged:
        return
    print(
        "   🚫 x0.5 заблокирован: таргет слабее по ELO "
        f"({decision.get('stake_team_name') or decision.get('target_side')}: "
        f"{float(decision.get('target_rating') or 0.0):.0f} vs "
        f"{float(decision.get('opposite_rating') or 0.0):.0f}, "
        f"diff={float(decision.get('elo_diff') or 0.0):.0f} >= "
        f"{float(decision.get('min_diff') or 0.0):.0f}) — {match_key}"
    )


# --- Обычная ставка не уходит без согласия ML-модели победителя -------------
#
# Панель обычной ставки ("СТАВКА НА <team> x<mult>") обязана нести мнение
# предматчевой модели: по ней работает вето, и оператор принимает решение с
# оглядкой на неё. Когда модель молчит, строка `🤖 ML-модель:` просто исчезает
# (`_format_win_model_line`) — и молчание становится неотличимо от согласия,
# а ставка уходит вслепую. 28.08.2026 так ушла ставка на Team Synapse: модель
# отказалась оценивать матч ("разметка позиций противоречит истории у 3
# слотов"), в панели строки не было, отправку это не остановило.
#
# Kills-хедеры множителя не несут (`_STAKE_HEADER_MULTIPLIER_RE`), поэтому под
# гейт не попадают: модель предсказывает победителя КАРТЫ, а не килы, и
# ML-строки у kills-панелей не бывает вовсе (28 из 28 отправок за 28.08.2026).
#
# Решение принимается по ФАКТИЧЕСКОМУ тексту сигнала — тем же приёмом, что и
# запрет x0.5 выше. Причина: путей отправки много (немедленный dispatch,
# delayed watcher, spec, pipeline, protracker), и сведены они только в
# `_deliver_and_persist_signal`; гейт в одной точке нельзя обойти новым путём.
BET_REQUIRE_WIN_MODEL = os.getenv("BET_REQUIRE_WIN_MODEL", "1") == "1"

# "🤖 ML-модель: Radiant 63.5% | ..." — сторона, за которую высказалась модель.
_WIN_MODEL_PANEL_RE = re.compile(
    r"^\s*\U0001F916\s*ML-\u043c\u043e\u0434\u0435\u043b\u044c:\s*(?P<side>Radiant|Dire)\b",
    re.M,
)
# "🕑 Late ML-модель: Dire 56.0%" — сторона late-модели.
# Строку печатает `_build_win_model_line` (см. ~5846); отказ модели молчаливый,
# тогда строки просто нет.
_LATE_WIN_MODEL_PANEL_RE = re.compile(
    r"^\s*\U0001F551\s*Late ML-модель:\s*(?P<side>Radiant|Dire)\b",
    re.M,
)
# "All: <team> WR≈65.0% от кэфа 1.54" из блока «Оценка WR». Одноимённый
# заголовок секции метрик ("All:" без WR) под регексп намеренно не подходит.
_WR_ALL_ESTIMATE_RE = re.compile(r"^\s*All:\s*(?P<team>\S.*?)\s+WR\u2248", re.M)
# "СТАВКА НА <team> x<mult>" — имя таргета берём из самой панели, чтобы
# сравнивать его с именем из WR-строки в одной и той же нормализации.
_STAKE_HEADER_TEAM_RE = re.compile(
    r"^\u0421\u0422\u0410\u0412\u041a\u0410 \u041d\u0410\s+(?P<team>.+?)\s+x\d+(?:[.,]\d+)?\s*$"
)


def _win_model_reject_for_delivery(
    message_text: Optional[str],
    stake_multiplier_context: Optional[Dict[str, Any]],
) -> Optional[Dict[str, Any]]:
    """Причина не отправлять обычную ставку, или None если препятствий нет.

    Три причины, все про согласие с моделью победителя карты:

    `model_missing` — строки ML в панели нет: модель не дала оценку (отказ
        входного гейта, недоступный артефакт, падение). Именно этот случай
        раньше проходил молча.
    `model_against` — сторона модели противоположна стороне ставки. Порога по
        модулю индекса ЗДЕСЬ НЕТ: `win_model_veto.blocks_veto` с порогом 8
        отменяет отдельный БЛОК, а это запрет самой отправки, и он строже.
    `all_against` — блок All высказался за другую команду.

    Сторона ставки для `model_against` берётся из `stake_multiplier_context`:
    в тексте панели сторон (radiant/dire) нет, только имена. Контекст приходит
    не со всех путей, и без него эта проверка пропускается — две другие
    работают всегда, они опираются только на текст.
    """
    if not BET_REQUIRE_WIN_MODEL:
        return None
    text = str(message_text or "")
    if _stake_multiplier_from_message(text) is None:
        return None                                  # не обычная ставка

    if _WIN_MODEL_PANEL_RE.search(text) is None:
        return {"reason": "model_missing"}

    ctx = stake_multiplier_context if isinstance(stake_multiplier_context, dict) else {}
    target_side = str(ctx.get("target_side") or "").strip().lower()
    model_side = _WIN_MODEL_PANEL_RE.search(text).group("side").strip().lower()
    if target_side in ("radiant", "dire") and model_side != target_side:
        return {
            "reason": "model_against",
            "model_side": model_side,
            "target_side": target_side,
        }

    # Первую строку читаем так же, как `_stake_multiplier_from_message`:
    # он уже подтвердил, что это заголовок обычной ставки.
    header = _STAKE_HEADER_TEAM_RE.match(text.splitlines()[0].strip())
    all_line = _WR_ALL_ESTIMATE_RE.search(text)
    if header is not None and all_line is not None:
        target_team = normalize_team_name_display(str(header.group("team") or "")).strip()
        all_team = normalize_team_name_display(str(all_line.group("team") or "")).strip()
        if target_team and all_team and target_team != all_team:
            return {
                "reason": "all_against",
                "all_team": all_team,
                "target_team": target_team,
            }
    return None


# Обычная ставка не уходит, если late-модель назвала сторону против target
# (просьба владельца 30.08.2026, уточнение: не только late-driven).
# Снимается без деплоя: BET_REQUIRE_LATE_WIN_MODEL=0.
BET_REQUIRE_LATE_WIN_MODEL = os.getenv("BET_REQUIRE_LATE_WIN_MODEL", "1") == "1"


def _is_late_driven_context(stake_multiplier_context: Optional[Dict[str, Any]]) -> bool:
    """Сторону ставки задаёт late-звезда, и её не подтверждает same-sign early.

    Та же популяция, что у late-гейта минимальной минуты: late-only, late+all,
    opposite-signs. Immediate late+early одного знака сюда НЕ попадает — там
    сторону подтверждает early, и это уже не «ставка на late».
    """
    ctx = stake_multiplier_context if isinstance(stake_multiplier_context, dict) else {}
    snapshot = _late27_dispatch_guard_snapshot_from_context(ctx)
    if not snapshot.get("has_late_star") or snapshot.get("early_supports_late"):
        return False
    late_sign = snapshot.get("late_sign")
    if late_sign not in (-1, 1):
        return False
    target_side = str(ctx.get("target_side") or "").strip().lower()
    if target_side not in ("radiant", "dire"):
        return False
    return _target_side_from_sign(late_sign) == target_side


def _late_win_model_reject_for_delivery(
    message_text: Optional[str],
    stake_multiplier_context: Optional[Dict[str, Any]],
) -> Optional[Dict[str, Any]]:
    """Причина не отправлять обычную ставку из-за late-модели, или None.

    Две причины, популяции разные:

    `late_model_against` — сторона модели противоположна стороне ставки.
        Действует на ЛЮБУЮ обычную ставку (late/early/all): строка в панели
        есть, и она называет не target. Порога по уверенности нет.
    `late_model_missing` — строки late-модели в панели нет. Только late-driven
        (`_is_late_driven_context`): там ставка уходит ТОЛЬКО когда модель
        явно назвала сторону таргета. У early/all строки часто нет, и это
        не «против» — молчание их не режет.

    Проверка идёт по ФАКТИЧЕСКОМУ тексту сигнала — тем же приёмом, что и
    предматчевый гейт: путей отправки много, сведены они только в
    `_deliver_and_persist_signal`, и гейт в одной точке нельзя обойти новым
    путём. Читать вердикт из `win_model_veto.last_late(index)` в момент
    доставки нельзя: история разложений держит 32 записи, а ставка уходит
    через десятки минут после оценки.
    """
    if not BET_REQUIRE_LATE_WIN_MODEL:
        return None
    text = str(message_text or "")
    if _stake_multiplier_from_message(text) is None:
        return None                                  # не обычная ставка

    match = _LATE_WIN_MODEL_PANEL_RE.search(text)
    if match is not None:
        ctx = stake_multiplier_context if isinstance(stake_multiplier_context, dict) else {}
        target_side = str(ctx.get("target_side") or "").strip().lower()
        late_model_side = match.group("side").strip().lower()
        if target_side in ("radiant", "dire") and late_model_side != target_side:
            return {
                "reason": "late_model_against",
                "late_model_side": late_model_side,
                "target_side": target_side,
            }
        return None

    if not _is_late_driven_context(stake_multiplier_context):
        return None
    return {"reason": "late_model_missing"}


_late_win_model_block_logged_lock = threading.Lock()
_late_win_model_block_logged_keys: set = set()


def _log_late_win_model_block_once(match_key: str, decision: Dict[str, Any]) -> None:
    """Печатает причину блока late-ставки один раз на матч."""
    log_key = f"{match_key}|{decision.get('reason')}"
    with _late_win_model_block_logged_lock:
        already_logged = log_key in _late_win_model_block_logged_keys
        _late_win_model_block_logged_keys.add(log_key)
    if already_logged:
        return
    if str(decision.get("reason") or "") == "late_model_missing":
        detail = "late-модель не дала оценку (строки в панели нет)"
    else:
        detail = (
            f"late-модель против таргета (модель за {decision.get('late_model_side')}, "
            f"ставка на {decision.get('target_side')})"
        )
    print(f"   🚫 Ставка заблокирована late-моделью: {detail} — {match_key}")


_win_model_block_logged_lock = threading.Lock()
_win_model_block_logged_keys: set = set()


def _log_win_model_block_once(match_key: str, decision: Dict[str, Any]) -> None:
    """Печатает причину блока один раз на матч (перепроверок много)."""
    reason = str(decision.get("reason") or "")
    log_key = f"{match_key}|{reason}"
    with _win_model_block_logged_lock:
        already_logged = log_key in _win_model_block_logged_keys
        _win_model_block_logged_keys.add(log_key)
    if already_logged:
        return
    if reason == "model_missing":
        detail = "ML-модель не дала оценку (строки в панели нет)"
    elif reason == "model_against":
        detail = (
            f"ML-модель против таргета (модель за {decision.get('model_side')}, "
            f"ставка на {decision.get('target_side')})"
        )
    else:
        detail = (
            f"блок All против таргета (All за {decision.get('all_team')}, "
            f"ставка на {decision.get('target_team')})"
        )
    print(f"   🚫 Ставка заблокирована: {detail} — {match_key}")


def _blank_dota2protracker_result() -> Dict[str, Any]:
    return {
        "pro_cp1vs1_early": 0.0,
        "pro_cp1vs1_late": 0.0,
        "pro_duo_synergy_early": 0.0,
        "pro_duo_synergy_late": 0.0,
        "pro_cp1vs1_early_games": 0,
        "pro_cp1vs1_late_games": 0,
        "pro_duo_synergy_early_games": 0,
        "pro_duo_synergy_late_games": 0,
        "pro_cp1vs1_valid": False,
        "pro_duo_synergy_valid": False,
        "pro_cp1vs1_reason": "not_computed",
        "pro_duo_synergy_reason": "not_computed",
        "pro_cp1vs1_diagnostics": {},
        "pro_duo_synergy_diagnostics": {},
        # Попозиционный базовый WR героев (dota2protracker /api/heroes/list).
        "pro_solo_wr_early": 0.0,
        "pro_solo_wr_late": 0.0,
        "pro_solo_wr_early_games": 0,
        "pro_solo_wr_late_games": 0,
        "pro_solo_wr_valid": False,
        "pro_solo_wr_reason": "not_computed",
        "pro_solo_wr_diagnostics": {},
        "pro_solo_wr_metric": "position_baseline_wr",
        # Общий WR героя по всем позициям (та же сводка, другой срез).
        "pro_solo_wr_overall_early": 0.0,
        "pro_solo_wr_overall_late": 0.0,
        "pro_solo_wr_overall_early_games": 0,
        "pro_solo_wr_overall_late_games": 0,
        "pro_solo_wr_overall_valid": False,
        "pro_solo_wr_overall_reason": "not_computed",
        "pro_solo_wr_overall_diagnostics": {},
        "pro_solo_wr_overall_metric": "overall_hero_wr",
        # Solo lane-adv: базовый лейн-перевес героев, приор для парного
        # lane_adv (подстановка — только под PRO_LANE_SOLO_FALLBACK).
        "pro_lane_solo": 0.0,
        "pro_lane_solo_valid": False,
        "pro_lane_solo_covered_lanes": 0,
        "pro_lane_solo_metric": "lane_adv_solo",
        "pro_lane_solo_fallback_used": False,
        # Lane synergy 1+1 (@10 NW). pro_lane_advantage is omitted until enrich runs
        # so _dota2protracker_lane_adv_value can return None when not computed.
        "pro_duo_lane": 0.0,
        "pro_duo_lane_valid": False,
        "pro_duo_lane_games": 0,
        "pro_duo_lane_metric": "lane_adv",
        "pro_duo_synergy_metric": "match_wr",
        "pro_lane_metric": "lane_adv",
    }


def _format_dota2protracker_value(value: Any) -> str:
    try:
        return f"{float(value):+,.2f}".replace(",", "")
    except (TypeError, ValueError):
        return "+0.00"


_DOTA2PROTRACKER_STAR_OUTPUT_KEYS = (
    "dota2protracker_cp1vs1",
    "dota2protracker_duo",
    "dota2protracker_solo",
    "dota2protracker_solo_overall",
)


def _format_dota2protracker_output_value(value: Any) -> Any:
    numeric_value = _coerce_metric_value(value)
    if numeric_value is None:
        return value
    suffix = "*" if isinstance(value, str) and value.strip().endswith("*") else ""
    return f"{_format_dota2protracker_value(numeric_value)}{suffix}"


def _dota2protracker_metric_is_valid(
    protracker_payload: Optional[Dict[str, Any]],
    metric_name: str,
) -> bool:
    if not isinstance(protracker_payload, dict):
        return False
    if metric_name == "cp1vs1":
        return bool(protracker_payload.get("pro_cp1vs1_valid"))
    if metric_name == "synergy_duo":
        return bool(protracker_payload.get("pro_duo_synergy_valid"))
    return False


def _has_valid_dota2protracker_signal(protracker_payload: Optional[Dict[str, Any]]) -> bool:
    return (
        _dota2protracker_metric_is_valid(protracker_payload, "cp1vs1")
        or _dota2protracker_metric_is_valid(protracker_payload, "synergy_duo")
    )


def _has_dispatchable_dota2protracker_signal(
    protracker_payload: Optional[Dict[str, Any]],
) -> bool:
    if not isinstance(protracker_payload, dict):
        return False
    cp_valid = bool(protracker_payload.get("pro_cp1vs1_valid"))
    duo_valid = bool(protracker_payload.get("pro_duo_synergy_valid"))
    cp_value = float(protracker_payload.get("pro_cp1vs1_late", protracker_payload.get("pro_cp1vs1_early", 0.0)) or 0.0)
    duo_value = float(
        protracker_payload.get("pro_duo_synergy_late", protracker_payload.get("pro_duo_synergy_early", 0.0)) or 0.0
    )
    return (
        (cp_valid and abs(cp_value) >= DOTA2PROTRACKER_CP1VS1_GATE_ABS)
        or (duo_valid and abs(duo_value) >= DOTA2PROTRACKER_DUO_GATE_ABS)
    )


def _build_dota2protracker_gate_summary(
    protracker_payload: Optional[Dict[str, Any]],
) -> str:
    payload = dict(_blank_dota2protracker_result())
    if isinstance(protracker_payload, dict):
        payload.update(protracker_payload)
    cp_valid = bool(payload.get("pro_cp1vs1_valid"))
    duo_valid = bool(payload.get("pro_duo_synergy_valid"))
    cp_value = float(payload.get("pro_cp1vs1_late", payload.get("pro_cp1vs1_early", 0.0)) or 0.0)
    duo_value = float(payload.get("pro_duo_synergy_late", payload.get("pro_duo_synergy_early", 0.0)) or 0.0)
    cp_pass = cp_valid and abs(cp_value) >= DOTA2PROTRACKER_CP1VS1_GATE_ABS
    duo_pass = duo_valid and abs(duo_value) >= DOTA2PROTRACKER_DUO_GATE_ABS
    return (
        "gate="
        f"cp(abs>={DOTA2PROTRACKER_CP1VS1_GATE_ABS:g}, valid={cp_valid}, pass={cp_pass}), "
        f"duo(abs>={DOTA2PROTRACKER_DUO_GATE_ABS:g}, valid={duo_valid}, pass={duo_pass})"
    )


def _format_dota2protracker_metric(
    *,
    value: Any,
    valid: bool,
) -> str:
    if not valid:
        return "invalid"
    return _format_dota2protracker_value(value)


def _build_dota2protracker_star_output(
    protracker_payload: Optional[Dict[str, Any]],
) -> Dict[str, float]:
    """Values merged into All metrics.

    - Protracker_1vs1: match-WR counterpick 1v1 (STAR-eligible)
    - Protracker_duo: match-WR duo synergy (display under 1vs1 in All)
    Lane synergy 1+1 stays only inside Lane_adv_protracker.
    """
    payload = dict(_blank_dota2protracker_result())
    if isinstance(protracker_payload, dict):
        payload.update(protracker_payload)
    out: Dict[str, float] = {}

    if bool(payload.get("pro_cp1vs1_valid")):
        raw_value = payload.get("pro_cp1vs1_late", payload.get("pro_cp1vs1_early", 0.0))
        try:
            value = float(raw_value)
        except (TypeError, ValueError):
            value = None
        if value is not None and math.isfinite(value) and value != 0.0:
            out["dota2protracker_cp1vs1"] = value

    if bool(payload.get("pro_duo_synergy_valid")):
        raw_duo = payload.get("pro_duo_synergy_late", payload.get("pro_duo_synergy_early", 0.0))
        try:
            duo_value = float(raw_duo)
        except (TypeError, ValueError):
            duo_value = None
        if duo_value is not None and math.isfinite(duo_value) and duo_value != 0.0:
            out["dota2protracker_duo"] = duo_value

    if bool(payload.get("pro_solo_wr_valid")):
        raw_solo = payload.get("pro_solo_wr_late", payload.get("pro_solo_wr_early", 0.0))
        try:
            solo_value = float(raw_solo)
        except (TypeError, ValueError):
            solo_value = None
        if solo_value is not None and math.isfinite(solo_value) and solo_value != 0.0:
            out["dota2protracker_solo"] = solo_value

    if bool(payload.get("pro_solo_wr_overall_valid")):
        raw_overall = payload.get(
            "pro_solo_wr_overall_late", payload.get("pro_solo_wr_overall_early", 0.0)
        )
        try:
            overall_value = float(raw_overall)
        except (TypeError, ValueError):
            overall_value = None
        if overall_value is not None and math.isfinite(overall_value) and overall_value != 0.0:
            out["dota2protracker_solo_overall"] = overall_value

    return out


def _build_all_star_output(
    post_lane_output: Optional[Dict[str, Any]],
    protracker_payload: Optional[Dict[str, Any]],
) -> Dict[str, Any]:
    all_output: Dict[str, Any] = {}
    if isinstance(post_lane_output, dict):
        # pos1_vs_pos1 is display-only (non-star); still copy it so All-block
        # messages show the metric instead of permanent ``None``.
        for key in (
            "counterpick_1vs1",
            "counterpick_1vs2",
            "solo",
            "synergy_duo",
            "synergy_trio",
            "pos1_vs_pos1",
            # Индекс ML-модели и его источник. Без них вето на секции
            # all_output было МЁРТВЫМ: `blocks_veto` читает индекс из самого
            # блока, а сюда его никто не копировал, поэтому порог 0 («режем
            # любое несогласие») ни разу ничего не отрезал. Секция при этом
            # состоит в STAR_THRESHOLD_SECTIONS и вето для неё вызывается.
            win_model_veto.INDEX_KEY,
            win_model_veto.SOURCE_KEY,
        ):
            if key in post_lane_output:
                all_output[key] = post_lane_output.get(key)
    all_output.update(_build_dota2protracker_star_output(protracker_payload))
    return all_output


def _build_dota2protracker_debug_summary(
    protracker_payload: Optional[Dict[str, Any]],
) -> str:
    payload = dict(_blank_dota2protracker_result())
    if isinstance(protracker_payload, dict):
        payload.update(protracker_payload)
    cp_valid = bool(payload.get("pro_cp1vs1_valid"))
    duo_valid = bool(payload.get("pro_duo_synergy_valid"))
    cp_reason = str(payload.get("pro_cp1vs1_reason") or "unknown")
    duo_reason = str(payload.get("pro_duo_synergy_reason") or "unknown")
    cp_diag = payload.get("pro_cp1vs1_diagnostics") or {}
    duo_diag = payload.get("pro_duo_synergy_diagnostics") or {}
    cp_value = payload.get("pro_cp1vs1_late", payload.get("pro_cp1vs1_early", 0.0))
    duo_value = payload.get("pro_duo_synergy_late", payload.get("pro_duo_synergy_early", 0.0))
    solo_valid = bool(payload.get("pro_solo_wr_valid"))
    solo_reason = str(payload.get("pro_solo_wr_reason") or "unknown")
    solo_diag = payload.get("pro_solo_wr_diagnostics") or {}
    solo_value = payload.get("pro_solo_wr_late", payload.get("pro_solo_wr_early", 0.0))
    overall_valid = bool(payload.get("pro_solo_wr_overall_valid"))
    overall_reason = str(payload.get("pro_solo_wr_overall_reason") or "unknown")
    overall_diag = payload.get("pro_solo_wr_overall_diagnostics") or {}
    overall_value = payload.get(
        "pro_solo_wr_overall_late", payload.get("pro_solo_wr_overall_early", 0.0)
    )
    return (
        "Protracker_1vs1="
        f"{_format_dota2protracker_metric(value=cp_value, valid=cp_valid)} "
        f"(valid={cp_valid}, reason={cp_reason}, diag={cp_diag}), "
        "Protracker_duo="
        f"{_format_dota2protracker_metric(value=duo_value, valid=duo_valid)} "
        f"(valid={duo_valid}, reason={duo_reason}, diag={duo_diag}), "
        "Protracker_solo="
        f"{_format_dota2protracker_metric(value=solo_value, valid=solo_valid)} "
        f"(valid={solo_valid}, reason={solo_reason}, diag={solo_diag}), "
        "Protracker_solo_overall="
        f"{_format_dota2protracker_metric(value=overall_value, valid=overall_valid)} "
        f"(valid={overall_valid}, reason={overall_reason}, diag={overall_diag})"
    )


def _build_dota2protracker_log_lines(
    protracker_payload: Optional[Dict[str, Any]],
) -> List[str]:
    payload = dict(_blank_dota2protracker_result())
    if isinstance(protracker_payload, dict):
        payload.update(protracker_payload)

    cp_valid = bool(payload.get("pro_cp1vs1_valid"))
    duo_valid = bool(payload.get("pro_duo_synergy_valid"))
    cp_reason = str(payload.get("pro_cp1vs1_reason") or "unknown")
    duo_reason = str(payload.get("pro_duo_synergy_reason") or "unknown")
    cp_value = payload.get("pro_cp1vs1_late", payload.get("pro_cp1vs1_early", 0.0))
    duo_value = payload.get("pro_duo_synergy_late", payload.get("pro_duo_synergy_early", 0.0))
    cp_games = int(payload.get("pro_cp1vs1_late_games", payload.get("pro_cp1vs1_early_games", 0)) or 0)
    duo_games = int(payload.get("pro_duo_synergy_late_games", payload.get("pro_duo_synergy_early_games", 0)) or 0)
    cp_diag = payload.get("pro_cp1vs1_diagnostics") or {}
    duo_diag = payload.get("pro_duo_synergy_diagnostics") or {}
    solo_valid = bool(payload.get("pro_solo_wr_valid"))
    solo_reason = str(payload.get("pro_solo_wr_reason") or "unknown")
    solo_value = payload.get("pro_solo_wr_late", payload.get("pro_solo_wr_early", 0.0))
    solo_games = int(payload.get("pro_solo_wr_late_games", payload.get("pro_solo_wr_early_games", 0)) or 0)
    solo_diag = payload.get("pro_solo_wr_diagnostics") or {}
    overall_valid = bool(payload.get("pro_solo_wr_overall_valid"))
    overall_reason = str(payload.get("pro_solo_wr_overall_reason") or "unknown")
    overall_value = payload.get(
        "pro_solo_wr_overall_late", payload.get("pro_solo_wr_overall_early", 0.0)
    )
    overall_games = int(
        payload.get(
            "pro_solo_wr_overall_late_games", payload.get("pro_solo_wr_overall_early_games", 0)
        )
        or 0
    )
    overall_diag = payload.get("pro_solo_wr_overall_diagnostics") or {}
    lane_adv_present = isinstance(protracker_payload, dict) and "pro_lane_advantage" in protracker_payload
    lane_adv = payload.get("pro_lane_advantage", 0.0) if lane_adv_present else 0.0

    return [
        "   📊 Dota2ProTracker:",
        "      Lane_adv_protracker: "
        f"{_format_dota2protracker_metric(value=lane_adv, valid=lane_adv_present)}",
        "      Lane_adv_solo: "
        f"{_format_dota2protracker_metric(value=payload.get('pro_lane_solo', 0.0), valid=bool(payload.get('pro_lane_solo_valid')))} "
        f"(lanes={payload.get('pro_lane_solo_covered_lanes')}/3, "
        f"fallback_used={bool(payload.get('pro_lane_solo_fallback_used'))})",
        "      Protracker_1vs1: "
        f"{_format_dota2protracker_metric(value=cp_value, valid=cp_valid)} "
        f"(valid={cp_valid}, games={cp_games}, reason={cp_reason}, diag={cp_diag})",
        "      Protracker_duo: "
        f"{_format_dota2protracker_metric(value=duo_value, valid=duo_valid)} "
        f"(valid={duo_valid}, games={duo_games}, reason={duo_reason}, diag={duo_diag})",
        "      Protracker_solo: "
        f"{_format_dota2protracker_metric(value=solo_value, valid=solo_valid)} "
        f"(valid={solo_valid}, games={solo_games}, reason={solo_reason}, diag={solo_diag})",
        "      Protracker_solo_overall: "
        f"{_format_dota2protracker_metric(value=overall_value, valid=overall_valid)} "
        f"(valid={overall_valid}, games={overall_games}, reason={overall_reason}, diag={overall_diag})",
    ]


def _build_series_score_line(live_league: Optional[Dict[str, Any]]) -> str:
    try:
        live_league = live_league or {}
        r_wins = live_league.get('radiant_series_wins')
        d_wins = live_league.get('dire_series_wins')
        if r_wins is not None or d_wins is not None:
            r_wins = int(r_wins or 0)
            d_wins = int(d_wins or 0)
            if r_wins == 0 and d_wins == 0:
                # Valve отдаёт счёт не всегда: 25.08.2026 в серии
                # Nemiga — PuckChamp он был на второй карте и пропал на
                # третьей, и карточка показывала 0-0 при счёте 1:1. Свои
                # сыгранные карты мы знаем точно.
                remembered = _winline_series_score_remembered(live_league)
                if remembered:
                    return f"{remembered[0]}-{remembered[1]}\n"
            return f"{r_wins}-{d_wins}\n"
    except Exception:
        pass
    return ""


def _build_series_score_line_with_fallback(
    live_league: Optional[Dict[str, Any]],
    fallback_score_text: str = "",
) -> str:
    score_line = _build_series_score_line(live_league)
    if score_line:
        return score_line
    score_text = str(fallback_score_text or "").strip()
    if not score_text:
        return ""
    normalized = re.sub(r"\s*:\s*", "-", score_text)
    return f"{normalized}\n"


def _build_dota2protracker_block(
    protracker_payload: Optional[Dict[str, Any]],
    star_output: Optional[Dict[str, Any]] = None,
) -> str:
    """Compact ProTracker block for probe/only-message paths.

    Protracker_1vs1 = match-WR counterpick 1v1.
    Protracker_duo = match-WR duo synergy.
    Lane synergy 1+1 is not listed here: folded into Lane_adv_protracker.
    """
    payload = dict(_blank_dota2protracker_result())
    if isinstance(protracker_payload, dict):
        payload.update(protracker_payload)
    cp_value = payload.get("pro_cp1vs1_late", payload.get("pro_cp1vs1_early", 0.0))
    duo_value = payload.get("pro_duo_synergy_late", payload.get("pro_duo_synergy_early", 0.0))
    solo_value = payload.get("pro_solo_wr_late", payload.get("pro_solo_wr_early", 0.0))
    overall_value = payload.get(
        "pro_solo_wr_overall_late", payload.get("pro_solo_wr_overall_early", 0.0)
    )
    cp_valid = bool(payload.get("pro_cp1vs1_valid"))
    duo_valid = bool(payload.get("pro_duo_synergy_valid"))
    solo_valid = bool(payload.get("pro_solo_wr_valid"))
    overall_valid = bool(payload.get("pro_solo_wr_overall_valid"))
    cp_label = _format_dota2protracker_metric(value=cp_value, valid=cp_valid)
    if cp_valid and isinstance(star_output, dict):
        starred_cp = star_output.get("dota2protracker_cp1vs1")
        if isinstance(starred_cp, str) and starred_cp.strip().endswith("*"):
            cp_label = starred_cp.strip()

    return (
        "\ndota2protracker:\n"
        f"Protracker_1vs1: {cp_label}\n"
        f"Protracker_duo: {_format_dota2protracker_metric(value=duo_value, valid=duo_valid)}\n"
        f"Protracker_solo: {_format_dota2protracker_metric(value=solo_value, valid=solo_valid)}\n"
        f"Protracker_solo_overall: "
        f"{_format_dota2protracker_metric(value=overall_value, valid=overall_valid)}\n"
    )


def _dota2protracker_lane_adv_value(protracker_payload: Optional[Dict[str, Any]]) -> Optional[float]:
    if not isinstance(protracker_payload, dict):
        return None
    if "pro_lane_advantage" not in protracker_payload:
        return None
    payload = dict(_blank_dota2protracker_result())
    payload.update(protracker_payload)
    try:
        lane_adv = float(payload.get("pro_lane_advantage", 0.0))
    except (TypeError, ValueError):
        return None
    if not math.isfinite(lane_adv):
        return None
    return lane_adv


def _dota2protracker_lane_solo_value(
    protracker_payload: Optional[Dict[str, Any]],
) -> Optional[float]:
    """Solo lane-adv матча: None, если базовых значений не хватило на 3 лейна."""
    if not isinstance(protracker_payload, dict):
        return None
    if not protracker_payload.get("pro_lane_solo_valid"):
        return None
    try:
        value = float(protracker_payload.get("pro_lane_solo", 0.0))
    except (TypeError, ValueError):
        return None
    return value if math.isfinite(value) else None


def _build_dota2protracker_lane_adv_line(protracker_payload: Optional[Dict[str, Any]]) -> str:
    """Lane advantage from ProTracker (minute-10 lane NW components).

    Второй строкой идёт Lane_adv_solo — тот же лейн-перевес, но собранный из
    базовых значений героев вместо парных матчапов. Показываем оба, потому что
    расходятся они заметно (на живом драфте +0.89 против +2.53), и пока solo
    не проверен, подменять им основное число нельзя.
    """
    lane_adv = _dota2protracker_lane_adv_value(protracker_payload)
    head = (
        "Lane_adv_protracker: None\n"
        if lane_adv is None
        else f"Lane_adv_protracker: {lane_adv:+.2f}\n"
    )
    solo = _dota2protracker_lane_solo_value(protracker_payload)
    if solo is None:
        return head
    suffix = ""
    if isinstance(protracker_payload, dict) and protracker_payload.get("pro_lane_solo_fallback_used"):
        suffix = " (fallback)"
    return f"{head}Lane_adv_solo: {solo:+.2f}{suffix}\n"


def _same_sign_lane_adv_guard(
    *,
    star_sign: Optional[int],
    lane_adv_dict_value: Optional[float],
    lane_adv_protracker_value: Optional[float],
    lane_adv_solo_value: Optional[float] = None,
) -> Dict[str, Any]:
    """Направление лейнов для immediate-отправки в 00.

    Два независимых якоря направления:
      * ``lane_adv_dict`` того же знака, что target, с ``|adv| >= 3`` — как было;
      * пара протрекерных лейн-перевесов (``Lane_adv_protracker`` +
        ``Lane_adv_solo``): оба того же знака, что target. Порог по модулю у
        пары свой (``LANE_ADV_PAIR_SIGN_MIN_ABS``, по умолчанию — только знак),
        поэтому пара вытягивает случаи, где ``|lane_adv_dict|`` не добрал 3.
        Пара НЕ применяется, если ``lane_adv_dict`` смотрит в противоположную
        сторону выше своего порога — противоречие лейнов остаётся блокировкой.
    """
    star_side = _target_side_from_sign(star_sign)
    dict_sign = _numeric_sign(lane_adv_dict_value, min_abs=LANE_ADV_DICT_SIGN_MIN_ABS)
    protracker_sign = _numeric_sign(lane_adv_protracker_value, min_abs=LANE_ADV_PROTRACKER_SIGN_MIN_ABS)
    pair_protracker_sign = _numeric_sign(
        lane_adv_protracker_value, min_abs=LANE_ADV_PAIR_SIGN_MIN_ABS
    )
    pair_solo_sign = _numeric_sign(lane_adv_solo_value, min_abs=LANE_ADV_PAIR_SIGN_MIN_ABS)
    opposing_sources: List[str] = []
    if star_sign in (-1, 1):
        if dict_sign == -int(star_sign):
            opposing_sources.append("lane_adv_dict")
    dict_aligned = bool(
        star_side in {"radiant", "dire"}
        and dict_sign in (-1, 1)
        and dict_sign == star_sign
    )
    pair_sign = (
        int(pair_protracker_sign)
        if (
            pair_protracker_sign in (-1, 1)
            and pair_solo_sign in (-1, 1)
            and int(pair_protracker_sign) == int(pair_solo_sign)
        )
        else None
    )
    pair_aligned = bool(
        LANE_ADV_PAIR_ALIGN_ENABLED
        and star_side in {"radiant", "dire"}
        and pair_sign in (-1, 1)
        and pair_sign == star_sign
        and "lane_adv_dict" not in opposing_sources
    )
    return {
        "enabled": star_side in {"radiant", "dire"},
        "star_sign": star_sign,
        "star_side": star_side,
        "lane_adv_dict": lane_adv_dict_value,
        "lane_adv_dict_sign": dict_sign,
        "lane_adv_dict_sign_min_abs": LANE_ADV_DICT_SIGN_MIN_ABS,
        "lane_adv_protracker": lane_adv_protracker_value,
        "lane_adv_protracker_sign": protracker_sign,
        "lane_adv_protracker_sign_min_abs": LANE_ADV_PROTRACKER_SIGN_MIN_ABS,
        "lane_adv_solo": lane_adv_solo_value,
        "lane_adv_solo_sign": pair_solo_sign,
        "lane_adv_pair_sign_min_abs": LANE_ADV_PAIR_SIGN_MIN_ABS,
        "lane_adv_pair_sign": pair_sign,
        "lane_adv_pair_aligned": bool(pair_aligned),
        "lane_adv_dict_aligned": bool(dict_aligned),
        "aligned_source": (
            "lane_adv_dict"
            if dict_aligned
            else ("lane_adv_protracker_solo_pair" if pair_aligned else None)
        ),
        "opposes_target": bool(opposing_sources),
        "opposing_sources": opposing_sources,
        "aligned": bool(dict_aligned or pair_aligned),
    }


def _build_dota2protracker_only_message(
    *,
    radiant_team_name: str,
    dire_team_name: str,
    live_league: Optional[Dict[str, Any]],
    protracker_payload: Optional[Dict[str, Any]],
) -> str:
    return (
        "DOTA2PROTRACKER\n"
        f"{normalize_team_name_display(str(radiant_team_name or ''))} VS {normalize_team_name_display(str(dire_team_name or ''))}\n"
        f"{_build_series_score_line(live_league)}"
        f"{_build_dota2protracker_lane_adv_line(protracker_payload)}"
        f"{_build_dota2protracker_block(protracker_payload)}"
    )


def _build_lane_adv_standalone_kills_message(
    *,
    radiant_team_name: str,
    dire_team_name: str,
    target_team_name: str,
    live_league: Optional[Dict[str, Any]],
    top: Any,
    mid: Any,
    bot: Any,
    protracker_payload: Optional[Dict[str, Any]],
    team_elo_block: str,
    game_time_seconds: Any,
    radiant_lead: Any,
    lane_adv_dict_value: Optional[float],
    lane_kills_adv: Any = None,
    radiant_heroes_and_pos: Any = None,
    dire_heroes_and_pos: Any = None,
    kills_window_header_label: Any = None,
) -> str:
    """Build the dispatch message for the standalone "lane_adv_dict ≥ 8" kills
    trigger. Used when the regular STAR signal block is empty/rejected — we
    still want to send a kills bet on the team that is dominating the lanes.
    """
    header = _format_signal_header(
        stake_team_name=str(target_team_name or "НЕИЗВЕСТНАЯ КОМАНДА"),
        stake_multiplier=1.0,
        special_header_mode="early_kills",
        kills_window_label=kills_window_header_label,
    )
    lane_block = _build_lane_block(
        top,
        mid,
        bot,
        lane_adv_line=_build_dota2protracker_lane_adv_line(protracker_payload),
        lane_adv_dict_line=_build_lane_dict_adv_line(top, mid, bot),
        lane_kills_adv=lane_kills_adv,
    )
    live_state_block = _format_live_message_state_block(
        game_time_seconds=game_time_seconds,
        radiant_lead=radiant_lead,
        radiant_team_name=radiant_team_name,
        dire_team_name=dire_team_name,
        show_kills_time_blocks=False,
        kills_release_status=NETWORTH_STATUS_LANE_ADV_DICT_STANDALONE_KILLS_SEND,
        radiant_heroes_and_pos=radiant_heroes_and_pos,
        dire_heroes_and_pos=dire_heroes_and_pos,
    )
    return (
        f"{header}\n"
        f"{normalize_team_name_display(str(radiant_team_name or ''))} VS {normalize_team_name_display(str(dire_team_name or ''))}\n"
        f"{_build_series_score_line(live_league)}"
        f"{lane_block}"
        f"{team_elo_block or ''}"
        f"{live_state_block}"
    )


def _build_prematch_model_bet_message(
    *,
    radiant_team_name: str,
    dire_team_name: str,
    target_team_name: str,
    live_league: Optional[Dict[str, Any]],
    top: Any,
    mid: Any,
    bot: Any,
    protracker_payload: Optional[Dict[str, Any]],
    team_elo_block: str,
    game_time_seconds: Any,
    radiant_lead: Any,
    model_line: str,
    radiant_heroes_and_pos: Any = None,
    dire_heroes_and_pos: Any = None,
    full_message_text: Any = None,
) -> str:
    """Тело самостоятельной ставки предматчевой модели.

    Заголовок — обычный «СТАВКА НА <team> x1»: это ставка на победу, а не на
    килы. ВСЁ ОСТАЛЬНОЕ СОДЕРЖИМОЕ СООБЩЕНИЯ СОХРАНЯЕТСЯ: если вызывающий
    передал готовое тело сигнала (звёздные хиты, блоки Early/Late/All/Mix, WR,
    ELO, линии, кэфы), переписывается ТОЛЬКО первая строка — таргет
    разворачивается на сторону модели, а оператор видит ту же картину, что и в
    обычной ставке. Строка модели с минимальным кэфом уже входит в блок
    звёздных хитов, отдельно её добавлять не нужно.

    Компактная сборка ниже — запасной путь для веток, где готового тела нет.
    """
    header = _format_signal_header(
        stake_team_name=str(target_team_name or "НЕИЗВЕСТНАЯ КОМАНДА"),
        stake_multiplier=1.0,
    )
    body = str(full_message_text or "").strip()
    if body:
        lines = body.splitlines()
        if lines and lines[0].startswith("СТАВКА НА "):
            lines[0] = header                       # только таргет, блоки на месте
        else:
            lines.insert(0, header)                 # тело без заголовка (no-star ветка)
        text = "\n".join(lines)
        if model_line and model_line.strip() and model_line.strip() not in text:
            # Тело собрано без блока звёздных хитов — вносим строку модели сами,
            # иначе минимальный кэф в сообщении не появится.
            lines.insert(1, model_line.rstrip("\n"))
            text = "\n".join(lines)
        return text
    lane_block = _build_lane_block(
        top,
        mid,
        bot,
        lane_adv_line=_build_dota2protracker_lane_adv_line(protracker_payload),
        lane_adv_dict_line=_build_lane_dict_adv_line(top, mid, bot),
    )
    live_state_block = _format_live_message_state_block(
        game_time_seconds=game_time_seconds,
        radiant_lead=radiant_lead,
        radiant_team_name=radiant_team_name,
        dire_team_name=dire_team_name,
        show_kills_time_blocks=False,
        radiant_heroes_and_pos=radiant_heroes_and_pos,
        dire_heroes_and_pos=dire_heroes_and_pos,
    )
    return (
        f"{header}\n"
        f"{normalize_team_name_display(str(radiant_team_name or ''))} VS {normalize_team_name_display(str(dire_team_name or ''))}\n"
        f"{_build_series_score_line(live_league)}"
        f"{model_line or ''}"
        f"{lane_block}"
        f"{team_elo_block or ''}"
        f"{live_state_block}"
    )


def _build_early_local_kills_message(
    *,
    radiant_team_name: str,
    dire_team_name: str,
    target_team_name: str,
    live_league: Optional[Dict[str, Any]],
    metrics_payload: Dict[str, Any],
    team_elo_block: str,
    game_time_seconds: Any,
    radiant_lead: Any,
    star_target_wr: int,
    protracker_payload: Optional[Dict[str, Any]] = None,
    radiant_heroes_and_pos: Any = None,
    dire_heroes_and_pos: Any = None,
    kills_window_header_label: Any = None,
) -> str:
    """Build a FULL kills-bet body for the early (pre-networth-gate) release.

    The standalone lane_adv_dict kills bet must go out within the first 0-3
    minutes, so the body is assembled from data that does not need the network:
    the local synergy/counterpick star blocks (early/late/all), the
    lane_adv_dict line and the team ELO block.

    ``protracker_payload`` is optional and comes from the daily-warmed hero
    cache (``_resolve_early_kills_protracker_payload``): on a warm cache the
    enrichment costs ~0.1s, so the kills bet shows the very same
    ``Lane_adv_protracker`` / ``Protracker_*`` values that the later outcome bet
    will show. Without a payload the ProTracker lines are omitted entirely
    (never rendered as ``None``) and the caller logs the failure — waiting on
    the fetch here would put 20-60s on the kills critical path.
    """
    s = metrics_payload if isinstance(metrics_payload, dict) else {}
    header = _format_signal_header(
        stake_team_name=str(target_team_name or "НЕИЗВЕСТНАЯ КОМАНДА"),
        stake_multiplier=1.0,
        special_header_mode="early_kills",
        kills_window_label=kills_window_header_label,
    )
    top = s.get('top')
    mid = s.get('mid')
    bot = s.get('bot')
    has_protracker = isinstance(protracker_payload, dict) and bool(protracker_payload)
    # Lane_adv_protracker joins only when the payload came from the warm cache;
    # otherwise the lane block stays local-only (lane_adv_dict).
    lane_block = _build_lane_block(
        top,
        mid,
        bot,
        lane_adv_line=(
            _build_dota2protracker_lane_adv_line(protracker_payload)
            if has_protracker
            else ""
        ),
        lane_adv_dict_line=_build_lane_dict_adv_line(top, mid, bot),
        lane_kills_adv=s.get('lane_kills_adv_dict'),
    )

    early_output_log = _decorate_star_block_for_display(
        raw_block=s.get('early_output', {}),
        section="early_output",
        target_wr=star_target_wr,
    )
    early_end_output_log = _decorate_star_block_for_display(
        raw_block=s.get('early_end_output', {}) or {},
        section="early_end_output",
        target_wr=star_target_wr,
    )
    mid_output_log = _decorate_star_block_for_display(
        raw_block=s.get('mid_output', {}),
        section="mid_output",
        target_wr=star_target_wr,
    )
    # all_output = post_lane_output + ProTracker star output — exactly as in the
    # outcome-bet body, so both messages agree. Without a payload only the local
    # (post_lane) part is built.
    local_all_output = _build_all_star_output(
        s.get('post_lane_output', {}),
        protracker_payload if has_protracker else None,
    )
    all_output_log = _decorate_star_block_for_display(
        raw_block=local_all_output,
        section="all_output",
        target_wr=star_target_wr,
    )

    def _signal_team_name(sign: Optional[int]) -> str:
        side = _target_side_from_sign(sign)
        if side == "radiant":
            return str(radiant_team_name or "Radiant")
        if side == "dire":
            return str(dire_team_name or "Dire")
        return ""

    early_rec = _recommend_odds_for_block(early_output_log, 'early')
    early_end_rec = _recommend_odds_for_block(early_end_output_log, 'early_end')
    late_rec = _recommend_odds_for_block(mid_output_log, 'late')
    all_rec = _recommend_odds_for_block(all_output_log, 'all')

    def _wr_pct_from_rec(rec: Optional[dict]) -> Optional[float]:
        if isinstance(rec, dict):
            try:
                return float(rec.get("wr_pct"))
            except (TypeError, ValueError):
                return None
        return None

    wr_lines: List[str] = []
    if early_rec:
        line = _format_wr_estimate_line(
            "Early NW",
            _signal_team_name(_star_block_sign(early_output_log)),
            _wr_pct_from_rec(early_rec),
            early_rec,
        )
        if line:
            wr_lines.append(line)
    if early_end_rec:
        line = _format_wr_estimate_line(
            "Early Winner",
            _signal_team_name(_star_block_sign(early_end_output_log)),
            _wr_pct_from_rec(early_end_rec),
            early_end_rec,
        )
        if line:
            wr_lines.append(line)
    if late_rec:
        line = _format_wr_estimate_line(
            "Late",
            _signal_team_name(_star_block_sign(mid_output_log)),
            _wr_pct_from_rec(late_rec),
            late_rec,
        )
        if line:
            wr_lines.append(line)
    if all_rec:
        line = _format_wr_estimate_line(
            "All",
            _signal_team_name(_star_block_sign(all_output_log)),
            _wr_pct_from_rec(all_rec),
            all_rec,
        )
        if line:
            wr_lines.append(line)
    wr_block = "Оценка WR:\n" + "\n".join(wr_lines) + "\n" if wr_lines else ""

    star_hits_summary_block = _build_star_hits_summary_block(
        early_output=s.get('early_output', {}),
        mid_output=s.get('mid_output', {}),
        all_output=local_all_output,
    )

    metric_list = [
        ('counterpick_1vs1', 'Counterpick_1vs1'),
        ('pos1_vs_pos1', 'Pos1vsPos1'),
        ('counterpick_1vs2', 'Counterpick_1vs2'),
        ('solo', 'Solo'),
        ('synergy_duo', 'Synergy_duo'),
        ('synergy_trio', 'Synergy_trio'),
    ]
    # All block: Solo + ProTracker display metrics (1vs1 match WR, duo lane 1+1).
    # The ProTracker rows are listed only when the payload is there — a missing
    # payload used to print four bare ``None`` rows.
    all_metric_list = [
        ('counterpick_1vs1', 'Counterpick_1vs1'),
        ('pos1_vs_pos1', 'Pos1vsPos1'),
        ('counterpick_1vs2', 'Counterpick_1vs2'),
        ('solo', 'Solo'),
        ('synergy_duo', 'Synergy_duo'),
        ('synergy_trio', 'Synergy_trio'),
    ]
    if has_protracker:
        all_metric_list.extend(
            [
                ('dota2protracker_cp1vs1', 'Protracker_1vs1'),
                ('dota2protracker_duo', 'Protracker_duo'),
                ('dota2protracker_solo', 'Protracker_solo'),
                ('dota2protracker_solo_overall', 'Protracker_solo_overall'),
                ('dltv_rating', 'DLTV_rating'),
            ]
        )

    def _format_metrics(title: str, data: dict, metrics: list) -> str:
        lines = [title]
        for key, label in metrics:
            value = (data or {}).get(key)
            if key in _DOTA2PROTRACKER_STAR_OUTPUT_KEYS:
                value = _format_dota2protracker_output_value(value)
            lines.append(f"{label}: {value}")
        return "\n".join(lines) + "\n"

    early_block = _format_metrics("Early NW (20-28):", early_output_log, metric_list)
    early_end_block = _format_metrics(
        "Early Winner (20-28):", early_end_output_log, metric_list
    )
    mid_block = _format_metrics("Late: (28-60 min):", mid_output_log, metric_list)
    all_block = _format_metrics("All:", all_output_log, all_metric_list)
    mix_block = _format_metrics("Mix:", all_output_log, _STAR_METRICS_BLOCK_MIX_LIST)

    live_state_block = _format_live_message_state_block(
        game_time_seconds=game_time_seconds,
        radiant_lead=radiant_lead,
        radiant_team_name=radiant_team_name,
        dire_team_name=dire_team_name,
        show_kills_time_blocks=False,
        radiant_heroes_and_pos=radiant_heroes_and_pos,
        dire_heroes_and_pos=dire_heroes_and_pos,
    )
    return (
        f"{header}\n"
        f"{normalize_team_name_display(str(radiant_team_name or ''))} VS {normalize_team_name_display(str(dire_team_name or ''))}\n"
        f"{_build_series_score_line(live_league)}"
        f"{lane_block}"
        f"{team_elo_block or ''}"
        f"{wr_block}"
        f"{star_hits_summary_block}"
        f"{_compose_star_metric_blocks_for_message(early_block + early_end_block, mid_block, all_block, mix_block)}"
        f"{live_state_block}"
    )


_PIPELINE_PROBE_METRICS = (
    "counterpick_1vs1",
    "pos1_vs_pos1",
    "counterpick_1vs2",
    "solo",
    "synergy_duo",
    "synergy_trio",
)


def _format_pipeline_probe_value(value: Any) -> str:
    try:
        return f"{float(value):+.2f}"
    except (TypeError, ValueError):
        text = str(value or "").strip()
        return text if text else "N/A"


def _format_pipeline_probe_phase_block(title: str, data: Optional[Dict[str, Any]]) -> str:
    block = data if isinstance(data, dict) else {}
    lines: List[str] = []
    for metric in _PIPELINE_PROBE_METRICS:
        if metric not in block:
            continue
        games = block.get(f"{metric}_games")
        games_suffix = ""
        if metric != "solo":
            try:
                games_value = int(games)
                if games_value > 0:
                    games_suffix = f" ({games_value} games)"
            except (TypeError, ValueError):
                pass
        lines.append(f"{metric}: {_format_pipeline_probe_value(block.get(metric))}{games_suffix}")
    if not lines:
        lines.append("no covered metrics")
    return f"{title}:\n" + "\n".join(lines) + "\n"


# Порог уверенности позиций sourcetv (stats_conf перестановочного резолвера
# probe): ниже порога — варнинг с драфтом добавляется в текст основного
# сигнала этой карты (НЕ отдельным сообщением).
SOURCETV_POS_RECHECK_CONF = float(os.getenv("SOURCETV_POS_RECHECK_CONF", "0.65"))
_SOURCETV_POS_WARNING_BY_KEY: Dict[str, str] = {}


def _maybe_alert_low_confidence_sourcetv_positions(
    match_key: str,
    data: Dict[str, Any],
    radiant_team_name: str,
    dire_team_name: str,
    radiant_heroes_and_pos: Optional[Dict[str, Any]],
    dire_heroes_and_pos: Optional[Dict[str, Any]],
) -> None:
    meta = data.get("_pos_resolution") if isinstance(data, dict) else None
    if not isinstance(meta, dict):
        return
    low_sides = []
    for side_key, side_name, side_draft in (
        ("radiant", radiant_team_name, radiant_heroes_and_pos),
        ("dire", dire_team_name, dire_heroes_and_pos),
    ):
        side_meta = meta.get(side_key) or {}
        # conf — комбинированная уверенность (совпадения с историей игрока = 1.0,
        # остальные слоты по статистике героя); stats_conf — фолбэк для старых payload.
        conf = side_meta.get("conf", side_meta.get("stats_conf"))
        if (
            str(side_meta.get("method") or "") == "permutation"
            and isinstance(conf, (int, float))
            and float(conf) < SOURCETV_POS_RECHECK_CONF
        ):
            low_sides.append((side_name or side_key, side_meta, side_draft))
    if not low_sides:
        _SOURCETV_POS_WARNING_BY_KEY.pop(_signal_fingerprint_registry_key(match_key), None)
        return
    lines = ["⚠️ Низкая уверенность позиций — перепроверь драфт:"]
    for side_name, side_meta, side_draft in low_sides:
        conf_value = side_meta.get("conf", side_meta.get("stats_conf"))
        lines.append(
            f"{side_name}: conf={float(conf_value or 0):.2f} "
            f"(совпало с историей: {side_meta.get('raw_matched') or 0}/5, "
            f"история есть у {side_meta.get('raw_known') or 0}/5 игроков)"
        )
        lines.append(_format_pipeline_probe_draft_side(side_draft))
    _SOURCETV_POS_WARNING_BY_KEY[_signal_fingerprint_registry_key(match_key)] = "\n".join(lines)
    print(f"   ⚠️ Низкая уверенность позиций — варнинг будет добавлен к сигналу: {match_key}")


def _format_pipeline_probe_draft_side(side: Optional[Dict[str, Any]]) -> str:
    side = side if isinstance(side, dict) else {}
    chunks: List[str] = []
    for pos in ("pos1", "pos2", "pos3", "pos4", "pos5"):
        payload = side.get(pos) or {}
        hero_id_raw = payload.get("hero_id") if isinstance(payload, dict) else None
        try:
            hero_id = int(hero_id_raw or 0)
        except (TypeError, ValueError):
            hero_id = 0
        hero_name = ""
        if isinstance(payload, dict):
            hero_name = str(
                payload.get("hero_name")
                or payload.get("_hero_name")
                or payload.get("name")
                or ""
            ).strip()
        if not hero_name and hero_id > 0:
            hero_name = str(HERO_ID_TO_NAME.get(str(hero_id)) or HERO_ID_TO_NAME.get(hero_id) or "").strip()
        hero_label = hero_name or f"hero{hero_id or '?'}"
        chunks.append(f"{pos}:{hero_label}({hero_id or '?'})")
    return ", ".join(chunks)


def _build_pipeline_probe_message(
    *,
    radiant_team_name: str,
    dire_team_name: str,
    live_league: Optional[Dict[str, Any]],
    fallback_score_text: str,
    game_time_seconds: Any,
    radiant_lead: Any,
    radiant_heroes_and_pos: Dict[str, Any],
    dire_heroes_and_pos: Dict[str, Any],
    metrics_payload: Dict[str, Any],
    protracker_payload: Optional[Dict[str, Any]],
) -> str:
    lane_block = _build_lane_block(
        metrics_payload.get('top'),
        metrics_payload.get('mid'),
        metrics_payload.get('bot'),
        lane_adv_line=_build_dota2protracker_lane_adv_line(protracker_payload),
        lane_adv_dict_line=_build_lane_dict_adv_line(
            metrics_payload.get('top'),
            metrics_payload.get('mid'),
            metrics_payload.get('bot'),
        ),
        lane_kills_adv=metrics_payload.get('lane_kills_adv_dict'),
    )
    return (
        f"{_format_signal_header(stake_team_name='PIPELINE CHECK', stake_multiplier=1)}\n"
        f"{normalize_team_name_display(str(radiant_team_name or ''))} VS {normalize_team_name_display(str(dire_team_name or ''))}\n"
        f"{_build_series_score_line_with_fallback(live_league, fallback_score_text)}"
        f"{_format_live_message_state_block(game_time_seconds=game_time_seconds, radiant_lead=radiant_lead, radiant_team_name=radiant_team_name, dire_team_name=dire_team_name, radiant_heroes_and_pos=radiant_heroes_and_pos, dire_heroes_and_pos=dire_heroes_and_pos)}"
        "mode: send_every_parsed_match\n"
        "source: get_heads/cyberscore_try\n"
        f"Radiant draft: {_format_pipeline_probe_draft_side(radiant_heroes_and_pos)}\n"
        f"Dire draft: {_format_pipeline_probe_draft_side(dire_heroes_and_pos)}\n\n"
        f"{lane_block}"
        f"{_format_pipeline_probe_phase_block('Early', metrics_payload.get('early_output'))}"
        f"{_format_pipeline_probe_phase_block('Late', metrics_payload.get('mid_output'))}"
        f"{_format_pipeline_probe_phase_block('Post-lane', metrics_payload.get('post_lane_output'))}"
    )


def _build_minimal_odds_only_message(
    *,
    radiant_team_name: str,
    dire_team_name: str,
    live_league: Optional[Dict[str, Any]],
    fallback_score_text: str,
) -> str:
    return (
        f"{normalize_team_name_display(str(radiant_team_name or ''))} VS {normalize_team_name_display(str(dire_team_name or ''))}\n"
        f"{_build_series_score_line_with_fallback(live_league, fallback_score_text)}"
    )


def _strip_dota2protracker_message_block_lines(lines: List[str]) -> List[str]:
    stripped_lines: List[str] = []
    idx = 0
    while idx < len(lines):
        line = str(lines[idx])
        compact = line.strip().lower()
        if compact == "dota2protracker:":
            if stripped_lines and not str(stripped_lines[-1]).strip():
                stripped_lines.pop()
            idx += 1
            while idx < len(lines):
                next_compact = str(lines[idx]).strip().lower()
                if (
                    not next_compact
                    or next_compact.startswith("cp1vs1:")
                    or next_compact.startswith("protracker_1vs1:")
                    or next_compact.startswith("protracker_duo:")
                    or next_compact.startswith("protracker_solo:")
                    or next_compact.startswith("protracker_solo_overall:")
                    or next_compact.startswith("synergy_duo:")
                    or next_compact.startswith("synergy_duo(match_wr):")
                ):
                    idx += 1
                    continue
                break
            continue
        stripped_lines.append(line)
        idx += 1
    return stripped_lines


def _normalize_late_dispatch_smc(
    stake_multiplier_context: Optional[Dict[str, Any]],
) -> Optional[Dict[str, Any]]:
    """Strip ``special_header_mode="early_kills"`` from a stake_multiplier_context
    so a late dispatch renders ``СТАВКА НА <team>`` instead of inheriting the
    early/kills header from the original cycle's base build.

    Returns a fresh dict copy when normalization is needed, otherwise returns
    the original context untouched. Callers feed the result to
    ``_refresh_stake_multiplier_message`` for late dispatches that share the
    same base ``message_text`` as the early/kills release.
    """
    if not isinstance(stake_multiplier_context, dict):
        return stake_multiplier_context
    mode = str(stake_multiplier_context.get("special_header_mode") or "").strip()
    if mode != "early_kills":
        return stake_multiplier_context
    normalized = dict(stake_multiplier_context)
    normalized["special_header_mode"] = ""
    return normalized


# Game-time cutoff past which the "Ранние килы" header is stripped even when
# the delayed-payload reason is NOT in ``late_payload_reasons`` (e.g. a
# tier1_early_kills bet that waited for the networth gate and fired late).
EARLY_KILLS_HEADER_MAX_GAME_TIME_SECONDS = _safe_float_env(
    "EARLY_KILLS_HEADER_MAX_GAME_TIME_SECONDS",
    16.0 * 60.0,
)


def _maybe_strip_early_kills_header_late(
    payload: Dict[str, Any],
    game_time_seconds: Optional[float],
) -> None:
    """Strip ``early_kills`` header when game time is past the early window.

    Safety-net guard: even when the delayed-payload reason is NOT in the
    ``late_payload_reasons`` set, if we are dispatching past
    ``EARLY_KILLS_HEADER_MAX_GAME_TIME_SECONDS`` we force the regular
    ``СТАВКА НА <team>`` header.
    """
    import math as _math
    if game_time_seconds is None:
        return
    try:
        gt = float(game_time_seconds)
    except (TypeError, ValueError):
        return
    cutoff = float(EARLY_KILLS_HEADER_MAX_GAME_TIME_SECONDS)
    if _math.isnan(gt) or gt < cutoff:
        return
    smc = payload.get("stake_multiplier_context")
    if not isinstance(smc, dict):
        return
    if str(smc.get("special_header_mode") or "").strip() != "early_kills":
        return
    normalized = _normalize_late_dispatch_smc(smc)
    if normalized is not smc:
        payload["stake_multiplier_context"] = normalized
        print(
            "   🏷️  late kills-header strip: game_time="
            f"{int(gt)}s >= {int(cutoff)}s cutoff → regular header"
        )


def _stake_multiplier_from_context(
    stake_multiplier_context: Optional[Dict[str, Any]],
    *,
    game_time_seconds: Optional[float],
    radiant_lead: Optional[float],
) -> float:
    """Return the main-signal stake implied by a persisted dispatch context."""
    if not isinstance(stake_multiplier_context, dict):
        return 0.5
    return _stake_multiplier_for_signal(
        team_elo_meta=None,
        target_side=stake_multiplier_context.get("target_side"),
        selected_early_sign=stake_multiplier_context.get("selected_early_sign"),
        selected_late_sign=stake_multiplier_context.get("selected_late_sign"),
        has_selected_early_star=bool(stake_multiplier_context.get("has_selected_early_star")),
        has_selected_late_star=bool(stake_multiplier_context.get("has_selected_late_star")),
        early_wr_pct=stake_multiplier_context.get("early_wr_pct"),
        late_wr_pct=stake_multiplier_context.get("late_wr_pct"),
        game_time_seconds=game_time_seconds,
        radiant_lead=radiant_lead,
        late_star_hit_count=stake_multiplier_context.get("late_star_hit_count"),
        target_rating=stake_multiplier_context.get("target_rating"),
        opposite_rating=stake_multiplier_context.get("opposite_rating"),
        target_elo_wr=stake_multiplier_context.get("target_elo_wr"),
        force_half_due_to_early_no_valid_late=bool(
            stake_multiplier_context.get("force_half_due_to_early_no_valid_late")
        ),
        selected_all_sign=stake_multiplier_context.get("selected_all_sign"),
        has_selected_all_star=bool(stake_multiplier_context.get("has_selected_all_star")),
        all_star_hit_count=stake_multiplier_context.get("all_star_hit_count"),
        early_star_hit_count=stake_multiplier_context.get("early_star_hit_count"),
        late_star_hit_metrics=stake_multiplier_context.get("late_star_hit_metrics"),
        synergy_opposes_target=bool(
            stake_multiplier_context.get("synergy_opposes_target")
            or (
                isinstance(stake_multiplier_context.get("synergy_confirmation_snapshot"), dict)
                and stake_multiplier_context["synergy_confirmation_snapshot"].get("has_opposite")
            )
        ),
    )


def _late_speculative_allowed_for_context(
    stake_multiplier_context: Optional[Dict[str, Any]],
    *,
    game_time_seconds: Optional[float],
    radiant_lead: Optional[float],
) -> bool:
    """Allow speculative x0.5 only when the same context implies main > x0.5."""
    if not isinstance(stake_multiplier_context, dict):
        return False
    try:
        late_hits = int(stake_multiplier_context.get("late_star_hit_count") or 0)
    except (TypeError, ValueError):
        late_hits = 0
    if (
        not bool(stake_multiplier_context.get("has_selected_late_star"))
        or late_hits < LATE_PUB_COMEBACK_SPECULATIVE_MIN_LATE_HITS
    ):
        return False
    return bool(
        _stake_multiplier_from_context(
            stake_multiplier_context,
            game_time_seconds=game_time_seconds,
            radiant_lead=radiant_lead,
        )
        > 0.5
    )


def _refresh_stake_multiplier_message(
    message_text: str,
    *,
    stake_multiplier_context: Optional[Dict[str, Any]],
    game_time_seconds: Optional[float],
    radiant_lead: Optional[float],
    force_multiplier: Optional[float] = None,
) -> str:
    if not isinstance(message_text, str) or not message_text.startswith("СТАВКА НА "):
        return message_text
    if not isinstance(stake_multiplier_context, dict):
        return message_text

    stake_team_name = str(stake_multiplier_context.get("stake_team_name") or "").strip()
    if not stake_team_name:
        return message_text
    special_header_mode = str(stake_multiplier_context.get("special_header_mode") or "").strip()

    if force_multiplier is not None:
        # Спекулятивный watcher навязывает фиксированный множитель (x0.5),
        # обходя динамический расчёт по hit-count/WR.
        try:
            multiplier = float(force_multiplier)
        except (TypeError, ValueError):
            multiplier = 0.5
        multiplier_skip_recompute = True
    else:
        multiplier_skip_recompute = False
    if not multiplier_skip_recompute:
        multiplier = _stake_multiplier_from_context(
            stake_multiplier_context,
            game_time_seconds=game_time_seconds,
            radiant_lead=radiant_lead,
        )

    new_header = _format_signal_header(
        stake_team_name=stake_team_name,
        stake_multiplier=multiplier,
        special_header_mode=special_header_mode,
        kills_window_label=stake_multiplier_context.get("kills_window_header_label"),
    )
    lines = _strip_dota2protracker_message_block_lines(message_text.splitlines())
    if not lines:
        return message_text
    lines[0] = new_header

    try:
        radiant_team_name = str(stake_multiplier_context.get("radiant_team_name") or "").strip()
        dire_team_name = str(stake_multiplier_context.get("dire_team_name") or "").strip()
    except Exception:
        radiant_team_name = ""
        dire_team_name = ""
    live_state_lines = _format_live_message_state_block(
        game_time_seconds=game_time_seconds,
        radiant_lead=radiant_lead,
        radiant_team_name=radiant_team_name,
        dire_team_name=dire_team_name,
        show_kills_time_blocks=False,
        kills_release_status=(
            stake_multiplier_context.get("kills_release_status")
            or stake_multiplier_context.get("release_reason")
            or stake_multiplier_context.get("dispatch_status_label")
        ),
    ).strip().splitlines()
    filtered_lines = [
        line
        for line in lines
        if not str(line).startswith("Time:")
        and not str(line).startswith("Networth:")
        and not str(line).startswith("Kills time blocks:")
        and not str(line).startswith("Kills window blocks:")
        and not str(line).startswith("Kills gate:")
    ]
    # Prefer anchoring after the full ProTracker pair so duo stays under 1vs1
    # and Time/Networth/Kills-gate blocks stay at the bottom of metrics.
    live_state_insert_prefixes = (
        "Counterpick_1vs1:",
        "Counterpick_1vs2:",
        "Solo:",
        "Synergy_duo:",
        "Synergy_trio:",
        "Protracker_1vs1:",
        "Protracker_duo:",
        "Protracker_solo:",
        "Protracker_solo_overall:",
        "Pos1vsPos1:",
        "DLTV_rating:",
    )
    insert_after_idx = -1
    protracker_duo_idx = -1
    protracker_1vs1_idx = -1
    protracker_solo_idx = -1
    protracker_solo_overall_idx = -1
    for idx, line in enumerate(filtered_lines):
        text = str(line)
        if text.startswith("Protracker_1vs1:"):
            protracker_1vs1_idx = idx
        if text.startswith("Protracker_duo:"):
            protracker_duo_idx = idx
        if text.startswith("Protracker_solo:"):
            protracker_solo_idx = idx
        if text.startswith("Protracker_solo_overall:"):
            protracker_solo_overall_idx = idx
        if any(text.startswith(prefix) for prefix in live_state_insert_prefixes):
            insert_after_idx = idx
    # If any ProTracker line exists, always insert after the LAST of them
    # (иначе live-блок разрезал бы пару 1vs1/duo или отрезал бы solo).
    if (
        protracker_1vs1_idx >= 0
        or protracker_duo_idx >= 0
        or protracker_solo_idx >= 0
        or protracker_solo_overall_idx >= 0
    ):
        insert_after_idx = max(
            protracker_1vs1_idx,
            protracker_duo_idx,
            protracker_solo_idx,
            protracker_solo_overall_idx,
        )
    if insert_after_idx >= 0:
        filtered_lines[insert_after_idx + 1 : insert_after_idx + 1] = live_state_lines
    else:
        if filtered_lines and str(filtered_lines[-1]).strip():
            filtered_lines.append("")
        filtered_lines.extend(live_state_lines)
    trailing_newline = "\n" if message_text.endswith("\n") else ""
    return "\n".join(filtered_lines) + trailing_newline


def _format_recheck_metrics_summary(payload: Optional[Dict[str, Any]]) -> str:
    """Build a compact one-line metrics summary for a delayed-queue recheck,
    reusing the metrics computed at first parse (stored in
    ``stake_multiplier_context``). No recomputation — this keeps re-checks cheap.

    Returns e.g.: ``early=None, late=Dire 70%WR, all=Dire 75%WR``.
    """
    if not isinstance(payload, dict):
        return ""
    smc = payload.get("stake_multiplier_context")
    return _format_recheck_metrics_summary_from_smc(smc)


def _format_recheck_metrics_summary_from_smc(smc: Optional[Dict[str, Any]]) -> str:
    """Compact ``early=.., late=.., all=..`` summary built directly from a
    stake_multiplier_context-shaped dict (team names + per-phase star sign / WR).
    Shared by the delayed-queue recheck path and the pre-queue wait path so both
    surface the same one-line WR view without recomputing draft metrics."""
    if not isinstance(smc, dict):
        return ""
    radiant_name = str(smc.get("radiant_team_name") or "Radiant").strip() or "Radiant"
    dire_name = str(smc.get("dire_team_name") or "Dire").strip() or "Dire"

    def _side_label(sign: Any) -> Optional[str]:
        try:
            s = int(sign)
        except (TypeError, ValueError):
            return None
        if s == 1:
            return radiant_name
        if s == -1:
            return dire_name
        return None

    def _block(has_key: str, sign_key: str, wr_key: str) -> str:
        if not bool(smc.get(has_key)):
            return "None"
        side = _side_label(smc.get(sign_key))
        wr = smc.get(wr_key)
        try:
            wr_txt = f"{int(round(float(wr)))}%WR" if wr is not None else "?"
        except (TypeError, ValueError):
            wr_txt = "?"
        if side is None:
            return wr_txt
        return f"{side} {wr_txt}"

    early = _block("has_selected_early_star", "selected_early_sign", "early_wr_pct")
    late = _block("has_selected_late_star", "selected_late_sign", "late_wr_pct")
    all_ = _block("has_selected_all_star", "selected_all_sign", "all_wr_pct")
    return f"early={early}, late={late}, all={all_}"


def _format_recheck_target_summary(payload: Optional[Dict[str, Any]]) -> str:
    """Return ``target=<side>±<diff>`` for a delayed-queue recheck, reusing the
    stored monitor target side and the freshest known networth diff."""
    if not isinstance(payload, dict):
        return ""
    side = str(
        payload.get("networth_target_side")
        or (payload.get("add_url_details") or {}).get("target_side")
        or ""
    ).strip().lower()
    if side not in {"radiant", "dire"}:
        return ""
    diff_raw = payload.get("target_networth_diff")
    if diff_raw is None:
        diff_raw = (payload.get("add_url_details") or {}).get("target_networth_diff")
    try:
        diff_txt = f"{int(float(diff_raw)):+d}" if diff_raw is not None else "n/a"
    except (TypeError, ValueError):
        diff_txt = "n/a"
    return f"target={side} diff={diff_txt}"


def _dynamic_monitor_snapshot_for_payload(
    payload: Optional[Dict[str, Any]],
    game_time_seconds: Optional[float],
) -> Dict[str, Any]:
    threshold_raw = None
    status_label = ""
    if isinstance(payload, dict):
        threshold_raw = payload.get("networth_monitor_threshold")
        status_label = str(payload.get("dispatch_status_label") or "")
    try:
        threshold_value = float(threshold_raw) if threshold_raw is not None else None
    except (TypeError, ValueError):
        threshold_value = None
    snapshot = {
        "threshold": threshold_value,
        "status_label": status_label,
        "profile": str((payload or {}).get("dynamic_monitor_profile") or ""),
    }
    if not isinstance(payload, dict):
        return snapshot
    try:
        current_game_time = float(game_time_seconds) if game_time_seconds is not None else None
    except (TypeError, ValueError):
        current_game_time = None
    if current_game_time is None:
        return snapshot

    if snapshot["profile"] == "late_top25_elo_block_opposite_monitor":
        if current_game_time < float(NETWORTH_GATE_LATE_TOP25_ELO_BLOCK_WINDOW_START_SECONDS):
            snapshot["threshold"] = None
            return snapshot
        next_threshold_raw = payload.get(
            "networth_monitor_threshold_17_to_20",
            payload.get("networth_monitor_threshold"),
        )
        try:
            next_threshold = float(next_threshold_raw) if next_threshold_raw is not None else None
        except (TypeError, ValueError):
            next_threshold = None
        next_status_label = str(
            payload.get("networth_monitor_status_17_to_20")
            or payload.get("dispatch_status_label")
            or snapshot["status_label"]
            or ""
        )
        snapshot["threshold"] = next_threshold
        snapshot["status_label"] = next_status_label
        return snapshot

    if snapshot["profile"] == "same_sign_lane_adv_wait_4_10":
        target_game_time_raw = payload.get("target_game_time")
        try:
            target_game_time = (
                float(target_game_time_raw)
                if target_game_time_raw is not None
                else float(NETWORTH_GATE_SAME_SIGN_LANE_ADV_FALLBACK_SECONDS)
            )
        except (TypeError, ValueError):
            target_game_time = float(NETWORTH_GATE_SAME_SIGN_LANE_ADV_FALLBACK_SECONDS)
        if current_game_time < float(NETWORTH_GATE_SAME_SIGN_LANE_ADV_WINDOW_START_SECONDS):
            snapshot["threshold"] = None
            snapshot["status_label"] = str(
                payload.get("networth_monitor_status_pre4")
                or payload.get("dispatch_status_label")
                or NETWORTH_STATUS_SAME_SIGN_LANE_ADV_PRE3_WAIT
            )
            return snapshot
        if current_game_time < target_game_time:
            next_threshold_raw = payload.get(
                "networth_monitor_threshold_4_to_10",
                payload.get("networth_monitor_threshold"),
            )
            try:
                next_threshold = float(next_threshold_raw) if next_threshold_raw is not None else None
            except (TypeError, ValueError):
                next_threshold = None
            snapshot["threshold"] = next_threshold
            snapshot["status_label"] = str(
                payload.get("networth_monitor_status_4_to_10")
                or NETWORTH_STATUS_SAME_SIGN_LANE_ADV_WAIT_800
            )
            return snapshot
        snapshot["threshold"] = None
        snapshot["status_label"] = str(
            payload.get("fallback_send_status_label")
            or NETWORTH_STATUS_SAME_SIGN_LANE_ADV_FALLBACK_10_SEND
        )
        return snapshot

    if snapshot["profile"] == LATE_PRE27_DOMINANCE_PROFILE:
        pre27_snapshot = _late_pre27_dominance_snapshot(payload, current_game_time)
        snapshot["threshold"] = pre27_snapshot.get("threshold")
        snapshot["status_label"] = str(
            pre27_snapshot.get("status_label")
            or payload.get("dispatch_status_label")
            or snapshot["status_label"]
            or ""
        )
        if pre27_snapshot.get("hold_seconds") is not None:
            snapshot["hold_seconds"] = pre27_snapshot.get("hold_seconds")
        return snapshot

    if snapshot["profile"] == LATE_PRE27_WATCHER_PROFILE:
        pre27_snapshot = _late_pre27_watcher_snapshot(payload, current_game_time)
        snapshot["threshold"] = pre27_snapshot.get("threshold")
        snapshot["status_label"] = str(
            pre27_snapshot.get("status_label")
            or payload.get("dispatch_status_label")
            or snapshot["status_label"]
            or ""
        )
        if pre27_snapshot.get("source_minute") is not None:
            snapshot["source_minute"] = pre27_snapshot.get("source_minute")
        if pre27_snapshot.get("hold_seconds") is not None:
            snapshot["hold_seconds"] = pre27_snapshot.get("hold_seconds")
        return snapshot

    if snapshot["profile"] == ALL_ONLY_WATCHER_PROFILE:
        all_only_snap = _all_only_watcher_snapshot(payload, current_game_time)
        snapshot["threshold"] = all_only_snap.get("threshold")
        snapshot["status_label"] = str(
            all_only_snap.get("status_label")
            or payload.get("dispatch_status_label")
            or snapshot["status_label"]
            or ""
        )
        if all_only_snap.get("source_minute") is not None:
            snapshot["source_minute"] = all_only_snap.get("source_minute")
        if all_only_snap.get("drop_without_fallback"):
            snapshot["drop_without_fallback"] = True
        return snapshot

    if snapshot["profile"] == "late_only_opposite_signs_early90_tier1_fast_release":
        target_game_time_raw = payload.get("target_game_time")
        try:
            target_game_time = (
                float(target_game_time_raw)
                if target_game_time_raw is not None
                else float(LATE_PUB_COMEBACK_TABLE_START_SECONDS)
            )
        except (TypeError, ValueError):
            target_game_time = float(LATE_PUB_COMEBACK_TABLE_START_SECONDS)

        if current_game_time < float(NETWORTH_GATE_EARLY_WINDOW_END_SECONDS):
            next_threshold_raw = payload.get(
                "networth_monitor_threshold_4_to_10",
                payload.get("networth_monitor_threshold"),
            )
            next_status_label = str(
                payload.get("networth_monitor_status_4_to_10")
                or payload.get("dispatch_status_label")
                or snapshot["status_label"]
                or ""
            )
        elif current_game_time < target_game_time:
            next_threshold_raw = payload.get(
                "networth_monitor_threshold_10_to_20",
                payload.get("networth_monitor_threshold"),
            )
            next_status_label = str(
                payload.get("networth_monitor_status_10_to_20")
                or payload.get("dispatch_status_label")
                or snapshot["status_label"]
                or ""
            )
        else:
            snapshot["threshold"] = None
            return snapshot

        try:
            next_threshold = float(next_threshold_raw) if next_threshold_raw is not None else None
        except (TypeError, ValueError):
            next_threshold = None
        snapshot["threshold"] = next_threshold
        snapshot["status_label"] = next_status_label
        return snapshot

    if snapshot["profile"] != "late_only_opposite_signs_early90":
        return snapshot
    snapshot["threshold"] = None
    snapshot["status_label"] = str(
        payload.get("dispatch_status_label")
        or payload.get("timeout_status_label")
        or snapshot["status_label"]
        or ""
    )
    return snapshot


def _format_game_clock(game_time_seconds: Any) -> str:
    try:
        sec = max(0.0, float(game_time_seconds or 0.0))
    except (TypeError, ValueError):
        sec = 0.0
    return f"{int(sec // 60):02d}:{int(sec % 60):02d}"


