# kills_window dict blocks (Early Winner path) — stable indices.
KILLS_WINDOW_BLOCKS = (
    {"index": 0, "label": "5_15", "start_min": 5, "end_min": 15},
    {"index": 1, "label": "10_20", "start_min": 10, "end_min": 20},
    {"index": 2, "label": "15_25", "start_min": 15, "end_min": 25},
    {"index": 3, "label": "20_30", "start_min": 20, "end_min": 30},
)

_EARLY_KILLS_STATUS_TO_BLOCK_INDEX = {
    NETWORTH_STATUS_TIER1_EARLY_KILLS_LANE_ADV_DICT_IMMEDIATE_SEND: 0,
    NETWORTH_STATUS_LANE_ADV_DICT_STANDALONE_KILLS_SEND: 0,
    NETWORTH_STATUS_TIER1_EARLY_KILLS_PRE6_WAIT: 0,
    NETWORTH_STATUS_TIER1_EARLY_KILLS_3_6_LEAD_SEND: 1,
    NETWORTH_STATUS_TIER1_EARLY_KILLS_6_10_TARGET_NONNEG_SEND: 2,
    # historical name 4_12; runtime window is 10–13 fallback.
    NETWORTH_STATUS_TIER1_EARLY_KILLS_4_12_SEND_500: 3,
    NETWORTH_STATUS_TIER1_EARLY_KILLS_WINDOW_CLOSED: 4,
}


def _coerce_game_time_seconds(game_time_seconds: Any) -> Optional[float]:
    if game_time_seconds is None:
        return None
    try:
        value = float(game_time_seconds)
    except (TypeError, ValueError):
        return None
    if value != value:  # NaN
        return None
    return value


def _early_kills_time_block_index_from_game_time(
    game_time_seconds: Any,
) -> Optional[int]:
    gt = _coerce_game_time_seconds(game_time_seconds)
    if gt is None:
        return None
    if gt < 3 * 60:
        return 0
    if gt < 6 * 60:
        return 1
    if gt < 10 * 60:
        return 2
    if gt < float(NETWORTH_GATE_TIER1_EARLY_KILLS_DISPATCH_MAX_SECONDS):
        return 3
    return 4


def _early_kills_time_block_index_from_status(
    status_label: Any,
) -> Optional[int]:
    key = str(status_label or "").strip()
    if not key:
        return None
    if key in _EARLY_KILLS_STATUS_TO_BLOCK_INDEX:
        return int(_EARLY_KILLS_STATUS_TO_BLOCK_INDEX[key])
    # soft match for future renames
    low = key.lower()
    if "window_closed" in low or "closed" in low and "kills" in low:
        return 4
    if "3_6" in low or "3-6" in low:
        return 1
    if "6_10" in low or "6-10" in low:
        return 2
    if "4_12" in low or "fallback" in low or "10_" in low:
        return 3
    if "immediate" in low or "standalone" in low or "pre6" in low or "pre3" in low:
        return 0
    return None


def _resolve_early_kills_time_block(
    *,
    game_time_seconds: Any = None,
    status_label: Any = None,
) -> Optional[Dict[str, Any]]:
    idx = _early_kills_time_block_index_from_status(status_label)
    if idx is None:
        idx = _early_kills_time_block_index_from_game_time(game_time_seconds)
    if idx is None:
        return None
    for block in EARLY_KILLS_TIME_BLOCKS:
        if int(block["index"]) == int(idx):
            return dict(block)
    return None


def _kills_window_block_index(label: Any) -> Optional[int]:
    text = str(label or "").strip()
    if not text:
        return None
    for block in KILLS_WINDOW_BLOCKS:
        if str(block["label"]) == text:
            return int(block["index"])
    return None


def _format_early_kills_time_blocks_block(
    *,
    game_time_seconds: Any = None,
    status_label: Any = None,
    kills_window_label: Any = None,
) -> str:
    """Telegram visibility: ordered kills time blocks + active index.

    Two modes:
      * NW/time gate (tier1 Early STAR kills / standalone) — default.
      * kills_window nearest block (Early Winner path) when label given.
    """
    lines: list[str] = []
    window_label = str(kills_window_label or "").strip()
    if window_label:
        active_idx = _kills_window_block_index(window_label)
        catalog = " | ".join(
            f"[{b['index']}]{b['label']}" for b in KILLS_WINDOW_BLOCKS
        )
        if active_idx is None:
            lines.append(f"Kills window blocks: {catalog}")
            lines.append(f"Kills gate: window {window_label} (nearest)")
        else:
            block = KILLS_WINDOW_BLOCKS[active_idx]
            lines.append(f"Kills window blocks: {catalog}")
            lines.append(
                f"Kills gate: [{active_idx}] {block['label']} "
                f"({block['start_min']}-{block['end_min']}m nearest)"
            )
        return "\n".join(lines) + "\n"

    catalog = " | ".join(
        f"[{b['index']}]{b['label']}" for b in EARLY_KILLS_TIME_BLOCKS
    )
    lines.append(f"Kills time blocks: {catalog}")
    active = _resolve_early_kills_time_block(
        game_time_seconds=game_time_seconds,
        status_label=status_label,
    )
    max_m = int(float(NETWORTH_GATE_TIER1_EARLY_KILLS_DISPATCH_MAX_SECONDS) // 60)
    header_m = int(float(EARLY_KILLS_HEADER_MAX_GAME_TIME_SECONDS) // 60)
    if active is None:
        lines.append(
            f"Kills gate: n/a | hard max {max_m}:00 | header strip {header_m}:00"
        )
    else:
        status_bit = ""
        status_text = str(status_label or "").strip()
        if status_text:
            status_bit = f" | status={status_text}"
        lines.append(
            f"Kills gate: [{active['index']}] {active['label']} "
            f"({active['rule']}) | hard max {max_m}:00 | "
            f"header strip {header_m}:00{status_bit}"
        )
    return "\n".join(lines) + "\n"


def _format_kills_window_values_block(
    *,
    radiant_heroes_and_pos: Any = None,
    dire_heroes_and_pos: Any = None,
) -> str:
    """Compute kills_window expected_diff for all windows and format for display.

    Always visible in the signal message above Time/Networth so the user can
    see the draft-based kill-window estimates regardless of bet type.
    """
    if not _ensure_kills_window_dict_loaded():
        return ""
    try:
        radiant_tokens = _draft_tokens_for_kills_window(radiant_heroes_and_pos)
        dire_tokens = _draft_tokens_for_kills_window(dire_heroes_and_pos)
        if not radiant_tokens or not dire_tokens:
            return ""
        kw = calculate_kills_window_advantage(
            radiant_tokens, dire_tokens, kills_window_dict, window=None,
        )
    except Exception as exc:
        logger.warning("kills_window display block failed: %s", exc)
        return ""
    if not isinstance(kw, dict) or not kw:
        return ""
    lines: list[str] = ["Kills_window:"]
    for start_m, end_m in _kills_window_specs():
        label = _kills_window_label(start_m, end_m)
        payload = kw.get(label)
        if isinstance(payload, dict):
            try:
                ed = float(payload.get("expected_diff", 0.0))
                lines.append(f"  {label}: {ed:+.2f}")
            except (TypeError, ValueError):
                lines.append(f"  {label}: n/a")
        else:
            lines.append(f"  {label}: n/a")
    return "\n".join(lines) + "\n"


def _strongest_kills_window_label(
    ed_by_label: Any,
    target_sign: Any,
    *,
    min_abs_ed: float = 0.0,
) -> Optional[str]:
    """Label of the same-side kills_window block with max |expected_diff|.

    Used to name the concrete window in the "Ранние килы" bet title. Only
    blocks whose expected_diff points at ``target_sign`` (and passes
    ``min_abs_ed``) compete; ties keep the earliest window.
    """
    if not isinstance(ed_by_label, dict) or not ed_by_label:
        return None
    try:
        sign = int(target_sign)
    except (TypeError, ValueError):
        return None
    if sign not in (-1, 1):
        return None
    try:
        min_abs = max(0.0, float(min_abs_ed))
    except (TypeError, ValueError):
        min_abs = 0.0
    best_label: Optional[str] = None
    best_abs = 0.0
    for block in KILLS_WINDOW_BLOCKS:
        label = str(block["label"])
        try:
            value = float(ed_by_label.get(label))
        except (TypeError, ValueError):
            continue
        if not math.isfinite(value) or value == 0.0:
            continue
        if (1 if value > 0 else -1) != sign:
            continue
        if abs(value) < min_abs:
            continue
        if best_label is None or abs(value) > best_abs:
            best_label = label
            best_abs = abs(value)
    return best_label


def _format_live_message_state_block(
    *,
    game_time_seconds: Any,
    radiant_lead: Any,
    radiant_team_name: Any,
    dire_team_name: Any,
    show_kills_time_blocks: bool = False,
    kills_release_status: Any = None,
    kills_window_label: Any = None,
    radiant_heroes_and_pos: Any = None,
    dire_heroes_and_pos: Any = None,
) -> str:
    time_line = f"Time: {_format_game_clock(game_time_seconds)}"
    try:
        lead_value = float(radiant_lead or 0.0)
    except (TypeError, ValueError):
        lead_value = 0.0
    abs_lead = int(round(abs(lead_value)))
    if _networth_lead_is_unknown(radiant_lead, game_time_seconds):
        # Пустой фид больше не рисуем как «равный нетворс» — это фейковые данные.
        networth_line = "Networth: н/д (нет данных)"
    elif abs_lead <= 0:
        networth_line = "Networth: 0"
    elif lead_value > 0:
        networth_line = f"Networth: {str(radiant_team_name or 'Radiant')} +{abs_lead}"
    else:
        networth_line = f"Networth: {str(dire_team_name or 'Dire')} +{abs_lead}"
    kills_window_block = _format_kills_window_values_block(
        radiant_heroes_and_pos=radiant_heroes_and_pos,
        dire_heroes_and_pos=dire_heroes_and_pos,
    )
    body = f"{kills_window_block}{time_line}\n{networth_line}\n"
    if show_kills_time_blocks or kills_window_label:
        body += _format_early_kills_time_blocks_block(
            game_time_seconds=game_time_seconds,
            status_label=kills_release_status,
            kills_window_label=kills_window_label,
        )
    return body


# Match-key → steam_id / json_url remembered while processing a live card so
# delayed / multi-branch dispatch can still fetch DLTV draft votes.
_DLTV_DISPATCH_CONTEXT_BY_MATCH_KEY: Dict[str, Dict[str, Any]] = {}
_DLTV_DISPATCH_CONTEXT_LOCK = threading.Lock()


def _steam_id_from_dltv_json_url(json_url: Any) -> Optional[int]:
    text = str(json_url or "").strip()
    if not text:
        return None
    match = re.search(
        r"(?:dltv\.org/live/|sourcetv://matches/)(\d+)",
        text,
        flags=re.IGNORECASE,
    )
    if not match:
        return None
    try:
        value = int(match.group(1))
    except (TypeError, ValueError):
        return None
    return value if value > 0 else None


def _remember_dltv_dispatch_context(
    match_key: str,
    *,
    steam_id: Any = None,
    json_url: Any = None,
    live_data: Any = None,
) -> None:
    key = str(match_key or "").strip()
    if not key:
        return
    resolved_steam = _coerce_int(steam_id)
    if resolved_steam <= 0:
        resolved_steam = _steam_id_from_dltv_json_url(json_url) or 0
    if resolved_steam <= 0 and isinstance(live_data, dict):
        resolved_steam = int(_extract_live_match_id(live_data) or 0)
    payload: Dict[str, Any] = {}
    if resolved_steam > 0:
        payload["steam_id"] = int(resolved_steam)
    url_text = str(json_url or "").strip()
    if url_text:
        payload["json_url"] = url_text
    elif resolved_steam > 0:
        payload["json_url"] = f"https://dltv.org/live/{resolved_steam}.json"
    if isinstance(live_data, dict):
        vote = _parse_dltv_draft_vote_from_live_payload(live_data)
        if vote is not None:
            payload["last_vote"] = vote
    if not payload:
        return
    with _DLTV_DISPATCH_CONTEXT_LOCK:
        prev = dict(_DLTV_DISPATCH_CONTEXT_BY_MATCH_KEY.get(key) or {})
        prev.update(payload)
        _DLTV_DISPATCH_CONTEXT_BY_MATCH_KEY[key] = prev


def _lookup_dltv_dispatch_context(match_key: str) -> Dict[str, Any]:
    key = str(match_key or "").strip()
    if not key:
        return {}
    with _DLTV_DISPATCH_CONTEXT_LOCK:
        cached = dict(_DLTV_DISPATCH_CONTEXT_BY_MATCH_KEY.get(key) or {})
    if cached:
        return cached
    with monitored_matches_lock:
        delayed = monitored_matches.get(key)
    if isinstance(delayed, dict):
        steam = _steam_id_from_dltv_json_url(delayed.get("json_url"))
        out: Dict[str, Any] = {}
        if steam:
            out["steam_id"] = int(steam)
        if delayed.get("json_url"):
            out["json_url"] = str(delayed.get("json_url"))
        return out
    return {}


def _parse_dltv_draft_vote_from_live_payload(data: Any) -> Optional[Dict[str, Any]]:
    """Extract draft-vote bar from DLTV live/{steam_id}.json.

    UI ``picks__new-vote``: side_0 = Radiant, side_1 = Dire.

    ``db.first_team`` / ``db.second_team`` are series-order slots, NOT always
    Radiant/Dire. Resolve actual sides via each team's ``is_radiant`` flag
    (same rule as the main DLTV card path).

    Payload БЕЗ блока ``db.series.likes`` — это не dltv live JSON (например
    sourcetv-payload основного цикла), и голосованием он не является: возвращаем
    ``None``, иначе мнимое «0-0» перебивало бы HTTP-резолв, в котором голоса и
    лежат. Настоящее «голосов нет» — это присутствующий ``likes`` с нулями.
    """
    if not isinstance(data, dict):
        return None
    series = ((data.get("db") or {}).get("series") or {}) if isinstance(data.get("db"), dict) else {}
    if not isinstance(series, dict):
        series = {}
    if not isinstance(series.get("likes"), dict):
        return None
    likes = series.get("likes")
    try:
        radiant_likes = float(likes.get("side_0") or 0)
        dire_likes = float(likes.get("side_1") or 0)
    except (TypeError, ValueError):
        return None
    if radiant_likes < 0 or dire_likes < 0:
        return None
    total = radiant_likes + dire_likes
    first_team = (data.get("db") or {}).get("first_team") if isinstance(data.get("db"), dict) else {}
    second_team = (data.get("db") or {}).get("second_team") if isinstance(data.get("db"), dict) else {}
    if not isinstance(first_team, dict):
        first_team = {}
    if not isinstance(second_team, dict):
        second_team = {}

    first_name = str(first_team.get("title") or first_team.get("name") or "").strip()
    second_name = str(second_team.get("title") or second_team.get("name") or "").strip()
    first_is_radiant = first_team.get("is_radiant")
    second_is_radiant = second_team.get("is_radiant")

    # Prefer explicit is_radiant flags; fall back to series order only when both
    # sides omit the flag (legacy payloads / unit fixtures).
    if first_is_radiant is True or second_is_radiant is False:
        radiant_name = first_name or "Radiant"
        dire_name = second_name or "Dire"
    elif first_is_radiant is False or second_is_radiant is True:
        radiant_name = second_name or "Radiant"
        dire_name = first_name or "Dire"
    else:
        radiant_name = first_name or "Radiant"
        dire_name = second_name or "Dire"

    return {
        "radiant_likes": radiant_likes,
        "dire_likes": dire_likes,
        "radiant_pct": round(100.0 * radiant_likes / total, 1) if total > 0 else None,
        "dire_pct": round(100.0 * dire_likes / total, 1) if total > 0 else None,
        "radiant_team": radiant_name,
        "dire_team": dire_name,
        "is_draft_voting": series.get("is_draft_voting"),
        "steam_id": _extract_live_match_id(data),
    }


def _format_dltv_rating_line(vote: Optional[Dict[str, Any]], *, unavailable: bool = False) -> str:
    if unavailable:
        return "DLTV rating: unavailable"
    if not isinstance(vote, dict):
        return "DLTV rating: unavailable"
    try:
        r_likes = float(vote.get("radiant_likes") or 0)
        d_likes = float(vote.get("dire_likes") or 0)
    except (TypeError, ValueError):
        return "DLTV rating: unavailable"
    total = r_likes + d_likes
    if total <= 0:
        return "DLTV rating: no votes"
    r_pct = vote.get("radiant_pct")
    d_pct = vote.get("dire_pct")
    try:
        r_pct_f = float(r_pct) if r_pct is not None else 100.0 * r_likes / total
        d_pct_f = float(d_pct) if d_pct is not None else 100.0 * d_likes / total
    except (TypeError, ValueError):
        r_pct_f = 100.0 * r_likes / total
        d_pct_f = 100.0 * d_likes / total
    radiant = normalize_team_name_display(str(vote.get("radiant_team") or "Radiant")) or "Radiant"
    dire = normalize_team_name_display(str(vote.get("dire_team") or "Dire")) or "Dire"
    return (
        f"DLTV rating: {radiant} {r_pct_f:.1f}% / {dire} {d_pct_f:.1f}% "
        f"({int(round(r_likes))}-{int(round(d_likes))})"
    )


def _fetch_dltv_live_json_for_rating(steam_id: int) -> Optional[Dict[str, Any]]:
    url = f"https://dltv.org/live/{int(steam_id)}.json"
    timeout = float(DLTV_RATING_FETCH_TIMEOUT_SECONDS)
    try:
        resp = requests.get(url, proxies=PROXIES, timeout=timeout, verify=False)
        if resp.status_code == 200:
            data = resp.json()
            return data if isinstance(data, dict) else None
        if resp.status_code == 429:
            rotate_proxy()
    except Exception as exc:
        logger.warning("DLTV rating fetch failed via proxy for %s: %s", steam_id, exc)
    try:
        resp = requests.get(url, proxies=None, timeout=timeout, verify=False)
        if resp.status_code == 200:
            data = resp.json()
            return data if isinstance(data, dict) else None
    except Exception as exc:
        logger.warning("DLTV rating fetch failed direct for %s: %s", steam_id, exc)
    return None


def _resolve_dltv_draft_vote_for_dispatch(
    match_key: str,
    *,
    json_url: Any = None,
    live_data: Any = None,
    steam_id: Any = None,
) -> tuple[Optional[Dict[str, Any]], str]:
    """Fresh-parse DLTV draft vote before dispatch.

    Returns (vote_or_none, source) where source is live_data|fetch|cache|none.
    """
    if isinstance(live_data, dict):
        vote = _parse_dltv_draft_vote_from_live_payload(live_data)
        if vote is not None:
            return vote, "live_data"

    ctx = _lookup_dltv_dispatch_context(match_key)
    resolved_steam = _coerce_int(steam_id)
    if resolved_steam <= 0:
        resolved_steam = _steam_id_from_dltv_json_url(json_url) or 0
    if resolved_steam <= 0:
        resolved_steam = _coerce_int(ctx.get("steam_id"))
    if resolved_steam <= 0:
        resolved_steam = _steam_id_from_dltv_json_url(ctx.get("json_url")) or 0

    if resolved_steam > 0:
        fetched = _fetch_dltv_live_json_for_rating(int(resolved_steam))
        if isinstance(fetched, dict):
            vote = _parse_dltv_draft_vote_from_live_payload(fetched)
            if vote is not None:
                _remember_dltv_dispatch_context(
                    match_key,
                    steam_id=resolved_steam,
                    json_url=f"https://dltv.org/live/{resolved_steam}.json",
                    live_data=fetched,
                )
                return vote, "fetch"

    cached_vote = ctx.get("last_vote")
    if isinstance(cached_vote, dict):
        return cached_vote, "cache"
    return None, "none"


_DLTV_RATING_STAR_CACHE: Dict[str, Tuple[float, Optional[float]]] = {}
_DLTV_RATING_STAR_CACHE_LOCK = threading.Lock()


def _dltv_rating_star_cache_get(match_key: str) -> Tuple[bool, Optional[float]]:
    """(hit, value) из TTL-кэша; кэшируется и отрицательный результат (нет голосов)."""
    ttl = float(DLTV_RATING_STAR_TTL_SECONDS)
    if ttl <= 0:
        return False, None
    key = str(match_key or "").strip()
    if not key:
        return False, None
    with _DLTV_RATING_STAR_CACHE_LOCK:
        entry = _DLTV_RATING_STAR_CACHE.get(key)
    if not entry:
        return False, None
    stamp, value = entry
    if (time.time() - float(stamp)) > ttl:
        return False, None
    return True, value


def _dltv_rating_star_cache_put(match_key: str, value: Optional[float]) -> None:
    if float(DLTV_RATING_STAR_TTL_SECONDS) <= 0:
        return
    key = str(match_key or "").strip()
    if not key:
        return
    with _DLTV_RATING_STAR_CACHE_LOCK:
        _DLTV_RATING_STAR_CACHE[key] = (time.time(), value)


def _dltv_rating_star_value(
    match_key: str,
    *,
    json_url: Any = None,
    live_data: Any = None,
    steam_id: Any = None,
) -> Optional[float]:
    """STAR-значение метрики ``dltv_rating`` = ``radiant_pct - 50``.

    Знак как у остальных star-метрик: ``+`` = Radiant, ``-`` = Dire. Порог хита
    (30) живёт в ``data/star_thresholds_by_wr.json`` для секции ``all_output``
    на уровнях WR60/WR65, поэтому в ``⭐ Star hits`` метрика всегда печатается
    как WR65. Возвращает ``None``, когда голосование выключено, недоступно или
    ровно 50/50 (нулевые значения star-логикой всё равно игнорируются).

    Результат (в том числе отрицательный) кэшируется на
    ``DLTV_RATING_STAR_TTL_SECONDS``: голоса берутся HTTP-запросом, а метрика
    считается каждый цикл на каждый матч.
    """
    if not DLTV_RATING_IN_SIGNAL:
        return None
    cached, cached_value = _dltv_rating_star_cache_get(match_key)
    if cached:
        return cached_value
    vote, _source = _resolve_dltv_draft_vote_for_dispatch(
        match_key,
        json_url=json_url,
        live_data=live_data,
        steam_id=steam_id,
    )
    if not isinstance(vote, dict):
        _dltv_rating_star_cache_put(match_key, None)
        return None
    try:
        radiant_likes = float(vote.get("radiant_likes") or 0)
        dire_likes = float(vote.get("dire_likes") or 0)
    except (TypeError, ValueError):
        _dltv_rating_star_cache_put(match_key, None)
        return None
    total = radiant_likes + dire_likes
    # Мало голосов -> процент не сигнал: 100/0 достигается одним голосом.
    # Типичное финальное голосование — десятки голосов (медиана ~68 по логу),
    # так что для нормальных матчей это не фильтр, а отсечка вырожденных.
    if total <= 0 or total < float(DLTV_RATING_MIN_VOTES):
        _dltv_rating_star_cache_put(match_key, None)
        return None
    raw_pct = vote.get("radiant_pct")
    if raw_pct is None:
        raw_pct = 100.0 * radiant_likes / total
    try:
        value = round(float(raw_pct) - 50.0, 1)
    except (TypeError, ValueError):
        _dltv_rating_star_cache_put(match_key, None)
        return None
    if not math.isfinite(value) or value == 0.0:
        _dltv_rating_star_cache_put(match_key, None)
        return None
    _dltv_rating_star_cache_put(match_key, value)
    return value


def _apply_dltv_rating_star_metric(
    all_output: Optional[Dict[str, Any]],
    match_key: str,
    *,
    json_url: Any = None,
    live_data: Any = None,
    steam_id: Any = None,
) -> Optional[float]:
    """Дописать ``dltv_rating`` в базовый All-блок (in-place). Вернуть значение."""
    if not isinstance(all_output, dict):
        return None
    value = _dltv_rating_star_value(
        match_key,
        json_url=json_url,
        live_data=live_data,
        steam_id=steam_id,
    )
    if value is None:
        return None
    all_output["dltv_rating"] = value
    return value


def _append_dltv_rating_line(message_text: str, line: str) -> str:
    text = str(message_text or "")
    rating_line = str(line or "").strip()
    if not rating_line:
        return text
    # Replace a previously appended rating line (re-dispatch / refresh paths).
    stripped = re.sub(
        r"(?:\n|^)DLTV rating:[^\n]*",
        "",
        text,
        flags=re.IGNORECASE,
    ).rstrip()
    if not stripped:
        return rating_line
    return f"{stripped}\n{rating_line}"


def _enrich_message_with_dltv_rating(
    match_key: str,
    message_text: str,
    *,
    json_url: Any = None,
    live_data: Any = None,
    steam_id: Any = None,
) -> str:
    if not DLTV_RATING_IN_SIGNAL:
        return message_text
    vote, source = _resolve_dltv_draft_vote_for_dispatch(
        match_key,
        json_url=json_url,
        live_data=live_data,
        steam_id=steam_id,
    )
    line = _format_dltv_rating_line(vote, unavailable=(vote is None))
    print(f"   📊 {line} (source={source})")
    return _append_dltv_rating_line(message_text, line)


def _late_comeback_monitor_entry_for_game_time(
    game_time_seconds: Any,
) -> tuple[Optional[int], Optional[float]]:
    if not isinstance(late_comeback_ceiling_thresholds, dict) or not late_comeback_ceiling_thresholds:
        return None, None
    try:
        minute = int(max(0.0, float(game_time_seconds or 0.0)) // 60)
    except (TypeError, ValueError):
        return None, None
    threshold_raw = late_comeback_ceiling_thresholds.get(str(minute))
    try:
        threshold = float(threshold_raw) if threshold_raw is not None else None
    except (TypeError, ValueError):
        threshold = None
    return minute, threshold


def _late_comeback_monitor_deadline_seconds() -> Optional[float]:
    try:
        max_minute = int(late_comeback_ceiling_max_minute)
    except (TypeError, ValueError):
        return None
    return float((max_minute + 1) * 60)


def _late_comeback_monitor_check(
    *,
    game_time_seconds: Any,
    target_networth_diff: Optional[float],
) -> Dict[str, Any]:
    minute, threshold = _late_comeback_monitor_entry_for_game_time(game_time_seconds)
    try:
        target_diff = float(target_networth_diff) if target_networth_diff is not None else None
    except (TypeError, ValueError):
        target_diff = None
    deficit = None
    if target_diff is not None:
        deficit = abs(target_diff) if target_diff < 0 else 0.0
    ready = bool(deficit is not None and threshold is not None and deficit <= threshold)
    return {
        "minute": minute,
        "threshold": threshold,
        "deficit": deficit,
        "ready": ready,
    }


def _post_target_comeback_ceiling_decision(
    *,
    game_time_seconds: Any,
    target_networth_diff: Optional[float],
) -> Dict[str, Any]:
    check = _late_comeback_monitor_check(
        game_time_seconds=game_time_seconds,
        target_networth_diff=target_networth_diff,
    )
    deadline_game_time = _late_comeback_monitor_deadline_seconds()
    try:
        current_game_time = float(game_time_seconds or 0.0)
    except (TypeError, ValueError):
        current_game_time = None
    threshold = check.get("threshold")
    ready = bool(check.get("ready"))
    should_monitor = bool(
        threshold is not None
        and not ready
        and deadline_game_time is not None
        and current_game_time is not None
        and current_game_time < deadline_game_time
    )
    should_timeout = bool(
        threshold is not None
        and not ready
        and deadline_game_time is not None
        and current_game_time is not None
        and current_game_time >= deadline_game_time
    )
    return {
        **check,
        "available": bool(threshold is not None),
        "deadline_game_time": deadline_game_time,
        "should_monitor": should_monitor,
        "should_timeout": should_timeout,
    }


def _is_cyberscore_match_url(url: Optional[str]) -> bool:
    return "cyberscore.live" in str(url or "").lower() and "/matches/" in str(url or "").lower()


def _cyberscore_item_game_time(item: Any) -> int:
    if not isinstance(item, dict):
        return 0
    try:
        return int(item.get("game_time") or item.get("ticks_game_time") or 0)
    except (TypeError, ValueError):
        return 0


def _cyberscore_cache_bust_url(target_url: str) -> str:
    separator = "&" if "?" in str(target_url or "") else "?"
    return f"{target_url}{separator}_delayed_ts={int(time.time() * 1000)}"


def _get_cyberscore_delayed_html_via_camoufox(target_url: str) -> Optional[str]:
    if not CAMOUFOX_AVAILABLE:
        print("⚠️ CyberScore delayed state: Camoufox unavailable")
        return None
    target_url = str(target_url or "").strip()
    if not target_url:
        return None
    try:
        _kind, cache_key = _cyberscore_long_page_kind_and_key(target_url)
        _cyberscore_close_cached_long_page(cache_key, reason="delayed fresh fetch")
    except Exception:
        pass
    fresh_url = _cyberscore_cache_bust_url(target_url)
    attempts = max(1, int(CYBERSCORE_CAMOUFOX_FETCH_ATTEMPTS or 1))
    for attempt_index in range(attempts):
        html = _get_cyberscore_html_via_one_shot(fresh_url)
        if html:
            return html
        if attempt_index + 1 < attempts:
            print(f"🔁 CyberScore delayed fetch retry {attempt_index + 2}/{attempts}: {target_url}")
    return None


def _fetch_cyberscore_delayed_match_state(match_url: Optional[str]) -> Optional[Dict[str, Optional[float]]]:
    if not match_url:
        return None
    match_id_match = re.search(r"/matches/(\d+)", str(match_url or ""))
    match_id = match_id_match.group(1) if match_id_match else ""

    # 1. Сначала проверяем кэш листинга (0 сетевых запросов)
    listing_item = CYBERSCORE_LISTING_ITEM_CACHE.get(str(match_id)) if match_id else None
    if isinstance(listing_item, dict):
        payload = _cyberscore_item_to_runtime_payload(listing_item)
        game_time = payload.get("game_time")
        radiant_lead = payload.get("radiant_lead")
        try:
            game_time_value = float(game_time)
            lead_value = float(radiant_lead) if radiant_lead is not None else None
            return _bookmaker_enrich_delayed_match_state(
                {"game_time": game_time_value, "radiant_lead": lead_value},
                payload,
            )
        except (TypeError, ValueError):
            pass

    # 2. Проверяем состояние живого ватчера (websocket/page, если включен)
    watcher_state = _fetch_cyberscore_live_watcher_state(str(match_url))
    if isinstance(watcher_state, dict):
        return watcher_state

    # 3. Фолбек: детальный сетевой запрос (если матча нет в кэше)
    response_text = _get_cyberscore_delayed_html_via_camoufox(str(match_url))
    cyber_item = None
    if response_text:
        cyber_item = _extract_cyberscore_match_item_from_html(response_text, match_id=match_id or None)
    if not isinstance(cyber_item, dict):
        return None
    payload = _cyberscore_item_to_runtime_payload(cyber_item)
    game_time = payload.get("game_time")
    radiant_lead = payload.get("radiant_lead")
    try:
        game_time_value = float(game_time)
    except (TypeError, ValueError):
        return None
    try:
        lead_value = float(radiant_lead) if radiant_lead is not None else None
    except (TypeError, ValueError):
        lead_value = None
    return _bookmaker_enrich_delayed_match_state({"game_time": game_time_value, "radiant_lead": lead_value}, payload)


def _fetch_sourcetv_delayed_match_state(json_url: str) -> Optional[Dict[str, Optional[float]]]:
    """game_time/radiant_lead для delayed-watcher из SOURCETV_MATCHES_PATH (URL sourcetv://matches/<id>)."""
    id_match = re.search(r"sourcetv://matches/(\d+)", str(json_url))
    if not id_match:
        return None
    try:
        with open(SOURCETV_MATCHES_PATH) as f:
            matches = json.load(f)
    except Exception:
        return None
    payload = matches.get(id_match.group(1))
    if not isinstance(payload, dict):
        return None
    # протухшая запись (probe не обновлял >300с) — данных нет
    if time.time() - float(payload.get("timestamp") or 0) > 300:
        return None
    try:
        game_time_value = float(payload.get("game_time"))
    except (TypeError, ValueError):
        return None
    try:
        radiant_lead = payload.get("radiant_lead")
        lead_value = float(radiant_lead) if radiant_lead is not None else None
    except (TypeError, ValueError):
        lead_value = None
    return _bookmaker_enrich_delayed_match_state({"game_time": game_time_value, "radiant_lead": lead_value}, payload)


def _sourcetv_delayed_league_meta(
    json_url: Optional[str],
) -> Optional[Tuple[int, str]]:
    """``(league_id, league_name)`` матча из моста по sourcetv://-URL."""
    id_match = re.search(r"sourcetv://matches/(\d+)", str(json_url or ""))
    if not id_match:
        return None
    try:
        with open(SOURCETV_MATCHES_PATH) as f:
            matches = json.load(f)
    except Exception:
        return None
    payload = matches.get(id_match.group(1))
    if not isinstance(payload, dict):
        return None
    try:
        league_id = int(payload.get("league_id") or 0)
    except (TypeError, ValueError):
        league_id = 0
    return league_id, str(payload.get("league_name") or "")


def _sourcetv_delayed_league_name(json_url: Optional[str]) -> Optional[str]:
    """Обратная совместимость для callers, которым нужно только название."""
    meta = _sourcetv_delayed_league_meta(json_url)
    return meta[1] if meta is not None else None


def _fetch_delayed_match_state(json_url: Optional[str]) -> Optional[Dict[str, Optional[float]]]:
    if not json_url:
        return None
    if str(json_url).startswith("sourcetv://"):
        return _fetch_sourcetv_delayed_match_state(str(json_url))
    if _is_cyberscore_match_url(json_url):
        return _fetch_cyberscore_delayed_match_state(json_url)
    try:
        resp = make_request_with_retry(
            json_url,
            max_retries=3,
            retry_delay=2,
            headers=globals().get('headers'),
        )
    except Exception as e:
        print(f"⚠️ Delayed sender: ошибка запроса game_time ({json_url}): {e}")
        return None
    if not resp or resp.status_code != 200:
        return None
    try:
        payload = resp.json()
    except Exception:
        return None

    game_time = payload.get('game_time')
    if game_time is None:
        live_league = payload.get('live_league_data') or {}
        game_time = live_league.get('game_time')
    if game_time is None:
        live_match = (payload.get('live_league_data') or {}).get('match') or {}
        game_time = live_match.get('game_time')
    if game_time is None:
        return None

    radiant_lead = payload.get('radiant_lead')
    if radiant_lead is None:
        live_league = payload.get('live_league_data') or {}
        radiant_lead = live_league.get('radiant_lead')
    if radiant_lead is None:
        live_match = (payload.get('live_league_data') or {}).get('match') or {}
        radiant_lead = live_match.get('radiant_lead')

    try:
        game_time_value = float(game_time)
    except (TypeError, ValueError):
        return None
    lead_value: Optional[float]
    try:
        lead_value = float(radiant_lead) if radiant_lead is not None else None
    except (TypeError, ValueError):
        lead_value = None
    return _bookmaker_enrich_delayed_match_state({"game_time": game_time_value, "radiant_lead": lead_value}, payload)


def _fetch_delayed_match_game_time(json_url: Optional[str]) -> Optional[float]:
    state = _fetch_delayed_match_state(json_url)
    if not isinstance(state, dict):
        return None
    value = state.get("game_time")
    try:
        return float(value) if value is not None else None
    except (TypeError, ValueError):
        return None


def _maybe_refresh_stale_cyberscore_delayed_state(
    match_key: str,
    payload: Dict[str, Any],
    *,
    current_game_time: float,
    target_game_time: float,
    now_ts: float,
    last_progress_at: float,
) -> bool:
    json_url = str(payload.get("json_url") or "")
    if not _is_cyberscore_match_url(json_url):
        return False
    stale_age = float(now_ts) - float(last_progress_at)
    if stale_age < float(CYBERSCORE_DELAYED_STALE_REFRESH_SECONDS):
        return False
    try:
        last_refresh_at = float(payload.get("last_cyberscore_stale_refresh_at") or 0.0)
    except (TypeError, ValueError):
        last_refresh_at = 0.0
    if last_refresh_at and now_ts - last_refresh_at < float(CYBERSCORE_DELAYED_STALE_REFRESH_SECONDS):
        return False
    match_id_match = re.search(r"/matches/(\d+)", json_url)
    if match_id_match:
        with contextlib.suppress(Exception):
            CYBERSCORE_LISTING_ITEM_CACHE.pop(match_id_match.group(1), None)
    with contextlib.suppress(Exception):
        _shared_camoufox_session.request_reset()
    try:
        refresh_count = int(payload.get("cyberscore_stale_refresh_count") or 0) + 1
    except (TypeError, ValueError):
        refresh_count = 1
    _update_delayed_match(
        match_key,
        last_cyberscore_stale_refresh_at=float(now_ts),
        cyberscore_stale_refresh_count=refresh_count,
    )
    print(
        "🔄 CyberScore delayed stale state refresh requested: "
        f"{match_key} (game_time={int(current_game_time)}, "
        f"target={_format_game_clock(target_game_time)}, "
        f"stale_age={int(stale_age)}s, count={refresh_count})"
    )
    return True


def _runtime_payload_delayed_state(payload: Optional[Dict[str, Any]]) -> Optional[Dict[str, Optional[float]]]:
    if not isinstance(payload, dict):
        return None
    game_time = payload.get("game_time")
    if game_time is None:
        live_league = payload.get("live_league_data") or {}
        game_time = live_league.get("game_time")
    if game_time is None:
        live_match = (payload.get("live_league_data") or {}).get("match") or {}
        game_time = live_match.get("game_time")
    try:
        game_time_value = float(game_time)
    except (TypeError, ValueError):
        return None
    radiant_lead = payload.get("radiant_lead")
    if radiant_lead is None:
        live_league = payload.get("live_league_data") or {}
        radiant_lead = live_league.get("radiant_lead")
    if radiant_lead is None:
        live_match = (payload.get("live_league_data") or {}).get("match") or {}
        radiant_lead = live_match.get("radiant_lead")
    try:
        lead_value = float(radiant_lead) if radiant_lead is not None else None
    except (TypeError, ValueError):
        lead_value = None
    return {"game_time": game_time_value, "radiant_lead": lead_value}


def _queue_delayed_state_override(match_key: str, state: Optional[Dict[str, Optional[float]]]) -> bool:
    if not match_key or not isinstance(state, dict):
        return False
    try:
        game_time_value = float(state.get("game_time"))
    except (TypeError, ValueError):
        return False
    radiant_lead = state.get("radiant_lead")
    try:
        lead_value = float(radiant_lead) if radiant_lead is not None else None
    except (TypeError, ValueError):
        lead_value = None
    with delayed_state_overrides_lock:
        delayed_state_overrides[str(match_key)] = {
            "game_time": game_time_value,
            "radiant_lead": lead_value,
        }
    return True


def _pop_delayed_state_override(match_key: str) -> Optional[Dict[str, Optional[float]]]:
    with delayed_state_overrides_lock:
        return delayed_state_overrides.pop(str(match_key), None)


def _try_release_delayed_from_live_recheck(
    match_key: str,
    payload: Dict[str, Any],
    runtime_payload: Optional[Dict[str, Any]],
    target_game_time: float,
) -> bool:
    state = _runtime_payload_delayed_state(runtime_payload)
    if not isinstance(state, dict):
        return False
    try:
        current_game_time = float(state.get("game_time"))
    except (TypeError, ValueError):
        return False
    if current_game_time < float(target_game_time):
        return False
    if not _queue_delayed_state_override(match_key, state):
        return False
    target_side = str(payload.get("networth_target_side") or "").strip().lower()
    if target_side not in {"radiant", "dire"}:
        details = payload.get("add_url_details")
        if isinstance(details, dict):
            target_side = str(details.get("target_side") or "").strip().lower()
    target_diff = _target_networth_diff_from_radiant_lead(
        state.get("radiant_lead"), target_side, current_game_time
    )
    print(
        "   ⚡ Delayed live fast-check: "
        f"{match_key} crossed target={_format_game_clock(target_game_time)} "
        f"at game_time={_format_game_clock(current_game_time)}, "
        f"target_side={target_side or 'n/a'}, "
        f"target_diff={int(target_diff) if target_diff is not None else 'n/a'}, "
        f"reason={payload.get('reason', 'unknown')}"
    )
    _drain_due_delayed_signals_once(only_match_key=match_key)
    return True


def _drain_due_delayed_signals_once(only_match_key: Optional[str] = None) -> None:
    with monitored_matches_lock:
        if only_match_key is None:
            queued_items = list(monitored_matches.items())
        else:
            only_payload = monitored_matches.get(str(only_match_key))
            queued_items = [(str(only_match_key), only_payload)] if only_payload is not None else []
    if not queued_items:
        return

    now_ts = time.time()
    for match_key, payload in queued_items:
        if _is_url_processed(match_key):
            _drop_delayed_match(match_key, reason="already_processed")
            continue
        # League-guard: фильтр лиг применяется в get_heads только при первичном
        # приёме, но delayed-очередь живёт независимо (и переживает рестарт со
        # старым кодом). Если sourcetv-матч жив в мосте и его лига вне allowlist —
        # дропаем, чтобы мусорный турнир не ушёл по таймеру watcher'а.
        if str(payload.get("json_url") or "").startswith("sourcetv://"):
            _gd_league_meta = _sourcetv_delayed_league_meta(payload.get("json_url"))
            if (
                _gd_league_meta is not None
                and not _league_matches_allowlist(*_gd_league_meta)
            ):
                _gd_league = _gd_league_meta[1]
                _drop_delayed_match(match_key, reason="league_not_in_allowlist")
                print(f"   🚫 Delayed дроп: лига вне allowlist ({_gd_league}) — {match_key}")
                continue
        next_retry_at_raw = payload.get("next_retry_at")
        try:
            next_retry_at = float(next_retry_at_raw) if next_retry_at_raw is not None else 0.0
        except (TypeError, ValueError):
            next_retry_at = 0.0
        if next_retry_at > now_ts:
            continue
        target_game_time = float(payload.get('target_game_time', DELAYED_SIGNAL_TARGET_GAME_TIME))
        delayed_state = _pop_delayed_state_override(match_key)
        if isinstance(delayed_state, dict):
            print(
                "⚡ Delayed sender: using live recheck state "
                f"for {match_key} (game_time={int(float(delayed_state.get('game_time') or 0))})"
            )
        else:
            # Fallback: fetch only if no override arrived (main cycle should push overrides).
            # Локальный sourcetv-json читаем на каждом тике (дёшево и всегда свежий),
            # сетевые источники — не чаще DELAYED_SIGNAL_REMOTE_MIN_INTERVAL_SECONDS.
            delayed_json_url = payload.get('json_url')
            if not str(delayed_json_url or "").startswith("sourcetv://"):
                try:
                    last_remote_fetch_at = float(payload.get('last_remote_fetch_at') or 0.0)
                except (TypeError, ValueError):
                    last_remote_fetch_at = 0.0
                if now_ts - last_remote_fetch_at < DELAYED_SIGNAL_REMOTE_MIN_INTERVAL_SECONDS:
                    continue
                _update_delayed_match(match_key, last_remote_fetch_at=now_ts)
            delayed_state = _fetch_delayed_match_state(delayed_json_url)
        if not isinstance(delayed_state, dict):
            queued_at = float(payload.get('queued_at', now_ts))
            # После 4 часов без game_time считаем сигнал устаревшим.
            if now_ts - queued_at > DELAYED_SIGNAL_NO_DATA_TIMEOUT_SECONDS:
                _drop_delayed_match(match_key, reason="no_data_timeout")
                print(f"⚠️ Delayed сигнал устарел и удален: {match_key}")
            continue
        current_game_time_raw = delayed_state.get("game_time")
        try:
            current_game_time = float(current_game_time_raw)
        except (TypeError, ValueError):
            continue
        current_radiant_lead = delayed_state.get("radiant_lead")
        delayed_reason = str(payload.get("reason") or "").strip().lower()
        with monitored_matches_lock:
            current_payload = monitored_matches.get(match_key)
            if current_payload is None:
                continue
            prev_game_time = float(current_payload.get('last_game_time', current_game_time))
            last_progress_at = float(current_payload.get('last_progress_at', current_payload.get('queued_at', now_ts)))
            if current_game_time > prev_game_time + 1:
                last_progress_at = now_ts
        _update_delayed_match(
            match_key,
            last_game_time=float(current_game_time),
            last_checked_at=float(now_ts),
            last_progress_at=float(last_progress_at),
        )
        payload = dict(payload)
        payload.update(
            {
                "last_game_time": float(current_game_time),
                "last_checked_at": float(now_ts),
                "last_progress_at": float(last_progress_at),
            }
        )
        if now_ts - last_progress_at > DELAYED_SIGNAL_NO_PROGRESS_TIMEOUT_SECONDS:
            _drop_delayed_match(match_key, reason="no_progress_timeout")
            print(
                f"⚠️ Delayed сигнал удален (нет прогресса game_time): "
                f"{match_key}, last_game_time={int(current_game_time)}"
            )
            continue
        if delayed_reason == "late_only_opposite_signs":
            opposite_min_dispatch_time = float(LATE_PUB_COMEBACK_TABLE_START_SECONDS)
            opposite_payload_updates: Dict[str, Any] = {}
            late_pre27_dominance_active = bool(
                payload.get("dynamic_monitor_profile") == LATE_PRE27_DOMINANCE_PROFILE
            )
            if target_game_time < opposite_min_dispatch_time:
                target_game_time = opposite_min_dispatch_time
                opposite_payload_updates["target_game_time"] = float(opposite_min_dispatch_time)
            if payload.get("dynamic_monitor_profile") in {
                "late_only_opposite_signs_early90",
                "late_only_opposite_signs_early90_tier1_fast_release",
            }:
                opposite_payload_updates["dynamic_monitor_profile"] = ""
            if (
                not late_pre27_dominance_active
                and payload.get("networth_monitor_threshold") is not None
            ):
                opposite_payload_updates["networth_monitor_threshold"] = None
            if (
                not late_pre27_dominance_active
                and payload.get("networth_monitor_deadline_game_time") is not None
            ):
                opposite_payload_updates["networth_monitor_deadline_game_time"] = None
            if (
                not late_pre27_dominance_active
                and payload.get("send_on_target_game_time") is not True
            ):
                opposite_payload_updates["send_on_target_game_time"] = True
            if opposite_payload_updates:
                _update_delayed_match(match_key, **opposite_payload_updates)
                payload = dict(payload)
                payload.update(opposite_payload_updates)
            if current_game_time < opposite_min_dispatch_time and not late_pre27_dominance_active:
                _maybe_refresh_stale_cyberscore_delayed_state(
                    match_key,
                    payload,
                    current_game_time=current_game_time,
                    target_game_time=opposite_min_dispatch_time,
                    now_ts=now_ts,
                    last_progress_at=last_progress_at,
                )
                continue

        monitor_snapshot = _dynamic_monitor_snapshot_for_payload(payload, current_game_time)
        monitor_threshold: Optional[float] = None
        monitor_threshold_raw = monitor_snapshot.get("threshold", payload.get("networth_monitor_threshold"))
        if monitor_threshold_raw is not None:
            try:
                monitor_threshold = float(monitor_threshold_raw)
            except (TypeError, ValueError):
                monitor_threshold = None
        monitor_target_side = str(payload.get("networth_target_side") or "").strip().lower()
        if monitor_target_side not in {"radiant", "dire"}:
            payload_details = payload.get("add_url_details")
            if isinstance(payload_details, dict):
                monitor_target_side = str(payload_details.get("target_side") or "").strip().lower()
        monitor_deadline_raw = payload.get("networth_monitor_deadline_game_time", target_game_time)
        try:
            monitor_deadline_game_time = float(monitor_deadline_raw)
        except (TypeError, ValueError):
            monitor_deadline_game_time = float(target_game_time)
        dynamic_status_label = str(monitor_snapshot.get("status_label") or payload.get("dispatch_status_label") or "")
        if dynamic_status_label and (
            payload.get("dispatch_status_label") != dynamic_status_label
            or payload.get("networth_monitor_threshold") != monitor_threshold
        ):
            _update_delayed_match(
                match_key,
                dispatch_status_label=dynamic_status_label,
                networth_monitor_threshold=monitor_threshold,
            )
        # Профиль монитора может требовать свой hold (ранний релиз при early у
        # оппонента: лид должен держаться N игровых секунд подряд).
        monitor_hold_seconds_raw = monitor_snapshot.get("hold_seconds")
        if monitor_hold_seconds_raw is None:
            monitor_hold_seconds_raw = payload.get(
                "networth_monitor_hold_seconds",
                NETWORTH_MONITOR_HOLD_SECONDS,
            )
        try:
            monitor_hold_seconds = max(0.0, float(monitor_hold_seconds_raw))
        except (TypeError, ValueError):
            monitor_hold_seconds = float(NETWORTH_MONITOR_HOLD_SECONDS)
        monitor_hold_allow_zero_threshold = bool(
            payload.get("networth_monitor_hold_allow_zero_threshold")
        )
        monitor_hold_started_raw = payload.get("networth_monitor_hold_started_game_time")
        try:
            monitor_hold_started_game_time = (
                float(monitor_hold_started_raw)
                if monitor_hold_started_raw is not None
                else None
            )
        except (TypeError, ValueError):
            monitor_hold_started_game_time = None
        late_comeback_monitor_active = bool(payload.get("late_comeback_monitor_active"))
        late_comeback_monitor_candidate = bool(payload.get("late_comeback_monitor_candidate"))
        late_comeback_force_after_target = bool(payload.get("late_comeback_force_after_target"))
        late_comeback_deadline_raw = payload.get(
            "late_comeback_monitor_deadline_game_time",
            _late_comeback_monitor_deadline_seconds(),
        )
        try:
            late_comeback_deadline_game_time = (
                float(late_comeback_deadline_raw)
                if late_comeback_deadline_raw is not None
                else None
            )
        except (TypeError, ValueError):
            late_comeback_deadline_game_time = None
        late_comeback_delta_raw = payload.get("late_comeback_delta_pp")
        try:
            late_comeback_delta_pp = (
                float(late_comeback_delta_raw)
                if late_comeback_delta_raw is not None
                else None
            )
        except (TypeError, ValueError):
            late_comeback_delta_pp = None
        monitor_ready = False
        monitor_target_diff: Optional[float] = None
        late_comeback_check: Optional[Dict[str, Any]] = None
        monitor_hold_check: Optional[Dict[str, Any]] = None
        late_pub_comeback_table_active = bool(payload.get("late_pub_comeback_table_active"))
        late_pub_comeback_table_decision: Optional[Dict[str, Any]] = None
        late_pub_comeback_table_wr_level_raw = payload.get("late_pub_comeback_table_wr_level")
        try:
            late_pub_comeback_table_wr_level = (
                int(late_pub_comeback_table_wr_level_raw)
                if late_pub_comeback_table_wr_level_raw is not None
                else None
            )
        except (TypeError, ValueError):
            late_pub_comeback_table_wr_level = None
        if monitor_target_side in {"radiant", "dire"}:
            monitor_target_diff = _target_networth_diff_from_radiant_lead(
                current_radiant_lead,
                monitor_target_side,
                current_game_time,
            )
        if late_pub_comeback_table_active and not _late_pub_table_has_thresholds(late_pub_comeback_table_wr_level):
            resolved_wr_level = _late_pub_table_wr_level_from_payload(payload)
            if _late_pub_table_has_thresholds(resolved_wr_level):
                late_pub_comeback_table_wr_level = int(resolved_wr_level or 0)
                _update_delayed_match(
                    match_key,
                    late_pub_comeback_table_wr_level=int(late_pub_comeback_table_wr_level),
                )
        if (
            not late_pub_comeback_table_active
            and monitor_target_side in {"radiant", "dire"}
            and current_game_time >= float(DELAYED_SIGNAL_TARGET_GAME_TIME)
            and str(payload.get("dynamic_monitor_profile") or "") != ALL_ONLY_WATCHER_PROFILE
        ):
            resolved_wr_level = _late_pub_table_wr_level_from_payload(payload)
            if _late_pub_table_has_thresholds(resolved_wr_level):
                if current_game_time < float(LATE_PUB_COMEBACK_TABLE_START_SECONDS):
                    updated_target_game_time = max(
                        float(target_game_time),
                        float(LATE_PUB_COMEBACK_TABLE_START_SECONDS),
                    )
                    if float(target_game_time) < updated_target_game_time:
                        _update_delayed_match(
                            match_key,
                            target_game_time=float(updated_target_game_time),
                        )
                        target_game_time = float(updated_target_game_time)
                        payload = dict(payload)
                        payload["target_game_time"] = float(updated_target_game_time)
                    _maybe_refresh_stale_cyberscore_delayed_state(
                        match_key,
                        payload,
                        current_game_time=current_game_time,
                        target_game_time=target_game_time,
                        now_ts=now_ts,
                        last_progress_at=last_progress_at,
                    )
                    continue
                late_pub_comeback_table_active = True
                late_pub_comeback_table_wr_level = int(resolved_wr_level or 0)
                target_game_time = max(
                    float(target_game_time),
                    float(LATE_PUB_COMEBACK_TABLE_START_SECONDS),
                )
                base_add_url_details = payload.get("add_url_details")
                updated_add_url_details = (
                    dict(base_add_url_details)
                    if isinstance(base_add_url_details, dict)
                    else {}
                )
                updated_add_url_details.update(
                    {
                        "dispatch_status_label": NETWORTH_STATUS_LATE_PUB_TABLE_WAIT,
                        "delay_reason": "post_27_00_wr_grid_monitor",
                        "target_game_time": int(target_game_time),
                        "target_side": monitor_target_side,
                        "networth_target_side": monitor_target_side,
                        "late_pub_comeback_table_wr_level": int(late_pub_comeback_table_wr_level),
                    }
                )
                if monitor_target_diff is not None:
                    updated_add_url_details["target_networth_diff"] = float(monitor_target_diff)
                _update_delayed_match(
                    match_key,
                    reason="post_27_00_wr_grid_monitor",
                    target_game_time=float(target_game_time),
                    dispatch_status_label=NETWORTH_STATUS_LATE_PUB_TABLE_WAIT,
                    add_url_details=updated_add_url_details,
                    fallback_send_status_label=NETWORTH_STATUS_LATE_PUB_TABLE_WAIT,
                    send_on_target_game_time=False,
                    late_pub_comeback_table_active=True,
                    late_pub_comeback_table_wr_level=int(late_pub_comeback_table_wr_level),
                    networth_target_side=monitor_target_side,
                    timeout_add_url_reason="star_signal_rejected_late_pub_comeback_table_timeout",
                    timeout_status_label=NETWORTH_STATUS_LATE_COMEBACK_TIMEOUT_NO_SEND,
                )
                payload = dict(payload)
                payload.update(
                    {
                        "reason": "post_27_00_wr_grid_monitor",
                        "target_game_time": float(target_game_time),
                        "dispatch_status_label": NETWORTH_STATUS_LATE_PUB_TABLE_WAIT,
                        "add_url_details": updated_add_url_details,
                        "fallback_send_status_label": NETWORTH_STATUS_LATE_PUB_TABLE_WAIT,
                        "send_on_target_game_time": False,
                        "late_pub_comeback_table_active": True,
                        "late_pub_comeback_table_wr_level": int(late_pub_comeback_table_wr_level),
                        "networth_target_side": monitor_target_side,
                    }
                )
        if late_pub_comeback_table_active:
            # Перепроверка late-гейта по снимку сигнала (delayed-запись
            # могла быть создана до 27:00). Условия статичны — при блокировке
            # watcher закрываем без отправки, вместо ожидания порога таблицы.
            late27_watcher_guard = _evaluate_late27_dispatch_guard(
                _late27_dispatch_guard_snapshot_from_context(
                    payload.get("stake_multiplier_context")
                ),
                target_side=monitor_target_side,
                game_time_seconds=current_game_time,
                force_odds_signal_test_active=bool(FORCE_ODDS_SIGNAL_TEST),
            )
            if late27_watcher_guard.get("blocked"):
                guard_add_url_details = payload.get("add_url_details")
                guard_add_url_details = (
                    dict(guard_add_url_details)
                    if isinstance(guard_add_url_details, dict)
                    else {}
                )
                guard_add_url_details.update(
                    _late27_dispatch_guard_reject_details(late27_watcher_guard)
                )
                guard_add_url_details["dispatch_mode"] = "rejected_late27_dispatch_guard_watcher"
                guard_add_url_details["sent_game_time"] = int(current_game_time)
                guard_add_url_details["target_side"] = monitor_target_side
                if monitor_target_diff is not None:
                    guard_add_url_details["target_networth_diff"] = float(monitor_target_diff)
                add_url(
                    match_key,
                    reason=LATE27_DISPATCH_GUARD_REJECT_REASON,
                    details=guard_add_url_details,
                )
                _drop_delayed_match(match_key, reason="late27_dispatch_guard")
                _delayed_verdict_msg = (
                    f"⏱️ Отложенный late сигнал отменен без отправки (late-гейт): {match_key} "
                    f"({_format_late27_dispatch_guard_log(late27_watcher_guard)}, "
                    f"game_time={int(current_game_time)})"
                )
                print(_delayed_verdict_msg)
                _record_map_verdict(
                    match_key,
                    verdict=_delayed_verdict_msg,
                    kind="cancel",
                    reason=LATE27_DISPATCH_GUARD_REJECT_REASON,
                    dispatch={
                        "dispatch_mode": "rejected_late27_dispatch_guard_watcher",
                        "game_time": current_game_time,
                        "target_side": monitor_target_side,
                        "target_networth_diff": (
                            float(monitor_target_diff)
                            if monitor_target_diff is not None
                            else None
                        ),
                    },
                    extra=guard_add_url_details,
                )
                continue
            late_pub_comeback_table_decision = _late_star_pub_table_decision(
                wr_level=late_pub_comeback_table_wr_level,
                game_time_seconds=current_game_time,
                target_networth_diff=monitor_target_diff,
            )
            if late_pub_comeback_table_decision.get("ready"):
                monitor_ready = True
            elif current_game_time >= float(LATE_PUB_COMEBACK_TABLE_START_SECONDS):
                base_add_url_details = payload.get("add_url_details")
                updated_add_url_details = (
                    dict(base_add_url_details)
                    if isinstance(base_add_url_details, dict)
                    else {}
                )
                updated_add_url_details["dispatch_status_label"] = NETWORTH_STATUS_LATE_PUB_TABLE_WAIT
                updated_add_url_details["target_side"] = monitor_target_side
                updated_add_url_details["networth_target_side"] = monitor_target_side
                updated_add_url_details["late_pub_comeback_table_wr_level"] = int(late_pub_comeback_table_wr_level or 0)
                if monitor_target_diff is not None:
                    updated_add_url_details["target_networth_diff"] = float(monitor_target_diff)
                if isinstance(late_pub_comeback_table_decision, dict):
                    if late_pub_comeback_table_decision.get("source_minute") is not None:
                        updated_add_url_details["late_pub_comeback_table_minute"] = int(
                            late_pub_comeback_table_decision.get("source_minute") or 0
                        )
                    if late_pub_comeback_table_decision.get("threshold") is not None:
                        updated_add_url_details["late_pub_comeback_table_threshold"] = float(
                            late_pub_comeback_table_decision.get("threshold") or 0.0
                        )
                # ── Спекулятивный x0.5 watcher (late comeback) ──────────────
                # Мы здесь = основной порог ещё НЕ достигнут (main not ready).
                # Если глубокий порог (×MULT) достигнут, late WR >= MIN_WR и
                # >= MIN_LATE_HITS late star-хитов, и спекулятив ещё не слался —
                # шлём ставку x0.5 с defer_add_url=True (watcher остаётся жить,
                # основной сигнал может прийти позже независимо).
                # Если основная ставка (x1+) по этой карте/команде уже ушла —
                # comeback-watcher отменяем целиком (не шлём x0.5 после x1).
                _spec_smc_pre = payload.get("stake_multiplier_context") or {}
                _main_fp = _main_late_stake_already_sent_for_map(
                    match_key,
                    stake_team_name=(
                        _spec_smc_pre.get("stake_team_name")
                        if isinstance(_spec_smc_pre, dict)
                        else None
                    ),
                    payload=payload if isinstance(payload, dict) else None,
                )
                if _main_fp:
                    print(
                        "⏱️ Comeback watcher отменен: основная ставка уже отправлена "
                        f"для {match_key} (fingerprint={_main_fp})"
                    )
                    _drop_delayed_matches_for_registry(
                        match_key,
                        reason="main_late_stake_cancels_comeback_watcher",
                    )
                    continue
                # WR здесь — СИГНАЛА, а не единой строки networth-гейта.
                # `late_pub_comeback_table_wr_level` с 30.08.2026 всегда равен
                # `_late_pub_table_gate_wr_level()` (в бою 90), и сравнение его
                # с порогом 70 было бы тавтологией: спекулятивная ветка
                # осталась бы без ограничения по WR вовсе.
                _spec_signal_wr_level = _late_pub_table_wr_level_from_signal_values(
                    late27_watcher_guard.get("late_wr_pct")
                )
                if (
                    not payload.get("speculative_half_sent")
                    and monitor_target_diff is not None
                    and _spec_signal_wr_level is not None
                    and int(_spec_signal_wr_level) >= LATE_PUB_COMEBACK_SPECULATIVE_MIN_WR
                ):
                    _spec_smc = payload.get("stake_multiplier_context") or {}
                    if _late_speculative_allowed_for_context(
                        _spec_smc,
                        game_time_seconds=current_game_time,
                        radiant_lead=current_radiant_lead,
                    ):
                        _spec_decision = _late_star_pub_table_decision(
                            wr_level=late_pub_comeback_table_wr_level,
                            game_time_seconds=current_game_time,
                            target_networth_diff=monitor_target_diff,
                            threshold_multiplier=LATE_PUB_COMEBACK_SPECULATIVE_THRESHOLD_MULT,
                        )
                        if _spec_decision.get("ready"):
                            _spec_details = dict(updated_add_url_details)
                            _spec_details["dispatch_status_label"] = (
                                NETWORTH_STATUS_LATE_PUB_TABLE_SPECULATIVE_SEND
                            )
                            _spec_details["late_pub_comeback_speculative"] = True
                            _spec_details["stake_multiplier"] = float(LATE_PUB_COMEBACK_SPECULATIVE_STAKE)
                            _spec_details["late_pub_comeback_table_wr_level"] = int(
                                late_pub_comeback_table_wr_level or 0
                            )
                            _spec_details["target_networth_diff"] = float(monitor_target_diff)
                            if _spec_decision.get("source_minute") is not None:
                                _spec_details["late_pub_comeback_table_minute"] = int(
                                    _spec_decision.get("source_minute") or 0
                                )
                            if _spec_decision.get("threshold") is not None:
                                _spec_details["late_pub_comeback_speculative_threshold"] = float(
                                    _spec_decision.get("threshold") or 0.0
                                )
                            if _spec_decision.get("base_threshold") is not None:
                                _spec_details["late_pub_comeback_table_threshold"] = float(
                                    _spec_decision.get("base_threshold") or 0.0
                                )
                            _spec_msg = _refresh_stake_multiplier_message(
                                payload.get("message", ""),
                                stake_multiplier_context=_normalize_late_dispatch_smc(
                                    payload.get("stake_multiplier_context")
                                ),
                                game_time_seconds=current_game_time,
                                radiant_lead=current_radiant_lead,
                                force_multiplier=float(LATE_PUB_COMEBACK_SPECULATIVE_STAKE),
                            )
                            _imm_obs, _imm_map = None, None
                            _s: Dict[str, Any] = {}
                            _mc = delayed_state.get("map_num") if isinstance(delayed_state, dict) else None
                            try: _mi = int(_mc) if _mc is not None else None
                            except (TypeError, ValueError): _mi = None
                            if _mi is not None and 1 <= _mi <= 5: _s["map_num"] = _mi
                            _sc = (delayed_state.get("status") if isinstance(delayed_state, dict) else None) or "live"
                            if _sc is not None and str(_sc).strip(): _s["status"] = str(_sc).strip().lower()
                            _src = delayed_state if isinstance(delayed_state, dict) else {}
                            _imm_enriched = _bookmaker_enrich_delayed_match_state(_s if _s else {}, _src)
                            if isinstance(_imm_enriched, dict):
                                try: _rm = int(_imm_enriched.get("map_num"))
                                except (TypeError, ValueError): _rm = None
                                if isinstance(_rm, int) and 1 <= _rm <= 5:
                                    _imm_obs=dict(_imm_enriched);_imm_obs["map_num"]=_rm;_dk=str(match_key or "").strip()
                                    if _dk: _imm_obs["match_key"]=_dk
                                    if not _imm_obs.get("status"): _imm_obs["status"]=str(_sc or "live").lower()
                                    _imm_obs.setdefault("observed_at", float(time.time())); _imm_map=_rm
                            _spec_sent = _deliver_and_persist_signal(
                                match_key,
                                _spec_msg,
                                stake_multiplier_context=_spec_smc,
                                current_map_observation=_imm_obs,
                                map_num=_imm_map,
                                selected_side=monitor_target_side,
                                add_url_reason="star_signal_sent_late_pub_comeback_speculative_half",
                                add_url_details=_spec_details,
                                defer_add_url=True,
                                json_url=payload.get("json_url")
                            )
                            if _spec_sent:
                                _update_delayed_match(match_key, speculative_half_sent=True)
                                payload = dict(payload)
                                payload["speculative_half_sent"] = True
                                print(
                                    "⏱️ Спекулятивный x0.5 отправлен (late comeback "
                                    f"×{LATE_PUB_COMEBACK_SPECULATIVE_THRESHOLD_MULT}): {match_key} "
                                    f"(min={_spec_decision.get('source_minute')}, "
                                    f"thr={int(_spec_decision.get('threshold') or 0)}, "
                                    f"diff={int(monitor_target_diff)}, "
                                    f"wr={late_pub_comeback_table_wr_level}, "
                                    f"late_hits={(_spec_smc or {}).get('late_star_hit_count')})"
                                )
                _update_delayed_match(
                    match_key,
                    add_url_details=updated_add_url_details,
                    dispatch_status_label=NETWORTH_STATUS_LATE_PUB_TABLE_WAIT,
                    last_checked_at=float(now_ts),
                )
                _maybe_refresh_stale_cyberscore_delayed_state(
                    match_key,
                    payload,
                    current_game_time=current_game_time,
                    target_game_time=target_game_time,
                    now_ts=now_ts,
                    last_progress_at=last_progress_at,
                )
                continue
        if late_comeback_monitor_active:
            late_comeback_check = _late_comeback_monitor_check(
                game_time_seconds=current_game_time,
                target_networth_diff=monitor_target_diff,
            )
            if late_comeback_check.get("ready"):
                monitor_ready = True
            elif (
                late_comeback_deadline_game_time is not None
                and current_game_time >= late_comeback_deadline_game_time
            ):
                monitor_ready = False
        elif (
            late_comeback_force_after_target
            and current_game_time >= target_game_time
            and monitor_target_diff is not None
        ):
            late_comeback_check = _late_comeback_monitor_check(
                game_time_seconds=current_game_time,
                target_networth_diff=monitor_target_diff,
            )
            if late_comeback_check.get("ready"):
                monitor_ready = True
                late_comeback_monitor_active = True
            elif (
                late_comeback_deadline_game_time is not None
                and current_game_time < late_comeback_deadline_game_time
            ):
                _update_delayed_match(
                    match_key,
                    late_comeback_monitor_active=True,
                    late_comeback_force_after_target=False,
                    late_comeback_monitor_deadline_game_time=float(late_comeback_deadline_game_time),
                    target_game_time=float(late_comeback_deadline_game_time),
                    send_on_target_game_time=False,
                    dispatch_status_label=NETWORTH_STATUS_LATE_COMEBACK_MONITOR_WAIT,
                )
                minute_label = late_comeback_check.get("minute")
                threshold_label = late_comeback_check.get("threshold")
                print(
                    "⏳ Late comeback monitor activated: "
                    f"{match_key} (source=strong_same_sign, game_time={int(current_game_time)}, "
                    f"target_diff={int(monitor_target_diff)}, "
                    f"minute={minute_label}, "
                    f"ceiling={int(threshold_label) if threshold_label is not None else 'n/a'}, "
                    f"deadline={_format_game_clock(late_comeback_deadline_game_time)})"
                )
                continue
        elif (
            late_comeback_monitor_candidate
            and late_comeback_delta_pp is not None
            and late_comeback_delta_pp > 0
            and current_game_time >= target_game_time
            and monitor_target_diff is not None
            and monitor_target_diff <= -NETWORTH_GATE_LATE_COMEBACK_LARGE_DEFICIT
        ):
            late_comeback_check = _late_comeback_monitor_check(
                game_time_seconds=current_game_time,
                target_networth_diff=monitor_target_diff,
            )
            if late_comeback_check.get("ready"):
                monitor_ready = True
                late_comeback_monitor_active = True
            elif (
                late_comeback_deadline_game_time is not None
                and current_game_time < late_comeback_deadline_game_time
            ):
                _update_delayed_match(
                    match_key,
                    late_comeback_monitor_active=True,
                    late_comeback_monitor_deadline_game_time=float(late_comeback_deadline_game_time),
                    target_game_time=float(late_comeback_deadline_game_time),
                    send_on_target_game_time=False,
                    dispatch_status_label=NETWORTH_STATUS_LATE_COMEBACK_MONITOR_WAIT,
                )
                minute_label = late_comeback_check.get("minute")
                threshold_label = late_comeback_check.get("threshold")
                print(
                    "⏳ Late comeback monitor activated: "
                    f"{match_key} (game_time={int(current_game_time)}, "
                    f"target_diff={int(monitor_target_diff)}, "
                    f"comeback_delta={late_comeback_delta_pp:+.2f} pp, "
                    f"minute={minute_label}, "
                    f"ceiling={int(threshold_label) if threshold_label is not None else 'n/a'}, "
                    f"deadline={_format_game_clock(late_comeback_deadline_game_time)})"
                )
                continue
        elif (
            late_comeback_monitor_candidate
            and current_game_time >= target_game_time
            and monitor_target_diff is not None
        ):
            post_target_comeback = _post_target_comeback_ceiling_decision(
                game_time_seconds=current_game_time,
                target_networth_diff=monitor_target_diff,
            )
            if post_target_comeback.get("ready"):
                monitor_ready = True
                late_comeback_monitor_active = True
                late_comeback_check = post_target_comeback
                late_comeback_deadline_game_time = post_target_comeback.get("deadline_game_time")
            elif post_target_comeback.get("should_monitor"):
                late_comeback_deadline_game_time = post_target_comeback.get("deadline_game_time")
                updated_add_url_details = dict(payload.get("add_url_details") or {})
                updated_add_url_details.update(
                    {
                        "dispatch_status_label": NETWORTH_STATUS_LATE_COMEBACK_MONITOR_WAIT,
                        "target_game_time": int(late_comeback_deadline_game_time or target_game_time),
                        "networth_target_side": monitor_target_side,
                        "target_networth_diff": float(monitor_target_diff),
                        "late_comeback_monitor_minute": post_target_comeback.get("minute"),
                        "late_comeback_monitor_threshold": post_target_comeback.get("threshold"),
                    }
                )
                _update_delayed_match(
                    match_key,
                    reason="post_target_comeback_ceiling_monitor",
                    dispatch_status_label=NETWORTH_STATUS_LATE_COMEBACK_MONITOR_WAIT,
                    add_url_details=updated_add_url_details,
                    target_game_time=float(late_comeback_deadline_game_time or target_game_time),
                    send_on_target_game_time=False,
                    late_comeback_monitor_active=True,
                    late_comeback_force_after_target=False,
                    late_comeback_monitor_deadline_game_time=float(late_comeback_deadline_game_time or target_game_time),
                )
                print(
                    "⏳ Post-target comeback monitor activated: "
                    f"{match_key} (game_time={int(current_game_time)}, "
                    f"target_diff={int(monitor_target_diff)}, "
                    f"minute={post_target_comeback.get('minute')}, "
                    f"ceiling={int(post_target_comeback.get('threshold') or 0)}, "
                    f"deadline={_format_game_clock(late_comeback_deadline_game_time)})"
                )
                continue
            elif post_target_comeback.get("should_timeout"):
                late_comeback_monitor_active = True
                late_comeback_check = post_target_comeback
                late_comeback_deadline_game_time = post_target_comeback.get("deadline_game_time")
        if (
            monitor_threshold is not None
            and monitor_target_side in {"radiant", "dire"}
            and current_game_time < monitor_deadline_game_time
        ):
            if monitor_target_diff is not None:
                monitor_hold_check = _networth_monitor_hold_check(
                    current_game_time=current_game_time,
                    target_networth_diff=monitor_target_diff,
                    monitor_threshold=monitor_threshold,
                    hold_started_game_time=monitor_hold_started_game_time,
                    hold_seconds=monitor_hold_seconds,
                    allow_zero_threshold=monitor_hold_allow_zero_threshold,
                )
                next_hold_started = monitor_hold_check.get("hold_started_game_time")
                if next_hold_started != monitor_hold_started_game_time:
                    _update_delayed_match(
                        match_key,
                        networth_monitor_hold_started_game_time=next_hold_started,
                    )
                if bool(monitor_hold_check.get("ready")):
                    monitor_ready = True

        if not monitor_ready and current_game_time < target_game_time:
            _maybe_refresh_stale_cyberscore_delayed_state(
                match_key,
                payload,
                current_game_time=current_game_time,
                target_game_time=target_game_time,
                now_ts=now_ts,
                last_progress_at=last_progress_at,
            )
            continue
        # Dispatcher ready — accelerate odds polling for tighter freshness.
        accelerate_winline_current_map_polling(match_key)
        if (
            delayed_reason == "same_sign_lane_adv_wait_4_10"
            and not monitor_ready
            and current_game_time
            > (
                NETWORTH_GATE_SAME_SIGN_LANE_ADV_FALLBACK_SECONDS
                + NETWORTH_GATE_SAME_SIGN_LANE_ADV_STALE_GRACE_SECONDS
            )
        ):
            add_url_details = payload.get("add_url_details")
            if not isinstance(add_url_details, dict):
                add_url_details = {}
            add_url_details = dict(add_url_details)
            add_url_details.setdefault("dispatch_status_label", NETWORTH_STATUS_SAME_SIGN_LANE_ADV_STALE_NO_SEND)
            add_url_details.setdefault("sent_game_time", int(current_game_time))
            add_url_details.setdefault("target_game_time", int(NETWORTH_GATE_SAME_SIGN_LANE_ADV_FALLBACK_SECONDS))
            add_url_details.setdefault("stale_grace_seconds", int(NETWORTH_GATE_SAME_SIGN_LANE_ADV_STALE_GRACE_SECONDS))
            add_url_details.setdefault("target_side", monitor_target_side)
            if monitor_target_diff is not None:
                add_url_details.setdefault("target_networth_diff", float(monitor_target_diff))
            add_url(
                match_key,
                reason="star_signal_rejected_same_sign_lane_adv_stale",
                details=add_url_details,
            )
            _drop_delayed_match(match_key, reason="same_sign_lane_adv_stale")
            _delayed_verdict_msg = (
                f"⏱️ Отложенный сигнал отменен без отправки: {match_key} "
                f"(reason={delayed_reason}, status={NETWORTH_STATUS_SAME_SIGN_LANE_ADV_STALE_NO_SEND}, "
                f"game_time={int(current_game_time)})"
            )
            print(_delayed_verdict_msg)
            _record_map_verdict(
                match_key,
                verdict=_delayed_verdict_msg,
                kind="cancel",
                reason="star_signal_rejected_same_sign_lane_adv_stale",
                dispatch={
                    "dispatch_mode": str(delayed_reason or "same_sign_lane_adv_wait_4_10"),
                    "game_time": current_game_time,
                    "target_side": monitor_target_side,
                    "target_networth_diff": (
                        float(monitor_target_diff)
                        if monitor_target_diff is not None
                        else None
                    ),
                },
                extra=add_url_details,
            )
            continue

        if _skip_dispatch_for_processed_url(match_key, "delayed отправки перед lock", indent=""):
            continue
        if not _acquire_signal_send_slot(match_key):
            print(f"⚠️ Пропуск delayed отправки: уже идет dispatch для {match_key}")
            continue
        try:
            if _skip_dispatch_for_processed_url(match_key, "delayed отправки после lock", indent=""):
                continue
            reason = payload.get('reason', 'unknown')
            fallback_send_status_label = str(
                payload.get("fallback_send_status_label") or NETWORTH_STATUS_LATE_FALLBACK_20_20_SEND
            )
            send_on_target_game_time = bool(payload.get("send_on_target_game_time", True))
            add_url_reason = str(payload.get('add_url_reason') or 'star_signal_sent_delayed')
            add_url_details = payload.get('add_url_details')
            if not isinstance(add_url_details, dict):
                add_url_details = {}
            add_url_details = dict(add_url_details)
            star_metrics_snapshot = payload.get("star_metrics_snapshot")
            if late_comeback_monitor_active and not monitor_ready:
                timeout_status_label = NETWORTH_STATUS_LATE_COMEBACK_TIMEOUT_NO_SEND
                if (
                    late_comeback_deadline_game_time is not None
                    and current_game_time >= late_comeback_deadline_game_time
                ):
                    add_url_details.setdefault("dispatch_status_label", timeout_status_label)
                    add_url_details.setdefault("sent_game_time", int(current_game_time))
                    add_url_details.setdefault(
                        "late_comeback_monitor_reached",
                        False,
                    )
                    if late_comeback_check:
                        add_url_details.setdefault(
                            "late_comeback_monitor_minute",
                            late_comeback_check.get("minute"),
                        )
                        add_url_details.setdefault(
                            "late_comeback_monitor_threshold",
                            late_comeback_check.get("threshold"),
                        )
                        add_url_details.setdefault(
                            "target_networth_diff",
                            float(monitor_target_diff or 0.0),
                        )
                    add_url(
                        match_key,
                        reason="star_signal_rejected_late_comeback_monitor_timeout",
                        details=add_url_details,
                    )
                    _drop_delayed_match(match_key, reason="late_comeback_timeout")
                    _delayed_verdict_msg = (
                        f"⏱️ Отложенный сигнал отменен без отправки: {match_key} "
                        f"(reason=late_comeback_monitor, status={timeout_status_label}, "
                        f"game_time={int(current_game_time)})"
                    )
                    print(_delayed_verdict_msg)
                    _record_map_verdict(
                        match_key,
                        verdict=_delayed_verdict_msg,
                        kind="cancel",
                        reason="star_signal_rejected_late_comeback_monitor_timeout",
                        dispatch={
                            "dispatch_mode": "late_comeback_monitor",
                            "game_time": current_game_time,
                            "target_side": monitor_target_side,
                            "target_networth_diff": (
                                float(monitor_target_diff)
                                if monitor_target_diff is not None
                                else None
                            ),
                        },
                        extra=add_url_details,
                    )
                    continue
            if (
                reason == "late_top25_elo_block_opposite_monitor"
                and current_game_time >= target_game_time
                and not monitor_ready
            ):
                if monitor_target_diff is not None and monitor_target_diff > 0:
                    monitor_ready = True
                    add_url_reason = "star_signal_sent_now_top25_late_elo_block_target_lead"
                    add_url_details.setdefault(
                        "dispatch_status_label",
                        NETWORTH_STATUS_LATE_TOP25_ELO_BLOCK_TARGET_LEAD_SEND,
                    )
                    add_url_details.setdefault(
                        "top25_late_elo_block_target_lead",
                        True,
                    )
                    add_url_details.setdefault(
                        "top25_late_elo_block_rank",
                        payload.get("top25_late_elo_block_rank"),
                    )
                else:
                    timeout_status_label = NETWORTH_STATUS_LATE_TOP25_ELO_BLOCK_TIMEOUT_NO_SEND
                    add_url_details.setdefault("dispatch_status_label", timeout_status_label)
                    add_url_details.setdefault("sent_game_time", int(current_game_time))
                    add_url_details.setdefault("target_game_time", int(target_game_time))
                    add_url_details.setdefault("target_networth_diff", float(monitor_target_diff or 0.0))
                    add_url_details.setdefault(
                        "top25_late_elo_block_rank",
                        payload.get("top25_late_elo_block_rank"),
                    )
                    add_url(
                        match_key,
                        reason="star_signal_rejected_top25_late_elo_block_timeout",
                        details=add_url_details,
                    )
                    _drop_delayed_match(match_key, reason="top25_late_elo_block_timeout")
                    _delayed_verdict_msg = (
                        f"⏱️ Отложенный сигнал отменен без отправки: {match_key} "
                        f"(reason={reason}, status={timeout_status_label}, game_time={int(current_game_time)})"
                    )
                    print(_delayed_verdict_msg)
                    _record_map_verdict(
                        match_key,
                        verdict=_delayed_verdict_msg,
                        kind="cancel",
                        reason="star_signal_rejected_top25_late_elo_block_timeout",
                        dispatch={
                            "dispatch_mode": str(reason or "late_top25_elo_block_opposite_monitor"),
                            "game_time": current_game_time,
                            "target_side": monitor_target_side,
                            "target_networth_diff": (
                                float(monitor_target_diff)
                                if monitor_target_diff is not None
                                else None
                            ),
                        },
                        extra=add_url_details,
                    )
                    continue
            if not monitor_ready and not send_on_target_game_time:
                timeout_add_url_reason = str(
                    payload.get("timeout_add_url_reason") or "star_signal_rejected_delayed_timeout"
                )
                timeout_status_label = str(
                    payload.get("timeout_status_label") or "delayed_timeout_no_send"
                )
                add_url_details.setdefault("dispatch_status_label", timeout_status_label)
                add_url_details.setdefault("sent_game_time", int(current_game_time))
                add_url_details.setdefault("target_game_time", int(target_game_time))
                add_url_details.setdefault("networth_monitor_reached", False)
                add_url(
                    match_key,
                    reason=timeout_add_url_reason,
                    details=add_url_details,
                )
                _drop_delayed_match(match_key, reason="target_reached_no_send")
                _delayed_verdict_msg = (
                    f"⏱️ Отложенный сигнал отменен без отправки: {match_key} "
                    f"(reason={reason}, status={timeout_status_label}, game_time={int(current_game_time)})"
                )
                print(_delayed_verdict_msg)
                _record_map_verdict(
                    match_key,
                    verdict=_delayed_verdict_msg,
                    kind="cancel",
                    reason=str(timeout_add_url_reason or "star_signal_rejected_delayed_timeout"),
                    dispatch={
                        "dispatch_mode": str(reason or "delayed_monitor"),
                        "game_time": current_game_time,
                        "target_side": monitor_target_side,
                        "target_networth_diff": (
                            float(monitor_target_diff)
                            if monitor_target_diff is not None
                            else None
                        ),
                    },
                    extra=add_url_details,
                )
                continue
            player_denylist_block = payload.get("player_denylist_block")
            if isinstance(player_denylist_block, dict):
                blocked_player_account_ids = [
                    int(pid)
                    for pid in (player_denylist_block.get("blocked_player_account_ids") or [])
                    if _coerce_int(pid) > 0
                ]
                if blocked_player_account_ids:
                    add_url_details.setdefault(
                        "dispatch_status_label",
                        "delayed_player_denylist_reject",
                    )
                    add_url_details.setdefault(
                        "target_side",
                        player_denylist_block.get("target_side"),
                    )
                    add_url_details.setdefault(
                        "target_team",
                        player_denylist_block.get("target_team"),
                    )
                    add_url_details.setdefault(
                        "blocked_player_account_ids",
                        blocked_player_account_ids,
                    )
                    add_url_details.setdefault(
                        "radiant_account_ids",
                        list(player_denylist_block.get("radiant_account_ids") or []),
                    )
                    add_url_details.setdefault(
                        "dire_account_ids",
                        list(player_denylist_block.get("dire_account_ids") or []),
                    )
                    add_url_details.setdefault(
                        "skipped_player_hits",
                        dict(player_denylist_block.get("skipped_player_hits") or {}),
                    )
                    add_url(
                        match_key,
                        reason="skip_player_denylist",
                        details=add_url_details,
                    )
                    _drop_delayed_match(match_key, reason="delayed_player_denylist")
                    _delayed_verdict_msg = (
                        f"⏱️ Отложенный сигнал отменен из-за player denylist: {match_key} "
                        f"(target_side={player_denylist_block.get('target_side')}, "
                        f"team={player_denylist_block.get('target_team')}, "
                        f"hits={blocked_player_account_ids})"
                    )
                    print(_delayed_verdict_msg)
                    _record_map_verdict(
                        match_key,
                        verdict=_delayed_verdict_msg,
                        kind="cancel",
                        reason="skip_player_denylist",
                        dispatch={
                            "dispatch_mode": str(reason or "delayed_monitor"),
                            "game_time": current_game_time,
                            "target_side": player_denylist_block.get("target_side"),
                        },
                        extra=add_url_details,
                    )
                    continue
            # Dual-signal coordination: if a kills signal was already sent for
            # this match (defer_add_url=True path) AND the late watcher is
            # about to dispatch on the SAME side as the kills target, cancel
            # the late dispatch (we don't want two bets on the same team) and
            # finalize add_url so the match is marked processed.
            kills_already_sent_for_match = bool(payload.get("kills_already_sent"))
            kills_target_side_for_match = str(payload.get("kills_target_side") or "").strip().lower()
            late_target_side_for_match = str(
                payload.get("networth_target_side")
                or add_url_details.get("target_side")
                or ""
            ).strip().lower()
            if (
                kills_already_sent_for_match
                and kills_target_side_for_match in {"radiant", "dire"}
                and late_target_side_for_match in {"radiant", "dire"}
                and kills_target_side_for_match == late_target_side_for_match
            ):
                add_url_details.setdefault(
                    "dispatch_status_label",
                    "late_already_covered_by_kills",
                )
                add_url_details["late_already_covered_by_kills"] = True
                add_url_details["kills_target_side"] = kills_target_side_for_match
                add_url(
                    match_key,
                    reason="late_already_covered_by_kills",
                    details=add_url_details,
                )
                _drop_delayed_match(match_key, reason="late_already_covered_by_kills")
                _delayed_verdict_msg = (
                    f"⏱️ Отложенный late сигнал отменен (kills уже покрыл этот side): {match_key} "
                    f"(kills_target_side={kills_target_side_for_match}, "
                    f"late_target_side={late_target_side_for_match})"
                )
                print(_delayed_verdict_msg)
                _record_map_verdict(
                    match_key,
                    verdict=_delayed_verdict_msg,
                    kind="cancel",
                    reason="late_already_covered_by_kills",
                    dispatch={
                        "dispatch_mode": str(reason or "delayed_monitor"),
                        "game_time": current_game_time,
                        "target_side": late_target_side_for_match or None,
                    },
                    extra=add_url_details,
                )
                continue
            add_url_details.setdefault('sent_game_time', int(current_game_time))
            late_pub_comeback_table_ready = bool(
                isinstance(late_pub_comeback_table_decision, dict)
                and late_pub_comeback_table_decision.get("ready")
            )
            if (
                late_pub_comeback_table_active
                and late_pub_comeback_table_ready
                and monitor_ready
                and monitor_target_diff is not None
            ):
                add_url_details["dispatch_status_label"] = NETWORTH_STATUS_LATE_PUB_TABLE_SEND
                add_url_details["late_pub_comeback_table_reached"] = True
                add_url_details["target_networth_diff"] = float(monitor_target_diff)
                add_url_details["late_pub_comeback_table_wr_level"] = int(late_pub_comeback_table_wr_level or 0)
                if isinstance(late_pub_comeback_table_decision, dict):
                    if late_pub_comeback_table_decision.get("source_minute") is not None:
                        add_url_details["late_pub_comeback_table_minute"] = int(
                            late_pub_comeback_table_decision.get("source_minute") or 0
                        )
                    if late_pub_comeback_table_decision.get("threshold") is not None:
                        add_url_details["late_pub_comeback_table_threshold"] = float(
                            late_pub_comeback_table_decision.get("threshold") or 0.0
                        )
            elif late_comeback_monitor_active and monitor_ready and monitor_target_diff is not None:
                add_url_details.setdefault("late_comeback_monitor_reached", True)
                add_url_details.setdefault("target_networth_diff", float(monitor_target_diff))
                if late_comeback_check:
                    add_url_details.setdefault(
                        "late_comeback_monitor_minute",
                        late_comeback_check.get("minute"),
                    )
                    add_url_details.setdefault(
                        "late_comeback_monitor_threshold",
                        late_comeback_check.get("threshold"),
                    )
            elif monitor_ready and monitor_target_diff is not None:
                add_url_details.setdefault("networth_monitor_early_release", True)
                if reason == "same_sign_lane_adv_wait_4_10":
                    add_url_details["dispatch_status_label"] = NETWORTH_STATUS_4_10_SEND_800
                    add_url_details["release_reason"] = NETWORTH_STATUS_4_10_SEND_800
                    add_url_details["networth_monitor_hold_seconds"] = 0.0
                elif payload.get("dynamic_monitor_profile") == LATE_PRE27_DOMINANCE_PROFILE:
                    add_url_details["dispatch_status_label"] = NETWORTH_STATUS_LATE_PRE27_DOMINANCE_WAIT
                    if monitor_threshold is not None:
                        add_url_details["release_reason"] = f"networth_monitor_{int(monitor_threshold)}"
                if monitor_threshold is not None:
                    add_url_details.setdefault("networth_monitor_threshold", float(monitor_threshold))
                if isinstance(monitor_hold_check, dict) and monitor_hold_check.get("enabled"):
                    add_url_details.setdefault(
                        "networth_monitor_hold_seconds",
                        float(monitor_hold_check.get("hold_seconds") or 0.0),
                    )
                    if monitor_hold_check.get("hold_started_game_time") is not None:
                        add_url_details.setdefault(
                            "networth_monitor_hold_started_game_time",
                            float(monitor_hold_check.get("hold_started_game_time") or 0.0),
                        )
                    add_url_details.setdefault(
                        "networth_monitor_hold_elapsed_seconds",
                        float(monitor_hold_check.get("held_seconds") or 0.0),
                    )
                add_url_details.setdefault("target_networth_diff", float(monitor_target_diff))
            else:
                if reason == "same_sign_lane_adv_wait_4_10":
                    add_url_details["dispatch_status_label"] = NETWORTH_STATUS_SAME_SIGN_LANE_ADV_FALLBACK_10_SEND
                    add_url_details["release_reason"] = NETWORTH_STATUS_SAME_SIGN_LANE_ADV_FALLBACK_10_SEND
                    if monitor_target_diff is not None:
                        add_url_details["target_networth_diff"] = float(monitor_target_diff)
                else:
                    add_url_details.setdefault("dispatch_status_label", fallback_send_status_label)
            # When delayed payload originated from a tier1_early_kills /
            # opposite-signs cycle, ``stake_multiplier_context`` may carry
            # ``special_header_mode="early_kills"``. For any late delayed
            # dispatch we want the regular "СТАВКА НА <late team>" header
            # instead. Restrict normalization to reasons that we actually
            # send as late dispatches (so kills-only delayed paths, if any,
            # would keep the "Ранние килы" header).
            late_payload_reasons = {
                "late_star_pub_comeback_table_monitor",
                "late_only_opposite_signs",
                "late_only_no_early_star_pre27_watcher",
                "late_all_no_early_star_pre27_watcher",
                "late_all_same_weak_early_pre27_watcher",
                "late_top25_elo_block_opposite_monitor",
                "late_star_comeback_ceiling_monitor",
                "post_target_comeback_ceiling_monitor",
                "strong_same_sign_comeback_ceiling_monitor",
            }
            payload_reason_lc = str(payload.get("reason") or "").strip().lower()
            if payload_reason_lc in late_payload_reasons:
                try:
                    _payload_smc = payload.get("stake_multiplier_context")
                    _normalized_smc = _normalize_late_dispatch_smc(_payload_smc)
                    if _normalized_smc is not _payload_smc:
                        payload["stake_multiplier_context"] = _normalized_smc
                except Exception:
                    pass
            # Safety-net: strip early_kills header when dispatching past the
            # early game window regardless of delayed-payload reason. This
            # catches tier1_early_kills payloads that fired late (e.g. 21:31).
            _maybe_strip_early_kills_header_late(payload, current_game_time)
            delivery_message_text = _refresh_stake_multiplier_message(
                payload.get('message', ''),
                stake_multiplier_context=payload.get("stake_multiplier_context"),
                game_time_seconds=current_game_time,
                radiant_lead=current_radiant_lead,
            )
            delayed_observation = None
            stored_obs = payload.get("current_map_observation") if isinstance(payload.get("current_map_observation"), dict) else {}
            if isinstance(delayed_state, dict):
                obs_map = delayed_state.get("map_num")
                obs_status = delayed_state.get("status")
                obs_at = delayed_state.get("observed_at")
                if obs_map is None:
                    obs_map = stored_obs.get("map_num", payload.get("map_num"))
                if not obs_status:
                    obs_status = stored_obs.get("status") or payload.get("status") or "live"
                if obs_at is None:
                    obs_at = stored_obs.get("observed_at")
                try:
                    obs_at_f = float(obs_at) if obs_at is not None else float(time.time())
                except (TypeError, ValueError):
                    obs_at_f = float(time.time())
                try:
                    obs_map_i = int(obs_map) if obs_map is not None else None
                except (TypeError, ValueError):
                    obs_map_i = None
                # Only attach observation when map is known; legacy delayed states without
                # map/status keep observation=None so odds delivery stays backward-compatible.
                if obs_map_i is not None and 1 <= obs_map_i <= 5:
                    delayed_observation = {
                        "map_num": obs_map_i,
                        "status": obs_status or "live",
                        "observed_at": obs_at_f,
                    }
            elif isinstance(stored_obs, dict) and stored_obs:
                try:
                    obs_map_i = int(stored_obs.get("map_num")) if stored_obs.get("map_num") is not None else None
                except (TypeError, ValueError):
                    obs_map_i = None
                if obs_map_i is not None and 1 <= obs_map_i <= 5:
                    delayed_observation = dict(stored_obs)
            if isinstance(delayed_observation, dict):
                # Bind drain-loop/delivery match_key into the rebuilt observation so
                # strict identity validation accepts the fresh map/status/observed_at.
                # Never invent a foreign key: use canonical delivery key when present;
                # keep stored identity only when it already equals that key (same value).
                delivery_key = str(match_key or "").strip()
                if delivery_key:
                    delayed_observation["match_key"] = delivery_key
                obs_status = str(delayed_observation.get("status") or "").strip().lower()
                if obs_status in {"finished", "ended", "complete", "completed"}:
                    try:
                        finished_map = delayed_observation.get("map_num")
                        _bookmaker_clear_odds_delivery_pending(
                            match_key,
                            map_num=finished_map,
                        )
                    except Exception:
                        pass
                    print(f"   ⏭️ Delayed bookmaker skip: match finished for {match_key}")
                    continue
            # Concrete delayed bets: forward only structured side fields already on
            # the delayed payload. Precedence matches established observation/side
            # plumbing (add_url_details.target_side → networth/kills → stake SMC).
            # Missing/empty structured side must be explicit None (fail-closed
            # selected_side_missing), never _BOOKMAKER_SELECTED_SIDE_UNSET dual footer.
            delayed_selected_side = (
                (
                    (add_url_details or {}).get("target_side")
                    if isinstance(add_url_details, dict)
                    else None
                )
                or payload.get("networth_target_side")
                or payload.get("kills_target_side")
                or (
                    (payload.get("stake_multiplier_context") or {}).get("target_side")
                    if isinstance(payload.get("stake_multiplier_context"), dict)
                    else None
                )
            )
            if delayed_selected_side is not None:
                delayed_selected_side = str(delayed_selected_side).strip() or None
            delivery_confirmed = _deliver_and_persist_signal(
                match_key,
                delivery_message_text,
                stake_multiplier_context=payload.get("stake_multiplier_context"),
                add_url_reason=add_url_reason,
                add_url_details=add_url_details,
                json_url=payload.get("json_url"),
                current_map_observation=delayed_observation,
                selected_side=delayed_selected_side,
            )
            if delivery_confirmed:
                _delayed_send_verdict_msg = (
                    f"⏱️ Отложенный сигнал отправлен (delayed worker): {match_key} "
                    f"(reason={reason}, add_url_reason={add_url_reason}, "
                    f"game_time={int(current_game_time)})"
                )
                _record_map_verdict(
                    match_key,
                    verdict=_delayed_send_verdict_msg,
                    kind="send",
                    reason=str(add_url_reason or "star_signal_sent_delayed"),
                    dispatch={
                        "dispatch_mode": str(reason or "delayed_monitor"),
                        "game_time": current_game_time,
                        "target_side": delayed_selected_side,
                        "target_networth_diff": (
                            float(monitor_target_diff)
                            if monitor_target_diff is not None
                            else None
                        ),
                    },
                    extra=add_url_details,
                )
                if (
                    late_pub_comeback_table_active
                    and late_pub_comeback_table_ready
                    and monitor_ready
                    and monitor_target_diff is not None
                ):
                    print(
                        f"⏱️ Отложенный сигнал отправлен по pub late comeback table: {match_key} "
                        f"(game_time={int(current_game_time)}, "
                        f"target_networth_diff={int(monitor_target_diff)}, "
                        f"wr={late_pub_comeback_table_wr_level}, "
                        f"minute={late_pub_comeback_table_decision.get('source_minute') if late_pub_comeback_table_decision else 'n/a'}, "
                        f"threshold={int(late_pub_comeback_table_decision.get('threshold')) if late_pub_comeback_table_decision and late_pub_comeback_table_decision.get('threshold') is not None else 'n/a'})"
                    )
                    _drop_delayed_matches_for_registry(
                        match_key,
                        reason="main_late_pub_table_sent_cancels_watcher",
                    )
                elif late_comeback_monitor_active and monitor_ready and monitor_target_diff is not None:
                    print(
                        f"⏱️ Отложенный сигнал отправлен по comeback ceiling: {match_key} "
                        f"(game_time={int(current_game_time)}, "
                        f"target_networth_diff={int(monitor_target_diff)}, "
                        f"minute={late_comeback_check.get('minute') if late_comeback_check else 'n/a'}, "
                        f"ceiling={int(late_comeback_check.get('threshold')) if late_comeback_check and late_comeback_check.get('threshold') is not None else 'n/a'})"
                    )
                elif (
                    reason == "late_top25_elo_block_opposite_monitor"
                    and current_game_time >= target_game_time
                    and monitor_target_diff is not None
                ):
                    print(
                        f"⏱️ Отложенный сигнал отправлен по top25 late ELO-block target lead: {match_key} "
                        f"(game_time={int(current_game_time)}, target_networth_diff={int(monitor_target_diff)})"
                    )
                elif monitor_ready and monitor_target_diff is not None:
                    monitor_desc = (
                        f"threshold={int(monitor_threshold)}"
                        if monitor_threshold is not None
                        else "monitor=unknown"
                    )
                    print(
                        f"⏱️ Отложенный сигнал отправлен раньше fallback: {match_key} "
                        f"(reason={reason}, game_time={int(current_game_time)}, "
                        f"target_networth_diff={int(monitor_target_diff)}, "
                        f"{monitor_desc})"
                    )
                else:
                    print(
                        f"⏱️ Отложенный сигнал отправлен: {match_key} "
                        f"(reason={reason}, status={fallback_send_status_label}, game_time={int(current_game_time)})"
                    )
        except Exception as e:
            print(f"⚠️ Ошибка отправки отложенного сигнала {match_key}: {e}")
            _schedule_delayed_retry(match_key, e, now_ts=now_ts)
        finally:
            _release_signal_send_slot(match_key)


def _delayed_sender_loop() -> None:
    while not delayed_sender_stop_event.is_set():
        try:
            _drain_due_delayed_signals_once()
        except Exception as e:
            print(f"⚠️ Delayed sender loop error: {e}")
        delayed_sender_stop_event.wait(DELAYED_SIGNAL_POLL_SECONDS)


def _ensure_delayed_sender_started() -> None:
    global delayed_sender_thread
    if delayed_sender_thread is not None and delayed_sender_thread.is_alive():
        return
    delayed_sender_stop_event.clear()
    delayed_sender_thread = threading.Thread(
        target=_delayed_sender_loop,
        name='delayed-signal-sender',
        daemon=True,
    )
    delayed_sender_thread.start()
    print("🧵 Delayed sender worker started")


def _bookmaker_urls_for_mode(mode: str) -> Dict[str, str]:
    raw = _BOOKMAKER_URLS_MAP or {}
    if not isinstance(raw, dict):
        return {}
    maybe_nested = raw.get(mode)
    if isinstance(maybe_nested, dict):
        return {str(k): str(v) for k, v in maybe_nested.items()}
    # backward compatibility if module provides flat map
    if all(isinstance(v, str) for v in raw.values()):
        return {str(k): str(v) for k, v in raw.items()}
    return {}


def _bookmaker_infer_map_num(live_league_data: Optional[dict], score_text: str = "") -> Optional[int]:
    payload = live_league_data if isinstance(live_league_data, dict) else {}
    match_payload = payload.get("match") if isinstance(payload.get("match"), dict) else {}

    def _to_int(value: Any) -> Optional[int]:
        try:
            return int(value)
        except (TypeError, ValueError):
            return None

    # Explicit current map context wins over series-score inference.
    for key in ("game_map_number", "map_num", "current_map", "map_number"):
        explicit = _to_int(payload.get(key))
        if explicit is None:
            explicit = _to_int(match_payload.get(key))
        if explicit is not None:
            return explicit if 1 <= explicit <= 5 else None

    r_wins = _to_int(payload.get("radiant_series_wins"))
    d_wins = _to_int(payload.get("dire_series_wins"))
    if r_wins is None:
        r_wins = _to_int(match_payload.get("radiant_series_wins"))
    if d_wins is None:
        d_wins = _to_int(match_payload.get("dire_series_wins"))

    if r_wins is not None and d_wins is not None:
        inferred = r_wins + d_wins + 1
        if 1 <= inferred <= 5:
            return inferred

    m = re.search(r"(\d+)\s*:\s*(\d+)", str(score_text or ""))
    if m:
        try:
            inferred = int(m.group(1)) + int(m.group(2)) + 1
        except Exception:
            inferred = None
        if inferred is not None and 1 <= inferred <= 5:
            return inferred
    return None


def _bookmaker_effective_sites_for_mode(gate_mode: Optional[str] = None) -> Tuple[str, ...]:
    """Odds-mode is Winline-only; presence keeps the configured multi-bookmaker set."""
    mode = _normalize_bookmaker_gate_mode(
        gate_mode if gate_mode is not None else BOOKMAKER_PREFETCH_GATE_MODE,
        default="odds",
    )
    if mode == "odds":
        return ("winline",)
    sites = tuple(BOOKMAKER_PREFETCH_SITES) if BOOKMAKER_PREFETCH_SITES else ("betboom", "pari", "winline")
    return sites


def _bookmaker_is_strict_winline_current_map(
    site_payload: Any,
    *,
    expected_map_num: Optional[int] = None,
) -> bool:
    if not isinstance(site_payload, dict):
        return False
    if bool(site_payload.get("market_closed")):
        return False
    if str(site_payload.get("market_kind") or "").strip() != "current_map_winner":
        return False
    try:
        map_num = int(site_payload.get("map_num")) if site_payload.get("map_num") is not None else None
    except (TypeError, ValueError):
        map_num = None
    if map_num is None or not (1 <= map_num <= 5):
        return False
    if expected_map_num is not None:
        try:
            expected = int(expected_map_num)
        except (TypeError, ValueError):
            expected = None
        if expected is not None and map_num != expected:
            return False
    if str(site_payload.get("p1_team") or "").strip() != "team1":
        return False
    if str(site_payload.get("p2_team") or "").strip() != "team2":
        return False
    odds = site_payload.get("odds")
    if not isinstance(odds, list) or len(odds) < 2:
        return False
    try:
        p1 = float(odds[0])
        p2 = float(odds[1])
    except (TypeError, ValueError):
        return False
    if not (math.isfinite(p1) and math.isfinite(p2) and p1 > 1.01 and p2 > 1.01):
        return False
    return True



def _bookmaker_validate_current_map_observation(
    observation: Any,
    *,
    expected_map_num: Optional[int] = None,
    expected_match_key: Optional[str] = None,
    now: Optional[float] = None,
    max_age_seconds: Optional[float] = None,
) -> str:
    """Normalize live current-map observation before odds reservation/send.

    Accepts only fresh exact-map observations bound to the expected delivery
    match_key and an explicit live/in-progress status from the existing contract
    vocabulary (online/live/running/inprogress/in_progress).

    Stable reasons: current_map_unavailable | current_map_mismatch | match_finished |
    current_map_observation_stale | ok.
    """
    if not isinstance(observation, dict):
        return "current_map_unavailable"

    # Bind observation identity to the resolver's canonical expected delivery key.
    # Fail closed unless match_key exists, is non-None/non-empty, and equals the
    # expected delivery key. Absent/None/empty/foreign identities never reserve.
    expected_key = str(expected_match_key or "").strip()
    if expected_key:
        obs_key = str(observation.get("match_key") or "").strip()
        if not obs_key or obs_key != expected_key:
            return "current_map_unavailable"

    status = str(observation.get("status") or "").strip().lower()
    # Terminal lifecycle: finished/ended and canceled variants — no reserve/send.
    if status in {"finished", "ended", "complete", "completed", "canceled", "cancelled"}:
        return "match_finished"
    # Existing-contract live/in-progress vocabulary only (see status_looks_live).
    if status not in {"online", "live", "running", "inprogress", "in_progress"}:
        # scheduled/pre-match/empty/unknown/missing → fail closed as unavailable.
        return "current_map_unavailable"

    try:
        obs_map = int(observation["map_num"]) if observation.get("map_num") is not None else None
    except (TypeError, ValueError, KeyError):
        obs_map = None
    if obs_map is None or not (1 <= obs_map <= 5):
        return "current_map_unavailable"
    if expected_map_num is not None:
        try:
            expected = int(expected_map_num)
        except (TypeError, ValueError):
            expected = None
        if expected is not None and obs_map != expected:
            return "current_map_mismatch"
    try:
        observed_at = float(observation.get("observed_at"))
    except (TypeError, ValueError):
        return "current_map_observation_stale"
    now_ts = float(now if now is not None else time.time())
    age_limit = float(
        max_age_seconds
        if max_age_seconds is not None
        else BOOKMAKER_ODDS_MAX_AGE_SECONDS
    )
    age = now_ts - observed_at
    if age < 0:
        return "current_map_observation_stale"
    if age > age_limit:
        return "current_map_observation_stale"
    return "ok"


def _bookmaker_validate_odds_freshness(
    snapshot: Any,
    *,
    now: Optional[float] = None,
    max_age_seconds: Optional[float] = None,
) -> str:
    """Gate open odds by successful-refresh timestamp.

    Stable reasons: odds_timestamp_missing | odds_timestamp_future | odds_stale | ok.
    Prefers odds_refreshed_at; falls back to finished_at for legacy snapshots.
    """
    if not isinstance(snapshot, dict):
        return "odds_timestamp_missing"
    raw_ts = snapshot.get("odds_refreshed_at")
    if raw_ts is None:
        raw_ts = snapshot.get("finished_at")
    if raw_ts is None:
        return "odds_timestamp_missing"
    try:
        refreshed_at = float(raw_ts)
    except (TypeError, ValueError):
        return "odds_timestamp_missing"
    now_ts = float(now if now is not None else time.time())
    age = now_ts - refreshed_at
    if age < 0:
        return "odds_timestamp_future"
    age_limit = float(
        max_age_seconds
        if max_age_seconds is not None
        else BOOKMAKER_ODDS_MAX_AGE_SECONDS
    )
    if age > age_limit:
        return "odds_stale"
    return "ok"


def _bookmaker_resolve_retained_deadline(
    *,
    prev: Optional[Dict[str, Any]],
    deadline_ts: Optional[float],
    now: float,
    create_if_missing: bool,
) -> Tuple[Optional[float], bool]:
    """Return (deadline_at, past_deadline). Never extends an existing deadline_at."""
    retained: Optional[float] = None
    if isinstance(prev, dict) and prev.get("deadline_at") is not None:
        try:
            retained = float(prev.get("deadline_at"))
        except (TypeError, ValueError):
            retained = None
    explicit: Optional[float] = None
    if deadline_ts is not None:
        try:
            explicit = float(deadline_ts)
        except (TypeError, ValueError):
            explicit = None
    if retained is not None:
        deadline_at = retained
    elif explicit is not None:
        deadline_at = explicit
    elif create_if_missing:
        deadline_at = float(now) + float(BOOKMAKER_ODDS_WAIT_DEADLINE_SECONDS)
    else:
        deadline_at = None
    # Inclusive terminal boundary: now == deadline_at is already past/terminal.
    past_deadline = bool(deadline_at is not None and float(now) >= float(deadline_at))
    return deadline_at, past_deadline


def _bookmaker_clear_odds_delivery_pending(
    match_key: str,
    *,
    map_num: Optional[int] = None,
    token: Optional[str] = None,
) -> None:
    """Drop pending for exact-map finished wait or matching owner-token completion.

    Match-key-only cleanup is forbidden: callers must pass the finishing operation's
    established current-map identity. Tokenless finished cleanup may delete only
    state == temporarily_closed_wait. Owner-token entries require an exact lease
    match (prepare/commit/rollback/map-change lifecycle); mismatched/missing tokens
    and tokenless non-wait states fail closed.
    """
    key = str(match_key or "").strip()
    if not key:
        return
    # No established map identity → no-op (do not wipe by match_key alone).
    if map_num is None:
        return
    try:
        expected_map = int(map_num)
    except (TypeError, ValueError):
        return
    expected_token = str(token or "").strip()
    with bookmaker_odds_delivery_pending_lock:
        entry = bookmaker_odds_delivery_pending.get(key)
        if not isinstance(entry, dict):
            return
        try:
            pending_map = int(entry.get("map_num")) if entry.get("map_num") is not None else None
        except (TypeError, ValueError):
            pending_map = None
        # Fail closed: missing/unknown pending map is never eligible for cleanup.
        # Exact match_key + map_num identity is mandatory for finished/owner clears.
        if pending_map is None or pending_map != expected_map:
            return
        pending_token = str(entry.get("token") or "").strip()
        if pending_token:
            # Owner reservation requires exact lease/token match.
            if not expected_token or expected_token != pending_token:
                return
        else:
            # Tokenless finished cleanup: only waiting state is eligible.
            if str(entry.get("state") or "") != "temporarily_closed_wait":
                return
        bookmaker_odds_delivery_pending.pop(key, None)



def _bookmaker_enrich_delayed_match_state(
    state: Optional[Dict[str, Any]],
    source: Any = None,
) -> Optional[Dict[str, Any]]:
    """Attach optional map/status/observed_at fields for bookmaker lifecycle gates."""
    if not isinstance(state, dict):
        return state
    out = dict(state)
    src = source if isinstance(source, dict) else {}
    # map_num
    if out.get("map_num") is None:
        for key in ("map_num", "bookmaker_map_num", "current_map", "map"):
            raw = src.get(key) if key in src else out.get(key)
            if raw is None:
                continue
            try:
                val = int(raw)
            except (TypeError, ValueError):
                continue
            if 1 <= val <= 5:
                out["map_num"] = val
                break
        if out.get("map_num") is None:
            # infer from series wins if present
            try:
                r = src.get("radiant_series_wins")
                d = src.get("dire_series_wins")
                if r is not None and d is not None:
                    inferred = int(r) + int(d) + 1
                    if 1 <= inferred <= 5:
                        out["map_num"] = inferred
            except (TypeError, ValueError):
                pass
    # status
    if out.get("status") is None:
        for key in ("status", "match_status", "state"):
            raw = src.get(key) if key in src else out.get(key)
            if raw is None:
                continue
            s = str(raw).strip().lower()
            if s:
                out["status"] = s
                break
        if out.get("status") is None:
            out["status"] = "live"
    # observed_at
    if out.get("observed_at") is None:
        for key in ("observed_at", "timestamp", "updated_at", "ts"):
            raw = src.get(key) if key in src else out.get(key)
            if raw is None:
                continue
            try:
                out["observed_at"] = float(raw)
                break
            except (TypeError, ValueError):
                continue
        if out.get("observed_at") is None:
            out["observed_at"] = float(time.time())
    return out


def _bookmaker_odds_market_state(match_key: str) -> str:
    """Return market state for odds-mode gate."""
    snapshot = _bookmaker_prefetch_lookup(match_key, wait_seconds=0.0)
    if not isinstance(snapshot, dict):
        return "prefetch_not_found"
    if str(snapshot.get("status") or "") != "done":
        if BOOKMAKER_PREFETCH_GATE_MODE == "odds" and snapshot.get("odds_refresh_ready") is False:
            return str(snapshot.get("error") or "shared_camoufox_refresh_failed")
        return f"prefetch_{snapshot.get('status') or 'unknown'}"
    sites_payload = snapshot.get("sites")
    if not isinstance(sites_payload, dict):
        return "invalid_sites_payload"
    expected_map = snapshot.get("map_num")
    try:
        expected_map_num = int(expected_map) if expected_map is not None else None
    except (TypeError, ValueError):
        expected_map_num = None
    winline = sites_payload.get("winline")
    if _bookmaker_is_strict_winline_current_map(winline, expected_map_num=expected_map_num):
        return "open_valid_odds"
    if isinstance(winline, dict) and bool(winline.get("market_closed")):
        return "temporarily_closed_wait"
    return "no_strict_winline_current_map"


def _bookmaker_new_reservation_token() -> str:
    return secrets.token_hex(16)


def _bookmaker_reservation_context_from_pending(
    match_key: str,
    pending_entry: Optional[Dict[str, Any]],
) -> Optional[Dict[str, Any]]:
    if not isinstance(pending_entry, dict):
        return None
    token = str(pending_entry.get("token") or "").strip()
    if not token:
        return None
    try:
        map_num = int(pending_entry.get("map_num")) if pending_entry.get("map_num") is not None else None
    except (TypeError, ValueError):
        map_num = None
    return {
        "match_key": str(match_key or ""),
        "map_num": map_num,
        "token": token,
        "state": str(pending_entry.get("state") or "prepared"),
        "created_at": pending_entry.get("created_at"),
        "updated_at": pending_entry.get("updated_at"),
    }


def _bookmaker_commit_odds_delivery(
    match_key: str,
    *,
    reservation_context: Optional[Dict[str, Any]] = None,
    pending_state: Optional[Dict[str, Any]] = None,
    map_num: Optional[int] = None,
    token: Optional[str] = None,
) -> bool:
    """Mark map-scoped odds reservation as confirmed sent. Token-scoped + idempotent."""
    pending = pending_state if isinstance(pending_state, dict) else bookmaker_odds_delivery_pending
    ctx = reservation_context if isinstance(reservation_context, dict) else {}
    key = str(match_key or ctx.get("match_key") or "").strip()
    if not key:
        return False
    try:
        expected_map = int(map_num) if map_num is not None else (
            int(ctx["map_num"]) if ctx.get("map_num") is not None else None
        )
    except (TypeError, ValueError, KeyError):
        expected_map = None
    expected_token = str(token or ctx.get("token") or "").strip()
    if not expected_token:
        return False
    now = time.time()
    with bookmaker_odds_delivery_pending_lock:
        prev = pending.get(key) if isinstance(pending.get(key), dict) else None
        if not isinstance(prev, dict):
            return False
        try:
            prev_map = int(prev.get("map_num")) if prev.get("map_num") is not None else None
        except (TypeError, ValueError):
            prev_map = None
        prev_token = str(prev.get("token") or "").strip()
        prev_state = str(prev.get("state") or "")
        if expected_map is not None and prev_map is not None and prev_map != expected_map:
            return False
        if prev_token and prev_token != expected_token:
            return False
        if prev_state == "sent":
            # Idempotent re-commit of the same ownership.
            if not prev_token or prev_token == expected_token:
                return True
            return False
        if prev_state not in {"prepared", "reserved", "open_valid_odds"}:
            return False
        pending[key] = {
            "map_num": prev_map if prev_map is not None else expected_map,
            "state": "sent",
            "token": expected_token,
            "created_at": float(prev.get("created_at") or now),
            "sent_at": now,
            "updated_at": now,
        }
        return True


def _bookmaker_rollback_odds_delivery(
    match_key: str,
    *,
    reservation_context: Optional[Dict[str, Any]] = None,
    pending_state: Optional[Dict[str, Any]] = None,
    map_num: Optional[int] = None,
    token: Optional[str] = None,
) -> bool:
    """Release a matching reservation so the same map can retry. Stale tokens are no-ops."""
    pending = pending_state if isinstance(pending_state, dict) else bookmaker_odds_delivery_pending
    ctx = reservation_context if isinstance(reservation_context, dict) else {}
    key = str(match_key or ctx.get("match_key") or "").strip()
    if not key:
        return False
    try:
        expected_map = int(map_num) if map_num is not None else (
            int(ctx["map_num"]) if ctx.get("map_num") is not None else None
        )
    except (TypeError, ValueError, KeyError):
        expected_map = None
    expected_token = str(token or ctx.get("token") or "").strip()
    if not expected_token:
        return False
    with bookmaker_odds_delivery_pending_lock:
        prev = pending.get(key) if isinstance(pending.get(key), dict) else None
        if not isinstance(prev, dict):
            return False
        prev_state = str(prev.get("state") or "")
        if prev_state == "sent":
            return False
        try:
            prev_map = int(prev.get("map_num")) if prev.get("map_num") is not None else None
        except (TypeError, ValueError):
            prev_map = None
        prev_token = str(prev.get("token") or "").strip()
        if expected_map is not None and prev_map is not None and prev_map != expected_map:
            return False
        if prev_token and prev_token != expected_token:
            return False
        if prev_state in {"prepared", "reserved", "open_valid_odds"}:
            pending.pop(key, None)
            return True
        return False


def _bookmaker_validate_odds_reservation_context(
    match_key: str,
    reservation_context: Optional[Dict[str, Any]],
) -> bool:
    """Validate an explicit minimal-preflight handoff without mutating the lease."""
    if not isinstance(reservation_context, dict):
        return False
    key = str(match_key or "").strip()
    context_key = str(reservation_context.get("match_key") or "").strip()
    token = str(reservation_context.get("token") or "").strip()
    if not key or context_key != key or not token:
        return False
    try:
        context_map = (
            int(reservation_context["map_num"])
            if reservation_context.get("map_num") is not None
            else None
        )
    except (TypeError, ValueError):
        return False
    with bookmaker_odds_delivery_pending_lock:
        pending = bookmaker_odds_delivery_pending.get(key)
        if not isinstance(pending, dict):
            return False
        try:
            pending_map = int(pending["map_num"]) if pending.get("map_num") is not None else None
        except (TypeError, ValueError):
            return False
        return (
            str(pending.get("state") or "") in {"prepared", "reserved"}
            and str(pending.get("token") or "").strip() == token
            and pending_map == context_map
        )


# Sentinel: omit selected_side → legacy dual P1/P2 footer (non-concrete / gate paths).
# Explicit None/empty on a concrete-bet path is fail-closed (no dual, no fabricated coeff).
_BOOKMAKER_SELECTED_SIDE_UNSET: Any = object()


def _bookmaker_map_selected_side_to_odds_index(selected_side: Any) -> Tuple[Optional[int], str]:
    """Map radiant|dire|team1|team2|p1|p2 to odds index. Fail-closed on unknown/missing."""
    if selected_side is None:
        return None, "selected_side_missing"
    side = str(selected_side).strip().lower()
    if not side:
        return None, "selected_side_missing"
    if side in {"radiant", "team1", "p1", "1"}:
        return 0, "ok"
    if side in {"dire", "team2", "p2", "2"}:
        return 1, "ok"
    return None, "selected_side_unmappable"


def _bookmaker_resolve_odds_delivery_state(
    match_key: str,
    *,
    pending_state: Optional[Dict[str, Any]] = None,
    deadline_ts: Optional[float] = None,
    map_num: Optional[int] = None,
    current_map_observation: Any = None,
    selected_side: Any = _BOOKMAKER_SELECTED_SIDE_UNSET,
) -> Dict[str, Any]:
    """Pending-poll state machine: closed wait -> prepare/reserve open odds; never marks sent."""
    pending = pending_state if isinstance(pending_state, dict) else {}
    now = time.time()
    try:
        expected_map = int(map_num) if map_num is not None else None
    except (TypeError, ValueError):
        expected_map = None

    prev = pending.get(match_key) if isinstance(pending.get(match_key), dict) else None
    if prev is not None and expected_map is not None:
        try:
            prev_map = int(prev.get("map_num")) if prev.get("map_num") is not None else None
        except (TypeError, ValueError):
            prev_map = None
        if prev_map is not None and prev_map != expected_map:
            pending.pop(match_key, None)
            prev = None

    market_state = _bookmaker_odds_market_state(match_key)
    snapshot = _bookmaker_prefetch_lookup(match_key, wait_seconds=0.0)
    sites_payload = (snapshot or {}).get("sites") if isinstance(snapshot, dict) else None
    winline = sites_payload.get("winline") if isinstance(sites_payload, dict) else None
    refresh_gate_ready = not (
        isinstance(snapshot, dict)
        and BOOKMAKER_PREFETCH_GATE_MODE == "odds"
        and snapshot.get("odds_refresh_ready") is False
    )
    if refresh_gate_ready and expected_map is not None and isinstance(winline, dict):
        if _bookmaker_is_strict_winline_current_map(winline, expected_map_num=expected_map):
            market_state = "open_valid_odds"
        elif bool(winline.get("market_closed")):
            market_state = "temporarily_closed_wait"
        else:
            market_state = "no_strict_winline_current_map"

    # W2: fresh exact-current-map observation is mandatory. None is never legacy-ok.
    # Bind observation match_key to this resolver's canonical expected delivery key.
    observation_reason = _bookmaker_validate_current_map_observation(
        current_map_observation,
        expected_map_num=expected_map,
        expected_match_key=match_key,
        now=now,
    )
    if observation_reason == "ok" and expected_map is None and isinstance(current_map_observation, dict):
        try:
            obs_map = int(current_map_observation.get("map_num"))
            if 1 <= obs_map <= 5:
                expected_map = obs_map
        except (TypeError, ValueError):
            pass

    if observation_reason in {"current_map_mismatch", "match_finished"}:
        pending.pop(match_key, None)
        return {
            "state": "terminal_skip",
            "should_send": False,
            "reason": observation_reason,
        }

    odds_fresh_reason = "ok"
    if market_state == "open_valid_odds":
        odds_fresh_reason = _bookmaker_validate_odds_freshness(snapshot, now=now)

    temporary_wait_reasons = {
        "current_map_unavailable",
        "current_map_observation_stale",
        "odds_stale",
        "odds_timestamp_missing",
        "odds_timestamp_future",
    }

    needs_wait = (
        market_state == "temporarily_closed_wait"
        or observation_reason in temporary_wait_reasons
        or (market_state == "open_valid_odds" and odds_fresh_reason != "ok")
    )

    deadline_at, past_deadline = _bookmaker_resolve_retained_deadline(
        prev=prev,
        deadline_ts=deadline_ts,
        now=now,
        create_if_missing=bool(
            needs_wait
            or market_state not in {"open_valid_odds"}
            or (prev and str(prev.get("state") or "") == "temporarily_closed_wait")
            or (prev and str(prev.get("state") or "") == "terminal_skip")
        ),
    )

    def _retain_terminal_deadline(reason: str) -> Dict[str, Any]:
        """Immutable retained-deadline terminal: tokenless, no prepare/reserve/send.

        past_deadline decisions must not create, replace, clear, or rewrite any
        pending/reservation entry (including updated_at/state transitions).
        """
        return {"state": "terminal_skip", "should_send": False, "reason": reason}

    # Retained deadline is an immutable terminal gate before any owner token path.
    if past_deadline:
        if market_state == "temporarily_closed_wait":
            terminal_reason = "deadline_while_closed"
        elif observation_reason in temporary_wait_reasons:
            terminal_reason = observation_reason
        elif odds_fresh_reason != "ok":
            terminal_reason = odds_fresh_reason
        else:
            terminal_reason = "deadline_expired"
        return _retain_terminal_deadline(terminal_reason)

    if market_state == "open_valid_odds" and not needs_wait:
        if prev and str(prev.get("state") or "") == "sent":
            return {
                "state": "open_valid_odds",
                "should_send": False,
                "reason": "already_sent",
                "reservation_context": _bookmaker_reservation_context_from_pending(match_key, prev),
            }
        # A second prepare is an observer, not the owner: never disclose or reuse the lease token.
        if prev and str(prev.get("state") or "") in {"prepared", "reserved"}:
            try:
                prev_map = int(prev.get("map_num")) if prev.get("map_num") is not None else None
            except (TypeError, ValueError):
                prev_map = None
            if expected_map is None or prev_map is None or prev_map == expected_map:
                return {
                    "state": "reservation_inflight",
                    "should_send": False,
                    "reason": "reservation_inflight",
                    "map_num": prev_map if prev_map is not None else expected_map,
                }
        token = _bookmaker_new_reservation_token()
        entry = {
            "map_num": expected_map,
            "state": "prepared",
            "token": token,
            "created_at": float((prev or {}).get("created_at") or now),
            "updated_at": now,
        }
        if isinstance(prev, dict) and prev.get("deadline_at") is not None:
            try:
                entry["deadline_at"] = float(prev.get("deadline_at"))
            except (TypeError, ValueError):
                pass
        pending[match_key] = entry
        block, ready, reason = _bookmaker_format_odds_block(
            match_key, selected_side=selected_side
        )
        reservation = _bookmaker_reservation_context_from_pending(match_key, pending[match_key])
        return {
            "state": "prepared",
            "should_send": bool(ready),
            "reason": reason if ready else (reason or "not_ready"),
            "block": block,
            "reservation_context": reservation,
            "token": token,
            "map_num": expected_map,
        }

    if needs_wait:
        if market_state == "temporarily_closed_wait":
            wait_reason = "temporarily_closed_wait"
        elif observation_reason in temporary_wait_reasons:
            wait_reason = observation_reason
        elif odds_fresh_reason != "ok":
            wait_reason = odds_fresh_reason
        else:
            wait_reason = "temporarily_closed_wait"
        entry = {
            "map_num": expected_map,
            "state": "temporarily_closed_wait",
            "created_at": float((prev or {}).get("created_at") or now),
            "updated_at": now,
        }
        if deadline_at is not None:
            entry["deadline_at"] = float(deadline_at)
        pending[match_key] = entry
        return {
            "state": "temporarily_closed_wait",
            "should_send": False,
            "reason": wait_reason,
            "deadline_at": deadline_at,
        }

    if prev and str(prev.get("state") or "") == "temporarily_closed_wait":
        return {
            "state": "temporarily_closed_wait",
            "should_send": False,
            "reason": market_state,
            "deadline_at": deadline_at,
        }

    return {"state": market_state, "should_send": False, "reason": market_state}

def _bookmaker_live_proxy_pool() -> List[Dict[str, Any]]:
    """Return proxy candidate dicts for bookmaker/Winline rotation. Does not mutate api_to_proxy."""
    out: List[Dict[str, Any]] = []
    seen = set()
    _allowed_countries = frozenset({"DE", "US", "RU"})

    def _country_for(url: str) -> str:
        """Classify proxy host. Fail-closed: unknown/empty/malformed => empty (not DE)."""
        host = ""
        try:
            host = (urlparse(str(url or "")).hostname or "").strip().lower()
        except Exception:
            host = ""
        if not host:
            return ""
        if host.startswith("77.221.150.") or host.startswith("109.120.147."):
            return "RU"
        if host.startswith("154.195."):
            return "DE"
        # Current US residential inventory
        if host.startswith("172.121.") or ".us." in host or host.endswith(".us"):
            return "US"
        # Unknown host: do not default to DE (fail closed for Winline).
        return ""

    def _normalize_country(raw: Any, url: str) -> str:
        label = str(raw or "").strip().upper()
        if label in _allowed_countries:
            return label
        if label:
            # Explicit non-allowlisted label (UNKNOWN, ??, etc.): keep non-DE/US identity
            # but never relabel as DE; empty means unclassified for Winline filter.
            return ""
        return _country_for(url)

    pools: List[Any] = []
    try:
        pools.append(BOOKMAKER_PROXY_POOL)
    except Exception:
        pass
    try:
        pools.append(DLTV_PROXY_POOL)
    except Exception:
        pass
    try:
        if BOOKMAKER_PROXY_URL:
            pools.append([BOOKMAKER_PROXY_URL])
    except Exception:
        pass

    for pool in pools:
        if not isinstance(pool, (list, tuple, set)):
            continue
        for item in pool:
            try:
                if isinstance(item, dict):
                    url = str(item.get("url") or item.get("proxy") or "").strip()
                    country = _normalize_country(item.get("country"), url)
                else:
                    url = str(item or "").strip()
                    country = _country_for(url)
            except Exception:
                continue
            if not url or url in seen:
                continue
            seen.add(url)
            out.append({"url": url, "country": country})
    return out


def _bookmaker_winline_proxy_candidates() -> List[Dict[str, Any]]:
    """Winline: explicit DE(+optional US) only; RU/unknown/empty excluded.

    Policy accepts currently available DE/US inventory:
    - up to 5 DE candidates
    - up to 1 US candidate when present
    - 5 DE + 0 US is valid (no fabricated US entry)
    Independent allowlist at filter: only DE/US pass; never promote RU/unknown.
    Credentials never logged via safe label helper.
    """
    pool = _bookmaker_live_proxy_pool()
    de: List[Dict[str, Any]] = []
    us: List[Dict[str, Any]] = []
    for p in pool:
        if not isinstance(p, dict):
            continue
        country = str(p.get("country") or "").strip().upper()
        if country == "DE":
            de.append(p)
        elif country == "US":
            us.append(p)
        # RU / unknown / empty / malformed: skip without error
    # Prefer DE, then optional US. Empty pool is allowed (caller decides direct/fallback).
    return de[:5] + us[:1]


def _bookmaker_proxy_safe_label(proxy_item: Any) -> str:
    """Sanitize proxy for logs: never include credentials."""
    url = ""
    country = ""
    if isinstance(proxy_item, dict):
        url = str(proxy_item.get("url") or proxy_item.get("proxy") or "")
        country = str(proxy_item.get("country") or "")
    else:
        url = str(proxy_item or "")
    if country.strip().upper() == "DIRECT":
        return "direct"
    try:
        parsed = urlparse(url)
        host = parsed.hostname or ""
        port = parsed.port or ""
        scheme = parsed.scheme or "http"
        label = f"{scheme}://{host}:{port}" if host else "proxy"
    except Exception:
        label = "proxy"
    if country:
        return f"{label} ({country})"
    return label


# Process-wide Winline proxy rotation for the shared Camoufox session.
_bookmaker_shared_proxy_candidates: List[Dict[str, Any]] = []
_bookmaker_shared_proxy_index: int = 0
_bookmaker_shared_proxy_lock = threading.Lock()


def _bookmaker_shared_winline_routes() -> List[Dict[str, Any]]:
    """Direct first; configured DE/US proxies remain automatic fallbacks."""
    return [
        {"url": "", "country": "DIRECT"},
        *list(_bookmaker_winline_proxy_candidates() or []),
    ]


def _bookmaker_select_shared_camoufox_proxy_kwargs() -> Dict[str, Any]:
    """Pick current direct/proxy Winline route; never log credentials."""
    global _bookmaker_shared_proxy_candidates, _bookmaker_shared_proxy_index
    with _bookmaker_shared_proxy_lock:
        if not _bookmaker_shared_proxy_candidates:
            _bookmaker_shared_proxy_candidates = _bookmaker_shared_winline_routes()
            _bookmaker_shared_proxy_index = 0
        candidates = list(_bookmaker_shared_proxy_candidates)
        if not candidates:
            return {}
        idx_local = _bookmaker_shared_proxy_index % len(candidates)
        item = candidates[idx_local]
    url = ""
    if isinstance(item, dict):
        url = str(item.get("url") or item.get("proxy") or "").strip()
    else:
        url = str(item or "").strip()
    if not url:
        print("   🌐 Shared Camoufox Winline route: direct")
        return {}
    kwargs = _camoufox_proxy_kwargs_from_url(url)
    if kwargs:
        with contextlib.suppress(Exception):
            print(f"   🌐 Shared Camoufox Winline proxy: {_bookmaker_proxy_safe_label(item)}")
    return kwargs


# Типы, которые ВСЕГДА означают дефект кода, а не сеть. Для них ротация прокси
# бессмысленна и вредна: она прячет баг за «нестабильным прокси» и вдобавок сносит
# тёплую страницу (холодная загрузка winline стоит секунды даже на живом пуле).
_CAMOUFOX_CODE_DEFECT_EXCEPTIONS = (
    TypeError, AttributeError, NameError, KeyError, IndexError,
    AssertionError, ImportError, NotImplementedError, ZeroDivisionError,
)

# Признаки сети/прокси в тексте ошибки. Playwright и Firefox пишут по-разному,
# поэтому смотрим на подстроки, а не на классы.
_CAMOUFOX_NETWORK_ERROR_MARKERS = (
    "proxy", "invalidproxy", "socks", "tunnel",
    "net::", "ns_error", "err_", "dns",
    "timeout", "timed out", "econnreset", "reset by peer",
    "connection", "unreachable", "handshake", "ssl", "tls",
    "navigating to", "page.goto",
)


def _camoufox_error_is_code_defect(exc: BaseException) -> bool:
    """True, если ошибку нельзя объяснить прокси или сетью.

    Неизвестные типы считаем сетевыми: так сохраняется прежняя страховка, и
    правка не отбирает ротацию у случаев, которых мы ещё не видели.
    """
    if isinstance(exc, _CAMOUFOX_CODE_DEFECT_EXCEPTIONS):
        return True
    text = f"{type(exc).__name__}: {exc}".lower()
    if any(marker in text for marker in _CAMOUFOX_NETWORK_ERROR_MARKERS):
        return False
    # RuntimeError/ValueError двусмысленны: без сетевых признаков это наш код
    # (именно так выглядела сегодняшняя поломка sync-обёрток парсера).
    return isinstance(exc, (RuntimeError, ValueError))


def _bookmaker_rotate_shared_camoufox_proxy(*, reason: str = "") -> None:
    """Advance DE/US candidate and force sequential close/cleanup before relaunch."""
    global _bookmaker_shared_proxy_candidates, _bookmaker_shared_proxy_index
    with _bookmaker_shared_proxy_lock:
        if not _bookmaker_shared_proxy_candidates:
            _bookmaker_shared_proxy_candidates = _bookmaker_shared_winline_routes()
            _bookmaker_shared_proxy_index = 0
        if _bookmaker_shared_proxy_candidates:
            _bookmaker_shared_proxy_index = (_bookmaker_shared_proxy_index + 1) % max(
                1, len(_bookmaker_shared_proxy_candidates)
            )
            nxt = _bookmaker_shared_proxy_candidates[_bookmaker_shared_proxy_index % len(_bookmaker_shared_proxy_candidates)]
            label = _bookmaker_proxy_safe_label(nxt)
        else:
            label = "none"
    reason_s = str(reason or "rotate").strip() or "rotate"
    print(f"   🔄 Shared Camoufox proxy rotate ({reason_s}) -> {label}")
    with contextlib.suppress(Exception):
        _shared_camoufox_session.request_reset()


def _bookmaker_restore_shared_camoufox_direct_route(*, reason: str = "") -> bool:
    """Make a valid fallback-page probe one-shot and restore the primary route."""
    global _bookmaker_shared_proxy_candidates, _bookmaker_shared_proxy_index
    with _bookmaker_shared_proxy_lock:
        if not _bookmaker_shared_proxy_candidates:
            _bookmaker_shared_proxy_candidates = _bookmaker_shared_winline_routes()
            _bookmaker_shared_proxy_index = 0
        if not _bookmaker_shared_proxy_candidates or _bookmaker_shared_proxy_index == 0:
            return False
        _bookmaker_shared_proxy_index = 0
    reason_s = str(reason or "valid_page").strip() or "valid_page"
    print(f"   ↩️ Shared Camoufox route restore ({reason_s}) -> direct")
    with contextlib.suppress(Exception):
        _shared_camoufox_session.request_reset()
    return True


def _bookmaker_refresh_snapshot_via_shared_camoufox(match_key: str) -> Optional[dict]:
    """Refresh odds snapshot in-process via process-wide shared Camoufox (no subprocess)."""
    if not BOOKMAKER_PREFETCH_ENABLED:
        return None
    snapshot = _bookmaker_prefetch_lookup(match_key, wait_seconds=0.0)
    if not isinstance(snapshot, dict):
        return None
    radiant_team = str(snapshot.get("radiant_team") or "")
    dire_team = str(snapshot.get("dire_team") or "")
    mode = str(snapshot.get("mode") or BOOKMAKER_PREFETCH_MODE or "live")
    map_num_raw = snapshot.get("map_num")
    try:
        map_num = int(map_num_raw) if map_num_raw is not None else None
    except (TypeError, ValueError):
        map_num = None
    if map_num is not None and not (1 <= map_num <= 5):
        map_num = None
    radiant_team_candidates = list(snapshot.get("radiant_team_candidates") or [radiant_team])
    dire_team_candidates = list(snapshot.get("dire_team_candidates") or [dire_team])
    try:
        if BOOKMAKER_CAMOUFOX_ENABLED and BOOKMAKER_CAMOUFOX_IMPORTED:
            sites_payload = _bookmaker_prefetch_fetch_camoufox_direct(
                radiant_team=radiant_team,
                dire_team=dire_team,
                mode=mode,
                map_num=map_num,
                radiant_team_candidates=radiant_team_candidates,
                dire_team_candidates=dire_team_candidates,
            )
        else:
            # Odds mode: never fall back to Camoufox subprocess. Cached sites remain
            # diagnostic-only and are explicitly made gate-ineligible.
            if BOOKMAKER_PREFETCH_GATE_MODE == "odds":
                unavailable_reason = (
                    "shared_camoufox_disabled"
                    if not BOOKMAKER_CAMOUFOX_ENABLED
                    else "shared_camoufox_import_unavailable"
                )
                logger.warning(
                    "BOOKMAKER_SHARED_CAMOUFOX_UNAVAILABLE %s: reason=%s imported=%s enabled=%s",
                    match_key,
                    unavailable_reason,
                    BOOKMAKER_CAMOUFOX_IMPORTED,
                    BOOKMAKER_CAMOUFOX_ENABLED,
                )
                failed_at = time.time()
                with bookmaker_prefetch_condition:
                    payload = bookmaker_prefetch_results.get(match_key)
                    if isinstance(payload, dict):
                        payload["status"] = "error"
                        payload.setdefault("sites", payload.get("sites") or {})
                        payload["error"] = unavailable_reason
                        payload["odds_refresh_ready"] = False
                        payload["odds_refresh_failed_at"] = failed_at
                        payload["finished_at"] = failed_at
                        bookmaker_prefetch_condition.notify_all()
                return _bookmaker_prefetch_lookup(match_key, wait_seconds=0.0)
            # Presence-safe fallback only when Camoufox is unavailable.
            sites_payload = _bookmaker_prefetch_fetch_subprocess(
                radiant_team=radiant_team,
                dire_team=dire_team,
                mode=mode,
                map_num=map_num,
                radiant_team_candidates=radiant_team_candidates,
                dire_team_candidates=dire_team_candidates,
            )
    except Exception as exc:
        logger.warning("BOOKMAKER_SHARED_CAMOUFOX_REFRESH_FAILED %s: %s", match_key, exc)
        with contextlib.suppress(Exception):
            _bookmaker_rotate_shared_camoufox_proxy(reason="refresh_error")
        if BOOKMAKER_PREFETCH_GATE_MODE == "odds":
            failed_at = time.time()
            with bookmaker_prefetch_condition:
                payload = bookmaker_prefetch_results.get(match_key)
                if isinstance(payload, dict):
                    payload["status"] = "error"
                    payload.setdefault("sites", payload.get("sites") or {})
                    payload["error"] = "shared_camoufox_refresh_failed"
                    payload["odds_refresh_ready"] = False
                    payload["odds_refresh_failed_at"] = failed_at
                    payload["finished_at"] = failed_at
                    bookmaker_prefetch_condition.notify_all()
            return _bookmaker_prefetch_lookup(match_key, wait_seconds=0.0)
        return snapshot
    refreshed_at = time.time()
    with bookmaker_prefetch_condition:
        payload = bookmaker_prefetch_results.get(match_key)
        if isinstance(payload, dict):
            payload["status"] = "done"
            payload["finished_at"] = refreshed_at
            payload["odds_refreshed_at"] = refreshed_at
            payload["odds_refresh_ready"] = True
            payload.pop("odds_refresh_failed_at", None)
            payload.pop("error", None)
            payload["sites"] = sites_payload
            bookmaker_prefetch_condition.notify_all()
    return _bookmaker_prefetch_lookup(match_key, wait_seconds=0.0)


def _bookmaker_prefetch_prune_locked(now_ts: float) -> List[str]:
    if not bookmaker_prefetch_results:
        return []
    ttl = max(60, int(BOOKMAKER_PREFETCH_RESULT_TTL_SECONDS))
    to_drop = []
    for match_key, payload in bookmaker_prefetch_results.items():
        status = str(payload.get("status") or "")
        finished_at = float(payload.get("finished_at") or payload.get("submitted_at") or 0.0)
        if status in {"done", "error"} and now_ts - finished_at > ttl:
            to_drop.append(match_key)
    for match_key in to_drop:
        bookmaker_prefetch_results.pop(match_key, None)
    return list(to_drop)


def _bookmaker_series_identity(match_key: str) -> Optional[str]:
    """Stable series base for bookmaker lifecycle: URL without numeric kills/score suffix.

    Uses the same normalization family as `_signal_fingerprint_registry_key` /
    `_draft_metrics_cache_key`. Requires an extractable series match id; never
    invents identity from a bare host or unknown path.
    """
    raw = str(match_key or "").strip()
    if not raw:
        return None
    # Already a lifecycle key: series|mapN → series portion only.
    m_life = re.match(r"^(?P<series>.+)\|map([1-5])$", raw)
    if m_life:
        raw = str(m_life.group("series") or "").strip()
    series = _signal_fingerprint_registry_key(raw)
    if not series:
        return None
    if _bookmaker_extract_match_id(series) is None:
        return None
    return series


def _bookmaker_lifecycle_identity(
    match_key: str,
    map_num: Any = None,
) -> Optional[str]:
    """Canonical internal identity: stable series + current map_num.

    Fail closed: missing/invalid series or map_num → None.
    Kills/score suffixes never participate. Different map_num values never collide.
    """
    series = _bookmaker_series_identity(match_key)
    if not series:
        return None
    try:
        resolved_map = int(map_num) if map_num is not None else None
    except (TypeError, ValueError):
        return None
    if resolved_map is None or not (1 <= resolved_map <= 5):
        return None
    return f"{series}|map{resolved_map}"


def _bookmaker_resolve_lifecycle_key(
    match_key: str,
    map_num: Any = None,
    *,
    results: Optional[Dict[str, Any]] = None,
) -> Optional[str]:
    """Resolve a raw/diagnostic URL or partial key to the canonical lifecycle key.

    When map_num is known, build the identity directly (fail closed on invalid).
    When map_num is absent, accept an already-canonical key, or uniquely match
    an existing results entry for the same series. Never fall back to series-only
    or raw score-suffixed URL as identity.
    """
    raw = str(match_key or "").strip()
    if not raw:
        return None
    if map_num is not None:
        return _bookmaker_lifecycle_identity(raw, map_num=map_num)
    # Already canonical?
    if re.search(r"\|map[1-5]$", raw):
        return raw if _bookmaker_lifecycle_identity(raw, map_num=int(raw.rsplit("|map", 1)[-1])) else None
    series = _bookmaker_series_identity(raw)
    if not series:
        return None
    table = results if isinstance(results, dict) else bookmaker_prefetch_results
    candidates: List[str] = []
    for key in list(table.keys()):
        key_s = str(key or "")
        if key_s.startswith(series + "|map") and re.search(r"\|map[1-5]$", key_s):
            candidates.append(key_s)
            continue
        payload = table.get(key)
        if not isinstance(payload, dict):
            continue
        # Diagnostic aliases stored on payload.
        diag = str(payload.get("diagnostic_url") or payload.get("url") or "").strip()
        if diag and _signal_fingerprint_registry_key(diag) == series:
            life = _bookmaker_lifecycle_identity(series, map_num=payload.get("map_num"))
            if life:
                candidates.append(life if life in table else key_s)
    # Dedup preserve order
    seen: set[str] = set()
    uniq: List[str] = []
    for c in candidates:
        if c not in seen:
            seen.add(c)
            uniq.append(c)
    if len(uniq) == 1:
        return uniq[0]
    # Prefer payload whose diagnostic_url equals the raw request when multiple maps.
    if len(uniq) > 1:
        for c in uniq:
            payload = table.get(c)
            if not isinstance(payload, dict):
                continue
            diag = str(payload.get("diagnostic_url") or payload.get("url") or "").strip()
            if diag == raw or _signal_fingerprint_registry_key(diag) == series and str(
                payload.get("status") or ""
            ) in {"queued", "running", "done"}:
                # Still ambiguous across maps — only accept exact diagnostic match.
                if diag == raw:
                    return c
        return None
    return None


def _bookmaker_terminalize_failed_lifecycle(
    match_key: str,
    map_num: Any = None,
) -> None:
    """Clear a failed canonical entry so the same series+map can re-queue.

    One shared driver/protocol failure must not leave the entry permanently
    queued/running/error under a score-suffixed raw key. Identity stays
    series+map only; diagnostic URL is not used as identity.
    """
    with bookmaker_prefetch_condition:
        life = _bookmaker_resolve_lifecycle_key(
            match_key,
            map_num=map_num,
            results=bookmaker_prefetch_results,
        )
        if not life:
            life = _bookmaker_lifecycle_identity(match_key, map_num=map_num)
        series = _bookmaker_series_identity(match_key)
        # Drop any raw score-suffixed aliases that leaked into the table for this series+map.
        if series is not None:
            try:
                expected_map = int(map_num) if map_num is not None else None
            except (TypeError, ValueError):
                expected_map = None
            for key in list(bookmaker_prefetch_results.keys()):
                key_s = str(key or "")
                if life and key_s == life:
                    continue
                if _bookmaker_series_identity(key_s) != series:
                    continue
                payload = bookmaker_prefetch_results.get(key)
                pmap = None
                if isinstance(payload, dict):
                    try:
                        pmap = int(payload.get("map_num")) if payload.get("map_num") is not None else None
                    except (TypeError, ValueError):
                        pmap = None
                if expected_map is None or pmap is None or pmap == expected_map:
                    bookmaker_prefetch_results.pop(key, None)
        if life:
            bookmaker_prefetch_results.pop(life, None)
            drop_q = [
                item
                for item in list(bookmaker_prefetch_queue)
                if str((item or {}).get("match_key") or "") == life
                or (
                    _bookmaker_lifecycle_identity(
                        str((item or {}).get("match_key") or ""),
                        map_num=(item or {}).get("map_num"),
                    )
                    == life
                )
            ]
            for item in drop_q:
                with contextlib.suppress(ValueError):
                    bookmaker_prefetch_queue.remove(item)
        bookmaker_prefetch_condition.notify_all()


def _bookmaker_prefetch_lookup(match_key: str, wait_seconds: float = 0.0) -> Optional[dict]:
    if not BOOKMAKER_PREFETCH_ENABLED:
        return None
    wait_seconds = max(0.0, float(wait_seconds or 0.0))
    deadline = time.time() + wait_seconds
    with bookmaker_prefetch_condition:
        while True:
            life = _bookmaker_resolve_lifecycle_key(
                match_key,
                results=bookmaker_prefetch_results,
            )
            lookup_key = life or str(match_key or "").strip()
            payload = bookmaker_prefetch_results.get(lookup_key) if lookup_key else None
            if payload is None and life is None:
                # Fail closed: no series-only / raw-score fallback when identity unresolved.
                return None
            if payload is None:
                return None
            status = str(payload.get("status") or "")
            if status in {"done", "error"}:
                return copy.deepcopy(payload)
            if wait_seconds <= 0.0:
                return copy.deepcopy(payload)
            remaining = deadline - time.time()
            if remaining <= 0:
                return copy.deepcopy(payload)
            bookmaker_prefetch_condition.wait(timeout=min(0.2, remaining))


def _bookmaker_extract_match_id(match_key: str) -> Optional[str]:
    m = re.search(r"/matches/(\d+)", str(match_key or ""))
    if not m:
        return None
    return str(m.group(1))


def _bookmaker_slugify_text(value: str) -> str:
    compact = re.sub(r"[^a-z0-9а-я]+", "-", str(value or "").strip().lower())
    compact = re.sub(r"-{2,}", "-", compact).strip("-")
    return compact


def _bookmaker_extract_team_aliases_from_series_url(
    *,
    series_url: str,
    league_title: str,
) -> Tuple[Optional[str], Optional[str]]:
    match = re.search(r"/matches/\d+/([^/?#]+)", str(series_url or ""))
    if not match:
        return None, None
    slug = str(match.group(1) or "").strip().lower()
    if "-vs-" not in slug:
        return None, None
    league_slug = _bookmaker_slugify_text(league_title)
    if league_slug and slug.endswith("-" + league_slug):
        slug = slug[: -(len(league_slug) + 1)]
    left, right = slug.split("-vs-", 1)
    left = left.strip("-")
    right = right.strip("-")
    if not left or not right:
        return None, None
    return left.replace("-", " ").strip(), right.replace("-", " ").strip()


def _bookmaker_build_team_candidates(primary_name: str, alias_name: Optional[str]) -> List[str]:
    candidates: List[str] = []
    seen: set[str] = set()
    for raw in (primary_name, alias_name):
        value = str(raw or "").strip()
        if not value:
            continue
        key = normalize_team_name(value)
        if not key or key in seen:
            continue
        seen.add(key)
        candidates.append(value)
    return candidates


def _bookmaker_source_snapshot_rows(match_key: str) -> Tuple[str, List[Dict[str, Any]]]:
    snapshot = _bookmaker_prefetch_lookup(match_key, wait_seconds=0.0)
    if not isinstance(snapshot, dict):
        return "", []
    map_context = ""
    map_num_raw = snapshot.get("map_num")
    if isinstance(map_num_raw, int) and 1 <= map_num_raw <= 5:
        map_context = f"карта {map_num_raw}"
    sites_payload = snapshot.get("sites")
    if not isinstance(sites_payload, dict):
        return map_context, []
    label_map = {
        "betboom": "BetBoom",
        "pari": "Pari",
        "winline": "Winline",
    }
    rows: List[Dict[str, Any]] = []
    for site in BOOKMAKER_PREFETCH_SITES:
        site_payload = sites_payload.get(site)
        p1: Optional[float] = None
        p2: Optional[float] = None
        reason: Optional[str] = None
        source_name = ""
        details_excerpt = ""
        match_found = False
        status = ""
        if isinstance(site_payload, dict):
            match_found = bool(site_payload.get("match_found", False))
            status = str(site_payload.get("status") or "")
            if bool(site_payload.get("market_closed")):
                reason = "map_market_closed"
            source_name = str(site_payload.get("source") or "").strip()
            if source_name:
                reason = source_name
            details_excerpt = str(site_payload.get("details") or "").strip()[:220]
            odds = site_payload.get("odds")
            if isinstance(odds, list) and len(odds) >= 2 and not bool(site_payload.get("market_closed")):
                try:
                    p1 = float(odds[0])
                    p2 = float(odds[1])
                except (TypeError, ValueError):
                    p1 = None
                    p2 = None
        rows.append(
            {
                "bookmaker": label_map.get(site, site),
                "П1": p1,
                "П2": p2,
                "reason": reason,
                "source": source_name,
                "details_excerpt": details_excerpt,
                "match_found": match_found,
                "status": status,
            }
        )
    return map_context, rows


def _log_bookmaker_source_snapshot(match_key: str, decision: str) -> None:
    if decision not in {"sent", "no_numeric_odds", "no_match_presence"}:
        return
    match_url = str(match_key or "")
    map_context, rows = _bookmaker_source_snapshot_rows(match_url)
    if not rows:
        rows = [{"bookmaker": "unknown", "П1": None, "П2": None}]
    base_payload = {
        "timestamp": datetime.now().isoformat(timespec="seconds"),
        "match_id": _bookmaker_extract_match_id(match_url),
        "url": match_url,
        "map_context": map_context,
        "decision": decision,
    }
    for row in rows:
        payload = dict(base_payload)
        payload.update(row)
        snapshot_line = "BOOKMAKER_SOURCE_SNAPSHOT " + json.dumps(payload, ensure_ascii=False)
        logger.info(snapshot_line)
        # Keep snapshot visible in stdout/stderr-tail windows used for live ops evidence.
        print(snapshot_line)


# Sentinel lives next to resolve (above). Keep map helper once only — remove duplicate definition below.


def _bookmaker_format_odds_block(
    match_key: str,
    selected_side: Any = _BOOKMAKER_SELECTED_SIDE_UNSET,
) -> Tuple[str, bool, str]:
    snapshot = _bookmaker_prefetch_lookup(
        match_key,
        wait_seconds=BOOKMAKER_PREFETCH_MESSAGE_WAIT_SECONDS,
    )
    if not snapshot:
        return "", False, "prefetch_not_found"
    snapshot_status = str(snapshot.get("status") or "")
    if snapshot_status != "done":
        return "", False, f"prefetch_{snapshot_status or 'unknown'}"
    sites_payload = snapshot.get("sites")
    if not isinstance(sites_payload, dict):
        return "", False, "invalid_sites_payload"

    map_num_raw = snapshot.get("map_num")
    try:
        map_num = int(map_num_raw) if map_num_raw is not None else None
    except (TypeError, ValueError):
        map_num = None
    if map_num is not None and not (1 <= map_num <= 5):
        map_num = None

    winline = sites_payload.get("winline")
    if not _bookmaker_is_strict_winline_current_map(winline, expected_map_num=map_num):
        if isinstance(winline, dict) and bool(winline.get("market_closed")):
            return "", False, "temporarily_closed_wait"
        return "", False, "no_strict_winline_current_map"

    odds = winline.get("odds")  # type: ignore[union-attr]
    try:
        p1 = float(odds[0])
        p2 = float(odds[1])
    except (TypeError, ValueError, IndexError):
        return "", False, "no_numeric_odds"
    mode = str(snapshot.get("mode") or BOOKMAKER_PREFETCH_MODE)
    map_suffix = f", карта {map_num}" if map_num is not None else ""
    # Strict Winline-only display: P1=team1/radiant, P2=team2/dire.
    if selected_side is _BOOKMAKER_SELECTED_SIDE_UNSET:
        return f"БК ({mode}{map_suffix}): Winline П1 {p1:.2f} / П2 {p2:.2f}\n", True, "ok"
    odds_index, side_reason = _bookmaker_map_selected_side_to_odds_index(selected_side)
    if odds_index is None:
        return "", False, side_reason
    selected_decimal = p1 if odds_index == 0 else p2
    return f"Кэф Winline: {selected_decimal:.2f}\n", True, "ok"


def _bookmaker_format_presence_block(match_key: str) -> Tuple[str, bool, str]:
    snapshot = _bookmaker_prefetch_lookup(
        match_key,
        wait_seconds=BOOKMAKER_PREFETCH_MESSAGE_WAIT_SECONDS,
    )
    if not snapshot:
        return "", False, "prefetch_not_found"
    snapshot_status = str(snapshot.get("status") or "")
    if snapshot_status != "done":
        return "", False, f"prefetch_{snapshot_status or 'unknown'}"
    sites_payload = snapshot.get("sites")
    if not isinstance(sites_payload, dict):
        return "", False, "invalid_sites_payload"
    display_order = [
        ("winline", "Winline"),
        ("betboom", "BetBoom"),
        ("pari", "Pari"),
    ]
    cells: List[str] = []
    has_match_presence = False
    for site, site_label in display_order:
        site_payload = sites_payload.get(site)
        site_found = isinstance(site_payload, dict) and bool(site_payload.get("match_found", False))
        if site_found:
            has_match_presence = True
        marker = _bookmaker_presence_site_marker(site_payload)
        cells.append(f"{site_label} {marker}")
    all_sites_error = _bookmaker_presence_all_sites_error(sites_payload)
    if not cells or (not has_match_presence and not all_sites_error):
        return "", False, "no_match_presence"
    mode = str(snapshot.get("mode") or BOOKMAKER_PREFETCH_MODE)
    map_num_raw = snapshot.get("map_num")
    map_num = int(map_num_raw) if isinstance(map_num_raw, int) and 1 <= map_num_raw <= 5 else None
    map_suffix = f", карта {map_num}" if map_num is not None else ""
    reason = "all_sites_error" if (not has_match_presence and all_sites_error) else "ok"
    return f"БК ({mode}{map_suffix}): " + " | ".join(cells) + "\n", True, reason


def _bookmaker_format_gate_block(match_key: str) -> Tuple[str, bool, str]:
    if BOOKMAKER_PREFETCH_GATE_MODE == "presence":
        return _bookmaker_format_presence_block(match_key)
    return _bookmaker_format_odds_block(match_key)


def _bookmaker_sites_compact_summary(sites_payload: Any) -> str:
    if not isinstance(sites_payload, dict):
        return "sites=none"
    parts: List[str] = []
    for site in BOOKMAKER_PREFETCH_SITES:
        site_payload = sites_payload.get(site)
        if not isinstance(site_payload, dict):
            parts.append(f"{site}:error/missing")
            continue
        status = str(site_payload.get("status") or "unknown")
        if BOOKMAKER_PREFETCH_GATE_MODE == "presence":
            marker = _bookmaker_presence_site_state(site_payload)
            source_name = str(site_payload.get("source") or "").strip()
            source_suffix = f"/{source_name}" if source_name else ""
            parts.append(f"{site}:{marker}/{status}{source_suffix}")
        else:
            odds = site_payload.get("odds")
            match_odds = site_payload.get("match_odds")
            if isinstance(odds, list) and len(odds) >= 2:
                marker = "map_odds"
            elif isinstance(match_odds, list) and len(match_odds) >= 2:
                marker = "match_odds"
            elif bool(site_payload.get("market_closed")):
                marker = "closed"
            else:
                marker = "none"
            parts.append(f"{site}:{marker}/{status}")
    return ", ".join(parts) if parts else "sites=none"


def _bookmaker_presence_trace_summary(sites_payload: Any) -> str:
    if not isinstance(sites_payload, dict):
        return ""
    label_map = {
        "betboom": "BetBoom",
        "pari": "Pari",
        "winline": "Winline",
    }
    trace_parts: List[str] = []
    for site in BOOKMAKER_PREFETCH_SITES:
        site_payload = sites_payload.get(site)
        if not isinstance(site_payload, dict) or not bool(site_payload.get("match_found", False)):
            continue
        source_name = str(site_payload.get("source") or "").strip() or "unknown"
        details = str(site_payload.get("details") or "").strip()
        details_excerpt = details[:140] + ("..." if len(details) > 140 else "") if details else ""
        token = f"{label_map.get(site, site)}={source_name}"
        if details_excerpt:
            token += f" [{details_excerpt}]"
        trace_parts.append(token)
    return " | ".join(trace_parts)


def _bookmaker_presence_site_state(site_payload: Any) -> str:
    if not isinstance(site_payload, dict):
        return "error"
    if bool(site_payload.get("match_found", False)):
        return "found"
    source_name = str(site_payload.get("source") or "").strip().lower()
    if source_name in {
        "explicit_absence",
        "event_not_listed",
        "match_absent",
        "match_not_listed",
    }:
        return "absent"
    return "error"


def _bookmaker_presence_site_marker(site_payload: Any) -> str:
    state = _bookmaker_presence_site_state(site_payload)
    if state == "found":
        return "✅"
    if state == "absent":
        return "❌"
    return "error"


def _bookmaker_presence_has_partial_miss(snapshot: Optional[dict]) -> bool:
    payload = snapshot if isinstance(snapshot, dict) else {}
    sites_payload = payload.get("sites")
    if not isinstance(sites_payload, dict):
        return False
    has_found = False
    has_non_found = False
    for site in BOOKMAKER_PREFETCH_SITES:
        site_payload = sites_payload.get(site)
        if isinstance(site_payload, dict) and bool(site_payload.get("match_found", False)):
            has_found = True
        else:
            has_non_found = True
    return has_found and has_non_found


def _bookmaker_presence_all_sites_error(sites_payload: Any) -> bool:
    if not isinstance(sites_payload, dict):
        return False
    seen_any = False
    for site in BOOKMAKER_PREFETCH_SITES:
        site_payload = sites_payload.get(site)
        seen_any = True
        if _bookmaker_presence_site_state(site_payload) != "error":
            return False
    return seen_any


def _log_bookmaker_presence_gate(match_key: str, state: str, snapshot: Optional[dict]) -> None:
    payload = snapshot if isinstance(snapshot, dict) else {}
    status = str(payload.get("status") or "")
    sites_summary = _bookmaker_sites_compact_summary(payload.get("sites"))
    log_line = (
        f"BOOKMAKER_PRESENCE_GATE state={state} status={status or 'none'} "
        f"url={match_key} {sites_summary}"
    )
    if state == "error":
        error_text = str(payload.get("error") or "").strip()
        if error_text:
            log_line += f" error={error_text[:300]}"
    trace_summary = _bookmaker_presence_trace_summary(payload.get("sites"))
    if trace_summary:
        log_line += f" trace={trace_summary}"
    logger.info(log_line)
    print(log_line)


def _log_bookmaker_presence_failure_diagnostics(
    match_key: str,
    snapshot: Optional[dict],
    *,
    context: str,
    only_non_found: bool = False,
) -> None:
    payload = snapshot if isinstance(snapshot, dict) else {}
    map_context, rows = _bookmaker_source_snapshot_rows(match_key)
    if not rows:
        return
    base_payload = {
        "timestamp": datetime.now().isoformat(timespec="seconds"),
        "context": context,
        "match_id": _bookmaker_extract_match_id(match_key),
        "url": match_key,
        "map_context": map_context,
        "snapshot_status": str(payload.get("status") or ""),
        "proxy_url": str(BOOKMAKER_PROXY_URL or ""),
        "sites_summary": _bookmaker_sites_compact_summary(payload.get("sites")),
    }
    for row in rows:
        if only_non_found and bool(row.get("match_found", False)):
            continue
        diag_payload = dict(base_payload)
        diag_payload.update(row)
        diag_payload["details"] = str(row.get("details_excerpt") or "")
        line = "BOOKMAKER_PRESENCE_FAILURE_DIAGNOSTICS " + json.dumps(diag_payload, ensure_ascii=False)
        logger.error(line)
        print(line)


def _bookmaker_presence_gate_resolution(match_key: str) -> Tuple[str, Optional[dict]]:
    snapshot = _bookmaker_prefetch_lookup(match_key, wait_seconds=0.0)
    if not isinstance(snapshot, dict):
        return "pending", None
    snapshot_status = str(snapshot.get("status") or "")
    if snapshot_status in {"queued", "running", ""}:
        return "pending", snapshot
    if snapshot_status != "done":
        return "error", snapshot
    sites_payload = snapshot.get("sites")
    if not isinstance(sites_payload, dict):
        return "error", snapshot
    for site_payload in sites_payload.values():
        if isinstance(site_payload, dict) and bool(site_payload.get("match_found", False)):
            return "allow", snapshot
    if _bookmaker_presence_all_sites_error(sites_payload):
        return "allow", snapshot
    return "reject", snapshot


def _bookmaker_close_window_handles_unlocked(driver: Any, handles: List[str]) -> None:
    valid_handles = [str(handle or "").strip() for handle in handles if str(handle or "").strip()]
    if driver is None or not valid_handles:
        return
    try:
        known_handles = set(driver.window_handles or [])
    except Exception:
        known_handles = set()
    for handle in valid_handles:
        if handle not in known_handles:
            continue
        try:
            driver.switch_to.window(handle)
            driver.close()
        except Exception:
            continue


def _bookmaker_browser_bootstrap_unlocked(mode: str) -> bool:
    global bookmaker_browser_driver, bookmaker_browser_base_handles
    if _bookmaker_build_driver is None or _bookmaker_open_presence_site_tabs is None:
        return False
    if bookmaker_browser_driver is None:
        bookmaker_browser_driver = _bookmaker_build_driver(BOOKMAKER_PROXY_URL)
        bookmaker_browser_base_handles = {}
    if bookmaker_browser_base_handles:
        return True
    urls = _bookmaker_urls_for_mode(mode)
    effective_sites = _bookmaker_effective_sites_for_mode(BOOKMAKER_PREFETCH_GATE_MODE)
    selected_sites = [site for site in effective_sites if site in urls]
    if not selected_sites:
        return False
    bookmaker_browser_base_handles = _bookmaker_open_presence_site_tabs(
        bookmaker_browser_driver,
        selected_sites=selected_sites,
        urls=urls,
    )
    return bool(bookmaker_browser_base_handles)


# Camoufox browser reuse functions
CAMOUFOX_BROWSER_MAX_IDLE_SECONDS = 300  # 5 minutes idle = close browser


def _ensure_camoufox_browser() -> Any:
    """Legacy guard: direct Camoufox ownership moved to _SharedCamoufoxSession."""
    raise RuntimeError("Use _run_shared_camoufox_job() for Camoufox work")


def _close_camoufox_browser() -> None:
    """Close the persistent Camoufox browser if idle too long or on shutdown."""
    global bookmaker_camoufox_browser, bookmaker_camoufox_browser_last_used
    if bookmaker_camoufox_browser is not None:
        try:
            bookmaker_camoufox_browser.close()
        except Exception:
            pass
        bookmaker_camoufox_browser = None
        bookmaker_camoufox_browser_last_used = 0.0
        print("   🔒 Camoufox browser closed")


def _cleanup_on_exit() -> None:
    """Called on process exit to clean up resources."""
    _close_camoufox_browser()


atexit.register(_cleanup_on_exit)


def _should_close_camoufox_browser() -> bool:
    """Check if Camoufox browser should be closed due to inactivity."""
    global bookmaker_camoufox_browser, bookmaker_camoufox_browser_last_used
    if bookmaker_camoufox_browser is None:
        return False
    if bookmaker_camoufox_browser_last_used <= 0:
        return False
    idle = time.time() - bookmaker_camoufox_browser_last_used
    if idle > CAMOUFOX_BROWSER_MAX_IDLE_SECONDS:
        return True
    return False


def _bookmaker_try_open_match_details_with_candidates_unlocked(
    driver: Any,
    *,
    site: str,
    team1_candidates: List[str],
    team2_candidates: List[str],
) -> Optional[str]:
    if driver is None or _bookmaker_open_match_details_by_teams is None:
        return None
    seen_pairs = set()
    for team1_candidate in list(team1_candidates or []):
        for team2_candidate in list(team2_candidates or []):
            pair = (str(team1_candidate or "").strip().lower(), str(team2_candidate or "").strip().lower())
            if not pair[0] or not pair[1] or pair in seen_pairs:
                continue
            seen_pairs.add(pair)
            opened_url = _bookmaker_open_match_details_by_teams(
                driver,
                site=site,
                team1=str(team1_candidate or ""),
                team2=str(team2_candidate or ""),
            )
            if opened_url:
                return str(opened_url)
    return None


def _bookmaker_prune_match_tab_cache_unlocked(max_matches: Optional[int] = None) -> None:
    global bookmaker_browser_match_tabs
    limit = max(1, int(max_matches or BOOKMAKER_MATCH_TAB_CACHE_MAX_MATCHES or 8))
    while len(bookmaker_browser_match_tabs) > limit:
        stale_match_key, stale_payload = bookmaker_browser_match_tabs.popitem(last=False)
        handles = [
            str((site_payload or {}).get("handle") or "")
            for site_payload in ((stale_payload or {}).get("sites") or {}).values()
            if isinstance(site_payload, dict)
        ]
        _bookmaker_close_window_handles_unlocked(bookmaker_browser_driver, handles)
        logger.info("BOOKMAKER_MATCH_TAB_CACHE_EVICT url=%s handles=%s", stale_match_key, len(handles))


def _bookmaker_release_match_tabs(match_key: str) -> None:
    global bookmaker_browser_match_tabs
    raw = str(match_key or "").strip()
    if not raw:
        return
    # Resolve to canonical series+map identity when possible; also try series-base
    # aliases that may have been stored under raw score URLs historically.
    candidates: List[str] = [raw]
    life = _bookmaker_resolve_lifecycle_key(raw, results=bookmaker_prefetch_results)
    if life and life not in candidates:
        candidates.append(life)
    series = _bookmaker_series_identity(raw)
    with bookmaker_browser_lock:
        if series:
            for cached_key in list(bookmaker_browser_match_tabs.keys()):
                if cached_key in candidates:
                    continue
                if _bookmaker_series_identity(str(cached_key)) == series:
                    candidates.append(str(cached_key))
        for normalized_match_key in candidates:
            stale_payload = bookmaker_browser_match_tabs.pop(normalized_match_key, None)
            if not isinstance(stale_payload, dict):
                continue
            handles = [
                str((site_payload or {}).get("handle") or "")
                for site_payload in ((stale_payload or {}).get("sites") or {}).values()
                if isinstance(site_payload, dict)
            ]
            _bookmaker_close_window_handles_unlocked(bookmaker_browser_driver, handles)
            logger.info("BOOKMAKER_MATCH_TAB_CACHE_RELEASE url=%s handles=%s", normalized_match_key, len(handles))


def _bookmaker_open_cached_match_tabs_unlocked(
    match_key: str,
    *,
    radiant_team: str,
    dire_team: str,
    radiant_team_candidates: List[str],
    dire_team_candidates: List[str],
    mode: str,
    map_num: Optional[int],
) -> Dict[str, dict]:
    global bookmaker_browser_match_tabs
    sites_payload: Dict[str, dict] = {}
    if (
        bookmaker_browser_driver is None
        or _bookmaker_probe_presence_site_in_current_tab is None
        or _bookmaker_open_match_details_by_teams is None
    ):
        return sites_payload
    if not _bookmaker_browser_bootstrap_unlocked(mode):
        return sites_payload
    urls = _bookmaker_urls_for_mode(mode)
    cached_sites: Dict[str, dict] = {}
    for site in BOOKMAKER_PREFETCH_SITES:
        base_handle = str(bookmaker_browser_base_handles.get(site) or "").strip()
        site_url = str(urls.get(site) or "")
        if not base_handle or not site_url:
            continue
        try:
            bookmaker_browser_driver.switch_to.window(base_handle)
            result = _bookmaker_probe_presence_site_in_current_tab(
                bookmaker_browser_driver,
                site=site,
                url=site_url,
                team1=radiant_team,
                team2=dire_team,
                mode=mode,
                team1_aliases=radiant_team_candidates,
                team2_aliases=dire_team_candidates,
                extra_reload_on_empty=(site == "pari"),
                extra_scroll_passes=(2 if site in {"betboom", "winline"} else 1 if site == "pari" else 0),
            )
        except Exception as exc:
            result = None
            sites_payload[site] = {
                "status": "request_error",
                "match_found": False,
                "odds": [],
                "match_odds": [],
                "source": "tab_probe_error",
                "details": str(exc)[:500],
                "market_closed": False,
            }
        if result is None:
            continue
        sites_payload[site] = {
            "status": str(getattr(result, "status", "")),
            "match_found": bool(getattr(result, "match_found", False)),
            "odds": [],
            "match_odds": [],
            "source": str(getattr(result, "source", "")),
            "details": str(getattr(result, "details", ""))[:500],
            "market_closed": bool(getattr(result, "market_closed", False)),
        }
        if not bool(getattr(result, "match_found", False)):
            continue
        before_handles = set(bookmaker_browser_driver.window_handles or [])
        current_url = ""
        try:
            current_url = str(bookmaker_browser_driver.current_url or "") or site_url
        except Exception:
            current_url = site_url
        try:
            bookmaker_browser_driver.execute_script("window.open(arguments[0], '_blank');", current_url)
            new_handles = [handle for handle in bookmaker_browser_driver.window_handles if handle not in before_handles]
            match_handle = str(new_handles[0] if new_handles else bookmaker_browser_driver.window_handles[-1])
            bookmaker_browser_driver.switch_to.window(match_handle)
            time.sleep(1.0)
            opened_url = _bookmaker_try_open_match_details_with_candidates_unlocked(
                bookmaker_browser_driver,
                site=site,
                team1_candidates=radiant_team_candidates,
                team2_candidates=dire_team_candidates,
            )
            if not opened_url:
                _bookmaker_close_window_handles_unlocked(bookmaker_browser_driver, [match_handle])
                continue
            cached_sites[site] = {
                "handle": match_handle,
                "url": str(opened_url),
                "opened_at": time.time(),
                "map_num": int(map_num) if isinstance(map_num, int) and 1 <= map_num <= 5 else None,
            }
        except Exception as exc:
            sites_payload[site]["details"] = str(exc)[:500]
            _bookmaker_close_window_handles_unlocked(
                bookmaker_browser_driver,
                [h for h in bookmaker_browser_driver.window_handles if h not in before_handles],
            )
            continue
    if cached_sites:
        bookmaker_browser_match_tabs[match_key] = {
            "radiant_team": str(radiant_team or ""),
            "dire_team": str(dire_team or ""),
            "radiant_team_candidates": list(radiant_team_candidates or []),
            "dire_team_candidates": list(dire_team_candidates or []),
            "mode": str(mode or BOOKMAKER_PREFETCH_MODE),
            "map_num": int(map_num) if isinstance(map_num, int) and 1 <= map_num <= 5 else None,
            "sites": cached_sites,
            "created_at": time.time(),
            "last_refreshed_at": 0.0,
        }
        bookmaker_browser_match_tabs.move_to_end(match_key, last=True)
        _bookmaker_prune_match_tab_cache_unlocked()
    return sites_payload


def _bookmaker_refresh_cached_match_tabs_for_dispatch(match_key: str) -> Optional[dict]:
    normalized_match_key = str(match_key or "").strip()
    if not normalized_match_key:
        return None
    with bookmaker_browser_lock:
        cache_entry = bookmaker_browser_match_tabs.get(normalized_match_key)
        if not isinstance(cache_entry, dict):
            return None
        if bookmaker_browser_driver is None or _bookmaker_parse_map_market_on_current_page is None:
            return None
        refreshed_sites: Dict[str, dict] = {}
        for site in BOOKMAKER_PREFETCH_SITES:
            site_cache = (cache_entry.get("sites") or {}).get(site)
            if not isinstance(site_cache, dict):
                continue
            handle = str(site_cache.get("handle") or "").strip()
            if not handle:
                continue
            try:
                bookmaker_browser_driver.switch_to.window(handle)
                try:
                    bookmaker_browser_driver.refresh()
                    time.sleep(1.5)
                except Exception:
                    pass
                map_odds, body_text = _bookmaker_parse_map_market_on_current_page(
                    bookmaker_browser_driver,
                    site,
                    str(cache_entry.get("radiant_team") or ""),
                    str(cache_entry.get("dire_team") or ""),
                    cache_entry.get("map_num"),
                )
                market_closed = False
                if not map_odds and _bookmaker_is_map_market_closed is not None:
                    market_closed = bool(
                        _bookmaker_is_map_market_closed(
                            site,
                            body_text,
                            forced_map_num=cache_entry.get("map_num"),
                        )
                    )
                refreshed_sites[site] = {
                    "status": "ok",
                    "match_found": True,
                    "odds": list(map_odds or []),
                    "match_odds": [],
                    "source": "cached_match_tab_map_market" if map_odds else (
                        "cached_match_tab_map_market_closed" if market_closed else "cached_match_tab_map_missing"
                    ),
                    "details": str(body_text or "")[:500],
                    "market_closed": bool(market_closed),
                }
            except Exception as exc:
                refreshed_sites[site] = {
                    "status": "request_error",
                    "match_found": True,
                    "odds": [],
                    "match_odds": [],
                    "source": "cached_match_tab_error",
                    "details": str(exc)[:500],
                    "market_closed": False,
                }
        cache_entry["last_refreshed_at"] = time.time()
        bookmaker_browser_match_tabs.move_to_end(normalized_match_key, last=True)
        with bookmaker_prefetch_condition:
            payload = bookmaker_prefetch_results.get(normalized_match_key)
            if isinstance(payload, dict):
                payload["sites"] = dict(refreshed_sites or payload.get("sites") or {})
                payload["odds_refreshed_at"] = cache_entry["last_refreshed_at"]
                bookmaker_prefetch_condition.notify_all()
            return payload if isinstance(payload, dict) else None


def _bookmaker_best_effort_odds_block(
    match_key: str,
    selected_side: Any = _BOOKMAKER_SELECTED_SIDE_UNSET,
) -> Tuple[str, bool, str]:
    # Odds-mode delivery uses the same strict Winline current-map contract.
    return _bookmaker_format_odds_block(match_key, selected_side=selected_side)


def _bookmaker_refresh_snapshot_via_subprocess(match_key: str) -> Optional[dict]:
    """Legacy name kept for call-sites; odds mode uses shared Camoufox, not a subprocess browser.

    Presence mode may still use the subprocess path when Camoufox is unavailable.
    """
    if not BOOKMAKER_PREFETCH_ENABLED:
        return None
    # Odds delivery must never spawn a Camoufox subprocess: use process singleton / fail closed.
    if BOOKMAKER_PREFETCH_GATE_MODE == "odds" or (
        BOOKMAKER_CAMOUFOX_ENABLED and BOOKMAKER_CAMOUFOX_IMPORTED
    ):
        return _bookmaker_refresh_snapshot_via_shared_camoufox(match_key)
    if not BOOKMAKER_PREFETCH_USE_SUBPROCESS:
        return None
    snapshot = _bookmaker_prefetch_lookup(match_key, wait_seconds=0.0)
    if not isinstance(snapshot, dict):
        return None
    radiant_team = str(snapshot.get("radiant_team") or "")
    dire_team = str(snapshot.get("dire_team") or "")
    mode = str(snapshot.get("mode") or BOOKMAKER_PREFETCH_MODE or "live")
    map_num_raw = snapshot.get("map_num")
    try:
        map_num = int(map_num_raw) if map_num_raw is not None else None
    except (TypeError, ValueError):
        map_num = None
    if map_num is not None and not (1 <= map_num <= 5):
        map_num = None
    radiant_team_candidates = list(snapshot.get("radiant_team_candidates") or [radiant_team])
    dire_team_candidates = list(snapshot.get("dire_team_candidates") or [dire_team])
    try:
        sites_payload = _bookmaker_prefetch_fetch_subprocess(
            radiant_team=radiant_team,
            dire_team=dire_team,
            mode=mode,
            map_num=map_num,
            radiant_team_candidates=radiant_team_candidates,
            dire_team_candidates=dire_team_candidates,
        )
    except Exception as exc:
        logger.warning("BOOKMAKER_SUBPROCESS_REFRESH_FAILED %s: %s", match_key, exc)
        return snapshot
    refreshed_at = time.time()
    with bookmaker_prefetch_condition:
        payload = bookmaker_prefetch_results.get(match_key)
        if isinstance(payload, dict):
            payload["status"] = "done"
            payload["finished_at"] = refreshed_at
            payload["odds_refreshed_at"] = refreshed_at
            payload["sites"] = sites_payload
            bookmaker_prefetch_condition.notify_all()
    return _bookmaker_prefetch_lookup(match_key, wait_seconds=0.0)


def _replace_bookmaker_block_in_message(message_text: str, bookmaker_block: str) -> str:
    if not isinstance(message_text, str) or not message_text.strip():
        return message_text
    lines = message_text.splitlines()
    filtered: List[str] = []
    skipping_old_block = False
    for line in lines:
        stripped = str(line).strip()
        if (
            stripped.startswith("БК (")
            or stripped.startswith("Букмекеры (")
            or stripped.startswith("Кэф Winline:")
        ):
            skipping_old_block = True
            continue
        if skipping_old_block and (
            stripped.startswith("Winline")
            or stripped.startswith("BetBoom")
            or stripped.startswith("Pari")
            or stripped.startswith("Кэф Winline:")
        ):
            continue
        if skipping_old_block:
            skipping_old_block = False
        filtered.append(line)
    trailing_newline = "\n" if message_text.endswith("\n") else ""
    block = str(bookmaker_block or "").rstrip("\n")
    if block:
        filtered.append(block)
    return "\n".join(filtered) + trailing_newline


def _refresh_message_bookmaker_block_for_dispatch(
    match_key: str,
    message_text: str,
) -> str:
    """Legacy helper kept for tests/callers that only need message text refresh.

    Production dispatch callers must not pre-prepare: `_deliver_and_persist_signal`
    owns the single prepare/reserve + post-delivery commit path.
    """
    refreshed_message, bookmaker_ready, _bookmaker_reason, _reservation = (
        _bookmaker_prepare_message_for_delivery(
            match_key,
            message_text,
        )
    )
    if not bookmaker_ready:
        return message_text
    return refreshed_message


def _bookmaker_prepare_message_for_delivery(
    match_key: str,
    message_text: str,
    *,
    deadline_ts: Optional[float] = None,
    map_num: Optional[int] = None,
    current_map_observation: Any = None,
    selected_side: Any = _BOOKMAKER_SELECTED_SIDE_UNSET,
) -> Tuple[str, bool, str, Optional[Dict[str, Any]]]:
    """Prepare/reserve open Winline odds for delivery. Does not mark sent.

    Returns (message, ready, reason, reservation_context).
    reservation_context is present only when open odds were reserved for this map.
    """
    if not BOOKMAKER_PREFETCH_ENABLED or BOOKMAKER_PREFETCH_GATE_MODE != "odds":
        return message_text, True, "disabled", None
    # Odds mode always uses the shared/in-process contract; disabled/import/error is fail-closed.
    try:
        _bookmaker_refresh_snapshot_via_shared_camoufox(match_key)
    except Exception as exc:
        logger.warning("BOOKMAKER_SHARED_CAMOUFOX_REFRESH_FAILED %s: %s", match_key, exc)
        failed_at = time.time()
        with bookmaker_prefetch_condition:
            payload = bookmaker_prefetch_results.get(match_key)
            if isinstance(payload, dict):
                payload["status"] = "error"
                payload.setdefault("sites", payload.get("sites") or {})
                payload["error"] = "shared_camoufox_refresh_failed"
                payload["odds_refresh_ready"] = False
                payload["odds_refresh_failed_at"] = failed_at
                payload["finished_at"] = failed_at
                bookmaker_prefetch_condition.notify_all()

    snapshot = _bookmaker_prefetch_lookup(match_key, wait_seconds=0.0)
    # Fail-closed when shared Camoufox marked the snapshot gate-ineligible.
    if isinstance(snapshot, dict) and snapshot.get("odds_refresh_ready") is False:
        err = str(snapshot.get("error") or "shared_camoufox_refresh_failed")
        return message_text, False, err, None
    resolved_map = map_num
    if resolved_map is None and isinstance(snapshot, dict):
        try:
            raw_map = snapshot.get("map_num")
            resolved_map = int(raw_map) if raw_map is not None else None
        except (TypeError, ValueError):
            resolved_map = None
    if resolved_map is not None and not (1 <= int(resolved_map) <= 5):
        resolved_map = None
    if resolved_map is None and isinstance(current_map_observation, dict):
        try:
            raw_obs_map = current_map_observation.get("map_num")
            resolved_map = int(raw_obs_map) if raw_obs_map is not None else None
        except (TypeError, ValueError):
            resolved_map = None
        if resolved_map is not None and not (1 <= int(resolved_map) <= 5):
            resolved_map = None

    with bookmaker_odds_delivery_pending_lock:
        decision = _bookmaker_resolve_odds_delivery_state(
            match_key,
            pending_state=bookmaker_odds_delivery_pending,
            deadline_ts=deadline_ts,
            map_num=resolved_map,
            current_map_observation=current_map_observation,
            selected_side=selected_side,
        )
    state = str(decision.get("state") or "")
    reason = str(decision.get("reason") or state or "unknown")
    reservation = decision.get("reservation_context")
    if not isinstance(reservation, dict):
        reservation = None
    if state == "temporarily_closed_wait":
        return message_text, False, reason or "temporarily_closed_wait", reservation
    if state == "terminal_skip":
        return message_text, False, f"terminal_skip:{reason}", reservation
    if not decision.get("should_send"):
        # already_sent or not ready
        if reason == "already_sent":
            return message_text, False, "already_sent", reservation
        return message_text, False, reason or "no_strict_winline_current_map", reservation
    bookmaker_block = str(decision.get("block") or "")
    if not bookmaker_block:
        bookmaker_block, bookmaker_ready, bookmaker_reason = _bookmaker_best_effort_odds_block(
            match_key, selected_side=selected_side
        )
        if not bookmaker_ready:
            # Open market without numeric odds: release any reservation so later open can retry.
            if reservation is not None:
                _bookmaker_rollback_odds_delivery(match_key, reservation_context=reservation)
            return message_text, False, str(bookmaker_reason or "no_numeric_odds"), None
    return (
        _replace_bookmaker_block_in_message(message_text, bookmaker_block),
        True,
        "ok",
        reservation,
    )


def _build_bookmaker_empty_odds_block(match_key: str) -> str:
    snapshot = _bookmaker_prefetch_lookup(match_key, wait_seconds=0.0)
    mode = str((snapshot or {}).get("mode") or BOOKMAKER_PREFETCH_MODE or "live")
    map_num_raw = (snapshot or {}).get("map_num")
    map_num = int(map_num_raw) if isinstance(map_num_raw, int) and 1 <= map_num_raw <= 5 else None
    map_suffix = f", карта {map_num}" if map_num is not None else ""
    return f"БК ({mode}{map_suffix}): Winline —\n"


def _prepare_minimal_odds_only_message_for_delivery(
    match_key: str,
    message_text: str,
    *,
    deadline_ts: Optional[float] = None,
    map_num: Optional[int] = None,
    current_map_observation: Any = None,
    selected_side: Any = _BOOKMAKER_SELECTED_SIDE_UNSET,
) -> Tuple[str, bool, str, Optional[Dict[str, Any]]]:
    # Same production path as full prepare: shared Camoufox + state machine.
    return _bookmaker_prepare_message_for_delivery(
        match_key,
        message_text,
        deadline_ts=deadline_ts,
        map_num=map_num,
        current_map_observation=current_map_observation,
        selected_side=selected_side,
    )


def _bookmaker_prefetch_submit(
    match_key: str,
    radiant_team: str,
    dire_team: str,
    map_num: Optional[int] = None,
    series_url: str = "",
    league_title: str = "",
) -> None:
    if not BOOKMAKER_PREFETCH_ENABLED:
        return
    if not match_key:
        return
    # Fail closed: every internal lifecycle identity requires series + valid map_num.
    # Diagnostic/raw score URL may be retained on the payload only.
    try:
        resolved_map = int(map_num) if map_num is not None else None
    except (TypeError, ValueError):
        resolved_map = None
    if resolved_map is None or not (1 <= resolved_map <= 5):
        return
    lifecycle_key = _bookmaker_lifecycle_identity(match_key, map_num=resolved_map)
    if not lifecycle_key:
        # Also try series_url when match_key cannot yield a series id.
        lifecycle_key = _bookmaker_lifecycle_identity(series_url or "", map_num=resolved_map)
    if not lifecycle_key:
        return
    diagnostic_url = str(match_key or "").strip()
    _ensure_bookmaker_prefetch_started()
    now_ts = time.time()
    slug_radiant_team, slug_dire_team = _bookmaker_extract_team_aliases_from_series_url(
        series_url=series_url or match_key,
        league_title=league_title,
    )
    radiant_team_candidates = _bookmaker_build_team_candidates(radiant_team, slug_radiant_team)
    dire_team_candidates = _bookmaker_build_team_candidates(dire_team, slug_dire_team)
    stale_match_keys: List[str] = []
    with bookmaker_prefetch_condition:
        stale_match_keys = _bookmaker_prefetch_prune_locked(now_ts)
        existing = bookmaker_prefetch_results.get(lifecycle_key)
        if isinstance(existing, dict):
            status = str(existing.get("status") or "")
            if status in {"queued", "running", "done"} or (
                BOOKMAKER_PREFETCH_GATE_MODE == "presence" and status == "error"
            ):
                # Keep latest diagnostic URL on the shared lifecycle entry.
                if diagnostic_url:
                    existing["diagnostic_url"] = diagnostic_url
                    existing["url"] = diagnostic_url
                return
            # Odds mode: allow re-queue after terminal error (one-reset recovery).
        if len(bookmaker_prefetch_queue) >= max(10, int(BOOKMAKER_PREFETCH_MAX_PENDING)):
            print(f"   ⚠️ Bookmaker prefetch queue overflow ({len(bookmaker_prefetch_queue)}), skip {lifecycle_key}")
            return
        bookmaker_prefetch_results[lifecycle_key] = {
            "status": "queued",
            "mode": BOOKMAKER_PREFETCH_MODE,
            "gate_mode": BOOKMAKER_PREFETCH_GATE_MODE,
            "submitted_at": now_ts,
            "radiant_team": str(radiant_team or ""),
            "dire_team": str(dire_team or ""),
            "radiant_team_candidates": list(radiant_team_candidates),
            "dire_team_candidates": list(dire_team_candidates),
            "map_num": resolved_map,
            "sites": {},
            "diagnostic_url": diagnostic_url,
            "url": diagnostic_url,
            "lifecycle_key": lifecycle_key,
        }
        bookmaker_prefetch_queue.append(
            {
                "match_key": lifecycle_key,
                "radiant_team": str(radiant_team or ""),
                "dire_team": str(dire_team or ""),
                "radiant_team_candidates": list(radiant_team_candidates),
                "dire_team_candidates": list(dire_team_candidates),
                "map_num": resolved_map,
                "mode": BOOKMAKER_PREFETCH_MODE,
                "gate_mode": BOOKMAKER_PREFETCH_GATE_MODE,
                "submitted_at": now_ts,
                "series_url": str(series_url or ""),
                "league_title": str(league_title or ""),
                "diagnostic_url": diagnostic_url,
            }
        )
        bookmaker_prefetch_condition.notify()
    for stale_match_key in stale_match_keys:
        _bookmaker_release_match_tabs(stale_match_key)
    print(
        "   📥 Bookmaker prefetch queued: "
        f"{lifecycle_key} "
        f"(radiant={radiant_team_candidates}, dire={dire_team_candidates}, "
        f"mode={BOOKMAKER_PREFETCH_MODE}, gate={BOOKMAKER_PREFETCH_GATE_MODE}, "
        f"diag={diagnostic_url})"
    )


def _bookmaker_prefetch_fetch_subprocess(
    radiant_team: str,
    dire_team: str,
    mode: str,
    map_num: Optional[int] = None,
    radiant_team_candidates: Optional[List[str]] = None,
    dire_team_candidates: Optional[List[str]] = None,
) -> Dict[str, dict]:
    # Odds mode: Camoufox/bookmaker subprocess is unreachable regardless of import flags.
    # Callers must use shared/in-process refresh; fail closed with no fabricated odds.
    if BOOKMAKER_PREFETCH_GATE_MODE == "odds":
        raise RuntimeError(
            "bookmaker Camoufox subprocess is forbidden in odds mode "
            "(shared session only; fail closed when unavailable)"
        )
    if BOOKMAKER_PREFETCH_GATE_MODE == "presence":
        script_path = Path(__file__).resolve().parent / "bookmaker_selenium_odds.py"
        cmd = [
            sys.executable,
            str(script_path),
            "--mode",
            str(mode or BOOKMAKER_PREFETCH_MODE),
            "--team1",
            str(radiant_team or ""),
            "--team2",
            str(dire_team or ""),
            "--presence-only",
        ]
        for alias in list(radiant_team_candidates or [])[1:]:
            cmd.extend(["--team1-alias", str(alias)])
        for alias in list(dire_team_candidates or [])[1:]:
            cmd.extend(["--team2-alias", str(alias)])
    else:
        script_path = Path(__file__).resolve().parent / "bookmaker_selenium_odds.py"
        cmd = [
            sys.executable,
            str(script_path),
            "--mode",
            str(mode or BOOKMAKER_PREFETCH_MODE),
            "--team1",
            str(radiant_team or ""),
            "--team2",
            str(dire_team or ""),
            "--odds",
            "true" if BOOKMAKER_PREFETCH_ENABLED else "false",
        ]
    effective_sites = _bookmaker_effective_sites_for_mode(
        "presence" if BOOKMAKER_PREFETCH_GATE_MODE == "presence" else "odds"
    )
    if effective_sites:
        cmd.extend(["--sites", *effective_sites])
    if isinstance(map_num, int) and 1 <= map_num <= 5:
        cmd.extend(["--map-num", str(map_num)])

    proc = subprocess.run(
        cmd,
        capture_output=True,
        text=True,
        timeout=max(10, int(BOOKMAKER_PREFETCH_SUBPROCESS_TIMEOUT_SECONDS)),
        cwd=str(Path(__file__).resolve().parent.parent),
    )
    if proc.returncode != 0:
        err_tail = (proc.stderr or proc.stdout or "").strip()[-700:]
        raise RuntimeError(f"bookmaker subprocess failed rc={proc.returncode}: {err_tail}")

    raw = (proc.stdout or "").strip()
    if not raw:
        raise RuntimeError("bookmaker subprocess returned empty stdout")

    payload = None
    try:
        payload = json.loads(raw)
    except Exception:
        # Fallback: find the first complete JSON object starting from the first '{'
        first_brace = raw.find("{")
        if first_brace >= 0:
            candidate = raw[first_brace:]
            # Count braces to find the matching closing brace
            open_count = 0
            end_pos = -1
            for i, ch in enumerate(candidate):
                if ch == "{":
                    open_count += 1
                elif ch == "}":
                    open_count -= 1
                    if open_count == 0:
                        end_pos = i + 1
                        break
            if end_pos > 0:
                try:
                    payload = json.loads(candidate[:end_pos])
                except Exception:
                    pass
    if not isinstance(payload, dict):
        raise RuntimeError("bookmaker subprocess returned invalid JSON payload")

    sites_payload: Dict[str, dict] = {}
    for item in payload.get("results") or []:
        if not isinstance(item, dict):
            continue
        site = str(item.get("site") or "").strip().lower()
        if not site:
            continue
        sites_payload[site] = {
            "status": str(item.get("status") or ""),
            "match_found": bool(item.get("match_found", False)),
            "odds": list(item.get("odds") or []),
            "match_odds": list(item.get("match_odds") or []),
            "source": str(item.get("source") or ""),
            "details": str(item.get("details") or "")[:500],
            "market_closed": bool(item.get("market_closed", False)),
            "market_kind": item.get("market_kind"),
            "map_num": item.get("map_num"),
            "p1_team": item.get("p1_team"),
            "p2_team": item.get("p2_team"),
        }
    return sites_payload


def _bookmaker_prefetch_fetch_camoufox_direct(
    radiant_team: str,
    dire_team: str,
    mode: str,
    map_num: Optional[int] = None,
    radiant_team_candidates: Optional[List[str]] = None,
    dire_team_candidates: Optional[List[str]] = None,
) -> Dict[str, dict]:
    """Fetch bookmaker odds in reusable named tabs of the shared Camoufox browser."""
    if not BOOKMAKER_CAMOUFOX_IMPORTED or _bookmaker_parse_site_in_camoufox_page is None:
        raise RuntimeError("Camoufox not available")

    urls = _bookmaker_urls_for_mode(mode)
    effective_sites = _bookmaker_effective_sites_for_mode(BOOKMAKER_PREFETCH_GATE_MODE)
    selected_sites = [site for site in effective_sites if site in urls]

    team1 = str(radiant_team or "")
    team2 = str(dire_team or "")

    def _job(browser) -> Dict[str, dict]:
        results: Dict[str, dict] = {}
        session = _shared_camoufox_session
        for site in selected_sites:
            page_name = f"bookmaker:{site}"
            page = session.get_or_create_page(page_name, browser)
            try:
                result = _bookmaker_parse_site_in_camoufox_page(
                    page,
                    site=site,
                    url=urls[site],
                    team1=team1,
                    team2=team2,
                    mode=mode,
                    forced_map_num=map_num,
                )
                results[site] = {
                    "status": result.status,
                    "match_found": result.match_found,
                    "odds": result.odds,
                    "match_odds": result.match_odds,
                    "source": result.source,
                    "details": result.details[:500] if result.details else "",
                    "market_closed": result.market_closed,
                    "market_kind": getattr(result, "market_kind", None),
                    "map_num": getattr(result, "map_num", None),
                    "p1_team": getattr(result, "p1_team", None),
                    "p2_team": getattr(result, "p2_team", None),
                }
            except Exception as e:
                # Parser left page unrecoverable: drop only this named tab, keep browser.
                with contextlib.suppress(Exception):
                    session.invalidate_named_page(page_name)
                results[site] = {
                    "status": "error",
                    "match_found": False,
                    "odds": [],
                    "match_odds": [],
                    "source": "camoufox_direct_error",
                    "details": str(e)[:500],
                    "market_closed": False,
                }
            # Reusable named page: do not close after each job.
        return results

    return _run_shared_camoufox_job("bookmaker-prefetch", _job, timeout=180)


def _bookmaker_prefetch_loop() -> None:
    """Bookmaker prefetch worker. Reuses a single Camoufox browser when CAMOUFOX_ENABLED=1."""
    driver = None
    driver_tasks_done = 0
    browser_idle_check_counter = 0
    while not bookmaker_prefetch_stop_event.is_set():
        task = None
        with bookmaker_prefetch_condition:
            while not bookmaker_prefetch_queue and not bookmaker_prefetch_stop_event.is_set():
                bookmaker_prefetch_condition.wait(timeout=0.5)
            if bookmaker_prefetch_stop_event.is_set():
                break
            if bookmaker_prefetch_queue:
                task = bookmaker_prefetch_queue.popleft()
                match_key = str(task.get("match_key") or "")
                payload = bookmaker_prefetch_results.get(match_key)
                if isinstance(payload, dict):
                    payload["status"] = "running"
                    payload["started_at"] = time.time()
        if not task:
            # Periodic idle check
            browser_idle_check_counter += 1
            if browser_idle_check_counter >= 10:  # Every ~5 seconds
                browser_idle_check_counter = 0
                if _should_close_camoufox_browser():
                    _close_camoufox_browser()
            continue

        match_key = str(task.get("match_key") or "")
        radiant_team = str(task.get("radiant_team") or "")
        dire_team = str(task.get("dire_team") or "")
        radiant_team_candidates = list(task.get("radiant_team_candidates") or [radiant_team])
        dire_team_candidates = list(task.get("dire_team_candidates") or [dire_team])
        task_map_num_raw = task.get("map_num")
        try:
            task_map_num = int(task_map_num_raw) if task_map_num_raw is not None else None
        except (TypeError, ValueError):
            task_map_num = None
        if task_map_num is not None and not (1 <= task_map_num <= 5):
            task_map_num = None
        mode = str(task.get("mode") or BOOKMAKER_PREFETCH_MODE)
        try:
            if BOOKMAKER_PREFETCH_USE_SUBPROCESS and BOOKMAKER_CAMOUFOX_ENABLED and BOOKMAKER_CAMOUFOX_IMPORTED:
                # Direct Camoufox mode: reuse browser, no subprocess
                sites_payload = _bookmaker_prefetch_fetch_camoufox_direct(
                    radiant_team=radiant_team,
                    dire_team=dire_team,
                    mode=mode,
                    map_num=task_map_num,
                    radiant_team_candidates=radiant_team_candidates,
                    dire_team_candidates=dire_team_candidates,
                )
            elif BOOKMAKER_PREFETCH_USE_SUBPROCESS and BOOKMAKER_PREFETCH_GATE_MODE == "odds":
                # Odds mode: never spawn Camoufox subprocess when import/shared is unavailable.
                raise RuntimeError(
                    "shared_camoufox_unavailable: odds mode forbids bookmaker subprocess fallback"
                )
            elif BOOKMAKER_PREFETCH_USE_SUBPROCESS:
                # Presence-mode (or non-odds) may still use subprocess fallback.
                sites_payload = _bookmaker_prefetch_fetch_subprocess(
                    radiant_team=radiant_team,
                    dire_team=dire_team,
                    mode=mode,
                    map_num=task_map_num,
                    radiant_team_candidates=radiant_team_candidates,
                    dire_team_candidates=dire_team_candidates,
                )
            else:
                with bookmaker_browser_lock:
                    if not _bookmaker_browser_bootstrap_unlocked(mode):
                        raise RuntimeError("bookmaker browser session bootstrap failed")
                    driver = bookmaker_browser_driver
                    driver_tasks_done = 0
                    sites_payload = _bookmaker_open_cached_match_tabs_unlocked(
                        match_key,
                        radiant_team=radiant_team,
                        dire_team=dire_team,
                        radiant_team_candidates=radiant_team_candidates,
                        dire_team_candidates=dire_team_candidates,
                        mode=mode,
                        map_num=task_map_num,
                    )
            with bookmaker_prefetch_condition:
                payload = bookmaker_prefetch_results.get(match_key)
                if isinstance(payload, dict):
                    payload["status"] = "done"
                    payload["finished_at"] = time.time()
                    payload["sites"] = sites_payload
                bookmaker_prefetch_condition.notify_all()
            print(
                "   ✅ Bookmaker prefetch done: "
                f"{match_key} ({_bookmaker_sites_compact_summary(sites_payload)})"
            )
        except Exception as e:
            with bookmaker_prefetch_condition:
                payload = bookmaker_prefetch_results.get(match_key)
                if isinstance(payload, dict):
                    payload["status"] = "error"
                    payload["finished_at"] = time.time()
                    payload["error"] = str(e)
                bookmaker_prefetch_condition.notify_all()
            print(f"   ⚠️ Bookmaker prefetch error for {match_key}: {e}")
            # For Camoufox direct mode, don't close browser on error - just log and continue
            if not (BOOKMAKER_PREFETCH_USE_SUBPROCESS and BOOKMAKER_CAMOUFOX_ENABLED and BOOKMAKER_CAMOUFOX_IMPORTED):
                try:
                    if driver is not None and BOOKMAKER_PREFETCH_USE_SUBPROCESS:
                        driver.quit()
                except Exception:
                    pass
                if BOOKMAKER_PREFETCH_USE_SUBPROCESS:
                    driver = None
                    driver_tasks_done = 0

    # Cleanup: close persistent Camoufox browser on exit
    _close_camoufox_browser()
    try:
        if driver is not None and not (BOOKMAKER_PREFETCH_USE_SUBPROCESS and BOOKMAKER_CAMOUFOX_ENABLED and BOOKMAKER_CAMOUFOX_IMPORTED):
            driver.quit()
    except Exception:
        pass


def _ensure_bookmaker_prefetch_started() -> None:
    global bookmaker_prefetch_thread
    if not BOOKMAKER_PREFETCH_ENABLED:
        return
    thread = bookmaker_prefetch_thread
    if thread is not None:
        if thread.is_alive():
            # If stop was requested but odds got re-enabled before worker exit,
            # resume current worker instead of spawning a duplicate thread.
            if bookmaker_prefetch_stop_event.is_set():
                bookmaker_prefetch_stop_event.clear()
                with bookmaker_prefetch_condition:
                    bookmaker_prefetch_condition.notify_all()
            return
        bookmaker_prefetch_thread = None
    bookmaker_prefetch_stop_event.clear()
    bookmaker_prefetch_thread = threading.Thread(
        target=_bookmaker_prefetch_loop,
        name="bookmaker-prefetch",
        daemon=True,
    )
    bookmaker_prefetch_thread.start()
    print("🧵 Bookmaker prefetch worker started")


def _stop_bookmaker_prefetch_worker() -> None:
    global bookmaker_prefetch_thread, bookmaker_browser_driver, bookmaker_browser_base_handles, bookmaker_browser_match_tabs
    thread = bookmaker_prefetch_thread
    if thread is None:
        return
    bookmaker_prefetch_stop_event.set()
    with bookmaker_prefetch_condition:
        bookmaker_prefetch_condition.notify_all()
        bookmaker_prefetch_queue.clear()
        bookmaker_prefetch_results.clear()
    if thread.is_alive():
        thread.join(timeout=1.0)
    if thread.is_alive():
        bookmaker_prefetch_thread = thread
        print("🧵 Bookmaker prefetch worker stop requested (still shutting down)")
        return
    bookmaker_prefetch_thread = None
    with bookmaker_browser_lock:
        try:
            if bookmaker_browser_driver is not None:
                bookmaker_browser_driver.quit()
        except Exception:
            pass
        bookmaker_browser_driver = None
        bookmaker_browser_base_handles = {}
        bookmaker_browser_match_tabs = OrderedDict()
    print("🧵 Bookmaker prefetch worker stopped")

HERO_VALID_POSITIONS_DICT = {}
HERO_POSITION_COUNTS = {}
HERO_ID_TO_NAME = {}
try:
    with (BASE_DIR / 'hero_position_stats.json').open('r', encoding='utf-8') as f:
        _raw_position_stats = json.load(f)
    _min_position_pct = float(os.getenv("HERO_POSITION_STATS_MIN_PERCENTAGE", "1") or "1")
    for raw_hero_id, payload in (_raw_position_stats or {}).items():
        if not str(raw_hero_id).isdigit() or not isinstance(payload, dict):
            continue
        hero_id = str(raw_hero_id)
        hero_name = payload.get("hero_name")
        if hero_name:
            HERO_ID_TO_NAME[hero_id] = str(hero_name)
        raw_positions = payload.get("positions")
        if not isinstance(raw_positions, dict):
            continue
        valid_positions = []
        position_counts = {}
        for raw_pos, pos_stats in raw_positions.items():
            if not str(raw_pos).isdigit() or not isinstance(pos_stats, dict):
                continue
            pos_num = int(raw_pos)
            if not 1 <= pos_num <= 5:
                continue
            try:
                games = int(pos_stats.get("games", 0) or 0)
                percentage = float(pos_stats.get("percentage", 0) or 0)
            except (TypeError, ValueError):
                continue
            pos_label = f"POSITION_{pos_num}"
            if games > 0:
                position_counts[pos_label] = games
            if percentage >= _min_position_pct:
                valid_positions.append(pos_label)
        if valid_positions:
            HERO_VALID_POSITIONS_DICT[hero_id] = valid_positions
        if position_counts:
            HERO_POSITION_COUNTS[hero_id] = position_counts
except Exception as e:
    print(f"⚠️ Не удалось загрузить hero_position_stats.json: {e}")
    _report_missing_runtime_file(
        "hero_position_stats.json",
        BASE_DIR / "hero_position_stats.json",
        details=str(e),
    )


