                        delayed_payload['networth_monitor_status_17_to_19'] = str(dynamic_monitor_profile.get("status_17_to_19") or "")
                        delayed_payload['networth_monitor_status_20_to_26'] = str(dynamic_monitor_profile.get("status_20_to_26") or "")
